param(
    [Parameter(Mandatory = $true)]
    [string]$BaseUrl,

    [Parameter(Mandatory = $true)]
    [string]$Username,

    [string]$Client = "200",

    [string]$Language = "EN",

    [Parameter(Mandatory = $true)]
    [ValidateSet(
        "DiagnoseHelperApis",
        "InspectStructures",
        "InspectInterface",
        "InspectRepositoryApis",
        "InspectGuiApis",
        "InspectGuiObject",
        "InspectDdicApis",
        "DiagnoseDdicObject",
        "Install",
        "RepairInterface",
        "InstallRepositoryApi",
        "RepairRepositoryApi",
        "InstallDdicApi",
        "RepairDdicApi",
        "InstallApplicationLogApi",
        "RepairApplicationLogApi",
        "DiagnoseFunctionGroup",
        "DiagnoseRepositoryApi",
        "InspectAssignment",
        "AssignPackageTransport"
    )]
    [string]$Action,

    [ValidatePattern('^[ZY][A-Z0-9_]{0,29}$')]
    [string]$DdicObjectName = "ZCODEX_MCP_DE_0831",

    [ValidatePattern('^[A-Z/][A-Z0-9_/]{0,39}$')]
    [string]$GuiProgramName = "ZCODEX_MCP_DYNPRO",

    [ValidateSet("DOMA", "DTEL", "TABL", "TTYP")]
    [string]$DdicObjectType = "DTEL",

    [ValidatePattern('^[A-Z0-9]{10}$')]
    [string]$TransportNumber,

    [ValidatePattern('^[A-Z0-9]{10}$')]
    [string]$TransportTask,

    [ValidatePattern('^[A-Z/][A-Z0-9_/]{0,39}$')]
    [string]$PackageName = "ZABAP",

    [string]$ResultPath,

    [Security.SecureString]$SecurePassword,

    [switch]$AllowUnauthorized,

    [switch]$PassThru
)

$ErrorActionPreference = "Stop"

# Single source of truth for the CAPABILITIES self-description of the repository
# helper body ($repositoryFunctionSource). That body is shared by
# Z_ORVANTA_MCP_EXECUTE and Z_ORVANTA_MCP_DYNPRO_API, so both self-describe with
# the function module name they were generated for.
#
# Entry format: "<OPCODE>|<sinceVersion>|<R|W>". `sinceVersion` is the highest
# ev_version reported by that CASE branch, and PROTOCOL|MIN / PROTOCOL|MAX plus
# every OPERATION line are derived from this table -- never written a second time.
# Parsed offline by test/helper-capabilities-payload.test.ts.
#
# 操作码长度上限 30：本 body 部署到 Z_ORVANTA_MCP_EXECUTE 与 Z_ORVANTA_MCP_DYNPRO_API，两者的
# IV_OPERATION 都是 RS38L-NAME（CHAR 30，见 New-InstallProgram 的 $operationDbField）。更长
# 的名字会被 RFC 层截断而永远匹配不到 WHEN，助手只会回 OPERATION_NOT_ALLOWED。DDIC body 的
# 上限不同（BAPIRET2-PARAMETER，CHAR 32）；每个助手的上限由 test/helper-operation-limits.test.ts
# 从它自己的参数类型推导，不要在这里硬编码一个全局常量。
# >>> ORVANTA-CAPABILITY-TABLE
$helperCapabilityOperations = @(
    "READ_SAPSCRIPT_FORM|2.8|R",
    "READ_SMARTSTYLE|2.8|R",
    "READ_ADOBE_FORM|2.8|R",
    "CREATE_TRANSPORT_REQUEST|2.8|W",
    "ADD_OBJECTS_TO_TRANSPORT|2.8|W",
        "WRITE_FUNCTION_SOURCE|2.9|W",
    "READ_ENHANCEMENT_IMPL|2.6|R",
    "MANAGE_ENHANCEMENT_STATE|2.6|W",
    "DELETE_ENHANCEMENT_IMPL|2.5|W",
    "MANAGE_CLASSIC_BADI_IMPL|2.5|W",
    "READ_CLASSIC_BADI_DEFINITION|2.4|R",
    "READ_BTE_CONFIGURATION|2.3|R",
    "READ_CUSTOMER_EXIT_DEFINITION|2.2|R",
    "READ_CUSTOMER_EXIT_PROJECT|2.2|R",
    "CREATE_FUNCTION_GROUP|1.3|W",
    "CREATE_FUNCTION_INCLUDE|1.7|W",
    "READ_FUNCTION_INTERFACE|2.1|R",
    "CREATE_FUNCTION_MODULE|2.0|W",
    "PATCH_FUNCTION_INTERFACE|2.0|W",
    "INSPECT_REPOSITORY_ASSIGNMENT|1.3|R",
    "READ_GUI_DEFINITION|1.5|R",
    "PATCH_GUI_DEFINITION|1.5|W",
    "READ_SCREEN|1.1|R",
    "PATCH_SCREEN|1.4|W",
    "UPSERT_SCREEN|1.1|W",
    "DELETE_TRANSACTION|1.6|W",
    "DELETE_MODULE_POOL|1.6|W",
    "CREATE_MODULE_POOL|1.1|W",
    "READ_TRANSPORT_DETAILS|1.7|R",
    "DELETE_MESSAGE_CLASS|1.9|W",
    "UPDATE_MESSAGE_CLASS|1.8|W",
    "READ_TRANSACTION|1.2|R",
    "CREATE_REPORT_TRANSACTION|1.2|W",
    "CREATE_TRANSACTION|1.1|W",
    # Operations the repository CASE serves through shared clauses: a multi-opcode WHEN
    # ('X' OR 'Y'.) or a WHEN continued on the next line. A single-opcode scan of the CASE
    # misses these, so they are listed here explicitly and kept adjacent for review.
    "UPDATE_HOOK_ENHANCEMENT|2.6|W",
    "UPDATE_BADI_ENHANCEMENT|2.6|W",
    "CREATE_HOOK_ENHANCEMENT|2.5|W",
    "CREATE_BADI_ENHANCEMENT|2.5|W",
    "READ_TEXT_ELEMENTS|1.7|R",
    "MERGE_TEXT_ELEMENTS|1.7|W",
    "READ_MESSAGE_CLASS|1.2|R",
    "CREATE_MESSAGE_CLASS|1.2|W"
)
# <<< ORVANTA-CAPABILITY-TABLE

# Capability table of Z_ORVANTA_MCP_DDIC_API. Entry format is the same as the
# repository table above, but `sinceVersion` carries a different meaning here: the
# DDIC CASE only sets lv_object_type/lv_write flags and the actual ev_version values
# are emitted deep inside the shared code paths, so a per-branch scan cannot derive
# them. Each opcode therefore records the contract minimum of the capability group
# that owns it (src/capabilities.ts): ddic-helper-core 1.2,
# ddic-helper-transparent-table 1.5, ddic-helper-controlled-delete 1.6,
# ddic-helper-transparent-table-complex 1.7.
# Parsed offline by test/helper-capabilities-payload.test.ts.
# >>> ORVANTA-DDIC-CAPABILITY-TABLE
$ddicCapabilityOperations = @(
    "READ_DOMAIN|1.2|R",
    # 1.16：写入成功的判据从"存在活动版本"改成"保存产生的非活动版本已被激活消费"
    # （写后 state = 'M' 读取的 gotstate 必须为 'A'）。1.15 及更早的助手在对象原本
    # 就活动时无论激活是否生效都报成功——2026-09-25 锁对象假成功事件正是如此
    # （.logs/mcp-incident-20260925-001201-upsert-lock-object-false-success.md）。
    # 凡是走"PUT + ACTIVATE + 写后校验"的写操作，其成功含义都变了，因此这些行的
    # sinceVersion 一律抬到 1.16；只读操作与删除路径（不激活）不受影响，保持原值。
    # 这 14 行是唯一的 |1.16| 行，故 PROTOCOL|MAX 由 1.15 派生为 1.16。
    # 1.11 行的 READ/DELETE 号码段与维护视图、1.8/1.9 的搜索帮助与锁对象读取都不动：
    # 能力不得混用最低协议，抬读操作会把可用的读报成 unsupported。
    "UPSERT_DOMAIN|1.16|W",
    "READ_DATA_ELEMENT|1.2|R",
    "UPSERT_DATA_ELEMENT|1.16|W",
    "READ_STRUCTURE|1.2|R",
    "UPSERT_STRUCTURE|1.16|W",
    "READ_TABLE_TYPE|1.2|R",
    "UPSERT_TABLE_TYPE|1.16|W",
    "READ_TRANSPARENT_TABLE|1.5|R",
    # 1.15：透明表字段写入新增 REFTABLE/REFFIELD（DD03P 参考表/参考字段）。数量(QUAN)与货币
    # (CURR)字段没有内在单位，DDIC 激活检查会以"指定参考表和参考字段"拒绝，而调用方此前**无法
    # 表达**这两个属性——2026-09-24 实测：SE11 与助手对同一对象同样失败，日志给出该原因，且
    # 同日的对照实验（字段全部为字符型的表）创建后 DD02L AS4LOCAL='A' 正常激活，证明这是唯一
    # 阻塞项（同一检查输出的"增强类别"两行是提示而非错误：对照表 EXCLASS='0' 也激活成功）。
    # 属性集变了，能拒绝该属性的 1.14 及更早助手就不能再被报成 available，故三个字段写入操作的
    # sinceVersion 一律抬到 1.15；已发布的 1.14 仍提供 RESUME_TABLE_ACTIVATION，那一行不动。
    # 1.16 起这三行再抬一次：属性集不变，但成功判据变了（见上方 1.16 段）。
    "CREATE_TRANSPARENT_TABLE|1.16|W",
    "DELETE_DOMAIN|1.6|W",
    "DELETE_DATA_ELEMENT|1.6|W",
    "DELETE_STRUCTURE|1.6|W",
    "DELETE_TRANSPARENT_TABLE|1.6|W",
    "DELETE_TABLE_TYPE|1.6|W",
    "APPEND_TRANSPARENT_TABLE_FIELDS|1.16|W",
    "PATCH_TRANSPARENT_TABLE_FIELDS|1.16|W",
    "PATCH_TRANSPARENT_TABLE_SETTINGS|1.16|W",
    "RECOVER_TABLE_CONVERSION|1.7|W",
    "READ_SEARCH_HELP|1.8|R",
    "UPSERT_SEARCH_HELP|1.16|W",
    "DELETE_SEARCH_HELP|1.8|W",
    "READ_LOCK_OBJECT|1.9|R",
    "UPSERT_LOCK_OBJECT|1.16|W",
    "DELETE_LOCK_OBJECT|1.9|W",
    # R-20 改名后的操作码在这里记录为 1.11 而不是 1.10：1.10 载体发布的是 35 字符的
    # RESUME_TRANSPARENT_TABLE_ACTIVATION，被 CHAR 32 的 IV_OPERATION 截断，从未成功派发过。
    # 写 1.10 等于宣称"某个 1.10 助手投递过 RESUME_TABLE_ACTIVATION"，那是假的。见
    # test/helper-operation-limits.test.ts 与 src/helper-operation-limits.ts。
    # 1.14 再抬一次：1.11/1.12 的助手虽然能派发这个名字，却从未真正执行过恢复激活——它们把该
    # 操作当成转换恢复（lv_recover），无工作清单时回 WORKLIST_REQUIRED，有工作清单时执行一次
    # DD_DB_CONVERTER 并 RETURN，永远到不了自己的 lv_resume 激活分支。1.13 走通了这条分支，但
    # 分支里裸调 DD_TABL_ACT：未传 DEVICE/PRID 时 mass_act_tabl 没有协议通道、不改写 ACT_RESULT，
    # 实测恒返回 ACT_RC=8 / ACT_ROWS=0 且对象保持非活动（2026-09-24 事件，同一缺陷也存在于
    # TABL 臂的正常创建路径）。既然没有任何已发布助手提供**可用**的 RESUME_TABLE_ACTIVATION，
    # sinceVersion 就必须是第一个可用的版本 1.14；否则服务端会继续把 1.13 助手报成 available
    # （与 2026-09-23 事件同一类错误）。1.16 起再抬一次：恢复激活同样要证明"没有残留
    # 维护版本"，1.14/1.15 的恢复分支只做激活、不校验结果，与本次修复同一判据。
    "RESUME_TABLE_ACTIVATION|1.16|W",
    # D6-3 编号范围对象（TNRO + TNROT，区间值不在范围）。1.11 与 RESUME_TABLE_ACTIVATION 同批发布：
    # 三者都是本轮新加的 CASE 分支，任何已发布的助手都不曾提供，因此 sinceVersion 只能是 1.11。
    # 操作码长度：READ 24 / UPSERT 26 / DELETE 26，均在 DDIC 助手 BAPIRET2-PARAMETER(CHAR 32) 之内。
    "READ_NUMBER_RANGE_OBJECT|1.11|R",
    "UPSERT_NUMBER_RANGE_OBJECT|1.16|W",
    "DELETE_NUMBER_RANGE_OBJECT|1.11|W",
    # D6-4 维护视图（DD25V/DD26V/DD27P/DD28V）。同样与 1.11 同批发布：这三个 CASE 分支在
    # 1.10 及以前不存在。操作码长度：READ 21 / UPSERT 23 / DELETE 23，均在 CHAR 32 之内。
    "READ_MAINTENANCE_VIEW|1.11|R",
    "UPSERT_MAINTENANCE_VIEW|1.16|W",
    "DELETE_MAINTENANCE_VIEW|1.11|W",
    # D6-5 append 结构字段级写入。字段行只写 append 自身（DD_TBFD_PUT），随后直接激活基表
    # （DDIF_TABL_ACTIVATE），绝不手写基表的 DD03L 行集——依据 .doc/d6-5-activation-sufficiency-20260922.md
    # §4 的源码追踪。1.11 及以前不存在该分支，故 sinceVersion 只能是 1.12。
    # 操作码长度：UPSERT_APPEND_STRUCTURE_FIELDS = 31，在 BAPIRET2-PARAMETER(CHAR 32) 之内。
    # 1.16：该分支同样以"保存后必须已激活"为成功判据（写后 state = 'M' 探针），故随写路径抬起。
    "UPSERT_APPEND_STRUCTURE_FIELDS|1.16|W"
)
# <<< ORVANTA-DDIC-CAPABILITY-TABLE

# The DDIC helper publishes no separately approved scopes.
$ddicCapabilityScopes = @()

$ddicCapabilityVersions = $ddicCapabilityOperations | ForEach-Object {
    $ddicCapabilityTableParts = $_ -split "\|"
    [version]$ddicCapabilityTableParts[1]
}
$ddicCapabilityMinVersion = (
    $ddicCapabilityVersions | Sort-Object | Select-Object -First 1
).ToString()
$ddicCapabilityMaxVersion = (
    $ddicCapabilityVersions | Sort-Object -Descending | Select-Object -First 1
).ToString()

# Separately approved scopes of the repository helper. Empty on purpose: the
# REPORT_PARAMETERS scope belongs to Z_ORVANTA_OPS_READ
# (scripts/report-parameters-source.mjs), not to this body. Add
# "<SCOPE>|<enabled|disabled>" entries here to publish a scope.
$helperCapabilityScopes = @()

# PROTOCOL|MIN is the oldest protocol revision this helper still implements
# (lowest sinceVersion); PROTOCOL|MAX is the highest revision it implements.
$helperCapabilityVersions = $helperCapabilityOperations | ForEach-Object {
    $capabilityTableParts = $_ -split "\|"
    [version]$capabilityTableParts[1]
}
$helperCapabilityMinVersion = (
    $helperCapabilityVersions | Sort-Object | Select-Object -First 1
).ToString()
$helperCapabilityMaxVersion = (
    $helperCapabilityVersions | Sort-Object -Descending | Select-Object -First 1
).ToString()

function New-InspectionProgram {
    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "TYPE-POOLS abap.",
        "NEW-PAGE NO-TITLE LINE-COUNT 0 LINE-SIZE 255.",
        "DATA lo_descr TYPE REF TO cl_abap_structdescr.",
        "DATA lt_components TYPE abap_component_tab.",
        "DATA ls_component TYPE abap_componentdescr.",
        "DATA lv_name TYPE string.",
        "DO 2 TIMES.",
        "  IF sy-index = 1.",
        "    lv_name = 'RSIMP'.",
        "  ELSE.",
        "    lv_name = 'RSEXP'.",
        "  ENDIF.",
        "  lo_descr ?= cl_abap_typedescr=>describe_by_name( lv_name ).",
        "  lt_components = lo_descr->get_components( ).",
        "  WRITE: / 'STRUCT', lv_name.",
        "  LOOP AT lt_components INTO ls_component.",
        "    WRITE: / ls_component-name.",
        "  ENDLOOP.",
        "ENDDO."
    )
}

function New-InterfaceInspectionProgram {
    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "DATA lt_import TYPE TABLE OF rsimp.",
        "DATA lt_export TYPE TABLE OF rsexp.",
        "DATA lt_change TYPE TABLE OF rscha.",
        "DATA lt_tables TYPE TABLE OF rstbl.",
        "DATA lt_except TYPE TABLE OF rsexc.",
        "DATA lt_docu TYPE TABLE OF rsfdo.",
        "DATA lt_source TYPE TABLE OF rssource.",
        "DATA ls_import TYPE rsimp.",
        "DATA ls_export TYPE rsexp.",
        "DATA lv_remote TYPE rs38l-remote.",
        "DATA lv_line TYPE string.",
        "CALL FUNCTION 'RPY_FUNCTIONMODULE_READ_NEW'",
        "  EXPORTING functionname = 'RFC_SYSTEM_INFO'",
        "  IMPORTING remote_call = lv_remote",
        "  TABLES import_parameter = lt_import",
        "    changing_parameter = lt_change",
        "    export_parameter = lt_export",
        "    tables_parameter = lt_tables",
        "    exception_list = lt_except",
        "    documentation = lt_docu",
        "    source = lt_source.",
        "WRITE: / 'REMOTE', lv_remote.",
        "LOOP AT lt_import INTO ls_import.",
        "  CONCATENATE 'I' ls_import-parameter ls_import-dbfield",
        "    INTO lv_line SEPARATED BY '|'.",
        "  CONCATENATE lv_line ls_import-types ls_import-optional",
        "    INTO lv_line SEPARATED BY '|'.",
        "  CONCATENATE lv_line ls_import-reference ls_import-typ",
        "    INTO lv_line SEPARATED BY '|'.",
        "  WRITE / lv_line.",
        "ENDLOOP.",
        "LOOP AT lt_export INTO ls_export.",
        "  CONCATENATE 'E' ls_export-parameter ls_export-dbfield",
        "    INTO lv_line SEPARATED BY '|'.",
        "  CONCATENATE lv_line ls_export-types ls_export-reference",
        "    INTO lv_line SEPARATED BY '|'.",
        "  CONCATENATE lv_line ls_export-typ",
        "    INTO lv_line SEPARATED BY '|'.",
        "  WRITE / lv_line.",
        "ENDLOOP."
    )
}

function New-RepositoryApiInspectionProgram {
    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "TYPE-POOLS abap.",
        "NEW-PAGE NO-TITLE LINE-COUNT 0 LINE-SIZE 255.",
        "DATA lo_descr TYPE REF TO cl_abap_structdescr.",
        "DATA lt_components TYPE abap_component_tab.",
        "DATA ls_component TYPE abap_componentdescr.",
        "DATA lt_import TYPE TABLE OF rsimp.",
        "DATA lt_export TYPE TABLE OF rsexp.",
        "DATA lt_change TYPE TABLE OF rscha.",
        "DATA lt_tables TYPE TABLE OF rstbl.",
        "DATA lt_except TYPE TABLE OF rsexc.",
        "DATA lt_docu TYPE TABLE OF rsfdo.",
        "DATA lt_source TYPE TABLE OF rssource.",
        "DATA ls_import TYPE rsimp.",
        "DATA ls_export TYPE rsexp.",
        "DATA ls_change TYPE rscha.",
        "DATA ls_tables TYPE rstbl.",
        "DATA ls_seocompo TYPE seocompo.",
        "DATA ls_seometarel TYPE seometarel.",
        "DATA ls_dd03l TYPE dd03l.",
        "FIELD-SYMBOLS <lv_table_value> TYPE any.",
        "DATA lv_name TYPE rs38l-name.",
        "DATA lv_existing_name TYPE rs38l-name.",
        "DATA lv_line TYPE string.",
        "DATA lv_remote TYPE rs38l-remote.",
        "DATA lt_names TYPE TABLE OF string.",
        "DATA lo_intf TYPE REF TO cl_abap_intfdescr.",
        "DATA ls_method TYPE abap_methdescr.",
        "DATA ls_parameter TYPE abap_parmdescr.",
        "SELECT * FROM seocompo INTO ls_seocompo",
        "  WHERE clsname = 'IF_ENH_TOOL'",
        "     OR clsname = 'IF_ENH_OBJECT'",
        "     OR clsname = 'IF_ENH_OBJECT_DOCU'.",
        "  WRITE: / 'OO_METHOD', ls_seocompo-clsname,",
        "    ls_seocompo-cmpname, ls_seocompo-cmptype.",
        "ENDSELECT.",
        "SELECT * FROM seometarel INTO ls_seometarel",
        "  WHERE clsname = 'IF_ENH_TOOL'",
        "     OR clsname = 'IF_ENH_OBJECT'",
        "     OR clsname = 'IF_ENH_OBJECT_DOCU'.",
        "  WRITE: / 'OO_RELATION', ls_seometarel-clsname,",
        "    ls_seometarel-refclsname, ls_seometarel-reltype.",
        "ENDSELECT.",
        "SELECT * FROM dd03l INTO ls_dd03l",
        "  WHERE as4local = 'A'",
        "    AND ( tabname = 'TBE24' OR tabname = 'TBE34'",
        "       OR tabname = 'TPS24' OR tabname = 'TPS34' ).",
        "  WRITE: / 'DDIC_FIELD', ls_dd03l-tabname,",
        "    ls_dd03l-fieldname, ls_dd03l-position, ls_dd03l-rollname.",
        "ENDSELECT.",
        "lo_intf ?= cl_abap_typedescr=>describe_by_name(",
        "  'IF_ENH_OBJECT_DOCU' ).",
        "READ TABLE lo_intf->methods INTO ls_method",
        "  WITH KEY name = 'SET_SHORTTEXT'.",
        "IF sy-subrc = 0.",
        "  LOOP AT ls_method-parameters INTO ls_parameter.",
        "    WRITE: / 'OO_PARAMETER', ls_parameter-name,",
        "      ls_parameter-parm_kind, ls_parameter-type_kind,",
        "      ls_parameter-length, ls_parameter-decimals.",
        "  ENDLOOP.",
        "ENDIF.",
        "SELECT funcname FROM tfdir INTO lv_name",
        "  WHERE funcname LIKE 'RPY%MESS%'",
        "     OR funcname LIKE 'RS%TEXTPOOL%'.",
        "  CONCATENATE 'CANDIDATE' lv_name",
        "    INTO lv_line SEPARATED BY '|'.",
        "  WRITE / lv_line.",
        "ENDSELECT.",
        "APPEND 'RSIMP' TO lt_names.",
        "APPEND 'RSEXP' TO lt_names.",
        "APPEND 'RSCHA' TO lt_names.",
        "APPEND 'RSTBL' TO lt_names.",
        "APPEND 'RSEXC' TO lt_names.",
        "APPEND 'RSFDO' TO lt_names.",
        "APPEND 'D020S' TO lt_names.",
        "APPEND 'D021S' TO lt_names.",
        "APPEND 'D022S' TO lt_names.",
        "APPEND 'D023S' TO lt_names.",
        "APPEND 'RPY_DYHEAD' TO lt_names.",
        "APPEND 'RPY_DYCATT' TO lt_names.",
        "APPEND 'RPY_DYFATC' TO lt_names.",
        "APPEND 'RPY_DYFLOW' TO lt_names.",
        "APPEND 'RPY_DYPARA' TO lt_names.",
        "APPEND 'TEXTPOOL' TO lt_names.",
        "APPEND 'T100' TO lt_names.",
        "APPEND 'T100A' TO lt_names.",
        "APPEND 'TSTC' TO lt_names.",
        "APPEND 'TSTCC' TO lt_names.",
        "LOOP AT lt_names INTO lv_name.",
        "  lo_descr ?= cl_abap_typedescr=>describe_by_name( lv_name ).",
        "  lt_components = lo_descr->get_components( ).",
        "  WRITE: / 'STRUCT', lv_name.",
        "  LOOP AT lt_components INTO ls_component.",
        "    WRITE / ls_component-name.",
        "  ENDLOOP.",
        "ENDLOOP.",
        "REFRESH lt_names.",
        "APPEND 'RPY_DYNPRO_READ' TO lt_names.",
        "APPEND 'RPY_DYNPRO_INSERT' TO lt_names.",
        "APPEND 'RPY_DYNPRO_READ_NATIVE' TO lt_names.",
        "APPEND 'RPY_DYNPRO_INSERT_NATIVE' TO lt_names.",
        "APPEND 'RPY_DYNPRO_DELETE' TO lt_names.",
        "APPEND 'RPY_PROGRAM_INSERT' TO lt_names.",
        "APPEND 'RPY_PROGRAM_UPDATE' TO lt_names.",
        "APPEND 'RPY_PROGRAM_DELETE' TO lt_names.",
        "APPEND 'RS_DELETE_PROGRAM' TO lt_names.",
        "APPEND 'RPY_TRANSACTION_READ' TO lt_names.",
        "APPEND 'RPY_TRANSACTION_INSERT' TO lt_names.",
        "APPEND 'RPY_TRANSACTION_DELETE' TO lt_names.",
        "APPEND 'RPY_MESSAGE_ID_READ' TO lt_names.",
        "APPEND 'RPY_MESSAGE_ID_INSERT' TO lt_names.",
        "APPEND 'RPY_MESSAGE_ID_SELECT' TO lt_names.",
        "APPEND 'RPY_MESSAGE_READ' TO lt_names.",
        "APPEND 'RPY_EXISTENCE_CHECK_MESS' TO lt_names.",
        "APPEND 'RS_TEXTPOOL_READ' TO lt_names.",
        "APPEND 'RS_TEXTPOOL_GET' TO lt_names.",
        "APPEND 'RS_TEXTPOOL_ADD' TO lt_names.",
        "APPEND 'MESSAGES_ACTIVE' TO lt_names.",
        "APPEND 'RS_CORR_INSERT' TO lt_names.",
        "LOOP AT lt_names INTO lv_name.",
        "  CLEAR lv_existing_name.",
        "  SELECT SINGLE funcname FROM tfdir INTO lv_existing_name",
        "    WHERE funcname = lv_name.",
        "  IF sy-subrc <> 0.",
        "    CONCATENATE 'FUNCTION_MISSING' lv_name",
        "      INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "    CONTINUE.",
        "  ENDIF.",
        "  REFRESH: lt_import, lt_export, lt_change, lt_tables,",
        "    lt_except, lt_docu, lt_source.",
        "  CLEAR lv_remote.",
        "  CALL FUNCTION 'RPY_FUNCTIONMODULE_READ_NEW'",
        "    EXPORTING functionname = lv_name",
        "    IMPORTING remote_call = lv_remote",
        "    TABLES import_parameter = lt_import",
        "      changing_parameter = lt_change",
        "      export_parameter = lt_export",
        "      tables_parameter = lt_tables",
        "      exception_list = lt_except",
        "      documentation = lt_docu",
        "      source = lt_source.",
        "  WRITE: / 'FUNCTION', lv_name, lv_remote.",
        "  LOOP AT lt_import INTO ls_import.",
        "    CONCATENATE 'I' ls_import-parameter",
        "      ls_import-dbfield INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "  ENDLOOP.",
        "  LOOP AT lt_export INTO ls_export.",
        "    CONCATENATE 'E' ls_export-parameter",
        "      ls_export-dbfield INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "  ENDLOOP.",
        "  LOOP AT lt_change INTO ls_change.",
        "    CONCATENATE 'C' ls_change-parameter",
        "      ls_change-dbfield INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "  ENDLOOP.",
        "  LOOP AT lt_tables INTO ls_tables.",
        "    CLEAR lv_line.",
        "    ASSIGN COMPONENT 'PARAMETER' OF STRUCTURE ls_tables",
        "      TO <lv_table_value>.",
        "    IF sy-subrc = 0.",
        "      CONCATENATE 'T' <lv_table_value>",
        "        INTO lv_line SEPARATED BY '|'.",
        "    ENDIF.",
        "    ASSIGN COMPONENT 'DBSTRUCT' OF STRUCTURE ls_tables",
        "      TO <lv_table_value>.",
        "    IF sy-subrc = 0.",
        "      CONCATENATE lv_line <lv_table_value>",
        "        INTO lv_line SEPARATED BY '|'.",
        "    ENDIF.",
        "    WRITE / lv_line.",
        "  ENDLOOP.",
        "ENDLOOP."
    )
}

function New-GuiApiInspectionProgram {
    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "TYPE-POOLS abap.",
        "NEW-PAGE NO-TITLE LINE-COUNT 0 LINE-SIZE 255.",
        "DATA lo_descr TYPE REF TO cl_abap_structdescr.",
        "DATA lt_components TYPE abap_component_tab.",
        "DATA ls_component TYPE abap_componentdescr.",
        "DATA lt_dfies TYPE TABLE OF dfies.",
        "DATA ls_dfies TYPE dfies.",
        "DATA lt_import TYPE TABLE OF rsimp.",
        "DATA lt_export TYPE TABLE OF rsexp.",
        "DATA lt_change TYPE TABLE OF rscha.",
        "DATA lt_tables TYPE TABLE OF rstbl.",
        "DATA lt_except TYPE TABLE OF rsexc.",
        "DATA lt_docu TYPE TABLE OF rsfdo.",
        "DATA lt_source TYPE TABLE OF rssource.",
        "DATA ls_import TYPE rsimp.",
        "DATA ls_export TYPE rsexp.",
        "DATA ls_change TYPE rscha.",
        "DATA ls_tables TYPE rstbl.",
        "DATA ls_except TYPE rsexc.",
        "DATA lv_name TYPE rs38l-name.",
        "DATA lv_existing_name TYPE rs38l-name.",
        "DATA lv_type_name TYPE string.",
        "DATA lv_existing_type TYPE ddobjname.",
        "DATA lv_line TYPE string.",
        "DATA lv_subrc_text TYPE c LENGTH 10.",
        "DATA lv_remote TYPE rs38l-remote.",
        "DATA lt_names TYPE TABLE OF string.",
        "DATA lt_type_names TYPE TABLE OF string.",
        "SELECT funcname FROM tfdir INTO lv_name",
        "  WHERE funcname LIKE 'RS%CUA%'",
        "     OR funcname LIKE 'RPY%MENU%'",
        "     OR funcname LIKE 'RPY%STATUS%'.",
        "  CONCATENATE 'CANDIDATE' lv_name",
        "    INTO lv_line SEPARATED BY '|'.",
        "  WRITE / lv_line.",
        "ENDSELECT.",
        "APPEND 'RS_CUA_INTERNAL_FETCH' TO lt_names.",
        "APPEND 'RS_CUA_INTERNAL_WRITE' TO lt_names.",
        "APPEND 'RS_CUA_INSERT' TO lt_names.",
        "APPEND 'RS_CUA_DELETE' TO lt_names.",
        "APPEND 'RS_CUA_COPY' TO lt_names.",
        "APPEND 'RPY_PROGRAM_READ' TO lt_names.",
        "APPEND 'RPY_PROGRAM_UPDATE' TO lt_names.",
        "APPEND 'RPY_PROGRAM_INSERT' TO lt_names.",
        "LOOP AT lt_names INTO lv_name.",
        "  CLEAR lv_existing_name.",
        "  SELECT SINGLE funcname FROM tfdir INTO lv_existing_name",
        "    WHERE funcname = lv_name.",
        "  IF sy-subrc <> 0.",
        "    CONCATENATE 'FUNCTION_MISSING' lv_name",
        "      INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "    CONTINUE.",
        "  ENDIF.",
        "  REFRESH: lt_import, lt_export, lt_change, lt_tables,",
        "    lt_except, lt_docu, lt_source.",
        "  CLEAR lv_remote.",
        "  CALL FUNCTION 'RPY_FUNCTIONMODULE_READ_NEW'",
        "    EXPORTING functionname = lv_name",
        "    IMPORTING remote_call = lv_remote",
        "    TABLES import_parameter = lt_import",
        "      changing_parameter = lt_change",
        "      export_parameter = lt_export",
        "      tables_parameter = lt_tables",
        "      exception_list = lt_except",
        "      documentation = lt_docu",
        "      source = lt_source.",
        "  CONCATENATE 'FUNCTION' lv_name lv_remote",
        "    INTO lv_line SEPARATED BY '|'.",
        "  WRITE / lv_line.",
        "  LOOP AT lt_import INTO ls_import.",
        "    CONCATENATE 'I' ls_import-parameter ls_import-dbfield",
        "      ls_import-types ls_import-optional ls_import-reference",
        "      INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "  ENDLOOP.",
        "  LOOP AT lt_export INTO ls_export.",
        "    CONCATENATE 'E' ls_export-parameter ls_export-dbfield",
        "      ls_export-types ls_export-reference",
        "      INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "  ENDLOOP.",
        "  LOOP AT lt_change INTO ls_change.",
        "    CONCATENATE 'C' ls_change-parameter ls_change-dbfield",
        "      INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "  ENDLOOP.",
        "  LOOP AT lt_tables INTO ls_tables.",
        "    CONCATENATE 'T' ls_tables-parameter ls_tables-dbstruct",
        "      INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "  ENDLOOP.",
        "  LOOP AT lt_except INTO ls_except.",
        "    CONCATENATE 'X' ls_except-exception",
        "      INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "  ENDLOOP.",
        "ENDLOOP.",
        "APPEND 'TRKEY' TO lt_type_names.",
        "APPEND 'RSMPE_ADM' TO lt_type_names.",
        "APPEND 'RSMPE_STAT' TO lt_type_names.",
        "APPEND 'RSMPE_FUNT' TO lt_type_names.",
        "APPEND 'RSMPE_MEN' TO lt_type_names.",
        "APPEND 'RSMPE_MNLT' TO lt_type_names.",
        "APPEND 'RSMPE_ACT' TO lt_type_names.",
        "APPEND 'RSMPE_BUT' TO lt_type_names.",
        "APPEND 'RSMPE_PFK' TO lt_type_names.",
        "APPEND 'RSMPE_STAF' TO lt_type_names.",
        "APPEND 'RSMPE_ATRT' TO lt_type_names.",
        "APPEND 'RSMPE_TITT' TO lt_type_names.",
        "APPEND 'RSMPE_BUTS' TO lt_type_names.",
        "LOOP AT lt_type_names INTO lv_type_name.",
        "  CLEAR lv_existing_type.",
        "  SELECT SINGLE tabname FROM dd02l INTO lv_existing_type",
        "    WHERE tabname = lv_type_name",
        "      AND as4local = 'A' AND as4vers = '0000'.",
        "  IF sy-subrc <> 0.",
        "    CONCATENATE 'TYPE_MISSING' lv_type_name",
        "      INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "    CONTINUE.",
        "  ENDIF.",
        "  REFRESH lt_dfies.",
        "  CALL FUNCTION 'DDIF_FIELDINFO_GET'",
        "    EXPORTING tabname = lv_existing_type langu = sy-langu",
        "    TABLES dfies_tab = lt_dfies",
        "    EXCEPTIONS not_found = 1 internal_error = 2 OTHERS = 3.",
        "  IF sy-subrc <> 0.",
        "    WRITE sy-subrc TO lv_subrc_text.",
        "    CONDENSE lv_subrc_text NO-GAPS.",
        "    CONCATENATE 'FIELDINFO_ERROR' lv_type_name lv_subrc_text",
        "      INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "    CONTINUE.",
        "  ENDIF.",
        "  CONCATENATE 'STRUCT' lv_type_name",
        "    INTO lv_line SEPARATED BY '|'.",
        "  WRITE / lv_line.",
        "  LOOP AT lt_dfies INTO ls_dfies.",
        "    CONCATENATE 'FIELD' lv_type_name ls_dfies-fieldname",
        "      ls_dfies-rollname ls_dfies-inttype ls_dfies-leng",
        "      INTO lv_line SEPARATED BY '|'.",
        "    WRITE / lv_line.",
        "  ENDLOOP.",
        "ENDLOOP."
    )
}

function New-GuiObjectInspectionProgram {
    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "NEW-PAGE NO-TITLE LINE-COUNT 0 LINE-SIZE 255.",
        "DATA ls_adm TYPE rsmpe_adm.",
        "DATA lt_sta TYPE TABLE OF rsmpe_stat.",
        "DATA lt_fun TYPE TABLE OF rsmpe_funt.",
        "DATA lt_men TYPE TABLE OF rsmpe_men.",
        "DATA lt_mtx TYPE TABLE OF rsmpe_mnlt.",
        "DATA lt_act TYPE TABLE OF rsmpe_act.",
        "DATA lt_but TYPE TABLE OF rsmpe_but.",
        "DATA lt_pfk TYPE TABLE OF rsmpe_pfk.",
        "DATA lt_set TYPE TABLE OF rsmpe_staf.",
        "DATA lt_doc TYPE TABLE OF rsmpe_atrt.",
        "DATA lt_tit TYPE TABLE OF rsmpe_titt.",
        "DATA lt_biv TYPE TABLE OF rsmpe_buts.",
        "DATA ls_sta TYPE rsmpe_stat.",
        "DATA ls_fun TYPE rsmpe_funt.",
        "DATA ls_men TYPE rsmpe_men.",
        "DATA ls_mtx TYPE rsmpe_mnlt.",
        "DATA ls_act TYPE rsmpe_act.",
        "DATA ls_but TYPE rsmpe_but.",
        "DATA ls_pfk TYPE rsmpe_pfk.",
        "DATA ls_set TYPE rsmpe_staf.",
        "DATA ls_tit TYPE rsmpe_titt.",
        "DATA ls_biv TYPE rsmpe_buts.",
        "DATA ls_tadir TYPE tadir.",
        "DATA ls_trdir TYPE trdir.",
        "DATA ls_tfdir TYPE tfdir.",
        "DATA lt_code TYPE TABLE OF abaptxt255.",
        "DATA ls_code TYPE abaptxt255.",
        "DATA lv_group TYPE rs38l-area.",
        "DATA lv_include TYPE sy-repid.",
        "DATA lv_lines TYPE i.",
        "DATA lv_langu TYPE eudb-langu.",
        "DATA lv_author TYPE eudb-autor.",
        "DATA lv_subrc_text TYPE c LENGTH 10.",
        "SELECT SINGLE * FROM tadir INTO ls_tadir",
        "  WHERE pgmid = 'R3TR' AND object = 'PROG'",
        "    AND obj_name = '$GuiProgramName'.",
        "WRITE: / 'TADIR', sy-subrc, ls_tadir-devclass,",
        "  ls_tadir-srcsystem, ls_tadir-genflag.",
        "SELECT SINGLE * FROM trdir INTO ls_trdir",
        "  WHERE name = '$GuiProgramName'.",
        "WRITE: / 'TRDIR', sy-subrc, ls_trdir-subc,",
        "  ls_trdir-rstat, ls_trdir-appl.",
        "READ REPORT '$GuiProgramName' INTO lt_code STATE 'A'.",
        "DESCRIBE TABLE lt_code LINES lv_lines.",
        "WRITE: / 'SOURCE_ACTIVE', sy-subrc, lv_lines.",
        "REFRESH lt_code.",
        "READ REPORT '$GuiProgramName' INTO lt_code STATE 'I'.",
        "DESCRIBE TABLE lt_code LINES lv_lines.",
        "WRITE: / 'SOURCE_INACTIVE', sy-subrc, lv_lines.",
        "CALL FUNCTION 'RS_CUA_INTERNAL_FETCH'",
        "  EXPORTING program = '$GuiProgramName'",
        "    language = sy-langu state = 'A'",
        "  IMPORTING adm = ls_adm langu = lv_langu author = lv_author",
        "  TABLES sta = lt_sta fun = lt_fun men = lt_men",
        "    mtx = lt_mtx act = lt_act but = lt_but pfk = lt_pfk",
        "    set = lt_set doc = lt_doc tit = lt_tit biv = lt_biv",
        "  EXCEPTIONS OTHERS = 1.",
        "WRITE sy-subrc TO lv_subrc_text.",
        "CONDENSE lv_subrc_text NO-GAPS.",
        "WRITE: / 'FETCH', lv_subrc_text, '$GuiProgramName',",
        "  lv_langu, lv_author.",
        "WRITE: / 'ADM', ls_adm-actcode, ls_adm-mencode,",
        "  ls_adm-pfkcode, ls_adm-defaultact, ls_adm-defaultpfk,",
        "  ls_adm-mod_langu.",
        "LOOP AT lt_sta INTO ls_sta.",
        "  WRITE: / 'STA', ls_sta-code, ls_sta-modal,",
        "    ls_sta-actcode, ls_sta-pfkcode, ls_sta-butcode,",
        "    ls_sta-int_note, ls_sta-ctxcode.",
        "ENDLOOP.",
        "LOOP AT lt_fun INTO ls_fun.",
        "  WRITE: / 'FUN', ls_fun-code, ls_fun-textno,",
        "    ls_fun-type, ls_fun-modif, ls_fun-text_type,",
        "    ls_fun-text_name, ls_fun-icon_id, ls_fun-fun_text,",
        "    ls_fun-icon_text, ls_fun-info_text, ls_fun-path.",
        "ENDLOOP.",
        "LOOP AT lt_men INTO ls_men.",
        "  WRITE: / 'MEN', ls_men-code, ls_men-no,",
        "    ls_men-ref_type, ls_men-ref_code, ls_men-ref_no.",
        "ENDLOOP.",
        "LOOP AT lt_mtx INTO ls_mtx.",
        "  WRITE: / 'MTX', ls_mtx-code, ls_mtx-text_type,",
        "    ls_mtx-text_name, ls_mtx-inc_prog,",
        "    ls_mtx-inc_status, ls_mtx-text, ls_mtx-path,",
        "    ls_mtx-int_note.",
        "ENDLOOP.",
        "LOOP AT lt_act INTO ls_act.",
        "  WRITE: / 'ACT', ls_act-code, ls_act-no,",
        "    ls_act-menucode.",
        "ENDLOOP.",
        "LOOP AT lt_but INTO ls_but.",
        "  WRITE: / 'BUT', ls_but-pfk_code, ls_but-code,",
        "    ls_but-no, ls_but-pfno.",
        "ENDLOOP.",
        "LOOP AT lt_pfk INTO ls_pfk.",
        "  WRITE: / 'PFK', ls_pfk-code, ls_pfk-pfno,",
        "    ls_pfk-funcode, ls_pfk-funno.",
        "ENDLOOP.",
        "LOOP AT lt_set INTO ls_set.",
        "  WRITE: / 'SET', ls_set-status, ls_set-function.",
        "ENDLOOP.",
        "LOOP AT lt_tit INTO ls_tit.",
        "  WRITE: / 'TIT', ls_tit-code, ls_tit-text.",
        "ENDLOOP.",
        "LOOP AT lt_biv INTO ls_biv.",
        "  WRITE: / 'BIV', ls_biv-obj_code, ls_biv-sub_code,",
        "    ls_biv-fcode.",
        "ENDLOOP.",
        "SELECT SINGLE * FROM tfdir INTO ls_tfdir",
        "  WHERE funcname = 'RS_DELETE_PROGRAM'.",
        "lv_group = ls_tfdir-pname+4.",
        "CONCATENATE 'L' lv_group 'U' ls_tfdir-include",
        "  INTO lv_include.",
        "REFRESH lt_code.",
        "READ REPORT lv_include INTO lt_code.",
        "DESCRIBE TABLE lt_code LINES lv_lines.",
        "WRITE: / 'DELETE_SOURCE', sy-subrc, lv_include, lv_lines.",
        "LOOP AT lt_code INTO ls_code.",
        "  WRITE: / 'RSDP', sy-tabix, ls_code-line.",
        "ENDLOOP."
    )
}

function New-DdicApiInspectionProgram {
    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "TYPE-POOLS abap.",
        "NEW-PAGE NO-TITLE LINE-COUNT 0 LINE-SIZE 255.",
        "DATA lo_descr TYPE REF TO cl_abap_structdescr.",
        "DATA lt_components TYPE abap_component_tab.",
        "DATA ls_component TYPE abap_componentdescr.",
        "DATA lt_names TYPE TABLE OF string.",
        "DATA lv_name TYPE string.",
        "DATA lv_type_kind TYPE c LENGTH 1.",
        "DATA lv_length TYPE i.",
        "DATA lv_decimals TYPE i.",
        "DATA ls_dd01v TYPE dd01v.",
        "DATA lt_dd07v TYPE TABLE OF dd07v.",
        "DATA ls_dd04v TYPE dd04v.",
        "DATA ls_dd02v TYPE dd02v.",
        "DATA ls_dd09v TYPE dd09v.",
        "DATA lt_dd03p TYPE TABLE OF dd03p.",
        "DATA ls_dd40v TYPE dd40v.",
        "DATA lt_dd42v TYPE TABLE OF dd42v.",
        "DATA lt_dd43v TYPE TABLE OF dd43v.",
        "DATA lv_gotstate TYPE ddgotstate.",
        "FIELD-SYMBOLS <ls_any> TYPE any.",
        "APPEND 'DD01V' TO lt_names.",
        "APPEND 'DD07V' TO lt_names.",
        "APPEND 'DD04V' TO lt_names.",
        "APPEND 'DD02V' TO lt_names.",
        "APPEND 'DD03P' TO lt_names.",
        "APPEND 'DD40V' TO lt_names.",
        "APPEND 'DD42V' TO lt_names.",
        "APPEND 'DD43V' TO lt_names.",
        "LOOP AT lt_names INTO lv_name.",
        "  lo_descr ?= cl_abap_typedescr=>describe_by_name( lv_name ).",
        "  lt_components = lo_descr->get_components( ).",
        "  WRITE: / 'STRUCT', lv_name.",
        "  LOOP AT lt_components INTO ls_component.",
        "    lv_type_kind = ls_component-type->type_kind.",
        "    lv_length = ls_component-type->length.",
        "    lv_decimals = ls_component-type->decimals.",
        "    WRITE: / ls_component-name, lv_type_kind,",
        "      lv_length, lv_decimals.",
        "  ENDLOOP.",
        "ENDLOOP.",
        "CALL FUNCTION 'DDIF_DOMA_GET'",
        "  EXPORTING name = 'BOOLE_D' state = 'A' langu = sy-langu",
        "  IMPORTING gotstate = lv_gotstate dd01v_wa = ls_dd01v",
        "  TABLES dd07v_tab = lt_dd07v",
        "  EXCEPTIONS OTHERS = 1.",
        "WRITE: / 'SAMPLE DOMA', sy-subrc, lv_gotstate.",
        "PERFORM dump_structure USING 'DD01V' ls_dd01v.",
        "LOOP AT lt_dd07v ASSIGNING <ls_any>.",
        "  PERFORM dump_structure USING 'DD07V' <ls_any>.",
        "  IF sy-tabix >= 2. EXIT. ENDIF.",
        "ENDLOOP.",
        "CALL FUNCTION 'DDIF_DTEL_GET'",
        "  EXPORTING name = 'BAPI_MSG' state = 'A' langu = sy-langu",
        "  IMPORTING gotstate = lv_gotstate dd04v_wa = ls_dd04v",
        "  EXCEPTIONS OTHERS = 1.",
        "WRITE: / 'SAMPLE DTEL', sy-subrc, lv_gotstate.",
        "PERFORM dump_structure USING 'DD04V' ls_dd04v.",
        "CALL FUNCTION 'DDIF_TABL_GET'",
        "  EXPORTING name = 'BAPIRET2' state = 'A' langu = sy-langu",
        "  IMPORTING gotstate = lv_gotstate dd02v_wa = ls_dd02v",
        "    dd09l_wa = ls_dd09v",
        "  TABLES dd03p_tab = lt_dd03p",
        "  EXCEPTIONS OTHERS = 1.",
        "WRITE: / 'SAMPLE TABL', sy-subrc, lv_gotstate.",
        "PERFORM dump_structure USING 'DD02V' ls_dd02v.",
        "LOOP AT lt_dd03p ASSIGNING <ls_any>.",
        "  PERFORM dump_structure USING 'DD03P' <ls_any>.",
        "  IF sy-tabix >= 2. EXIT. ENDIF.",
        "ENDLOOP.",
        "CALL FUNCTION 'DDIF_TTYP_GET'",
        "  EXPORTING name = 'BAPIRET2_T' state = 'A' langu = sy-langu",
        "  IMPORTING gotstate = lv_gotstate dd40v_wa = ls_dd40v",
        "  TABLES dd42v_tab = lt_dd42v dd43v_tab = lt_dd43v",
        "  EXCEPTIONS OTHERS = 1.",
        "WRITE: / 'SAMPLE TTYP', sy-subrc, lv_gotstate.",
        "PERFORM dump_structure USING 'DD40V' ls_dd40v.",
        "LOOP AT lt_dd42v ASSIGNING <ls_any>.",
        "  PERFORM dump_structure USING 'DD42V' <ls_any>.",
        "  IF sy-tabix >= 2. EXIT. ENDIF.",
        "ENDLOOP.",
        "LOOP AT lt_dd43v ASSIGNING <ls_any>.",
        "  PERFORM dump_structure USING 'DD43V' <ls_any>.",
        "  IF sy-tabix >= 2. EXIT. ENDIF.",
        "ENDLOOP.",
        "FORM dump_structure USING iv_label TYPE string",
        "  is_data TYPE any.",
        "  DATA lo_local TYPE REF TO cl_abap_structdescr.",
        "  DATA lt_local TYPE abap_component_tab.",
        "  DATA ls_local TYPE abap_componentdescr.",
        "  FIELD-SYMBOLS <lv_value> TYPE any.",
        "  lo_local ?= cl_abap_typedescr=>describe_by_data( is_data ).",
        "  lt_local = lo_local->get_components( ).",
        "  WRITE: / 'ROW', iv_label.",
        "  LOOP AT lt_local INTO ls_local.",
        "    ASSIGN COMPONENT ls_local-name OF STRUCTURE is_data",
        "      TO <lv_value>.",
        "    IF sy-subrc = 0 AND <lv_value> IS NOT INITIAL.",
        "      WRITE: / ls_local-name, <lv_value>.",
        "    ENDIF.",
        "  ENDLOOP.",
        "ENDFORM."
    )
}

function New-DdicObjectDiagnosticProgram {
    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "NEW-PAGE NO-TITLE LINE-COUNT 0 LINE-SIZE 255.",
        "DATA lt_check TYPE TABLE OF dcinspchk.",
        "DATA ls_check TYPE dcinspchk.",
        "DATA ls_dd02v TYPE dd02v.",
        "DATA ls_dd09v TYPE dd09v.",
        "DATA lt_dd03p TYPE TABLE OF dd03p.",
        "DATA ls_dd03p TYPE dd03p.",
        "DATA lv_gotstate TYPE ddgotstate.",
        "CALL FUNCTION 'DDIF_DD_CHECK'",
        "  EXPORTING objname = '$DdicObjectName'",
        "    objtype = '$DdicObjectType'",
        "  TABLES checktab = lt_check.",
        "LOOP AT lt_check INTO ls_check.",
        "  WRITE: / ls_check-kennz, ls_check-subrc,",
        "    ls_check-msgty, ls_check-msgid, ls_check-msgno,",
        "    ls_check-text.",
        "ENDLOOP.",
        "IF '$DdicObjectType' = 'TABL'.",
        "  CALL FUNCTION 'DDIF_TABL_GET'",
        "    EXPORTING name = '$DdicObjectName' state = 'M'",
        "      langu = sy-langu",
        "    IMPORTING gotstate = lv_gotstate dd02v_wa = ls_dd02v",
        "      dd09l_wa = ls_dd09v",
        "    TABLES dd03p_tab = lt_dd03p",
        "    EXCEPTIONS OTHERS = 1.",
        "  WRITE: / 'TABL', sy-subrc, lv_gotstate,",
        "    ls_dd02v-tabname, ls_dd02v-tabclass,",
        "    ls_dd02v-contflag, ls_dd02v-mainflag.",
        "  WRITE: / 'TECH', ls_dd09v-tabname, ls_dd09v-tabkat,",
        "    ls_dd09v-tabart, ls_dd09v-bufallow,",
        "    ls_dd09v-pufferung.",
        "  LOOP AT lt_dd03p INTO ls_dd03p.",
        "    WRITE: / 'FIELD', ls_dd03p-position,",
        "      ls_dd03p-fieldname, ls_dd03p-rollname,",
        "      ls_dd03p-keyflag, ls_dd03p-notnull,",
        "      ls_dd03p-comptype, ls_dd03p-datatype,",
        "      ls_dd03p-leng, ls_dd03p-decimals.",
        "  ENDLOOP.",
        "ENDIF."
    )
}

function New-DdicFunctionSource {
    # Self-description branch, same payload protocol as the repository helper. Only the
    # helper name and the version table differ. The four placeholders must stay
    # byte-identical to the repository block: New-InstallProgram detects them with the
    # same literals and substitutes the SHA-256 of this body into them.
    # >>> ORVANTA-DDIC-CAPABILITIES-SOURCE
    $ddicCapabilityHashSlots = @(
        "ORVANTAHASHSLOT1",
        "ORVANTAHASHSLOT2",
        "ORVANTAHASHSLOT3",
        "ORVANTAHASHSLOT4"
    )
    $ddicCapabilityPackageValue = ([string]$PackageName).Replace("%", "%25").Replace("|", "%7C")
    $ddicCapabilityTransportValue = (
        @([string]$TransportNumber, [string]$TransportTask) | ForEach-Object {
            $_.Replace("%", "%25").Replace("|", "%7C")
        }
    ) -join "|"
    $ddicCapabilityBranchLines = @(
        "    WHEN 'CAPABILITIES'.",
        "      CLEAR ls_source.",
        "      ls_source-line = 'HELPER|Z_ORVANTA_MCP_DDIC_API'.",
        "      APPEND ls_source TO it_source.",
        "      ls_source-line = 'PROTOCOL|MIN|$ddicCapabilityMinVersion'.",
        "      APPEND ls_source TO it_source.",
        "      ls_source-line = 'PROTOCOL|MAX|$ddicCapabilityMaxVersion'.",
        "      APPEND ls_source TO it_source."
    )
    foreach ($ddicCapabilityOperation in $ddicCapabilityOperations) {
        $ddicCapabilityParts = $ddicCapabilityOperation -split "\|"
        # 行宽（R-16 遗留）：真实运行时 $ddicCapabilityMaxVersion 为 4 字符版本串（当时 "1.10"，R-20 改名后
        # 由表里的 |1.11| 行派生为 "1.11"，宽度不变），长操作码会把单行推到 74 列，
        # 触发 New-InstallProgram 的 72 列守卫，使 DDIC 安装程序无法生成。拆成两行、把分隔符并入字面量后，
        # 生成的行内容与原 "SEPARATED BY '|'" 版本逐字节相同（OPERATION|<op>|<ver>|<access>），最长行仅 66 列。
        # 操作码长度上限：Z_ORVANTA_MCP_DDIC_API 的 IV_OPERATION 为 BAPIRET2-PARAMETER（CHAR 32），
        # 超过 32 字符的操作码会被 RFC 层截断而永远匹配不到 CASE 分支（0.46.14 的 resume 事故即此因）。
        $ddicCapabilityBranchLines += @(
            "      CONCATENATE 'OPERATION|$($ddicCapabilityParts[0])'",
            "        '|$($ddicCapabilityParts[1])|$($ddicCapabilityParts[2])'",
            "        INTO ls_source-line.",
            "      APPEND ls_source TO it_source."
        )
    }
    foreach ($ddicCapabilityScope in $ddicCapabilityScopes) {
        $ddicCapabilityBranchLines += @(
            "      ls_source-line = 'SCOPE|$ddicCapabilityScope'.",
            "      APPEND ls_source TO it_source."
        )
    }
    $ddicCapabilityBranchLines += @(
        "      CLEAR ls_source.",
        "      CONCATENATE 'SOURCE|HASH|' '$($ddicCapabilityHashSlots[0])' '$($ddicCapabilityHashSlots[1])'",
        "        '$($ddicCapabilityHashSlots[2])' '$($ddicCapabilityHashSlots[3])' INTO ls_source-line.",
        "      APPEND ls_source TO it_source.",
        "      ls_source-line = 'SOURCE|PACKAGE|$ddicCapabilityPackageValue'.",
        "      APPEND ls_source TO it_source.",
        "      ls_source-line = 'SOURCE|TRANSPORT|$ddicCapabilityTransportValue'.",
        "      APPEND ls_source TO it_source.",
        "      CONCATENATE sy-sysid sy-mandt INTO lv_payload_value",
        "        SEPARATED BY '/'.",
        "      REPLACE ALL OCCURRENCES OF '%' IN lv_payload_value WITH '%25'.",
        "      REPLACE ALL OCCURRENCES OF '|' IN lv_payload_value WITH '%7C'.",
        "      CONCATENATE 'RUNTIME|HOST' lv_payload_value INTO ls_source-line",
        "        SEPARATED BY '|'.",
        "      APPEND ls_source TO it_source.",
        "      CONCATENATE sy-datum sy-uzeit INTO lv_payload_value.",
        "      REPLACE ALL OCCURRENCES OF '%' IN lv_payload_value WITH '%25'.",
        "      REPLACE ALL OCCURRENCES OF '|' IN lv_payload_value WITH '%7C'.",
        "      lv_payload_index_text = sy-tzone.",
        "      CONDENSE lv_payload_index_text NO-GAPS.",
        "      CONCATENATE 'RUNTIME|TIME' lv_payload_value lv_payload_index_text",
        "        INTO ls_source-line SEPARATED BY '|'.",
        "      APPEND ls_source TO it_source.",
        "      ev_status = 'S'.",
        "      ev_code = 'CAPABILITIES'.",
        "      ev_version = '$ddicCapabilityMaxVersion'.",
        "      ev_message = 'ORVANTA helper capabilities'.",
        "      RETURN."
    )
    # <<< ORVANTA-DDIC-CAPABILITIES-SOURCE
    # D6-3 编号范围对象：TNRO/TNROT 的定义摘要（SHA1，大写十六进制）。
    # NROB 在 TADIR 中没有 AS4DATE/AS4TIME，无法像其他 DDIC 对象那样用"最后修改时间戳"做并发令牌，
    # 因此这里对 TNRO 整行 + 全部 TNROT 行按字段固定顺序做规范化拼接后取 SHA1。该值不是 DDIC 时间戳，
    # 服务层必须按"NROB 定义摘要"解释它（40 位 [0-9A-F]），不能套用 14 位时间戳校验。
    # 输入：ls_nrob_current（当前/落库后的 TNRO 行）与 lt_nrob_texts（全部 TNROT 行，需已 SORT BY langu）。
    # 输出：lv_nrob_version。
    $ddicNrobDigestLines = @(
        "      CLEAR lv_nrob_canonical.",
        "      CONCATENATE ls_nrob_current-object ls_nrob_current-dtelsobj",
        "        ls_nrob_current-nrtab ls_nrob_current-nrintfld",
        "        INTO lv_nrob_canonical SEPARATED BY '|'.",
        "      CONCATENATE lv_nrob_canonical ls_nrob_current-nrextfld",
        "        ls_nrob_current-nrfld ls_nrob_current-nrsobjfld",
        "        ls_nrob_current-nrelefld",
        "        INTO lv_nrob_canonical SEPARATED BY '|'.",
        "      lv_nrob_percentage_i = ls_nrob_current-percentage * 10.",
        "      lv_nrob_percentage = lv_nrob_percentage_i.",
        "      CONCATENATE lv_nrob_canonical ls_nrob_current-yearind",
        "        ls_nrob_current-domlen lv_nrob_percentage",
        "        ls_nrob_current-code",
        "        INTO lv_nrob_canonical SEPARATED BY '|'.",
        "      CONCATENATE lv_nrob_canonical ls_nrob_current-textind",
        "        ls_nrob_current-nreltxttab ls_nrob_current-nreltxtsob",
        "        ls_nrob_current-nreltxtele",
        "        INTO lv_nrob_canonical SEPARATED BY '|'.",
        "      CONCATENATE lv_nrob_canonical ls_nrob_current-nreltxttxt",
        "        ls_nrob_current-nreltxtlng ls_nrob_current-buffer",
        "        ls_nrob_current-noivbuffer",
        "        INTO lv_nrob_canonical SEPARATED BY '|'.",
        "      CONCATENATE lv_nrob_canonical ls_nrob_current-nonrswap",
        "        ls_nrob_current-rfcdest ls_nrob_current-nrcheckascii",
        "        INTO lv_nrob_canonical SEPARATED BY '|'.",
        "      LOOP AT lt_nrob_texts INTO ls_nrob_text.",
        "        CLEAR lv_nrob_value.",
        "        CONCATENATE ls_nrob_text-langu ls_nrob_text-txt",
        "          ls_nrob_text-txtshort INTO lv_nrob_value",
        "          SEPARATED BY '|'.",
        "        REPLACE ALL OCCURRENCES OF '%' IN lv_nrob_value",
        "          WITH '%25'.",
        "        REPLACE ALL OCCURRENCES OF '|' IN lv_nrob_value",
        "          WITH '%7C'.",
        "        CONCATENATE lv_nrob_canonical lv_nrob_value",
        "          INTO lv_nrob_canonical SEPARATED BY '|'.",
        "      ENDLOOP.",
        # CALL METHOD 的 RECEIVING 只接 RETURNING 参数。CL_ABAP_MESSAGE_DIGEST 里
        # CALCULATE_HASH_FOR_CHAR 声明的是 `exporting !EF_HASHSTRING type STRING`（已按 w200 类源码核对），
        # 所以必须用 IMPORTING 接收，否则 7.31 的 GENERATE 直接失败：
        #   形式参数 "EF_HASHSTRING" 不是 RETURNING 参数；而是 EXPORTING 参数
        # （2026-09-22 第二次 F8 事故，body line 586）。一处改动覆盖 4 个 digest arm。
        "      CALL METHOD cl_abap_message_digest=>calculate_hash_for_char",
        "        EXPORTING if_algorithm = 'SHA1'",
        "          if_data = lv_nrob_canonical",
        "        IMPORTING ef_hashstring = lv_nrob_digest",
        "        EXCEPTIONS others = 1.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'NUMBER_RANGE_VERSION_FAILED'.",
        "        ev_message = 'Number range definition digest failed'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        # EF_HASHSTRING 是 STRING 且按**引用**传递（passByValue=false）。引用参数要求实参与形参
        # **类型相容**、不做转换，而 lv_nrob_version 是 CHAR 40，会被 7.31 判为类型不相容：
        #   "LV_NROB_VERSION" 与形式参数 "EF_HASHSTRING" 类型不兼容
        # （2026-09-22 第三次 F8 事故，body line 586）。摘要先落 string 变量，再用赋值转换搬进版本号。
        "      lv_nrob_version = lv_nrob_digest.",
        "      TRANSLATE lv_nrob_version TO UPPER CASE."
    )
    # D6-3 响应中的 TNRO 属性行（H 行）。属性名 = TNRO 字段名，顺序 = 字段顺序，便于服务层按名取值。
    $ddicNrobHeaderPayloadLines = @(
        "      add_payload 'H' '1' 'OBJECT' ls_nrob_current-object.",
        "      add_payload 'H' '1' 'DTELSOBJ' ls_nrob_current-dtelsobj.",
        "      add_payload 'H' '1' 'NRTAB' ls_nrob_current-nrtab.",
        "      add_payload 'H' '1' 'NRINTFLD' ls_nrob_current-nrintfld.",
        "      add_payload 'H' '1' 'NREXTFLD' ls_nrob_current-nrextfld.",
        "      add_payload 'H' '1' 'NRFLD' ls_nrob_current-nrfld.",
        "      add_payload 'H' '1' 'NRSOBJFLD' ls_nrob_current-nrsobjfld.",
        "      add_payload 'H' '1' 'NRELEFLD' ls_nrob_current-nrelefld.",
        "      add_payload 'H' '1' 'YEARIND' ls_nrob_current-yearind.",
        "      add_payload 'H' '1' 'DOMLEN' ls_nrob_current-domlen.",
        "      add_payload 'H' '1' 'PERCENTAGE' ls_nrob_current-percentage.",
        "      add_payload 'H' '1' 'CODE' ls_nrob_current-code.",
        "      add_payload 'H' '1' 'TEXTIND' ls_nrob_current-textind.",
        "      add_payload 'H' '1' 'NRELTXTTAB' ls_nrob_current-nreltxttab.",
        "      add_payload 'H' '1' 'NRELTXTSOB' ls_nrob_current-nreltxtsob.",
        "      add_payload 'H' '1' 'NRELTXTELE' ls_nrob_current-nreltxtele.",
        "      add_payload 'H' '1' 'NRELTXTTXT' ls_nrob_current-nreltxttxt.",
        "      add_payload 'H' '1' 'NRELTXTLNG' ls_nrob_current-nreltxtlng.",
        "      add_payload 'H' '1' 'BUFFER' ls_nrob_current-buffer.",
        "      add_payload 'H' '1' 'NOIVBUFFER' ls_nrob_current-noivbuffer.",
        "      add_payload 'H' '1' 'NONRSWAP' ls_nrob_current-nonrswap.",
        "      add_payload 'H' '1' 'RFCDEST' ls_nrob_current-rfcdest.",
        "      add_payload 'H' '1' 'NRCHECKASCII' ls_nrob_current-nrcheckascii."
    )
    # D6-3 响应中的 TNROT 文本行（N1 行）与 check_object 警告行（W 行，字段取自 INOER）。
    $ddicNrobTextPayloadLines = @(
        "      LOOP AT lt_nrob_texts INTO ls_nrob_text.",
        "        lv_nrob_index = sy-tabix.",
        "        add_payload 'N1' lv_nrob_index 'LANGU' ls_nrob_text-langu.",
        "        add_payload 'N1' lv_nrob_index 'TXT' ls_nrob_text-txt.",
        "        add_payload 'N1' lv_nrob_index 'TXTSHORT'",
        "          ls_nrob_text-txtshort.",
        "      ENDLOOP."
    )
    $ddicNrobWarningPayloadLines = @(
        "      IF lt_nrob_warnings IS NOT INITIAL.",
        "        CLEAR lv_nrob_index.",
        "        LOOP AT lt_nrob_warnings INTO ls_nrob_error.",
        "          lv_nrob_index = lv_nrob_index + 1.",
        "          add_payload 'W' lv_nrob_index 'FIELDNAME'",
        "            ls_nrob_error-fieldname.",
        "          add_payload 'W' lv_nrob_index 'MSGID'",
        "            ls_nrob_error-msgid.",
        "          add_payload 'W' lv_nrob_index 'MSGNO'",
        "            ls_nrob_error-msgnumber.",
        "          add_payload 'W' lv_nrob_index 'MSGTYPE'",
        "            ls_nrob_error-msgtype.",
        "          add_payload 'W' lv_nrob_index 'MSGVAR1'",
        "            ls_nrob_error-msgvar1.",
        "          add_payload 'W' lv_nrob_index 'CRITCHANGE'",
        "            ls_nrob_error-critchange.",
        "        ENDLOOP.",
        "        add_payload 'M' '1' 'WARNING_COUNT' lv_nrob_index.",
        "      ENDIF."
    )
    # D6-4 维护视图响应中的 DD25V 头行（H 行）。属性名 = DD25V 字段名，顺序 = 字段顺序；
    # 读分支与写分支的回读共用这一段，两者都先把要报告的那一版放进 ls_mv_header。
    $ddicMvHeaderPayloadLines = @(
        "      add_payload 'H' '1' 'VIEWNAME' ls_mv_header-viewname.",
        "      add_payload 'H' '1' 'DDLANGUAGE' ls_mv_header-ddlanguage.",
        "      add_payload 'H' '1' 'MASTERLANG' ls_mv_header-masterlang.",
        # DD25V 的文本组件名是 DDTEXT（不是 DDTTEXT）。第七次 F8：body line 1524
        # “数据对象 LS_MV_HEADER 没有组件 DDTTEXT，但具有组件 DDTEXT”。本数组同时被
        # READ_MAINTENANCE_VIEW 与 UPSERT_MAINTENANCE_VIEW 的返回构造复用，因此一处拼错会在正文出现两次。
        "      add_payload 'H' '1' 'DDTEXT' ls_mv_header-ddtext.",
        "      add_payload 'H' '1' 'VIEWCLASS' ls_mv_header-viewclass.",
        "      add_payload 'H' '1' 'AGGTYPE' ls_mv_header-aggtype.",
        "      add_payload 'H' '1' 'ROOTTAB' ls_mv_header-roottab.",
        "      add_payload 'H' '1' 'VIEWGRANT' ls_mv_header-viewgrant.",
        "      add_payload 'H' '1' 'CUSTOMAUTH' ls_mv_header-customauth.",
        "      add_payload 'H' '1' 'GLOBALFLAG' ls_mv_header-globalflag.",
        "      add_payload 'H' '1' 'READONLY' ls_mv_header-readonly.",
        "      add_payload 'H' '1' 'MANKEY' ls_mv_header-mankey.",
        "      add_payload 'H' '1' 'APPLCLASS' ls_mv_header-applclass.",
        "      add_payload 'H' '1' 'AUTHCLASS' ls_mv_header-authclass.",
        "      add_payload 'H' '1' 'AS4LOCAL' ls_mv_header-as4local.",
        "      add_payload 'H' '1' 'AS4VERS' ls_mv_header-as4vers.",
        "      add_payload 'H' '1' 'AS4DATE' ls_mv_header-as4date.",
        "      add_payload 'H' '1' 'AS4TIME' ls_mv_header-as4time.",
        "      add_payload 'H' '1' 'AS4USER' ls_mv_header-as4user.",
        "      add_payload 'H' '1' 'ACTFLAG' ls_mv_header-actflag."
    )
    # D6-4 T1 行 = DD26V（基本表）全字段。索引取行序 1..n（TABPOS 由助手按同一次序写入）。
    $ddicMvBaseTabPayloadLines = @(
        "      CLEAR lv_mv_index.",
        "      LOOP AT lt_mv_basetabs INTO ls_mv_basetab.",
        "        lv_mv_index = lv_mv_index + 1.",
        "        add_payload 'T1' lv_mv_index",
        "          'DDLANGUAGE' ls_mv_basetab-ddlanguage.",
        "        add_payload 'T1' lv_mv_index",
        "          'VIEWNAME' ls_mv_basetab-viewname.",
        "        add_payload 'T1' lv_mv_index",
        "          'TABNAME' ls_mv_basetab-tabname.",
        "        add_payload 'T1' lv_mv_index",
        "          'FORTABNAME' ls_mv_basetab-fortabname.",
        "        add_payload 'T1' lv_mv_index",
        "          'FORFIELD' ls_mv_basetab-forfield.",
        "        add_payload 'T1' lv_mv_index",
        "          'FORDIR' ls_mv_basetab-fordir.",
        "      ENDLOOP."
    )
    # D6-4 T2 行 = DD27P（视图字段）中"读得到、且不是助手/激活自己算出来的"那一部分：
    # TABNAME/FIELDNAME/VIEWFIELD 是调用方可控的身份，其余是 SAP 从基本表推导出的属性，
    # 只报告不接收（见 src/tools.ts 的 upsert_maintenance_view 契约）。
    $ddicMvFieldPayloadLines = @(
        "      CLEAR lv_mv_index.",
        "      LOOP AT lt_mv_fields INTO ls_mv_field.",
        "        lv_mv_index = lv_mv_index + 1.",
        "        add_payload 'T2' lv_mv_index",
        "          'DDLANGUAGE' ls_mv_field-ddlanguage.",
        "        add_payload 'T2' lv_mv_index",
        "          'VIEWFIELD' ls_mv_field-viewfield.",
        "        add_payload 'T2' lv_mv_index",
        "          'TABNAME' ls_mv_field-tabname.",
        "        add_payload 'T2' lv_mv_index",
        "          'FIELDNAME' ls_mv_field-fieldname.",
        "        add_payload 'T2' lv_mv_index",
        "          'KEYFLAG' ls_mv_field-keyflag.",
        "        add_payload 'T2' lv_mv_index",
        "          'ENQMODE' ls_mv_field-enqmode.",
        "        add_payload 'T2' lv_mv_index",
        "          'RDONLY' ls_mv_field-rdonly.",
        "        add_payload 'T2' lv_mv_index",
        "          'ROLLNAME' ls_mv_field-rollname.",
        "        add_payload 'T2' lv_mv_index",
        "          'DOMNAME' ls_mv_field-domname.",
        "        add_payload 'T2' lv_mv_index",
        "          'DATATYPE' ls_mv_field-datatype.",
        "        add_payload 'T2' lv_mv_index",
        "          'FLENGTH' ls_mv_field-flength.",
        "        add_payload 'T2' lv_mv_index",
        "          'DECIMALS' ls_mv_field-decimals.",
        "        add_payload 'T2' lv_mv_index",
        "          'CHECKTABLE' ls_mv_field-checktable.",
        "        add_payload 'T2' lv_mv_index",
        "          'SHLPNAME' ls_mv_field-shlpname.",
        "        add_payload 'T2' lv_mv_index",
        "          'SHLPFIELD' ls_mv_field-shlpfield.",
        "        add_payload 'T2' lv_mv_index",
        "          'LOGFLAG' ls_mv_field-logflag.",
        "        add_payload 'T2' lv_mv_index",
        "          'DDTEXT' ls_mv_field-ddtext.",
        "      ENDLOOP."
    )
    # D6-4 T3 行 = DD28V（选择条件）全字段，只读报告：本工具不写选择条件（VISC 开关为空格），
    # 因为 DD28V-OPERATOR/NEGATION/CONTLINE/AND_OR 的合法值与语义在本工作区尚未建立。
    $ddicMvSelCondPayloadLines = @(
        "      CLEAR lv_mv_index.",
        "      LOOP AT lt_mv_selconds INTO ls_mv_selcond.",
        "        lv_mv_index = lv_mv_index + 1.",
        "        add_payload 'T3' lv_mv_index",
        "          'DDLANGUAGE' ls_mv_selcond-ddlanguage.",
        "        add_payload 'T3' lv_mv_index",
        "          'CONDNAME' ls_mv_selcond-condname.",
        "        add_payload 'T3' lv_mv_index",
        "          'POSITION' ls_mv_selcond-position.",
        "        add_payload 'T3' lv_mv_index",
        "          'TABNAME' ls_mv_selcond-tabname.",
        "        add_payload 'T3' lv_mv_index",
        "          'FIELDNAME' ls_mv_selcond-fieldname.",
        "        add_payload 'T3' lv_mv_index",
        "          'NEGATION' ls_mv_selcond-negation.",
        "        add_payload 'T3' lv_mv_index",
        "          'OPERATOR' ls_mv_selcond-operator.",
        "        add_payload 'T3' lv_mv_index",
        "          'CONSTANTS' ls_mv_selcond-constants.",
        "        add_payload 'T3' lv_mv_index",
        "          'CONTLINE' ls_mv_selcond-contline.",
        "        add_payload 'T3' lv_mv_index",
        "          'AND_OR' ls_mv_selcond-and_or.",
        "        add_payload 'T3' lv_mv_index",
        "          'OFFSET' ls_mv_selcond-offset.",
        "        add_payload 'T3' lv_mv_index",
        "          'FLENGTH' ls_mv_selcond-flength.",
        "        add_payload 'T3' lv_mv_index",
        "          'MCOFIELD' ls_mv_selcond-mcofield.",
        "      ENDLOOP."
    )
    # D6-4 写维护视图：把调用方属性值写入 DDIC 组件后，检查是否因目标字段过短而被静默截断。
    # 三处调用（视图头 / 基表 / 视图字段）共用同一模板，只有错误消息不同。
    # 不能做成 FORM：FORM 无法访问功能模块的局部变量与字段符号 <lv_mv_field>。
    # （2026-09-22 第六次 F8 前这三处写的是 PERFORM mv_property_check.，而该 FORM 全篇不存在：
    #   报表只会报“字段 LS_MV_GOTSTATE 未知”这一个先到的错误，若继续依赖它下一轮必然再失败。）
    # 7.31 Unicode 约束：DESCRIBE FIELD ... LENGTH 必须带单位；IN CHARACTER MODE 只接受 C/N/D/T，
    # 所以先取 TYPE、只对字符型比较字符长度；STRING 的长度用 STRLEN（STRING 不能用于 IN CHARACTER MODE）。
    $ddicMvPropertyCheckTemplate = @(
        "            DESCRIBE FIELD <lv_mv_field> TYPE lv_mv_datatype.",
        "            lv_mv_input_value = lv_mv_value.",
        "            CONDENSE lv_mv_input_value.",
        "            lv_mv_input_length = STRLEN( lv_mv_input_value ).",
        "            IF lv_mv_datatype = 'C' OR lv_mv_datatype = 'N'",
        "               OR lv_mv_datatype = 'D' OR lv_mv_datatype = 'T'.",
        "              DESCRIBE FIELD <lv_mv_field>",
        "                LENGTH lv_mv_field_length IN CHARACTER MODE.",
        "              IF lv_mv_input_length > lv_mv_field_length.",
        "                ev_status = 'E'. ev_code = 'PROPERTY_VALUE_INVALID'.",
        "                ev_message = '@@MESSAGE@@'.",
        "                ev_version = '1.11'. RETURN.",
        "              ENDIF.",
        "            ENDIF."
    )
    $ddicMvPropertyCheckViewLines = @(
        $ddicMvPropertyCheckTemplate |
        ForEach-Object { $_.Replace('@@MESSAGE@@', 'View property value truncated') }
    )
    $ddicMvPropertyCheckTableLines = @(
        $ddicMvPropertyCheckTemplate |
        ForEach-Object { $_.Replace('@@MESSAGE@@', 'Base table property value truncated') }
    )
    $ddicMvPropertyCheckFieldLines = @(
        $ddicMvPropertyCheckTemplate |
        ForEach-Object { $_.Replace('@@MESSAGE@@', 'View field property value truncated') }
    )
    # D6-3 三个新分支。全部自带完整校验与 RETURN，不落入后面 DDIC 专用的公共写流程
    # （公共流程假定对象类型是 DD*/TABL/ENQU 等，对 NROB 无意义）。
    return @(
        "  DATA ls_dd01v TYPE dd01v.",
        "  DATA lt_dd07v TYPE TABLE OF dd07v.",
        "  DATA ls_dd07v TYPE dd07v.",
        "  DATA ls_dd04v TYPE dd04v.",
        "  DATA ls_dd02v TYPE dd02v.",
