        "  FIELD-SYMBOLS <ls_dd31v> TYPE dd31v.",
        "  FIELD-SYMBOLS <ls_dd32p> TYPE dd32p.",
        "  FIELD-SYMBOLS <ls_dd33v> TYPE dd33v.",
        "  DATA ls_dd25v TYPE dd25v.",
        "  DATA lt_dd26v TYPE TABLE OF dd26e.",
        "  DATA lt_dd27p TYPE TABLE OF dd27p.",
        "  DATA ls_current_dd25v TYPE dd25v.",
        "  DATA lt_current_dd26v TYPE TABLE OF dd26e.",
        "  DATA lt_current_dd27p TYPE TABLE OF dd27p.",
        "  DATA ls_dd26v TYPE dd26e.",
        "  DATA ls_dd27p TYPE dd27p.",
        "  FIELD-SYMBOLS <ls_dd26v> TYPE dd26e.",
        "  FIELD-SYMBOLS <ls_dd27p> TYPE dd27p.",
        "  DATA lt_append_dd03p TYPE TABLE OF dd03p.",
        "  DATA lt_checked_dd03p TYPE TABLE OF dd03p.",
        "  DATA ls_compare_dd03p TYPE dd03p.",
        "  DATA lt_act_res TYPE TABLE OF dctablres.",
        "  DATA ls_act_res TYPE dctablres.",
        "  DATA lt_expected_tbatg TYPE TABLE OF tbatg.",
        "  DATA lt_current_tbatg TYPE TABLE OF tbatg.",
        "  DATA ls_expected_tbatg TYPE tbatg.",
        "  DATA ls_current_tbatg TYPE tbatg.",
