        "  DATA lt_dd43v TYPE TABLE OF dd43v.",
        "  DATA ls_dd43v TYPE dd43v.",
        "  DATA ls_tadir TYPE tadir.",
        "  DATA ls_source TYPE abaptxt255.",
        "  DATA lv_kind TYPE c LENGTH 2.",
        "  DATA lv_index_text TYPE string.",
        "  DATA lv_index TYPE i.",
        "  DATA lv_property TYPE c LENGTH 30.",
        "  DATA lv_value TYPE string.",
        "  DATA lv_object_type TYPE tadir-object.",
        "  DATA: BEGIN OF ls_corr_object,",
        "    objtype TYPE e071-object,",
        "    objname TYPE e071-obj_name,",
        "  END OF ls_corr_object.",
        "  DATA lv_tadir_type TYPE tadir-object.",
        "  DATA lv_state_type TYPE ddobjtyp.",
        "  DATA lv_gotstate TYPE ddgotstate.",
        "  DATA lv_active_state TYPE ddgotstate.",
        # 2026-09-25 假成功事件（.logs/mcp-incident-20260925-001201-upsert-lock-object-false-success.md）：
        # 写后校验原先只以 state = 'A' 读活动版本，对象**原本就活动**时该读取与本
        # 次写入是否激活无关、必然成功；而各类型 DDIF_*_ACTIVATE 的 rc 除 TABL 的
        # 转换判定外从不判定（原 5642-5649 取到的 lv_active_state 是死代码），于是
        # 激活被拒也报成功，DDIF_*_PUT 产生的非活动版本留存。本变量承载"写后是否
        # 仍残留非活动版本"的探针：以 state = 'M' 读取，gotstate 必须为 'A'（与读
        # 路径判定 INACTIVE_VERSION_EXISTS 的判据同源），否则按契约失败返回。
        "  DATA lv_leftover_state TYPE ddgotstate.",
        "  DATA lv_current_version TYPE c LENGTH 14.",
        "  DATA lv_existing TYPE c LENGTH 1.",
        "  DATA lv_write TYPE c LENGTH 1.",
        "  DATA lv_delete TYPE c LENGTH 1.",
        "  DATA lv_append TYPE c LENGTH 1.",
        "  DATA lv_patch TYPE c LENGTH 1.",
        "  DATA lv_settings TYPE c LENGTH 1.",
        "  DATA lv_recover TYPE c LENGTH 1.",
        "  DATA lv_resume TYPE c LENGTH 1.",
        "  DATA lv_describe TYPE c LENGTH 1.",
        "  DATA lv_changed TYPE c LENGTH 1.",
        "  DATA lv_key_closed TYPE c LENGTH 1.",
        "  DATA lv_current_has_mandt TYPE c LENGTH 1.",
        "  DATA lv_final_has_mandt TYPE c LENGTH 1.",
        "  DATA lv_mode TYPE c LENGTH 1.",
        "  DATA lv_rc TYPE sy-subrc.",
        "  DATA lv_activation_subrc TYPE sy-subrc.",
        # 2026-09-23 运行时回归：1.13 助手终于派发到恢复激活分支，但 DD_TABL_ACT 返回
        # subrc=0 且 act_result=0（DD_TABL_ACT 的 act_result 不是成功标志）而对象仍无活动
        # 版本，于是卡在"激活后校验"并只回 VERIFY_FAILED——真正的原因（激活子返回码、
        # act_res_tab 行数、DD_TABL_ACT 给出的 action/mode/dataloss）被丢弃，不可归因。
        # 该变量承载这些诊断，失败时写进 ev_message（BAPIRET2-MESSAGE，CHAR 220）并同时
        # 以 payload 行输出。
        "  DATA lv_verify_detail TYPE string.",
        "  DATA lv_verify_action TYPE string.",
        "  DATA lv_act_rows TYPE i.",
        # CONCATENATE 只接受字符型操作数（C/N/D/T/STRING）。sy-subrc 与 I 都是数值型，必须先
        # 经 WRITE ... TO 落到字符字段，否则 GENERATE 在正文行 4959 报
        # 「LV_ACTIVATION_SUBRC 必须为字符型数据对象」（2026-09-23 r33 第 9 次 F8 实测）。
        "  DATA lv_act_subrc_text TYPE c LENGTH 10.",
        "  DATA lv_act_rc_text TYPE c LENGTH 10.",
        "  DATA lv_act_rows_text TYPE c LENGTH 10.",
        "  DATA lv_put_subrc TYPE sy-subrc.",
        "  DATA lv_put_subrc_text TYPE c LENGTH 10.",
        "  DATA lv_msg_class TYPE sy-msgid.",
        "  DATA lv_msg_type TYPE sy-msgty.",
        "  DATA lv_msg_number TYPE sy-msgno.",
        "  DATA lv_msg_text TYPE string.",
        "  DATA lv_inactive_exists TYPE c LENGTH 1.",
        "  DATA lv_tadir_exists TYPE c LENGTH 1.",
        "  DATA lv_tadir_entry_left TYPE c LENGTH 1.",
        "  DATA lv_tadir_rc TYPE sy-subrc.",
        # r17: name pattern used to release the TLOCK order lock of this object before the
        # TADIR entry is deleted (see the delete tail for the verified reason).
        "  DATA lv_lock_pattern TYPE c LENGTH 130.",
        "  DATA ls_corr_enqu_tadir TYPE tadir.",
        "  DATA ls_corr_enqu_input TYPE tadir.",
        "  DATA ls_corr_enqu_object TYPE ko200.",
        "  DATA lt_corr_enqu_objects TYPE tredt_objects.",
        "  DATA lt_corr_enqu_recorded TYPE scts_tadir.",
        "  DATA lv_tadir_rc_text TYPE c LENGTH 10.",
        "  DATA lv_phase TYPE string.",
        "  DATA lv_recorded_request TYPE trkorr.",
        "  DATA lv_ddic_name TYPE ddobjname.",
        # D6-3 编号范围对象（TNRO/TNROT）分支的局部数据。ls_nrob_current 始终承载"数据库现值"，
        # ls_nrob_requested 承载"本次请求要落库的定义"；两者用同一 DDIC 类型，便于结构级比对。
        "  DATA ls_nrob_current TYPE tnro.",
        "  DATA ls_nrob_requested TYPE tnro.",
        "  DATA ls_nrob_text TYPE tnrot.",
        "  DATA lt_nrob_texts TYPE TABLE OF tnrot.",
        "  DATA ls_nrob_stored_text TYPE tnrot.",
        "  DATA lt_nrob_stored_texts TYPE TABLE OF tnrot.",
