        "  DATA lv_nrob_name TYPE tnro-object.",
        "  DATA lv_nrob_name_raw TYPE tadir-obj_name.",
        "  DATA lv_nrob_name_check TYPE tadir-obj_name.",
        "  DATA lv_nrob_language TYPE t002-spras.",
        "  DATA lv_nrob_indicator TYPE c LENGTH 1.",
        "  DATA lv_nrob_call_indicator TYPE c LENGTH 1.",
        "  DATA lv_nrob_returncode TYPE c LENGTH 1.",
        "  DATA lv_nrob_subrc TYPE sy-subrc.",
        "  DATA lv_nrob_interval TYPE c LENGTH 1.",
        "  DATA lv_nrob_converted TYPE c LENGTH 1.",
        "  DATA lv_nrob_tadir_removed TYPE c LENGTH 1.",
        "  DATA lv_nrob_datatype TYPE c LENGTH 1.",
        "  DATA lv_nrob_field_length TYPE i.",
        "  DATA lv_nrob_input_length TYPE i.",
        "  DATA lv_nrob_exists TYPE c LENGTH 1.",
        "  DATA lv_nrob_index TYPE i.",
        "  DATA lv_nrob_text_count TYPE i.",
        "  DATA lv_nrob_canonical TYPE string.",
        # TNRO-PERCENTAGE 是 TNRO 里唯一非字符型字段（DD03L：DATATYPE=DEC，LENG=3，DECIMALS=1，
        # INTTYPE=P）。7.31 的 CONCATENATE 只接受 C/N/D/T/STRING，直接传该字段会导致 GENERATE 失败：
        #   '"PERCENTAGE" 必须为字符型数据对象（数据类型 C, N, D, T 或 STRING）'
        # （2026-09-22 F8 事故，body line 553 / LS_NROB_CURRENT-PERCENTAGE）。
        # 但 DEC -> STRING 的隐式转换会使用**用户主数据的小数分隔符**，那会让摘要随用户/区域而变
        # —— 同一个版本令牌在读出与写回时可能不一致（这正是本会话已修过一次的同类陷阱）。
        # 因此不直接转换，而是先放大成整数再转 STRING：该字段只有 1 位小数，乘 10 后是精确整数，
        # 整数的字符串表示与区域无关，且对同一数据恒等。
        "  DATA lv_nrob_percentage TYPE string.",
        "  DATA lv_nrob_percentage_i TYPE i.",
        "  DATA lv_nrob_version TYPE c LENGTH 40.",
        # EF_HASHSTRING（STRING，按引用传递）必须用 string 实参接收：引用参数不做类型转换。
        "  DATA lv_nrob_digest TYPE string.",
        "  DATA lv_nrob_kind TYPE c LENGTH 2.",
        "  DATA lv_nrob_index_text TYPE string.",
        "  DATA lv_nrob_property TYPE string.",
