        "  DATA lv_nrob_check_value TYPE string.",
        "  DATA lv_nrob_input_value TYPE string.",
        "  FIELD-SYMBOLS <lv_nrob_field> TYPE any.",
        "  CONSTANTS c_nrob_retcode_warning TYPE c VALUE 'W'.",
        "  DATA lt_nrob_warnings TYPE TABLE OF inoer.",
        "  DATA lv_nrob_warning TYPE c LENGTH 1.",
        # D6-4 维护视图（VIEWCLASS='C'）分支的局部数据。ls_mv_header 始终承载"最终对外报告的
        # 那一版"（活动版优先，否则修订版），ls_mv_requested 承载"本次请求要写入的定义"。
        # TABLE OF dd26v/dd27p/dd28v 与 DD_VIEW_GET/DD_VIEW_PUT 的 TABLES 参数同型。
        "  CONSTANTS c_mv_max_rows TYPE i VALUE 5000.",
        "  DATA ls_mv_header TYPE dd25v.",
        "  DATA ls_mv_header_a TYPE dd25v.",
        "  DATA ls_mv_header_n TYPE dd25v.",
