        # “字段 LS_MV_GOTSTATE 未知”，即漏了本声明；与只读入参块 ls_mv_get 是两个不同对象。
        "  DATA ls_mv_gotstate TYPE dcviewget.",
        "  DATA ls_mv_ctrl TYPE dcviewput.",
        "  DATA lv_mv_put_state TYPE ddrefstruc-state.",
        "  DATA lv_mv_actmode TYPE ddrefstruc-mode.",
        "  DATA lv_mv_authchk TYPE ddrefstruc-bool.",
