        "  DATA ls_mv_basetab TYPE dd26v.",
        "  DATA lt_mv_basetabs_a TYPE TABLE OF dd26v.",
        "  DATA lt_mv_basetabs_n TYPE TABLE OF dd26v.",
        "  DATA lt_mv_fields TYPE TABLE OF dd27p.",
        "  DATA ls_mv_field TYPE dd27p.",
        "  DATA lt_mv_fields_a TYPE TABLE OF dd27p.",
        "  DATA lt_mv_fields_n TYPE TABLE OF dd27p.",
        "  DATA lt_mv_selconds TYPE TABLE OF dd28v.",
        "  DATA ls_mv_selcond TYPE dd28v.",
        "  DATA lt_mv_selconds_a TYPE TABLE OF dd28v.",
        "  DATA lt_mv_selconds_n TYPE TABLE OF dd28v.",
        "  DATA lv_mv_name TYPE dd25v-viewname.",
        "  DATA lv_mv_name_raw TYPE tadir-obj_name.",
        "  DATA lv_mv_name_check TYPE tadir-obj_name.",
        # 名称字符集校验的操作数必须转成 STRING：lv_nrob_name_raw / lv_mv_name_raw 是
        # TADIR-OBJ_NAME（CHAR 40），定长 C 字段的尾随填充空格无法去掉，而 CN 会把填充空格
        # 当作不在字符集内的字符，于是任何合法名称都会被判为 OBJECT_NAME_INVALID。
        # 赋给 STRING 时尾随空格被截掉；1.2 的通用写入校验（lv_value）一直使用同一写法。
        "  DATA lv_name_guard TYPE string.",
        # 客户命名判定的结果位。共享写入守卫要区分「Z/Y 开头」与「ENQU 的 E + Z/Y」两种合法形态，
        # 判定一次后由守卫统一拒绝，避免同一规则在两个地方各写一遍。
        "  DATA lv_customer_name TYPE c LENGTH 1.",
        "  DATA lv_mv_viewclass TYPE dd25v-viewclass.",
        # 固定长度 c(14)（= AS4DATE + AS4TIME），与公共 DDIC 流程的 lv_current_version 同型：
        # iv_expected_version 是 CHAR 220（BAPIRET2-MESSAGE），若本字段声明为 STRING，则 c 侧会
        # 带着 206 个尾随空格转成 STRING 参与比较，14 位时间戳永远不相等（R-20 记录的第 5 条陷阱）。
        "  DATA lv_mv_version TYPE c LENGTH 14.",
        "  DATA lv_mv_inactive TYPE c LENGTH 1.",
        "  DATA lv_mv_exists TYPE c LENGTH 1.",
        "  DATA lv_mv_delete_state TYPE dd25l-as4local.",
        "  DATA lv_mv_kind TYPE c LENGTH 2.",
        "  DATA lv_mv_index TYPE i.",
        "  DATA lv_mv_index_text TYPE string.",
        "  DATA lv_mv_property TYPE string.",
        "  DATA lv_mv_value TYPE string.",
        "  DATA lv_mv_input_value TYPE string.",
        "  DATA lv_mv_input_length TYPE i.",
        "  DATA lv_mv_field_length TYPE i.",
        "  DATA lv_mv_datatype TYPE c LENGTH 1.",
        "  DATA lv_mv_rc_text TYPE c LENGTH 10.",
        "  DATA lv_mv_ctrl_text TYPE c LENGTH 5.",
        "  DATA ls_mv_stored_tab TYPE dd26v.",
        "  DATA ls_mv_stored_field TYPE dd27p.",
        "  DATA lv_mv_tab_count TYPE i.",
        "  DATA lv_mv_field_count TYPE i.",
        "  DATA lv_mv_expected_count TYPE i.",
        "  DATA lv_mv_stored_count TYPE i.",
        "  DATA lv_mv_dd25l_count TYPE i.",
        "  DATA lv_mv_check_value TYPE string.",
        "  DATA lv_mv_recorded_request TYPE trkorr.",
        "  DATA lv_mv_tadir_removed TYPE c LENGTH 1.",
        "  DATA ls_mv_tadir TYPE tadir.",
        "  DATA ls_mv_tadir_input TYPE tadir.",
        "  DATA ls_mv_request TYPE e070.",
        "  DATA ls_mv_task TYPE e070.",
        "  DATA ls_mv_object TYPE ko200.",
        "  DATA lt_mv_objects TYPE tredt_objects.",
        "  DATA lt_mv_recorded TYPE scts_tadir.",
        "  DATA ls_mv_e071 TYPE e071.",
        "  FIELD-SYMBOLS <lv_mv_field> TYPE any.",
        # D6-5 append 结构字段级写入（UPSERT_APPEND_STRUCTURE_FIELDS）的局部数据。
        # ls_ap_header 承载 state='A' 回读到的 append 表头，SQLTAB 即激活目标基表。
        "  DATA ls_ap_header TYPE dd02v.",
        "  DATA ls_ap_dd09v TYPE dd09v.",
        "  DATA lv_ap_gotstate TYPE ddgotstate.",
        "  DATA lv_ap_tabclass TYPE dd02v-tabclass.",
        "  DATA lv_ap_base TYPE dd02v-sqltab.",
        "  DATA lv_ap_name TYPE ddobjname.",
        "  DATA lv_ap_name_raw TYPE tadir-obj_name.",
        "  DATA lv_ap_name_check TYPE tadir-obj_name.",
        "  DATA lv_ap_kind TYPE c LENGTH 2.",
        "  DATA lv_ap_index TYPE i.",
        "  DATA lv_ap_index_text TYPE string.",
        "  DATA lv_ap_property TYPE string.",
        "  DATA lv_ap_value TYPE string.",
        "  DATA lv_ap_field_count TYPE i.",
        "  DATA lv_ap_stored_count TYPE i.",
        "  DATA lv_ap_base_field_count TYPE i.",
        "  DATA lv_ap_unchanged TYPE c LENGTH 1.",
        "  DATA lv_ap_verify_ok TYPE c LENGTH 1.",
        "  DATA lv_ap_expected_text TYPE string.",
        "  DATA lv_ap_actual_text TYPE string.",
        "  DATA lv_ap_rc_text TYPE c LENGTH 10.",
        # 并发令牌：与读取路径发布的对象版本同构（CONCATENATE as4date as4time = 14 位）。
        "  DATA lv_ap_current_version TYPE c LENGTH 14.",
        # 调用前的追加字段集，用于删减传播校验与失败补偿。
        "  DATA lt_ap_before TYPE TABLE OF dd03p.",
        "  DATA lv_ap_base_delta_ok TYPE c LENGTH 1.",
        "  DATA lv_ap_base_mismatch_text TYPE string.",
        "  DATA lv_ap_removed_text TYPE string.",
        # D-4：字段集指纹（SHA1，40 位十六进制）。DD_TBFD_PUT 只写 DD03P、不动 DD02V，
        # 故字段级变更不会刷新表头时间戳，14 位版本号对丢失更新不敏感。
        "  DATA lv_ap_fingerprint TYPE hash160.",
        "  DATA lv_ap_fp_line TYPE string.",
        "  DATA lv_ap_fp_source TYPE string.",
        "  DATA lt_ap_fp TYPE TABLE OF string.",
        "  DATA lv_ap_guard TYPE string.",
        "  DATA ls_ap_restore TYPE dd03p.",
        "  DATA lt_ap_restore TYPE TABLE OF dd03p.",
        "  DATA ls_ap_requested TYPE dd03p.",
        "  DATA ls_ap_stored TYPE dd03p.",
        "  DATA lt_ap_requested TYPE TABLE OF dd03p.",
        "  DATA lt_ap_expanded TYPE TABLE OF dd03p.",
        "  FIELD-SYMBOLS <ls_ap_field> TYPE dd03p.",
        "  DATA lv_as4date TYPE as4date.",
