        "          dd27p_tab_n = lt_mv_fields_n",
        "          dd28v_tab_a = lt_mv_selconds_a",
        "          dd28v_tab_n = lt_mv_selconds_n",
        "        EXCEPTIONS access_failure = 1",
        "          others = 2.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'DDIC_READ_FAILED'.",
        "        ev_message = 'Maintenance view could not be read'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      IF ls_mv_header_a-viewname IS NOT INITIAL.",
        "        ls_mv_header = ls_mv_header_a.",
        "        lt_mv_basetabs = lt_mv_basetabs_a.",
        "        lt_mv_fields = lt_mv_fields_a.",
        "        lt_mv_selconds = lt_mv_selconds_a.",
        "      ELSE.",
        "        ls_mv_header = ls_mv_header_n.",
        "        lt_mv_basetabs = lt_mv_basetabs_n.",
        "        lt_mv_fields = lt_mv_fields_n.",
        "        lt_mv_selconds = lt_mv_selconds_n.",
        "        IF ls_mv_header-viewname IS INITIAL.",
        "          ev_status = 'E'. ev_code = 'DDIC_OBJECT_NOT_FOUND'.",
        "          ev_message = 'Maintenance view does not exist'.",
        "          ev_version = '1.11'. RETURN.",
        "        ENDIF.",
        "        lv_mv_inactive = 'X'.",
        "      ENDIF.",
        "      lv_mv_viewclass = ls_mv_header-viewclass.",
        "      CONCATENATE ls_mv_header-as4date ls_mv_header-as4time",
        "        INTO lv_mv_version.",
        "      SORT lt_mv_basetabs BY tabpos.",
        "      SORT lt_mv_fields BY objpos.",
        "      SORT lt_mv_selconds BY position.",
        "      CLEAR ls_mv_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_mv_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'VIEW'",
        "          AND obj_name = lv_mv_name.",
        "      add_payload 'M' '1' 'LANGUAGE' sy-langu.",
        "      add_payload 'M' '1' 'PACKAGE' ls_mv_tadir-devclass.",
        "      add_payload 'M' '1' 'VERSION' lv_mv_version.",
        "      add_payload 'M' '1' 'REQUEST' ls_mv_tadir-korrnum.",
        "      add_payload 'M' '1' 'INACTIVE' lv_mv_inactive.",
        "      add_payload 'M' '1' 'VIEWCLASS' lv_mv_viewclass.",
        "      add_payload 'M' '1' 'GOTSTATE' ls_mv_gotstate-view."
        ) + $ddicMvHeaderPayloadLines + $ddicMvBaseTabPayloadLines + $ddicMvFieldPayloadLines + $ddicMvSelCondPayloadLines + @(
        "      ev_status = 'S'. ev_code = 'MAINTENANCE_VIEW_READ'.",
        "      ev_message = 'Maintenance view read'.",
        "      ev_version = '1.11'. RETURN.",
        # D6-4 写维护视图。顺序固定：解析负载 -> 校验 -> DD_VIEW_PUT(PUT_STATE='N') -> 回读修订版
        # -> DD_VIEW_ACT(ACT_MODE=11) -> TADIR/E071 登记 -> 唯一一次 COMMIT -> 回读活动版。
        # 任何一步失败都 ROLLBACK WORK，激活与登记因此在同一个 LUW 里全有或全无。
        "    WHEN 'UPSERT_MAINTENANCE_VIEW'.",
        "      CLEAR: ls_mv_requested, ls_mv_header, ls_mv_header_a.",
        "      CLEAR: ls_mv_header_n, lv_mv_viewclass, lv_mv_exists.",
        "      CLEAR: lv_mv_version, lv_mv_tab_count, lv_mv_field_count.",
        "      CLEAR: lv_mv_recorded_request, lv_mv_tadir_removed.",
        "      CLEAR: ls_mv_tadir, lv_mv_check_value, ls_mv_e071.",
        "      CLEAR: lv_mv_rc, lv_mv_rc_text, lv_mv_dbact.",
        "      REFRESH: lt_mv_basetabs, lt_mv_fields, lt_mv_selconds.",
        "      REFRESH: lt_mv_basetabs_a, lt_mv_basetabs_n.",
        "      REFRESH: lt_mv_fields_a, lt_mv_fields_n.",
        "      REFRESH: lt_mv_selconds_a, lt_mv_selconds_n.",
        "      REFRESH: lt_mv_objects, lt_mv_recorded.",
        "      lv_mv_name_raw = iv_object_name.",
        "      CONDENSE lv_mv_name_raw NO-GAPS.",
        "      IF lv_mv_name_raw IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'OBJECT_NAME_REQUIRED'.",
        "        ev_message = 'Maintenance view name is required'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      IF lv_mv_name_raw(1) <> 'Z'",
        "         AND lv_mv_name_raw(1) <> 'Y'.",
        "        ev_status = 'E'. ev_code = 'CUSTOMER_OBJECT_REQUIRED'.",
        "        ev_message = 'Only Z or Y maintenance views are writable'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      lv_name_guard = lv_mv_name_raw.",
        "      IF lv_name_guard CN 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'.",
        "        ev_status = 'E'. ev_code = 'OBJECT_NAME_INVALID'.",
        "        ev_message = 'Invalid customer maintenance view name'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      lv_mv_name = lv_mv_name_raw.",
        "      lv_mv_name_check = lv_mv_name.",
        "      IF lv_mv_name_check <> lv_mv_name_raw.",
        "        ev_status = 'E'. ev_code = 'OBJECT_NAME_INVALID'.",
        "        ev_message = 'Maintenance view name is too long'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      CLEAR: lv_mv_tab_count, lv_mv_field_count.",
        "      LOOP AT it_source INTO ls_source.",
        "        CLEAR: lv_mv_kind, lv_mv_index_text.",
        "        CLEAR: lv_mv_property, lv_mv_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_mv_kind",
        "          lv_mv_index_text lv_mv_property lv_mv_value.",
        "        REPLACE ALL OCCURRENCES OF '%7C' IN lv_mv_value",
        "          WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25' IN lv_mv_value",
        "          WITH '%'.",
        "        TRANSLATE lv_mv_property TO UPPER CASE.",
        "        UNASSIGN <lv_mv_field>.",
        "        IF lv_mv_kind = 'H'.",
        "          IF lv_mv_index_text <> '1'.",
        "            ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "            ev_message = 'Header index must be one'.",
        "            ev_version = '1.11'. RETURN.",
        "          ENDIF.",
        "          IF lv_mv_property = 'ROOTTAB'",
        "             OR lv_mv_property = 'VIEWGRANT'",
        "             OR lv_mv_property = 'CUSTOMAUTH'",
        "             OR lv_mv_property = 'GLOBALFLAG'.",
        "            ASSIGN COMPONENT lv_mv_property",
        "              OF STRUCTURE ls_mv_requested TO <lv_mv_field>.",
        "            IF sy-subrc <> 0.",
        "              ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "              ev_message = 'View property not allowed'.",
        "              ev_version = '1.11'. RETURN.",
        "            ENDIF.",
        "            <lv_mv_field> = lv_mv_value."
        ) + $ddicMvPropertyCheckViewLines + @(
        "          ELSEIF lv_mv_property = 'VIEWNAME'",
        "             OR lv_mv_property = 'VIEWCLASS'",
        "             OR lv_mv_property = 'AGGTYPE'",
        "             OR lv_mv_property = 'DDLANGUAGE'",
        "             OR lv_mv_property = 'MASTERLANG'",
        "             OR lv_mv_property = 'DDTEXT'",
        "             OR lv_mv_property = 'AS4LOCAL'",
        "             OR lv_mv_property = 'AS4VERS'",
        "             OR lv_mv_property = 'AS4DATE'",
        "             OR lv_mv_property = 'AS4TIME'",
        "             OR lv_mv_property = 'AS4USER'",
        "             OR lv_mv_property = 'ACTFLAG'.",
        "            ev_status = 'E'. ev_code = 'PROPERTY_READ_ONLY'.",
        "            ev_message = 'View property is set by SAP'.",
        "            ev_version = '1.11'. RETURN.",
        "          ELSE.",
        "            ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "            ev_message = 'View property not allowed'.",
        "            ev_version = '1.11'. RETURN.",
        "          ENDIF.",
        "        ELSEIF lv_mv_kind = 'T1'.",
        "          IF lv_mv_index_text IS INITIAL",
        "             OR lv_mv_index_text CN '0123456789'.",
        "            ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "            ev_message = 'Base table index is invalid'.",
        "            ev_version = '1.11'. RETURN.",
        "          ENDIF.",
        "          lv_mv_index = lv_mv_index_text.",
        "          IF lv_mv_index <= 0 OR lv_mv_index > c_mv_max_rows",
        "             OR lv_mv_index > lv_mv_tab_count + 1.",
        "            ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "            ev_message = 'Base table index is invalid'.",
        "            ev_version = '1.11'. RETURN.",
        "          ENDIF.",
        "          IF lv_mv_property = 'TABNAME'",
        "             OR lv_mv_property = 'FORTABNAME'",
        "             OR lv_mv_property = 'FORFIELD'",
        "             OR lv_mv_property = 'FORDIR'.",
        "            READ TABLE lt_mv_basetabs INTO ls_mv_basetab",
        "              INDEX lv_mv_index.",
        "            IF sy-subrc <> 0.",
        "              CLEAR ls_mv_basetab.",
        "              lv_mv_tab_count = lv_mv_index.",
        "              APPEND ls_mv_basetab TO lt_mv_basetabs.",
        "            ENDIF.",
        "            ASSIGN COMPONENT lv_mv_property",
        "              OF STRUCTURE ls_mv_basetab TO <lv_mv_field>.",
        "            IF sy-subrc <> 0.",
        "              ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "              ev_message = 'Base table property not allowed'.",
        "              ev_version = '1.11'. RETURN.",
        "            ENDIF.",
        "            <lv_mv_field> = lv_mv_value."
        ) + $ddicMvPropertyCheckTableLines + @(
        "            ls_mv_basetab-viewname = lv_mv_name.",
        "            MODIFY lt_mv_basetabs FROM ls_mv_basetab",
        "              INDEX lv_mv_index.",
        "          ELSEIF lv_mv_property = 'VIEWNAME'",
        "             OR lv_mv_property = 'TABPOS'",
        "             OR lv_mv_property = 'DDLANGUAGE'.",
        "            ev_status = 'E'. ev_code = 'PROPERTY_READ_ONLY'.",
        "            ev_message = 'Base table key is set by the helper'.",
        "            ev_version = '1.11'. RETURN.",
        "          ELSE.",
        "            ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "            ev_message = 'Base table property not allowed'.",
        "            ev_version = '1.11'. RETURN.",
        "          ENDIF.",
        "        ELSEIF lv_mv_kind = 'T2'.",
        "          IF lv_mv_index_text IS INITIAL",
        "             OR lv_mv_index_text CN '0123456789'.",
        "            ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "            ev_message = 'View field index is invalid'.",
        "            ev_version = '1.11'. RETURN.",
        "          ENDIF.",
        "          lv_mv_index = lv_mv_index_text.",
        "          IF lv_mv_index <= 0 OR lv_mv_index > c_mv_max_rows",
        "             OR lv_mv_index > lv_mv_field_count + 1.",
        "            ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "            ev_message = 'View field index is invalid'.",
        "            ev_version = '1.11'. RETURN.",
        "          ENDIF.",
        "          IF lv_mv_property = 'VIEWFIELD'",
        "             OR lv_mv_property = 'TABNAME'",
        "             OR lv_mv_property = 'FIELDNAME'.",
        "            READ TABLE lt_mv_fields INTO ls_mv_field",
        "              INDEX lv_mv_index.",
        "            IF sy-subrc <> 0.",
        "              CLEAR ls_mv_field.",
        "              lv_mv_field_count = lv_mv_index.",
        "              APPEND ls_mv_field TO lt_mv_fields.",
        "            ENDIF.",
        "            ASSIGN COMPONENT lv_mv_property",
        "              OF STRUCTURE ls_mv_field TO <lv_mv_field>.",
        "            IF sy-subrc <> 0.",
        "              ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "              ev_message = 'View field property not allowed'.",
        "              ev_version = '1.11'. RETURN.",
        "            ENDIF.",
        "            <lv_mv_field> = lv_mv_value."
        ) + $ddicMvPropertyCheckFieldLines + @(
        "            ls_mv_field-viewname = lv_mv_name.",
        "            MODIFY lt_mv_fields FROM ls_mv_field",
        "              INDEX lv_mv_index.",
        "          ELSEIF lv_mv_property = 'VIEWNAME'",
        "             OR lv_mv_property = 'OBJPOS'",
        "             OR lv_mv_property = 'DDLANGUAGE'.",
        "            ev_status = 'E'. ev_code = 'PROPERTY_READ_ONLY'.",
        "            ev_message = 'View field key is set by the helper'.",
        "            ev_version = '1.11'. RETURN.",
        "          ELSE.",
        "            ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "            ev_message = 'View field property not allowed'.",
        "            ev_version = '1.11'. RETURN.",
        "          ENDIF.",
        "        ELSE.",
        "          ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "          ev_message = 'Unsupported view payload kind'.",
        "          ev_version = '1.11'. RETURN.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      IF lv_mv_tab_count IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'VIEW_BASE_TABLE_REQUIRED'.",
        "        ev_message = 'At least one base table is required'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      IF lv_mv_field_count IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'VIEW_FIELD_REQUIRED'.",
        "        ev_message = 'At least one view field is required'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      CLEAR lv_mv_index.",
        "      LOOP AT lt_mv_basetabs INTO ls_mv_basetab.",
        "        lv_mv_index = lv_mv_index + 1.",
        "        ls_mv_basetab-viewname = lv_mv_name.",
        "        ls_mv_basetab-tabpos = lv_mv_index.",
        "        ls_mv_basetab-ddlanguage = sy-langu.",
        "        IF ls_mv_basetab-tabname IS INITIAL.",
        "          ev_status = 'E'.",
        "          ev_code = 'VIEW_BASE_TABLE_REQUIRED'.",
        "          ev_message = 'Base table row needs a table name'.",
        "          ev_version = '1.11'. RETURN.",
        "        ENDIF.",
        "        MODIFY lt_mv_basetabs FROM ls_mv_basetab.",
        "      ENDLOOP.",
        "      CLEAR lv_mv_index.",
        "      LOOP AT lt_mv_fields INTO ls_mv_field.",
        "        lv_mv_index = lv_mv_index + 1.",
        "        ls_mv_field-viewname = lv_mv_name.",
        "        ls_mv_field-objpos = lv_mv_index.",
        "        ls_mv_field-ddlanguage = sy-langu.",
        "        IF ls_mv_field-viewfield IS INITIAL.",
        "          ls_mv_field-viewfield = ls_mv_field-fieldname.",
        "        ENDIF.",
        "        IF ls_mv_field-tabname IS INITIAL",
        "           OR ls_mv_field-fieldname IS INITIAL.",
        "          ev_status = 'E'. ev_code = 'VIEW_FIELD_REQUIRED'.",
        "          ev_message = 'View field row needs table and field'.",
        "          ev_version = '1.11'. RETURN.",
        "        ENDIF.",
        "        MODIFY lt_mv_fields FROM ls_mv_field.",
        "      ENDLOOP.",
        "      ls_mv_requested-viewname = lv_mv_name.",
        "      ls_mv_requested-viewclass = 'C'.",
        "      ls_mv_requested-aggtype = 'V'.",
        "      ls_mv_requested-ddlanguage = sy-langu.",
        "      ls_mv_requested-masterlang = sy-langu.",
        "      ls_mv_requested-ddtext = iv_description.",
        "      IF ls_mv_requested-roottab IS INITIAL.",
        "        READ TABLE lt_mv_basetabs INTO ls_mv_basetab INDEX 1.",
        "        ls_mv_requested-roottab = ls_mv_basetab-tabname.",
        "      ENDIF.",
        "      CLEAR: ls_mv_header_a, ls_mv_header_n, ls_mv_gotstate.",
        "      REFRESH: lt_mv_basetabs_a, lt_mv_basetabs_n.",
        "      REFRESH: lt_mv_fields_a, lt_mv_fields_n.",
        "      REFRESH: lt_mv_selconds_a, lt_mv_selconds_n.",
        "      CLEAR ls_mv_get.",
        "      ls_mv_get-view = 'M'.",
        "      CALL FUNCTION 'DD_VIEW_GET'",
        "        EXPORTING get_state = ls_mv_get",
        "          langu = sy-langu",
        "          prid = 1",
        "          view_name = lv_mv_name",
        "          withtext = 'X'",
        "        IMPORTING dd25v_wa_a = ls_mv_header_a",
        "          dd25v_wa_n = ls_mv_header_n",
        "          got_state = ls_mv_gotstate",
        "        TABLES dd26v_tab_a = lt_mv_basetabs_a",
        "          dd26v_tab_n = lt_mv_basetabs_n",
        "          dd27p_tab_a = lt_mv_fields_a",
        "          dd27p_tab_n = lt_mv_fields_n",
        "          dd28v_tab_a = lt_mv_selconds_a",
        "          dd28v_tab_n = lt_mv_selconds_n",
        "        EXCEPTIONS access_failure = 1",
        "          others = 2.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'DDIC_READ_FAILED'.",
        "        ev_message = 'Maintenance view could not be read'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      CLEAR: lv_mv_exists, lv_mv_viewclass, lv_mv_version.",
        "      IF ls_mv_header_a-viewname IS NOT INITIAL.",
        "        ls_mv_header = ls_mv_header_a.",
        "        lv_mv_exists = 'X'.",
        "      ELSEIF ls_mv_header_n-viewname IS NOT INITIAL.",
        "        ls_mv_header = ls_mv_header_n.",
        "        lv_mv_exists = 'X'.",
        "      ENDIF.",
        "      IF lv_mv_exists = 'X'.",
        "        lv_mv_viewclass = ls_mv_header-viewclass.",
        "        CONCATENATE ls_mv_header-as4date ls_mv_header-as4time",
        "          INTO lv_mv_version.",
        "      ENDIF.",
        "      IF lv_mv_viewclass IS NOT INITIAL",
        "         AND lv_mv_viewclass <> 'C'.",
        "        ev_status = 'E'. ev_code = 'VIEW_CLASS_NOT_SUPPORTED'.",
        "        ev_message = 'Only maintenance views can be written'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      IF lv_mv_exists = 'X' AND iv_expected_version IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'VERSION_REQUIRED'.",
        "        ev_message = 'expectedVersion is required to change it'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      IF lv_mv_exists IS INITIAL",
        "         AND iv_expected_version IS NOT INITIAL.",
        "        ev_status = 'E'. ev_code = 'DDIC_OBJECT_NOT_FOUND'.",
        "        ev_message = 'Maintenance view does not exist'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      IF lv_mv_exists = 'X'",
        "         AND lv_mv_version <> iv_expected_version.",
        "        ev_status = 'E'. ev_code = 'VERSION_MISMATCH'.",
        "        ev_message = 'Maintenance view changed since read'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      IF lv_mv_exists = 'X'.",
        "        CLEAR ls_mv_tadir.",
        "        SELECT SINGLE * FROM tadir INTO ls_mv_tadir",
        "          WHERE pgmid = 'R3TR' AND object = 'VIEW'",
        "            AND obj_name = lv_mv_name.",
        "        IF sy-subrc = 0",
        "           AND ls_mv_tadir-devclass <> iv_package.",
        "          ev_status = 'E'. ev_code = 'PACKAGE_MISMATCH'.",
        "          ev_message = 'View belongs to another package'.",
        "          ev_version = '1.11'. RETURN.",
        "        ENDIF.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM e070 INTO ls_mv_request",
        "        WHERE trkorr = iv_request.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'TRANSPORT_NOT_FOUND'.",
        "        ev_message = 'Transport request or task does not exist'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      CLEAR ls_mv_task.",
        "      IF ls_mv_request-strkorr IS NOT INITIAL.",
        "        ls_mv_task = ls_mv_request.",
        "        CLEAR ls_mv_request.",
        "        SELECT SINGLE * FROM e070 INTO ls_mv_request",
        "          WHERE trkorr = ls_mv_task-strkorr.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'. ev_code = 'TRANSPORT_NOT_FOUND'.",
        "          ev_message = 'Transport request of the task is missing'.",
        "          ev_version = '1.11'. RETURN.",
        "        ENDIF.",
        "      ELSE.",
        "        SELECT SINGLE * FROM e070 INTO ls_mv_task",
        "          WHERE strkorr = ls_mv_request-trkorr",
        "            AND as4user = sy-uname AND trstatus = 'D'.",
        "      ENDIF.",
        "      IF ls_mv_request-trfunction <> 'K'",
        "         OR ls_mv_request-trstatus <> 'D'",
        "         OR ls_mv_task-trstatus <> 'D'",
        "         OR ls_mv_task-as4user <> sy-uname.",
        "        ev_status = 'E'. ev_code = 'TRANSPORT_NOT_MODIFIABLE'.",
        "        ev_message = 'Open workbench task for user is required'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      lv_mv_put_state = 'N'.",
        "      IF lv_mv_put_state IS INITIAL",
        "         OR lv_mv_put_state CN 'ANR'.",
        "        ev_status = 'E'. ev_code = 'VIEW_PUT_STATE_INVALID'.",
        "        ev_message = 'Maintenance view put state is invalid'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      CLEAR ls_mv_ctrl.",
        "      ls_mv_ctrl-vihd = 'X'.",
        "      ls_mv_ctrl-vifd = 'X'.",
        "      ls_mv_ctrl-vibt = 'X'.",
        "      ls_mv_ctrl-visc = space.",
        "      ls_mv_ctrl-vits = space.",
        "      CALL FUNCTION 'DD_VIEW_PUT'",
        "        EXPORTING ctrl_view_put = ls_mv_ctrl",
        "          dd25v_wa = ls_mv_requested",
        "          prid = 1",
        "          put_state = lv_mv_put_state",
        "          view_name = lv_mv_name",
        "        TABLES dd26v_tab = lt_mv_basetabs",
        "          dd27p_tab = lt_mv_fields",
        "        EXCEPTIONS db_access_failure = 1",
        "          others = 2.",
        "      IF sy-subrc <> 0.",
        "        lv_mv_rc = sy-subrc.",
        "        ROLLBACK WORK.",
        "        CLEAR lv_mv_rc_text.",
        "        WRITE lv_mv_rc TO lv_mv_rc_text.",
        "        CONCATENATE 'Maintenance view write failed'",
        "          lv_mv_rc_text INTO ev_message SEPARATED BY ' '.",
        "        ev_status = 'E'. ev_code = 'VIEW_WRITE_FAILED'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_mv_header_a, ls_mv_header_n, ls_mv_gotstate.",
        "      REFRESH: lt_mv_basetabs_a, lt_mv_basetabs_n.",
        "      REFRESH: lt_mv_fields_a, lt_mv_fields_n.",
        "      REFRESH: lt_mv_selconds_a, lt_mv_selconds_n.",
        "      CLEAR ls_mv_get.",
        "      ls_mv_get-view = 'M'.",
        "      CALL FUNCTION 'DD_VIEW_GET'",
        "        EXPORTING get_state = ls_mv_get",
        "          langu = sy-langu",
        "          prid = 1",
        "          view_name = lv_mv_name",
        "          withtext = 'X'",
        "        IMPORTING dd25v_wa_a = ls_mv_header_a",
        "          dd25v_wa_n = ls_mv_header_n",
        "          got_state = ls_mv_gotstate",
        "        TABLES dd26v_tab_a = lt_mv_basetabs_a",
        "          dd26v_tab_n = lt_mv_basetabs_n",
        "          dd27p_tab_a = lt_mv_fields_a",
        "          dd27p_tab_n = lt_mv_fields_n",
        "          dd28v_tab_a = lt_mv_selconds_a",
        "          dd28v_tab_n = lt_mv_selconds_n",
        "        EXCEPTIONS access_failure = 1",
        "          others = 2.",
        "      IF sy-subrc <> 0",
        "         OR ls_mv_header_n-viewname IS INITIAL.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'VIEW_WRITE_VERIFY_FAILED'.",
        "        ev_message = 'Maintenance view was not written'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      IF ls_mv_header_n-ddtext IS NOT INITIAL",
        "         AND ls_mv_header_n-ddtext <> ls_mv_requested-ddtext.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'VIEW_WRITE_VERIFY_FAILED'.",
        "        ev_message = 'Stored view text differs'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      DESCRIBE TABLE lt_mv_basetabs_n LINES lv_mv_stored_count.",
        "      IF lv_mv_stored_count <> lv_mv_tab_count.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'VIEW_WRITE_VERIFY_FAILED'.",
        "        ev_message = 'Stored base table count differs'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      SORT lt_mv_basetabs_n BY tabpos.",
        "      CLEAR lv_mv_index.",
        "      LOOP AT lt_mv_basetabs_n INTO ls_mv_basetab.",
        "        lv_mv_index = lv_mv_index + 1.",
        "        READ TABLE lt_mv_basetabs INTO ls_mv_stored_tab",
        "          INDEX lv_mv_index.",
        "        IF sy-subrc <> 0.",
        "          ROLLBACK WORK.",
        "          ev_status = 'E'.",
        "          ev_code = 'VIEW_WRITE_VERIFY_FAILED'.",
        "          ev_message = 'Stored base table is missing'.",
        "          ev_version = '1.11'. RETURN.",
        "        ENDIF.",
        "        IF ls_mv_stored_tab-tabname <> ls_mv_basetab-tabname",
        "           OR ls_mv_stored_tab-fortabname",
        "             <> ls_mv_basetab-fortabname",
        "           OR ls_mv_stored_tab-forfield",
        "             <> ls_mv_basetab-forfield",
        "           OR ls_mv_stored_tab-fordir <> ls_mv_basetab-fordir.",
        "          ROLLBACK WORK.",
        "          ev_status = 'E'.",
        "          ev_code = 'VIEW_WRITE_VERIFY_FAILED'.",
        "          ev_message = 'Stored base table differs'.",
        "          ev_version = '1.11'. RETURN.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      DESCRIBE TABLE lt_mv_fields_n LINES lv_mv_stored_count.",
        "      IF lv_mv_stored_count <> lv_mv_field_count.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'VIEW_WRITE_VERIFY_FAILED'.",
        "        ev_message = 'Stored view field count differs'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      SORT lt_mv_fields_n BY objpos.",
        "      CLEAR lv_mv_index.",
        "      LOOP AT lt_mv_fields_n INTO ls_mv_field.",
        "        lv_mv_index = lv_mv_index + 1.",
        "        READ TABLE lt_mv_fields INTO ls_mv_stored_field",
        "          INDEX lv_mv_index.",
        "        IF sy-subrc <> 0.",
        "          ROLLBACK WORK.",
        "          ev_status = 'E'.",
        "          ev_code = 'VIEW_WRITE_VERIFY_FAILED'.",
        "          ev_message = 'Stored view field is missing'.",
        "          ev_version = '1.11'. RETURN.",
        "        ENDIF.",
        "        IF ls_mv_stored_field-viewfield <> ls_mv_field-viewfield",
        "           OR ls_mv_stored_field-tabname <> ls_mv_field-tabname",
        "           OR ls_mv_stored_field-fieldname",
        "             <> ls_mv_field-fieldname.",
        "          ROLLBACK WORK.",
        "          ev_status = 'E'.",
        "          ev_code = 'VIEW_WRITE_VERIFY_FAILED'.",
        "          ev_message = 'Stored view field differs'.",
        "          ev_version = '1.11'. RETURN.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      lv_mv_actmode = '11'.",
        "      IF lv_mv_actmode <> '1' AND lv_mv_actmode <> '9'",
        "         AND lv_mv_actmode <> '11'",
        "         AND lv_mv_actmode <> '12'.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'VIEW_ACT_MODE_INVALID'.",
        "        ev_message = 'Maintenance view act mode is invalid'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      lv_mv_authchk = 'X'.",
        # DD_VIEW_ACT 只在 PROTNAME 非空时用 STDO_LOG_OPEN 打开协议日志，却在结尾无条件按 PRID
        # 写日志（STDO_OBJ_HEADER/STDO_SMI1），并在 PROTNAME 非空时用 STDO_CLOSE 关闭。
        # 只传 prid = 1 而不传 PROTNAME 时日志从未打开，SAP 的 STDO 代码访问未赋值字段符号，
        # 运行期直接 GETWA_NOT_ASSIGNED 短转储（2026-09-22 16:24:16，RADBTOU5:1005）。
        # PRID 在 DD_VIEW_ACT 里是 VALUE 参数，由日志打开过程内部赋值，故这里仍传常量即可。
        # 传入非空的协议名后由 FM 自己打开并关闭日志，不留下打开状态。
        "      CLEAR: lv_mv_dbact, lv_mv_rc.",
        "      CALL FUNCTION 'DD_VIEW_ACT'",
        "        EXPORTING viewname = lv_mv_name",
        "          get_state = 'M'",
        "          act_mode = lv_mv_actmode",
        "          auth_chk = lv_mv_authchk",
        "          prid = 1",
        "          protname = 'ZORV_MCP_VIEW_ACT'",
        "        IMPORTING rc = lv_mv_rc",
        "          dbact = lv_mv_dbact",
        "        EXCEPTIONS view_not_found = 1",
        "          parameter_error = 2",
        "          actok_failure = 3",
        "          others = 4.",
        "      IF sy-subrc <> 0.",
        "        lv_mv_rc = sy-subrc.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'VIEW_ACTIVATION_FAILED'.",
        "        ev_message = 'Maintenance view activation failed'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      IF lv_mv_rc >= 8.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'VIEW_ACTIVATION_REJECTED'.",
        "        ev_message = 'Maintenance view activation reported rc 8'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      IF lv_mv_dbact IS NOT INITIAL.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'VIEW_DB_ACTION_REQUIRED'.",
        "        ev_message = 'Maintenance view needs a database action'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_mv_tadir_input, ls_mv_tadir.",
        "      ls_mv_tadir_input-pgmid = 'R3TR'.",
        "      ls_mv_tadir_input-object = 'VIEW'.",
        "      ls_mv_tadir_input-obj_name = lv_mv_name.",
        "      ls_mv_tadir_input-srcsystem = sy-sysid.",
        "      ls_mv_tadir_input-author = sy-uname.",
        "      ls_mv_tadir_input-devclass = iv_package.",
        "      ls_mv_tadir_input-masterlang = sy-langu.",
        "      CALL FUNCTION 'TR_TADIR_INTERFACE'",
        "        EXPORTING wi_test_modus = space",
        "          wi_tadir_pgmid = ls_mv_tadir_input-pgmid",
        "          wi_tadir_object = ls_mv_tadir_input-object",
        "          wi_tadir_obj_name = ls_mv_tadir_input-obj_name",
        "          wi_tadir_srcsystem = ls_mv_tadir_input-srcsystem",
        "          wi_tadir_author = ls_mv_tadir_input-author",
        "          wi_tadir_devclass = ls_mv_tadir_input-devclass",
        "          wi_tadir_masterlang = ls_mv_tadir_input-masterlang",
        "        IMPORTING new_tadir_entry = ls_mv_tadir",
        "        EXCEPTIONS others = 1.",
        "      IF sy-subrc <> 0 OR ls_mv_tadir-devclass <> iv_package.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'VIEW_TADIR_FAILED'.",
        "        ev_message = 'Maintenance view TADIR entry failed'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_mv_objects, lt_mv_recorded.",
        "      CLEAR ls_mv_object.",
        "      MOVE-CORRESPONDING ls_mv_tadir TO ls_mv_object.",
        "      APPEND ls_mv_object TO lt_mv_objects.",
        "      CALL FUNCTION 'TR_RECORD_OBJ_CHANGE_TO_REQ'",
        # iv_request 要的是请求（E070-TRFUNCTION = 'K'），不是请求下的任务。r15 实测传任务号
        # （ls_mv_task-trkorr）被 SAP 以 TK/886「请求类型不允许」拒绝；同库同 FM 的号码范围分支
        # （iv_request = ls_nrob_request-trkorr）一直成功，故与之一致改为请求号。
        # 上面 1999-2002 行的校验已经保证 ls_mv_request 是状态 D 的 'K' 请求、任务属于当前用户。
        "        EXPORTING iv_request = ls_mv_request-trkorr",
        "          it_objects = lt_mv_objects",
        "        IMPORTING et_tadir = lt_mv_recorded",
        "        EXCEPTIONS cancel = 1.",
        # 该 FM 在内部 TRINT_OBJECTS_CHECK_AND_INSERT 失败时执行
        # `MESSAGE ID sy-msgid TYPE sy-msgty NUMBER sy-msgno WITH ... RAISING cancel`，
        # 因此拒绝原因在 sy-msg* 里。只回固定文本会让调用方无法判断是包、对象类型还是请求侧被拒
        # （r13 实测即止步于此且无任何 SAP 信息）。这里把 SAP 原文与 msgid/msgno 一并回传，
        # 与共享传输失败路径（r12）保持同一诊断口径。
        "      IF sy-subrc <> 0.",
        "        IF sy-msgid IS INITIAL.",
        "          ev_message = 'Maintenance view transport record failed'.",
        "        ELSE.",
        "          MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "            WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "            INTO ev_message.",
        "          CONCATENATE 'Maintenance view transport record failed'",
        "            ev_message '[' sy-msgid '/' sy-msgno ']'",
        "            INTO ev_message SEPARATED BY space.",
        "        ENDIF.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'VIEW_TRANSPORT_RECORD_FAILED'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      CLEAR: ls_mv_e071, lv_mv_recorded_request.",
        "      SELECT SINGLE * FROM e071 INTO ls_mv_e071",
        "        WHERE trkorr = ls_mv_task-trkorr",
        "          AND pgmid = 'R3TR' AND object = 'VIEW'",
        "          AND obj_name = lv_mv_name.",
        "      IF sy-subrc <> 0.",
        "        SELECT SINGLE * FROM e071 INTO ls_mv_e071",
        "          WHERE trkorr = ls_mv_request-trkorr",
        "            AND pgmid = 'R3TR' AND object = 'VIEW'",
        "            AND obj_name = lv_mv_name.",
        "      ENDIF.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'VIEW_TRANSPORT_VERIFY_FAILED'.",
        "        ev_message = 'Maintenance view is not in the transport'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      lv_mv_recorded_request = ls_mv_e071-trkorr.",
        "      CLEAR: ls_mv_header_a, ls_mv_header_n, ls_mv_gotstate.",
        "      REFRESH: lt_mv_basetabs_a, lt_mv_basetabs_n.",
        "      REFRESH: lt_mv_fields_a, lt_mv_fields_n.",
        "      REFRESH: lt_mv_selconds_a, lt_mv_selconds_n.",
        "      CLEAR ls_mv_get.",
        "      ls_mv_get-view = 'M'.",
        "      CALL FUNCTION 'DD_VIEW_GET'",
        "        EXPORTING get_state = ls_mv_get",
        "          langu = sy-langu",
        "          prid = 1",
        "          view_name = lv_mv_name",
        "          withtext = 'X'",
        "        IMPORTING dd25v_wa_a = ls_mv_header_a",
        "          dd25v_wa_n = ls_mv_header_n",
        "          got_state = ls_mv_gotstate",
        "        TABLES dd26v_tab_a = lt_mv_basetabs_a",
        "          dd26v_tab_n = lt_mv_basetabs_n",
        "          dd27p_tab_a = lt_mv_fields_a",
        "          dd27p_tab_n = lt_mv_fields_n",
        "          dd28v_tab_a = lt_mv_selconds_a",
        "          dd28v_tab_n = lt_mv_selconds_n",
        "        EXCEPTIONS access_failure = 1",
        "          others = 2.",
        "      IF sy-subrc <> 0 OR ls_mv_header_a-viewname IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'VIEW_ACTIVATION_VERIFY_FAILED'.",
        "        ev_message = 'Maintenance view active version is missing'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      ls_mv_header = ls_mv_header_a.",
        "      lt_mv_basetabs = lt_mv_basetabs_a.",
        "      lt_mv_fields = lt_mv_fields_a.",
        "      lt_mv_selconds = lt_mv_selconds_a.",
        "      SORT lt_mv_basetabs BY tabpos.",
        "      SORT lt_mv_fields BY objpos.",
        "      SORT lt_mv_selconds BY position.",
        "      CLEAR lv_mv_version.",
        "      CONCATENATE ls_mv_header-as4date ls_mv_header-as4time",
        "        INTO lv_mv_version.",
        "      IF ls_mv_header-roottab <> ls_mv_requested-roottab.",
        "        ev_status = 'E'.",
        "        ev_code = 'VIEW_ACTIVATION_VERIFY_FAILED'.",
        "        ev_message = 'Active view root table differs'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      CONCATENATE ls_mv_ctrl-vihd ls_mv_ctrl-vifd",
        "        ls_mv_ctrl-vibt ls_mv_ctrl-visc ls_mv_ctrl-vits",
        "        INTO lv_mv_ctrl_text.",
        "      REFRESH it_source.",
        "      add_payload 'M' '1' 'LANGUAGE' sy-langu.",
        "      add_payload 'M' '1' 'PACKAGE' ls_mv_tadir-devclass.",
        "      add_payload 'M' '1' 'VERSION' lv_mv_version.",
        "      add_payload 'M' '1' 'REQUEST' lv_mv_recorded_request.",
        "      add_payload 'M' '1' 'INACTIVE' space.",
        "      add_payload 'M' '1' 'VIEWCLASS' ls_mv_header-viewclass.",
        "      add_payload 'M' '1' 'GOTSTATE' ls_mv_gotstate-view.",
        "      add_payload 'M' '1' 'ACT_MODE' lv_mv_actmode.",
        "      add_payload 'M' '1' 'AUTH_CHK' lv_mv_authchk.",
        "      add_payload 'M' '1' 'DBACT' lv_mv_dbact.",
        "      add_payload 'M' '1' 'ACT_RC' lv_mv_rc.",
        "      add_payload 'M' '1' 'PUT_STATE' lv_mv_put_state.",
        "      add_payload 'M' '1' 'CTRL_VIEW_PUT' lv_mv_ctrl_text."
        ) + $ddicMvHeaderPayloadLines + $ddicMvBaseTabPayloadLines + $ddicMvFieldPayloadLines + $ddicMvSelCondPayloadLines + @(
        "      ev_status = 'S'. ev_code = 'MAINTENANCE_VIEW_SAVED'.",
        "      ev_message = 'Maintenance view saved and activated'.",
        "      ev_version = '1.11'. RETURN.",
        # D6-4 删维护视图。DD_VIEW_DEL 没有 EXCEPTIONS，成败只能靠回读判定（陷阱 4）：
        # 先删（DEL_STATE='M' = 所有版本），提交后同时用 DD_VIEW_GET 与 DD25L 计数证明对象已消失，
        # 再删 TADIR 项并证明它已消失。
        # D6-5 字段级 append 写入。依据 .doc/d6-5-activation-sufficiency-20260922.md §4：
        #   步骤 1 只写 append 自身的 DD03L 行（DD_TBFD_PUT，PUT_STATE='A' → 活动行）；
        #   步骤 2 直接激活**基表**（路径 2b），由 EXPAND 把 append 的活动行并进基表。
        # 明确禁止：对基表调用任何 DD_TBFD_* / DD_TABL_PUT（按 TABL_NAME 整表替换，会用残缺清单
        # 覆盖基表定义）。因此本分支只对 append 名调用 DD_TBFD_PUT，基表只出现在激活参数里。
        # 规格 §6 缺口 1（PUT_STATE='A' 时内部 DELETE 可能是空操作）不靠假设处理：写后逐字段回读
        # 比对，不一致即 APPEND_FIELDS_VERIFY_MISMATCH 并把两侧字段名一并返回，绝不静默报成功。
        "    WHEN 'UPSERT_APPEND_STRUCTURE_FIELDS'.",
        "      CLEAR: ls_ap_header, ls_ap_dd09v, lv_ap_gotstate.",
        "      CLEAR: lv_ap_tabclass, lv_ap_base, lv_ap_unchanged.",
        "      CLEAR: lv_ap_verify_ok, lv_ap_index, lv_ap_rc_text.",
        "      CLEAR: lv_ap_expected_text, lv_ap_actual_text.",
        "      CLEAR: lv_ap_field_count, lv_ap_stored_count.",
        "      CLEAR: lv_ap_base_field_count, lv_ap_base_delta_ok.",
        "      CLEAR lv_ap_base_mismatch_text.",
        "      CLEAR lv_ap_removed_text.",
        "      REFRESH: lt_ap_requested, lt_ap_expanded, lt_current_dd03p.",
        "      REFRESH: lt_ap_before, lt_ap_restore.",
        "      lv_ap_name_raw = iv_object_name.",
        "      CONDENSE lv_ap_name_raw NO-GAPS.",
        "      IF lv_ap_name_raw IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'OBJECT_NAME_REQUIRED'.",
        "        ev_message = 'Append structure name is required'.",
        "        ev_version = '1.12'. RETURN.",
        "      ENDIF.",
        "      IF lv_ap_name_raw(1) <> 'Z'",
        "         AND lv_ap_name_raw(1) <> 'Y'.",
        "        ev_status = 'E'. ev_code = 'CUSTOMER_OBJECT_REQUIRED'.",
        "        ev_message = 'Only Z or Y append structures are writable'.",
        "        ev_version = '1.12'. RETURN.",
        "      ENDIF.",
        "      lv_name_guard = lv_ap_name_raw.",
        "      IF lv_name_guard CN 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'.",
        "        ev_status = 'E'. ev_code = 'OBJECT_NAME_INVALID'.",
        "        ev_message = 'Invalid customer append structure name'.",
        "        ev_version = '1.12'. RETURN.",
        "      ENDIF.",
        "      lv_ap_name = lv_ap_name_raw.",
        "      lv_ap_name_check = lv_ap_name.",
        "      IF lv_ap_name_check <> lv_ap_name_raw.",
        "        ev_status = 'E'. ev_code = 'OBJECT_NAME_INVALID'.",
        "        ev_message = 'Append structure name is too long'.",
        "        ev_version = '1.12'. RETURN.",
        "      ENDIF.",
        "      CLEAR lv_ap_field_count.",
        "      LOOP AT it_source INTO ls_source.",
        "        CLEAR: lv_ap_kind, lv_ap_index_text.",
        "        CLEAR: lv_ap_property, lv_ap_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_ap_kind",
        "          lv_ap_index_text lv_ap_property lv_ap_value.",
        "        REPLACE ALL OCCURRENCES OF '%7C' IN lv_ap_value",
        "          WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25' IN lv_ap_value",
        "          WITH '%'.",
        "        TRANSLATE lv_ap_property TO UPPER CASE.",
        "        IF lv_ap_kind <> 'A1'.",
        "          ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "          ev_message = 'Only A1 field rows are accepted here'.",
        "          ev_version = '1.12'. RETURN.",
        "        ENDIF.",
        "        IF lv_ap_index_text IS INITIAL.",
        "          ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "          ev_message = 'Field row index is required'.",
        "          ev_version = '1.12'. RETURN.",
        "        ENDIF.",
        "        lv_ap_index = lv_ap_index_text.",
        "        IF lv_ap_index < 1",
        "           OR lv_ap_index > lv_ap_field_count + 1.",
        "          ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "          ev_message =",
        "            'Field row indexes must be contiguous from one'.",
        "          ev_version = '1.12'. RETURN.",
        "        ENDIF.",
        "        IF lv_ap_index > lv_ap_field_count.",
        "          CLEAR ls_ap_requested.",
        "          APPEND ls_ap_requested TO lt_ap_requested.",
        "          lv_ap_field_count = lv_ap_index.",
        "        ENDIF.",
        "        READ TABLE lt_ap_requested INTO ls_ap_requested",
        "          INDEX lv_ap_index.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "          ev_message = 'Field row index out of range'.",
        "          ev_version = '1.12'. RETURN.",
        "        ENDIF.",
        "        IF lv_ap_property <> 'FIELDNAME'",
        "           AND lv_ap_property <> 'ROLLNAME'",
        # 1.15：追加的透明表字段同样可能是数量/货币型，缺参考表/参考字段一样激活不了。
        "           AND lv_ap_property <> 'REFTABLE'",
        "           AND lv_ap_property <> 'REFFIELD'",
        "           AND lv_ap_property <> 'DATATYPE'",
        "           AND lv_ap_property <> 'LENG'",
        "           AND lv_ap_property <> 'DECIMALS'",
        "           AND lv_ap_property <> 'KEYFLAG'",
        "           AND lv_ap_property <> 'NOTNULL'",
        "           AND lv_ap_property <> 'CHECKTABLE'",
        "           AND lv_ap_property <> 'INTTYPE'",
        "           AND lv_ap_property <> 'LOWERCASE'",
        "           AND lv_ap_property <> 'DDTEXT'.",
        "          ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "          ev_message = 'Append field property not allowed'.",
        "          ev_version = '1.12'. RETURN.",
        "        ENDIF.",
        "        ASSIGN COMPONENT lv_ap_property",
        "          OF STRUCTURE ls_ap_requested TO <lv_component>.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "          ev_message = 'Append field property not allowed'.",
        "          ev_version = '1.12'. RETURN.",
        "        ENDIF.",
        "        <lv_component> = lv_ap_value.",
        "        MODIFY lt_ap_requested FROM ls_ap_requested",
        "          INDEX lv_ap_index.",
        "      ENDLOOP.",
        "      REFRESH it_source.",
        "      IF lt_ap_requested[] IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'FIELDS_REQUIRED'.",
        "        ev_message = 'At least one append field is required'.",
        "        ev_version = '1.12'. RETURN.",
        "      ENDIF.",
        "      CALL FUNCTION 'DDIF_TABL_GET'",
        "        EXPORTING name = lv_ap_name state = 'A'",
        "          langu = sy-langu",
        "        IMPORTING gotstate = lv_ap_gotstate",
        "          dd02v_wa = ls_ap_header",
        "          dd09l_wa = ls_ap_dd09v",
        "        TABLES dd03p_tab = lt_current_dd03p",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'DDIC_READ_FAILED'.",
        "        ev_message = 'Append structure could not be read'.",
        "        ev_version = '1.12'. RETURN.",
        "      ENDIF.",
        "      IF ls_ap_header-tabname IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'DDIC_OBJECT_NOT_FOUND'.",
        "        ev_message = 'Append structure does not exist'.",
        "        ev_version = '1.12'. RETURN.",
        "      ENDIF.",
        "      lv_ap_tabclass = ls_ap_header-tabclass.",
        # 传基表名必须被拒绝：基表的 TABCLASS 不是 APPEND（透明表是 TRANSP）。
        "      IF lv_ap_tabclass <> 'APPEND'.",
        "        ev_status = 'E'. ev_code = 'NOT_AN_APPEND_STRUCTURE'.",
        "        ev_message =",
        "          'Not an append structure: name the append, not its base'.",
        "        ev_version = '1.12'. RETURN.",
        "      ENDIF.",
        "      lv_ap_base = ls_ap_header-sqltab.",
        "      IF lv_ap_base IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'APPEND_BASE_TABLE_MISSING'.",
        "        ev_message = 'Append structure has no base table'.",
        "        ev_version = '1.12'. RETURN.",
        "      ENDIF.",
        "      IF lv_ap_gotstate <> 'A'.",
        "        ev_status = 'E'. ev_code = 'INACTIVE_VERSION_EXISTS'.",
        "        ev_message = 'Append structure has an inactive version'.",
        "        ev_version = '1.12'. RETURN.",
        "      ENDIF.",
        # 并发令牌：本操作不走 lv_write 通用管线（无 lv_object_type 派发），
        # 必须在本地等价校验，否则 expectedVersion 形同虚设、丢失更新不可检测。
        # 令牌与读取路径同构：活动版本 as4date + as4time（14 位）。
        "      IF iv_expected_version IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'EXPECTED_VERSION_REQUIRED'.",
        "        ev_message =",
        "          'Existing append structure requires version token'.",
        "        ev_version = '1.12'. RETURN.",
        "      ENDIF.",
        # D-4：令牌优先按**字段集指纹**判定，与读取路径同构（都取 state='A' 的字段行）。
        # 指纹覆盖 POSITION/FIELDNAME/ROLLNAME，按位置排序后拼接，与读取顺序无关。
        "      REFRESH lt_ap_fp.",
        "      CLEAR lv_ap_fp_source.",
        "      LOOP AT lt_current_dd03p INTO ls_ap_stored.",
        "        CONCATENATE ls_ap_stored-position ls_ap_stored-fieldname",
        "          ls_ap_stored-rollname INTO lv_ap_fp_line SEPARATED BY ':'.",
        "        APPEND lv_ap_fp_line TO lt_ap_fp.",
        "      ENDLOOP.",
        "      SORT lt_ap_fp.",
        "      CLEAR lv_ap_fp_line.",
        "      LOOP AT lt_ap_fp INTO lv_ap_fp_line.",
        "        IF lv_ap_fp_source IS INITIAL.",
        "          lv_ap_fp_source = lv_ap_fp_line.",
        "        ELSE.",
        "          CONCATENATE lv_ap_fp_source lv_ap_fp_line",
        "            INTO lv_ap_fp_source SEPARATED BY '|'.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      CLEAR lv_ap_fingerprint.",
        "      CALL FUNCTION 'CALCULATE_HASH_FOR_CHAR'",
        "        EXPORTING alg = 'SHA1' data = lv_ap_fp_source",
        "        IMPORTING hash = lv_ap_fingerprint",
        "        EXCEPTIONS OTHERS = 1.",
        # 指纹命中即通过；否则退回 14 位版本号比较（向后兼容既有调用方）。
        "      IF iv_expected_version = lv_ap_fingerprint.",
        "        lv_ap_guard = 'FINGERPRINT'.",
        "      ELSE.",
        "        CONCATENATE ls_ap_header-as4date ls_ap_header-as4time",
        "          INTO lv_ap_current_version.",
        "        IF iv_expected_version <> lv_ap_current_version.",
        "          ev_status = 'E'. ev_code = 'VERSION_CONFLICT'.",
        "          ev_message =",
        "            'Append structure changed since it was read'.",
        "          ev_version = '1.12'. RETURN.",
        "        ENDIF.",
        "        lv_ap_guard = 'VERSION'.",
        "      ENDIF.",
        "      LOOP AT lt_ap_requested INTO ls_ap_requested.",
        "        IF ls_ap_requested-fieldname IS INITIAL",
        "           OR ls_ap_requested-rollname IS INITIAL.",
        "          ev_status = 'E'. ev_code = 'FIELDS_REQUIRED'.",
        "          ev_message =",
        "            'Each append field needs a name and a data element'.",
        "          ev_version = '1.12'. RETURN.",
        "        ENDIF.",
        "        IF ls_ap_requested-keyflag IS NOT INITIAL",
        "           OR ls_ap_requested-notnull IS NOT INITIAL.",
        "          ev_status = 'E'. ev_code = 'UNSAFE_TABLE_CHANGE'.",
        "          ev_message = 'Only nullable non-key fields may append'.",
        "          ev_version = '1.12'. RETURN.",
        "        ENDIF.",
        "        CLEAR: ls_reference_dd04v, lv_reference_state.",
        "        CALL FUNCTION 'DDIF_DTEL_GET'",
        "          EXPORTING name = ls_ap_requested-rollname state = 'A'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_reference_state",
        "            dd04v_wa = ls_reference_dd04v",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc <> 0 OR lv_reference_state <> 'A'.",
        "          ev_status = 'E'. ev_code = 'REFERENCE_NOT_FOUND'.",
        "          ev_message = 'Active data element reference not found'.",
        "          ev_version = '1.12'. RETURN.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      CLEAR lv_ap_index.",
        "      LOOP AT lt_ap_requested ASSIGNING <ls_ap_field>.",
        "        lv_ap_index = lv_ap_index + 1.",
        "        <ls_ap_field>-tabname = lv_ap_name.",
        "        <ls_ap_field>-ddlanguage = sy-langu.",
        "        <ls_ap_field>-position = lv_ap_index.",
        "        <ls_ap_field>-comptype = 'E'.",
        # 不要在这里写 AS4LOCAL / AS4VERS：DD03P（w200 实测 70 个组件）没有这两个字段。
        # 2026-09-23 首次 F8 实证：GENERATE 报 `数据对象 "<LS_AP_FIELD>" 没有名为 "AS4LOCAL" 的组件`。
        # 版本定位由 DD_TBFD_PUT 的 PUT_STATE='A' 决定（写 AS4LOCAL='A' 的活动行），
        # 与既有可用的 APPEND_TRANSPARENT_TABLE_FIELDS 分支保持一致：它也只设
        # TABNAME / DDLANGUAGE / COMPTYPE / POSITION。
        "        <ls_ap_field>-adminfield = '0'.",
        "      ENDLOOP.",
        "      DESCRIBE TABLE lt_ap_requested LINES lv_ap_field_count.",
        "      DESCRIBE TABLE lt_current_dd03p LINES lv_ap_stored_count.",
        "      lv_ap_unchanged = 'X'.",
        "      IF lv_ap_stored_count <> lv_ap_field_count.",
        "        lv_ap_unchanged = space.",
        "      ELSE.",
        "        LOOP AT lt_ap_requested INTO ls_ap_requested.",
        "          CLEAR ls_ap_stored.",
        "          READ TABLE lt_current_dd03p INTO ls_ap_stored",
        "            WITH KEY fieldname = ls_ap_requested-fieldname.",
        "          IF sy-subrc <> 0.",
        "            lv_ap_unchanged = space. EXIT.",
        "          ENDIF.",
        "          IF ls_ap_stored-rollname <> ls_ap_requested-rollname.",
        "            lv_ap_unchanged = space. EXIT.",
        "          ENDIF.",
        "        ENDLOOP.",
        "      ENDIF.",
        "      IF lv_ap_unchanged = 'X'.",
        "        ev_status = 'S'. ev_code = 'APPEND_FIELDS_UNCHANGED'.",
        "        ev_message =",
        "          'Append structure fields already match the request'.",
        "        ev_version = '1.12'.",
        "        add_payload 'M' '1' 'APPEND' lv_ap_name.",
        "        add_payload 'M' '1' 'BASE_TABLE' lv_ap_base.",
        "        add_payload 'M' '1' 'FIELD_COUNT' lv_ap_field_count.",
        "        add_payload 'M' '1' 'CHANGED' space.",
        "        RETURN.",
        "      ENDIF.",
        # 字段删减在本系统上不会传播到基表（实测：追加结构的行删掉了，基表仍保留该列），
        # 因此不可能成功。与其"先改坏再补偿"，不如在写入前直接拒绝。
        "      CLEAR lv_ap_removed_text.",
        "      LOOP AT lt_current_dd03p INTO ls_ap_stored.",
        "        READ TABLE lt_ap_requested TRANSPORTING NO FIELDS",
        "          WITH KEY fieldname = ls_ap_stored-fieldname.",
        "        IF sy-subrc <> 0.",
        "          CONCATENATE lv_ap_removed_text ls_ap_stored-fieldname",
        "            INTO lv_ap_removed_text SEPARATED BY ','.",
        "        ENDIF.",
        "      ENDLOOP.",
        # CONCATENATE ... SEPARATED BY 在左值为初始时仍会插入分隔符，故此处去掉前导逗号。
        "      SHIFT lv_ap_removed_text LEFT DELETING LEADING ','.",
        "      IF lv_ap_removed_text IS NOT INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'APPEND_FIELD_REMOVAL_NOT_SUPPORTED'.",
        "        ev_message = 'Append fields cannot be removed'.",
        "        CONCATENATE ev_message",
        "          '; the change does not reach the base table'",
        "          INTO ev_message.",
        "        ev_version = '1.12'.",
        "        add_payload 'M' '1' 'APPEND' lv_ap_name.",
        "        add_payload 'M' '1' 'BASE_TABLE' lv_ap_base.",
        "        add_payload 'M' '1' 'REMOVED_FIELDS' lv_ap_removed_text.",
        "        add_payload 'M' '1' 'CHANGED' space.",
        "        RETURN.",
        "      ENDIF.",
        # 保存调用前的追加字段集：补偿仍作为其它验证不符情形的兜底。
        "      lt_ap_before[] = lt_current_dd03p[].",
        "      CALL FUNCTION 'DD_TBFD_PUT'",
        "        EXPORTING tabl_name = lv_ap_name",
        "          put_state = 'A'",
        "        TABLES dd03p_tab = lt_ap_requested",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        lv_ap_rc_text = sy-subrc.",
        "        ev_status = 'E'. ev_code = 'APPEND_FIELDS_WRITE_FAILED'.",
        "        ev_message = 'Append field rows could not be written'.",
        "        ev_version = '1.12'.",
        "        add_payload 'M' '1' 'APPEND' lv_ap_name.",
        "        add_payload 'M' '1' 'BASE_TABLE' lv_ap_base.",
        "        add_payload 'M' '1' 'PUT_SUBRC' lv_ap_rc_text.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR lv_rc.",
        "      CALL FUNCTION 'DDIF_TABL_ACTIVATE'",
        "        EXPORTING name = lv_ap_base auth_chk = 'X'",
        "          excommit = 'X'",
        "        IMPORTING rc = lv_rc",
        "        EXCEPTIONS OTHERS = 1.",
        # DDIF_TABL_ACTIVATE 的 RC 是 DD_TABL_ACT 的 ACT_RESULT，不是成功标志：
        # 只有异常（sy-subrc）才是硬失败。实测新增成功时 RC 亦非零，按 RC 判定会误报失败。
        # 真正的成败一律由下面的写后回读（追加结构 + 基表）判定。
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        lv_ap_rc_text = lv_rc.",
        "        ev_status = 'E'. ev_code = 'BASE_TABLE_ACTIVATION_FAILED'.",
        "        ev_message = 'Base table activation raised an exception'.",
        "        ev_version = '1.12'.",
        "        add_payload 'M' '1' 'APPEND' lv_ap_name.",
        "        add_payload 'M' '1' 'BASE_TABLE' lv_ap_base.",
        "        add_payload 'M' '1' 'ACT_RC' lv_ap_rc_text.",
        "        add_payload 'M' '1' 'COMPENSATION_REQUIRED' 'X'.",
        "        RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      CLEAR: ls_ap_header, lv_ap_gotstate.",
        "      REFRESH lt_current_dd03p.",
        "      CALL FUNCTION 'DDIF_TABL_GET'",
        "        EXPORTING name = lv_ap_name state = 'A'",
        "          langu = sy-langu",
        "        IMPORTING gotstate = lv_ap_gotstate",
        "          dd02v_wa = ls_ap_header",
        "        TABLES dd03p_tab = lt_current_dd03p",
        "        EXCEPTIONS OTHERS = 1.",
        "      lv_ap_verify_ok = 'X'.",
        "      IF sy-subrc <> 0.",
        "        lv_ap_verify_ok = space.",
        "      ELSE.",
        "        DESCRIBE TABLE lt_current_dd03p LINES lv_ap_stored_count.",
        "        IF lv_ap_stored_count <> lv_ap_field_count.",
        "          lv_ap_verify_ok = space.",
        "        ELSE.",
        "          LOOP AT lt_ap_requested INTO ls_ap_requested.",
        "            CLEAR ls_ap_stored.",
        "            READ TABLE lt_current_dd03p INTO ls_ap_stored",
        "              WITH KEY fieldname = ls_ap_requested-fieldname.",
        "            IF sy-subrc <> 0.",
        "              lv_ap_verify_ok = space. EXIT.",
        "            ENDIF.",
        "            IF ls_ap_stored-rollname",
        "               <> ls_ap_requested-rollname.",
        "              lv_ap_verify_ok = space. EXIT.",
        "            ENDIF.",
        "          ENDLOOP.",
        "        ENDIF.",
        "      ENDIF.",
        # 基表的展开行数：证明 append 的活动行确实被 EXPAND 并进了基表（D6-5 的验收要点）。
        "      CLEAR: ls_ap_header, lv_ap_gotstate.",
        "      REFRESH lt_ap_expanded.",
        "      CALL FUNCTION 'DDIF_TABL_GET'",
        "        EXPORTING name = lv_ap_base state = 'A'",
        "          langu = sy-langu",
        "        IMPORTING gotstate = lv_ap_gotstate",
        "          dd02v_wa = ls_ap_header",
        "        TABLES dd03p_tab = lt_ap_expanded",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc = 0.",
        "        DESCRIBE TABLE lt_ap_expanded",
        "          LINES lv_ap_base_field_count.",
        "      ENDIF.",
        # 删减传播校验（D-2）：请求移除的字段必须真的从基表消失，请求保留/新增的字段必须出现在基表。
        # 只校验追加结构会漏掉"追加已改、基表残留旧列"的不一致，实测该情形确实发生过。
        "      lv_ap_base_delta_ok = 'X'.",
        "      LOOP AT lt_ap_before INTO ls_ap_stored.",
        "        READ TABLE lt_ap_requested TRANSPORTING NO FIELDS",
        "          WITH KEY fieldname = ls_ap_stored-fieldname.",
        "        IF sy-subrc <> 0.",
        "          READ TABLE lt_ap_expanded TRANSPORTING NO FIELDS",
        "            WITH KEY fieldname = ls_ap_stored-fieldname.",
        "          IF sy-subrc = 0.",
        "            lv_ap_base_delta_ok = space.",
        "            CONCATENATE lv_ap_base_mismatch_text",
        "              ls_ap_stored-fieldname",
        "              INTO lv_ap_base_mismatch_text SEPARATED BY ','.",
        "          ENDIF.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      LOOP AT lt_ap_requested INTO ls_ap_requested.",
        "        READ TABLE lt_ap_expanded TRANSPORTING NO FIELDS",
        "          WITH KEY fieldname = ls_ap_requested-fieldname.",
        "        IF sy-subrc <> 0.",
        "          lv_ap_base_delta_ok = space.",
        "          CONCATENATE lv_ap_base_mismatch_text",
        "            ls_ap_requested-fieldname",
        "            INTO lv_ap_base_mismatch_text SEPARATED BY ','.",
        "        ENDIF.",
        "      ENDLOOP.",
        # 同上去掉前导逗号。
        "      SHIFT lv_ap_base_mismatch_text LEFT DELETING LEADING ','.",
        "      CLEAR: lv_ap_expected_text, lv_ap_actual_text.",
        "      LOOP AT lt_ap_requested INTO ls_ap_requested.",
        "        IF lv_ap_expected_text IS INITIAL.",
        "          lv_ap_expected_text = ls_ap_requested-fieldname.",
        "        ELSE.",
        "          CONCATENATE lv_ap_expected_text",
        "            ls_ap_requested-fieldname",
        "            INTO lv_ap_expected_text SEPARATED BY ','.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      LOOP AT lt_current_dd03p INTO ls_ap_stored.",
        "        IF lv_ap_actual_text IS INITIAL.",
        "          lv_ap_actual_text = ls_ap_stored-fieldname.",
        "        ELSE.",
        "          CONCATENATE lv_ap_actual_text ls_ap_stored-fieldname",
        "            INTO lv_ap_actual_text SEPARATED BY ','.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      add_payload 'M' '1' 'APPEND' lv_ap_name.",
        "      add_payload 'M' '1' 'BASE_TABLE' lv_ap_base.",
        "      add_payload 'M' '1' 'FIELD_COUNT' lv_ap_field_count.",
        "      add_payload 'M' '1' 'BASE_FIELD_COUNT'",
        "        lv_ap_base_field_count.",
        "      IF lv_ap_verify_ok IS INITIAL OR lv_ap_base_delta_ok IS INITIAL.",
        # 补偿（D-1）：DD_TBFD_PUT 已改动追加结构，且该改动无法被 ROLLBACK 撤销。
        # 若就此返回，对象会停在"追加已改、基表未改"的不一致状态（实测发生过）。
        # 因此把追加结构恢复为调用前的字段集并重新激活，并把补偿结果如实回传。
        "        REFRESH lt_ap_restore.",
        "        CLEAR lv_ap_index.",
        "        LOOP AT lt_ap_before INTO ls_ap_stored.",
        "          CLEAR ls_ap_restore.",
        "          lv_ap_index = lv_ap_index + 1.",
        "          ls_ap_restore-tabname = lv_ap_name.",
        "          ls_ap_restore-ddlanguage = sy-langu.",
        "          ls_ap_restore-position = lv_ap_index.",
        "          ls_ap_restore-comptype = 'E'.",
        "          ls_ap_restore-adminfield = '0'.",
        "          ls_ap_restore-fieldname = ls_ap_stored-fieldname.",
        "          ls_ap_restore-rollname = ls_ap_stored-rollname.",
        "          APPEND ls_ap_restore TO lt_ap_restore.",
        "        ENDLOOP.",
        "        CALL FUNCTION 'DD_TBFD_PUT'",
        "          EXPORTING tabl_name = lv_ap_name",
        "            put_state = 'A'",
        "          TABLES dd03p_tab = lt_ap_restore",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc = 0.",
        "          CLEAR lv_rc.",
        "          CALL FUNCTION 'DDIF_TABL_ACTIVATE'",
        "            EXPORTING name = lv_ap_base auth_chk = 'X'",
        "              excommit = 'X'",
        "            IMPORTING rc = lv_rc",
        "            EXCEPTIONS OTHERS = 1.",
        "          IF sy-subrc = 0.",
        "            add_payload 'M' '1' 'COMPENSATED' 'X'.",
        "          ELSE.",
        "            add_payload 'M' '1' 'COMPENSATED' 'N'.",
        "          ENDIF.",
        "        ELSE.",
        "          add_payload 'M' '1' 'COMPENSATED' 'N'.",
        "        ENDIF.",
        "        ev_status = 'E'.",
        "        ev_code = 'APPEND_FIELDS_VERIFY_MISMATCH'.",
        "        ev_message =",
        "          'Append field rows do not match the request after activation'.",
        "        ev_version = '1.12'.",
        "        add_payload 'M' '1' 'EXPECTED_FIELDS'",
        "          lv_ap_expected_text.",
        "        add_payload 'M' '1' 'ACTUAL_FIELDS' lv_ap_actual_text.",
        "        add_payload 'M' '1' 'BASE_MISMATCH'",
        "          lv_ap_base_mismatch_text.",
        "        add_payload 'M' '1' 'CHANGED' 'X'.",
        "        RETURN.",
        "      ENDIF.",
        "      ev_status = 'S'. ev_code = 'APPEND_FIELDS_SAVED'.",
        "      ev_message = 'Append fields written and base table activated'.",
        "      ev_version = '1.12'.",
        "      add_payload 'M' '1' 'CHANGED' 'X'.",
        # 说明本次并发校验是靠指纹还是靠 14 位版本号命中的，便于运行时确认 D-4 生效。
        "      add_payload 'M' '1' 'GUARD' lv_ap_guard.",
        "      RETURN.",
        "    WHEN 'DELETE_MAINTENANCE_VIEW'.",
        "      CLEAR: ls_mv_header, ls_mv_header_a, ls_mv_header_n.",
        "      CLEAR: lv_mv_version, lv_mv_exists, lv_mv_viewclass.",
        "      CLEAR: ls_mv_tadir, lv_mv_tadir_removed.",
        "      CLEAR: lv_mv_dd25l_count, lv_mv_check_value.",
        "      CLEAR: lv_mv_delete_state, ls_mv_get.",
        "      REFRESH: lt_mv_basetabs_a, lt_mv_basetabs_n.",
        "      REFRESH: lt_mv_fields_a, lt_mv_fields_n.",
        "      REFRESH: lt_mv_selconds_a, lt_mv_selconds_n.",
        "      REFRESH it_source.",
        "      lv_mv_name_raw = iv_object_name.",
        "      CONDENSE lv_mv_name_raw NO-GAPS.",
        "      IF lv_mv_name_raw IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'OBJECT_NAME_REQUIRED'.",
        "        ev_message = 'Maintenance view name is required'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      lv_mv_name = lv_mv_name_raw.",
        "      lv_mv_name_check = lv_mv_name.",
        "      IF lv_mv_name_check <> lv_mv_name_raw.",
        "        ev_status = 'E'. ev_code = 'OBJECT_NAME_INVALID'.",
        "        ev_message = 'Maintenance view name is too long'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      ls_mv_get-view = 'M'.",
        "      CALL FUNCTION 'DD_VIEW_GET'",
        "        EXPORTING get_state = ls_mv_get",
        "          langu = sy-langu",
        "          prid = 1",
        "          view_name = lv_mv_name",
        "          withtext = 'X'",
        "        IMPORTING dd25v_wa_a = ls_mv_header_a",
        "          dd25v_wa_n = ls_mv_header_n",
        "          got_state = ls_mv_gotstate",
        "        TABLES dd26v_tab_a = lt_mv_basetabs_a",
        "          dd26v_tab_n = lt_mv_basetabs_n",
        "          dd27p_tab_a = lt_mv_fields_a",
        "          dd27p_tab_n = lt_mv_fields_n",
        "          dd28v_tab_a = lt_mv_selconds_a",
        "          dd28v_tab_n = lt_mv_selconds_n",
        "        EXCEPTIONS access_failure = 1",
        "          others = 2.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'DDIC_READ_FAILED'.",
        "        ev_message = 'Maintenance view could not be read'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      IF ls_mv_header_a-viewname IS NOT INITIAL.",
        "        ls_mv_header = ls_mv_header_a.",
        "        lv_mv_exists = 'X'.",
        "      ELSEIF ls_mv_header_n-viewname IS NOT INITIAL.",
        "        ls_mv_header = ls_mv_header_n.",
        "        lv_mv_exists = 'X'.",
        "      ENDIF.",
        "      IF lv_mv_exists IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'DDIC_OBJECT_NOT_FOUND'.",
        "        ev_message = 'Maintenance view does not exist'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      lv_mv_viewclass = ls_mv_header-viewclass.",
        "      IF lv_mv_viewclass IS NOT INITIAL",
        "         AND lv_mv_viewclass <> 'C'.",
        "        ev_status = 'E'. ev_code = 'VIEW_CLASS_NOT_SUPPORTED'.",
        "        ev_message = 'Only maintenance views can be deleted here'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      CONCATENATE ls_mv_header-as4date ls_mv_header-as4time",
        "        INTO lv_mv_version.",
        "      IF iv_expected_version IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'VERSION_REQUIRED'.",
        "        ev_message = 'expectedVersion is required to delete it'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      IF lv_mv_version <> iv_expected_version.",
        "        ev_status = 'E'. ev_code = 'VERSION_MISMATCH'.",
        "        ev_message = 'Maintenance view changed since read'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      CLEAR ls_mv_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_mv_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'VIEW'",
        "          AND obj_name = lv_mv_name.",
        "      IF sy-subrc = 0",
        "         AND ls_mv_tadir-devclass <> iv_package.",
        "        ev_status = 'E'. ev_code = 'PACKAGE_MISMATCH'.",
        "        ev_message = 'View belongs to another package'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      lv_mv_delete_state = 'M'.",
        "      CALL FUNCTION 'DD_VIEW_DEL'",
        "        EXPORTING viewname = lv_mv_name",
        "          del_state = lv_mv_delete_state",
        "          prid = 1.",
        "      COMMIT WORK AND WAIT.",
        "      CLEAR lv_mv_dd25l_count.",
        "      SELECT COUNT( * ) FROM dd25l INTO lv_mv_dd25l_count",
        "        WHERE viewname = lv_mv_name.",
        "      CLEAR: ls_mv_header_a, ls_mv_header_n, ls_mv_gotstate.",
        "      REFRESH: lt_mv_basetabs_a, lt_mv_basetabs_n.",
        "      REFRESH: lt_mv_fields_a, lt_mv_fields_n.",
        "      REFRESH: lt_mv_selconds_a, lt_mv_selconds_n.",
        "      CLEAR ls_mv_get.",
        "      ls_mv_get-view = 'M'.",
        "      CALL FUNCTION 'DD_VIEW_GET'",
        "        EXPORTING get_state = ls_mv_get",
        "          langu = sy-langu",
        "          prid = 1",
        "          view_name = lv_mv_name",
        "          withtext = 'X'",
        "        IMPORTING dd25v_wa_a = ls_mv_header_a",
        "          dd25v_wa_n = ls_mv_header_n",
        "          got_state = ls_mv_gotstate",
        "        TABLES dd26v_tab_a = lt_mv_basetabs_a",
        "          dd26v_tab_n = lt_mv_basetabs_n",
        "          dd27p_tab_a = lt_mv_fields_a",
        "          dd27p_tab_n = lt_mv_fields_n",
        "          dd28v_tab_a = lt_mv_selconds_a",
        "          dd28v_tab_n = lt_mv_selconds_n",
        "        EXCEPTIONS access_failure = 1",
        "          others = 2.",
        "      IF ls_mv_header_a-viewname IS NOT INITIAL",
        "         OR ls_mv_header_n-viewname IS NOT INITIAL",
        "         OR lv_mv_dd25l_count <> 0.",
        "        ev_status = 'E'. ev_code = 'VIEW_DELETE_VERIFY_FAILED'.",
        "        ev_message = 'Maintenance view is still present'.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      IF ls_mv_tadir IS NOT INITIAL.",
        "        CALL FUNCTION 'TR_TADIR_INTERFACE'",
        "          EXPORTING wi_delete_tadir_entry = 'X'",
        "            wi_test_modus = space",
        "            wi_tadir_pgmid = ls_mv_tadir-pgmid",
        "            wi_tadir_object = ls_mv_tadir-object",
        "            wi_tadir_obj_name = ls_mv_tadir-obj_name",
        "          EXCEPTIONS others = 1.",
        "        IF sy-subrc = 0.",
        "          COMMIT WORK AND WAIT.",
        "          CLEAR lv_mv_check_value.",
        "          SELECT SINGLE pgmid FROM tadir INTO lv_mv_check_value",
        "            WHERE pgmid = ls_mv_tadir-pgmid",
        "              AND object = ls_mv_tadir-object",
        "              AND obj_name = ls_mv_tadir-obj_name.",
        "          IF sy-subrc <> 0.",
        "            lv_mv_tadir_removed = 'X'.",
        "          ENDIF.",
        "        ENDIF.",
        "      ENDIF.",
        "      add_payload 'M' '1' 'PACKAGE' ls_mv_tadir-devclass.",
        "      add_payload 'M' '1' 'VERSION' lv_mv_version.",
        "      add_payload 'M' '1' 'REQUEST' ls_mv_tadir-korrnum.",
        "      add_payload 'M' '1' 'TADIR_ENTRY_REMOVED' lv_mv_tadir_removed.",
        "      ev_status = 'S'. ev_code = 'MAINTENANCE_VIEW_DELETED'.",
        "      ev_message = 'Maintenance view deleted'.",
        "      ev_version = '1.11'. RETURN.",
        "    WHEN OTHERS.",
        "      ev_status = 'E'. ev_code = 'OPERATION_NOT_SUPPORTED'.",
        "      ev_message = 'Unsupported DDIC operation'.",
        "      ev_version = '1.2'. RETURN.",
        "  ENDCASE.",
        "  IF iv_object_name IS INITIAL.",
        "    ev_status = 'E'. ev_code = 'OBJECT_NAME_REQUIRED'.",
        "    ev_message = 'DDIC object name is required'.",
        "    ev_version = '1.2'. RETURN.",
        "  ENDIF.",
        "  lv_ddic_name = iv_object_name.",
        "  IF lv_write = 'X'.",
        # ENQU 是唯一一个 SAP 自己就给客户对象加 E 前缀的 DDIC 家族：表 T 的锁对象通常命名为 ET。
        # 这条共享守卫原来只认 Z/Y 开头，于是服务端 0.47.16 已经放行的 EZPMCTPRP 到这里仍被拦
        # （2026-09-24 21:22 事件），调用方看到的是「公开说明允许、后端拒绝」。客户判定必须落在
        # 可选 E 之后的那个字符上；标准对象（EMARA）没有 Z/Y 紧随其后，仍然被拒。
        "    lv_customer_name = ''.",
        "    IF iv_object_name(1) = 'Z' OR iv_object_name(1) = 'Y'.",
        "      lv_customer_name = 'X'.",
        "    ENDIF.",
        "    IF lv_object_type = 'ENQU' AND iv_object_name(1) = 'E'.",
        "      IF iv_object_name+1(1) = 'Z' OR iv_object_name+1(1) = 'Y'.",
        "        lv_customer_name = 'X'.",
        "      ENDIF.",
        "    ENDIF.",
        "    IF lv_customer_name IS INITIAL.",
        "      ev_status = 'E'. ev_code = 'CUSTOMER_OBJECT_REQUIRED'.",
        "      ev_message = 'Only Z or Y, or E plus Z or Y for a lock object'.",
        "      ev_version = '1.2'. RETURN.",
        "    ENDIF.",
        "    lv_value = iv_object_name.",
        "    CONDENSE lv_value NO-GAPS.",
        "    IF lv_value CN 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'.",
        "      ev_status = 'E'. ev_code = 'OBJECT_NAME_INVALID'.",
        "      ev_message = 'Invalid customer DDIC object name'.",
        "      ev_version = '1.2'. RETURN.",
        "    ENDIF.",
        "    IF iv_package IS INITIAL OR iv_package = '`$TMP'",
        "       OR iv_request IS INITIAL",
        "       OR ( iv_description IS INITIAL AND lv_delete IS INITIAL",
        "         AND lv_append IS INITIAL AND lv_patch IS INITIAL",
        "         AND lv_settings IS INITIAL AND lv_recover IS INITIAL",
        # 1.13：resume 不再置 lv_recover，因此必须在这里与 recover 并列，否则一次不带 description
        # 的恢复激活会被 WRITE_INPUT_REQUIRED 拦下（服务端目前会填 description，但这条守卫的语义
        # 是『这些操作不需要描述』，不该依赖调用方恰好补了一个无关字段）。
        "         AND lv_resume IS INITIAL ).",
        "      ev_status = 'E'. ev_code = 'WRITE_INPUT_REQUIRED'.",
        "      ev_message = 'Description package and request required'.",
        "      ev_version = '1.2'. RETURN.",
        "    ENDIF.",
        "  ENDIF.",
        "  IF lv_write = 'X'.",
        "    LOOP AT it_source INTO ls_source.",
        "      CLEAR: lv_kind, lv_index_text, lv_property, lv_value.",
        "      SPLIT ls_source-line AT '|' INTO lv_kind lv_index_text",
        "        lv_property lv_value.",
        "      IF lv_index_text IS INITIAL",
        "         OR lv_index_text CN '0123456789'.",
        "        ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "        ev_message = 'DDIC payload index is invalid'.",
        "        ev_version = '1.2'. RETURN.",
        "      ENDIF.",
        "      lv_index = lv_index_text.",
        "      TRANSLATE lv_property TO UPPER CASE.",
        "      REPLACE ALL OCCURRENCES OF '%7C' IN lv_value WITH '|'.",
        "      REPLACE ALL OCCURRENCES OF '%25' IN lv_value WITH '%'.",
        "      IF lv_index <= 0 OR lv_property IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "        ev_message = 'DDIC payload is invalid'.",
        "        ev_version = '1.2'. RETURN.",
        "      ENDIF.",
        "      UNASSIGN <lv_component>.",
        "      CASE lv_kind.",
        "        WHEN 'H'.",
        "          IF lv_index <> 1.",
        "            ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "            ev_message = 'Header index must be one'.",
        "            ev_version = '1.2'. RETURN.",
        "          ENDIF.",
        "          CASE lv_object_type.",
        "            WHEN 'DOMA'.",
        "              IF lv_property <> 'DATATYPE'",
        "                 AND lv_property <> 'LENG'",
        "                 AND lv_property <> 'OUTPUTLEN'",
        "                 AND lv_property <> 'DECIMALS'",
        "                 AND lv_property <> 'LOWERCASE'",
        "                 AND lv_property <> 'SIGNFLAG'",
        "                 AND lv_property <> 'ENTITYTAB'",
        "                 AND lv_property <> 'CONVEXIT'.",
        "                ev_status = 'E'.",
        "                ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "                ev_message = 'Domain property not allowed'.",
        "                ev_version = '1.2'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'DATATYPE'",
        "                 AND lv_value <> 'CHAR' AND lv_value <> 'NUMC'",
        "                 AND lv_value <> 'DEC' AND lv_value <> 'DATS'",
        "                 AND lv_value <> 'TIMS'.",
        "                ev_status = 'E'. ev_code = 'DATATYPE_INVALID'.",
        "                ev_message = 'Unsupported domain data type'.",
        "                ev_version = '1.2'. RETURN.",
        "              ENDIF.",
        "              IF ( lv_property = 'LENG'",
        "                   OR lv_property = 'OUTPUTLEN'",
        "                   OR lv_property = 'DECIMALS' )",
        "                 AND ( lv_value IS INITIAL",
        "                   OR lv_value CN '0123456789' ).",
        "                ev_status = 'E'. ev_code = 'NUMBER_INVALID'.",
        "                ev_message = 'Domain length or decimals invalid'.",
        "                ev_version = '1.2'. RETURN.",
        "              ENDIF.",
        "              IF ( lv_property = 'LOWERCASE'",
        "                   OR lv_property = 'SIGNFLAG' )",
        "                 AND lv_value IS NOT INITIAL AND lv_value <> 'X'.",
        "                ev_status = 'E'. ev_code = 'FLAG_INVALID'.",
        "                ev_message = 'Domain flag must be X or empty'.",
        "                ev_version = '1.2'. RETURN.",
        "              ENDIF.",
        "              ASSIGN COMPONENT lv_property",
        "                OF STRUCTURE ls_dd01v TO <lv_component>.",
        "            WHEN 'SHLP'.",
        "              IF lv_property = 'ACTFLAG'",
        "                 OR lv_property = 'AS4DATE'",
        "                 OR lv_property = 'AS4TIME'",
        "                 OR lv_property = 'AS4USER'",
        "                 OR lv_property = 'ATTACHEXI'",
        "                 OR lv_property = 'ELEMEXI'",
        "                 OR lv_property = 'NOFIELDS'",
        "                 OR lv_property = 'DDLANGUAGE'.",
        "                ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "                CONCATENATE 'Derived or server-controlled'",
        "                ' search help property' INTO ev_message.",
        "                ev_version = '1.8'. RETURN.",
        "              ENDIF.",
        "              ASSIGN COMPONENT lv_property",
        "                OF STRUCTURE ls_dd30v TO <lv_component>.",
        "            WHEN 'ENQU'.",
        "              IF lv_property = 'LOCKOBJECT'",
        "                 OR lv_property = 'VIEWNAME'",
        "                 OR lv_property = 'ACTFLAG'",
        "                 OR lv_property = 'AS4DATE'",
        "                 OR lv_property = 'AS4TIME'",
        "                 OR lv_property = 'AS4USER'",
        "                 OR lv_property = 'DDLANGUAGE'.",
        "                ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "                CONCATENATE 'Derived or server-controlled'",
        "                ' lock object property' INTO ev_message.",
        "                ev_version = '1.9'. RETURN.",
        "              ENDIF.",
        "              ASSIGN COMPONENT lv_property",
        "                OF STRUCTURE ls_dd25v TO <lv_component>.",
        "            WHEN 'DTEL'.",
        "              IF lv_property <> 'DOMNAME'",
        "                 AND lv_property <> 'REPTEXT'",
        "                 AND lv_property <> 'SCRTEXT_S'",
        "                 AND lv_property <> 'SCRTEXT_M'",
        "                 AND lv_property <> 'SCRTEXT_L'.",
        "                ev_status = 'E'.",
        "                ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "                ev_message = 'Data element property not allowed'.",
        "                ev_version = '1.2'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'DOMNAME'",
        "                 AND lv_value CN",
        "                   'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_/'.",
        "                ev_status = 'E'. ev_code = 'REFERENCE_INVALID'.",
        "                ev_message = 'Invalid domain reference'.",
        "                ev_version = '1.2'. RETURN.",
        "              ENDIF.",
        "              ASSIGN COMPONENT lv_property",
        "                OF STRUCTURE ls_dd04v TO <lv_component>.",
            "            WHEN 'TTYP'.",
        "              IF lv_property <> 'ROWTYPE'.",
        "                ev_status = 'E'.",
        "                ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "                ev_message = 'Table type property not allowed'.",
        "                ev_version = '1.2'. RETURN.",
        "              ENDIF.",
        "              IF lv_value IS INITIAL OR lv_value CN",
        "                   'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_/'.",
        "                ev_status = 'E'. ev_code = 'REFERENCE_INVALID'.",
        "                ev_message = 'Invalid table row type reference'.",
        "                ev_version = '1.2'. RETURN.",
        "              ENDIF.",
              "              ASSIGN COMPONENT lv_property",
              "                OF STRUCTURE ls_dd40v TO <lv_component>.",
        "            WHEN 'TABL'.",
        "              IF lv_property <> 'CONTFLAG'",
        "                 AND lv_property <> 'MAINFLAG'",
        "                 AND lv_property <> 'TABKAT'",
        "                 AND lv_property <> 'TABART'",
        "                 AND lv_property <> 'BUFALLOW'",
        "                 AND lv_property <> 'PUFFERUNG'",
        "                 AND lv_property <> 'SCHFELDANZ'",
        "                 AND lv_property <> 'PROTOKOLL'.",
        "                ev_status = 'E'.",
        "                ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "                ev_message = 'Table property not allowed'.",
        "                ev_version = '1.3'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'TABART'",
        "                 AND lv_value <> 'APPL0'",
        "                 AND lv_value <> 'APPL1'",
        "                 AND lv_value <> 'APPL2'.",
        "                ev_status = 'E'. ev_code = 'DATA_CLASS_INVALID'.",
        "                ev_message = 'Invalid table data class'.",
        "                ev_version = '1.3'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'CONTFLAG'",
        "                 AND lv_value <> 'A' AND lv_value <> 'C'",
        "                 AND lv_value <> 'L' AND lv_value <> 'G'",
        "                 AND lv_value <> 'E' AND lv_value <> 'S'",
        "                 AND lv_value <> 'W'.",
        "                ev_status = 'E'.",
        "                ev_code = 'DELIVERY_CLASS_INVALID'.",
        "                ev_message = 'Invalid table delivery class'.",
        "                ev_version = '1.3'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'MAINFLAG'",
        "                 AND lv_value IS NOT INITIAL",
        "                 AND lv_value <> 'X' AND lv_value <> 'R'.",
        "                ev_status = 'E'. ev_code = 'FLAG_INVALID'.",
        "                ev_message = 'Invalid table maintenance flag'.",
        "                ev_version = '1.3'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'TABKAT'",
        "                 AND ( lv_value IS INITIAL",
        "                   OR lv_value CN '01234' ).",
        "                ev_status = 'E'. ev_code = 'NUMBER_INVALID'.",
        "                ev_message = 'Invalid table size category'.",
        "                ev_version = '1.3'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'BUFALLOW'",
        "                 AND lv_value <> 'N' AND lv_value <> 'A'",
        "                 AND lv_value <> 'X'.",
        "                ev_status = 'E'. ev_code = 'BUFFER_INVALID'.",
        "                ev_message = 'Invalid table buffering allowance'.",
        "                ev_version = '1.3'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'PUFFERUNG'",
        "                 AND lv_value IS NOT INITIAL",
        "                 AND lv_value <> 'P' AND lv_value <> 'G'",
        "                 AND lv_value <> 'X'.",
        "                ev_status = 'E'. ev_code = 'BUFFER_INVALID'.",
        "                ev_message = 'Invalid table buffering mode'.",
        "                ev_version = '1.3'. RETURN.",
        "              ENDIF.",
        "              IF lv_settings IS INITIAL",
        "                 AND ( ( lv_property = 'BUFALLOW'",
        "                   AND lv_value <> 'N' )",
        "                   OR ( lv_property = 'PUFFERUNG'",
        "                   AND lv_value IS NOT INITIAL ) ).",
        "                ev_status = 'E'. ev_code = 'BUFFER_INVALID'.",
        "                ev_message = 'New tables must disable buffering'.",
        "                ev_version = '1.3'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'SCHFELDANZ'",
        "                 AND lv_value IS NOT INITIAL",
        "                 AND lv_value CN '0123456789'.",
        "                ev_status = 'E'. ev_code = 'NUMBER_INVALID'.",
        "                ev_message = 'Invalid generic key field count'.",
        "                ev_version = '1.7'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'PROTOKOLL'",
        "                 AND lv_value IS NOT INITIAL AND lv_value <> 'X'.",
        "                ev_status = 'E'. ev_code = 'FLAG_INVALID'.",
        "                ev_message = 'Log data changes must be X or empty'.",
        "                ev_version = '1.7'. RETURN.",
        "              ENDIF.",
        "              IF lv_property = 'CONTFLAG'",
        "                 OR lv_property = 'MAINFLAG'.",
        "                ASSIGN COMPONENT lv_property",
        "                  OF STRUCTURE ls_dd02v TO <lv_component>.",
        "              ELSE.",
        "                ASSIGN COMPONENT lv_property",
        "                  OF STRUCTURE ls_dd09v TO <lv_component>.",
        "              ENDIF.",
            "            WHEN OTHERS.",
        "              ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "              ev_message = 'Structure has no header payload'.",
        "              ev_version = '1.2'. RETURN.",
        "          ENDCASE.",
        "        WHEN 'V'.",
        "          IF lv_object_type <> 'DOMA'",
        "             OR ( lv_property <> 'DOMVALUE_L'",
        "             AND lv_property <> 'DOMVALUE_H'",
        "             AND lv_property <> 'DDTEXT' ).",
        "            ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "            ev_message = 'Fixed value property not allowed'.",
        "            ev_version = '1.2'. RETURN.",
        "          ENDIF.",
        "          WHILE lines( lt_dd07v ) < lv_index.",
        "            CLEAR ls_dd07v. APPEND ls_dd07v TO lt_dd07v.",
        "          ENDWHILE.",
        "          READ TABLE lt_dd07v ASSIGNING <ls_value>",
        "            INDEX lv_index.",
        "          ASSIGN COMPONENT lv_property",
        "            OF STRUCTURE <ls_value> TO <lv_component>.",
        "        WHEN 'S1'.",
        "          IF lv_object_type <> 'SHLP'",
        "             OR lv_property = 'SHLPNAME'",
        "             OR lv_property = 'SHPOSITION'.",
        "            ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "            ev_message = 'Search help selection property not allowed'.",
        "            ev_version = '1.8'. RETURN.",
        "          ENDIF.",
        "          WHILE lines( lt_dd31v ) < lv_index.",
        "            CLEAR ls_dd31v. APPEND ls_dd31v TO lt_dd31v.",
        "          ENDWHILE.",
        "          READ TABLE lt_dd31v ASSIGNING <ls_dd31v>",
        "            INDEX lv_index.",
        "          ASSIGN COMPONENT lv_property",
        "            OF STRUCTURE <ls_dd31v> TO <lv_component>.",
        "        WHEN 'S2'.",
        "          IF lv_object_type <> 'SHLP'",
        "             OR lv_property = 'SHLPNAME'",
        "             OR lv_property = 'FLPOSITION'.",
        "            ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "            ev_message = 'Search help parameter property not allowed'.",
        "            ev_version = '1.8'. RETURN.",
        "          ENDIF.",
        "          WHILE lines( lt_dd32p ) < lv_index.",
        "            CLEAR ls_dd32p. APPEND ls_dd32p TO lt_dd32p.",
        "          ENDWHILE.",
        "          READ TABLE lt_dd32p ASSIGNING <ls_dd32p>",
        "            INDEX lv_index.",
        "          ASSIGN COMPONENT lv_property",
        "            OF STRUCTURE <ls_dd32p> TO <lv_component>.",
        "        WHEN 'S3'.",
        "          IF lv_object_type <> 'SHLP'",
        "             OR lv_property = 'SHLPNAME'.",
        "            ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "            CONCATENATE 'Search help field assignment'",
        "            ' property not allowed' INTO ev_message.",
        "            ev_version = '1.8'. RETURN.",
        "          ENDIF.",
        "          WHILE lines( lt_dd33v ) < lv_index.",
        "            CLEAR ls_dd33v. APPEND ls_dd33v TO lt_dd33v.",
        "          ENDWHILE.",
        "          READ TABLE lt_dd33v ASSIGNING <ls_dd33v>",
        "            INDEX lv_index.",
        "          ASSIGN COMPONENT lv_property",
        "            OF STRUCTURE <ls_dd33v> TO <lv_component>.",
        "        WHEN 'L1'.",
        "          IF lv_object_type <> 'ENQU'",
        "             OR lv_property = 'VIEWNAME'",
        "             OR lv_property = 'TABPOS'.",
        "            ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "            ev_message = 'Lock object table property not allowed'.",
        "            ev_version = '1.9'. RETURN.",
        "          ENDIF.",
        "          WHILE lines( lt_dd26v ) < lv_index.",
        "            CLEAR ls_dd26v. APPEND ls_dd26v TO lt_dd26v.",
        "          ENDWHILE.",
        "          READ TABLE lt_dd26v ASSIGNING <ls_dd26v>",
        "            INDEX lv_index.",
        "          ASSIGN COMPONENT lv_property",
        "            OF STRUCTURE <ls_dd26v> TO <lv_component>.",
        "        WHEN 'L2'.",
        "          IF lv_object_type <> 'ENQU'",
        "             OR lv_property = 'VIEWNAME'",
        "             OR lv_property = 'OBJPOS'.",
        "            ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "            ev_message = 'Lock object field property not allowed'.",
        "            ev_version = '1.9'. RETURN.",
        "          ENDIF.",
        "          WHILE lines( lt_dd27p ) < lv_index.",
        "            CLEAR ls_dd27p. APPEND ls_dd27p TO lt_dd27p.",
        "          ENDWHILE.",
        "          READ TABLE lt_dd27p ASSIGNING <ls_dd27p>",
        "            INDEX lv_index.",
        "          ASSIGN COMPONENT lv_property",
        "            OF STRUCTURE <ls_dd27p> TO <lv_component>.",
        "        WHEN 'F'.",
        "          IF lv_recover = 'X'.",
        "            IF lv_property <> 'OBJECT'",
        "               AND lv_property <> 'TABNAME'",
        "               AND lv_property <> 'INDNAME'",
        "               AND lv_property <> 'TGORDER'",
        "               AND lv_property <> 'FCT'",
        "               AND lv_property <> 'EXECMODE'",
        "               AND lv_property <> 'SEVERITY'",
        "               AND lv_property <> 'GDATE'",
        "               AND lv_property <> 'GUSER'.",
        "              ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "              ev_message = 'Conversion property not allowed'.",
        "              ev_version = '1.7'. RETURN.",
        "            ENDIF.",
        "            WHILE lines( lt_expected_tbatg ) < lv_index.",
        "              CLEAR ls_expected_tbatg.",
        "              APPEND ls_expected_tbatg TO lt_expected_tbatg.",
        "            ENDWHILE.",
        "            READ TABLE lt_expected_tbatg ASSIGNING <ls_tbatg>",
        "              INDEX lv_index.",
        "            ASSIGN COMPONENT lv_property",
        "              OF STRUCTURE <ls_tbatg> TO <lv_component>.",
        "          ELSE.",
        "          IF lv_object_type <> 'STRU' AND lv_object_type <> 'TABL'.",
        "            ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "            ev_message = 'Field payload not allowed'.",
        "            ev_version = '1.3'. RETURN.",
        "          ENDIF.",
        "          IF ( lv_property = 'PRECFIELD'",
        "               OR lv_property = 'COMPTYPE'",
        "               OR lv_property = 'ADMINFIELD'",
        "               OR lv_property = 'GROUPNAME'",
        "               OR lv_property = 'EXCLASS' )",
        "             AND lv_patch IS INITIAL.",
        "            ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "            ev_message = 'Complex component metadata is read-only'.",
        "            ev_version = '1.7'. RETURN.",
        "          ENDIF.",
        "          IF lv_property <> 'FIELDNAME'",
        "             AND lv_property <> 'ROLLNAME'",
        "             AND ( lv_object_type <> 'TABL'",
        "               OR ( lv_property <> 'KEYFLAG'",
        "                 AND lv_property <> 'NOTNULL'",
        # 1.15：参考表/参考字段。DD03P 的这两个组件由下面的 ASSIGN COMPONENT 直接承载，
        # 无需额外赋值代码；没有它们，数量/货币字段的定义写得出、却永远激活不了。
        "                 AND lv_property <> 'REFTABLE'",
        "                 AND lv_property <> 'REFFIELD'",
        "                 AND lv_property <> 'PRECFIELD'",
        "                 AND lv_property <> 'COMPTYPE'",
        "                 AND lv_property <> 'ADMINFIELD'",
        "                 AND lv_property <> 'GROUPNAME'",
        "                 AND lv_property <> 'EXCLASS' ) ).",
        "            ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "            ev_message = 'Table field property not allowed'.",
        "            ev_version = '1.3'. RETURN.",
        "          ENDIF.",
        "          IF lv_property = 'FIELDNAME'",
        "             AND ( lv_value IS INITIAL OR lv_value CN",
        "               'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_' )",
        "             AND ( lv_patch IS INITIAL OR lv_value CN",
        "               'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-' ).",
        "            ev_status = 'E'. ev_code = 'FIELD_VALUE_INVALID'.",
        "            ev_message = 'Invalid structure field name'.",
        "            ev_version = '1.2'. RETURN.",
        "          ENDIF.",
        "          IF lv_property = 'ROLLNAME'",
        "             AND ( lv_value IS INITIAL OR lv_value CN",
        "               'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_/' )",
        "             AND lv_patch IS INITIAL.",
        "            ev_status = 'E'. ev_code = 'REFERENCE_INVALID'.",
        "            ev_message = 'Invalid data element reference'.",
        "            ev_version = '1.2'. RETURN.",
        "          ENDIF.",
        "          IF ( lv_property = 'KEYFLAG'",
        "               OR lv_property = 'NOTNULL' )",
        "             AND lv_value IS NOT INITIAL AND lv_value <> 'X'.",
        "            ev_status = 'E'. ev_code = 'FLAG_INVALID'.",
        "            ev_message = 'Table field flag must be X or empty'.",
        "            ev_version = '1.3'. RETURN.",
        "          ENDIF.",
        "          IF lv_object_type = 'TABL'",
        "             AND lv_append IS INITIAL",
        "             AND lv_patch IS INITIAL",
        "             AND lv_property = 'NOTNULL' AND lv_value <> 'X'.",
        "            ev_status = 'E'. ev_code = 'NOTNULL_REQUIRED'.",
        "            ev_message = 'Transparent table fields must be not null'.",
        "            ev_version = '1.3'. RETURN.",
        "          ENDIF.",
        "          WHILE lines( lt_dd03p ) < lv_index.",
        "            CLEAR ls_dd03p. APPEND ls_dd03p TO lt_dd03p.",
        "          ENDWHILE.",
        "          READ TABLE lt_dd03p ASSIGNING <ls_field>",
        "            INDEX lv_index.",
        "          ASSIGN COMPONENT lv_property",
        "            OF STRUCTURE <ls_field> TO <lv_component>.",
        "          ENDIF.",
        "        WHEN OTHERS.",
        "          ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "          ev_message = 'Unknown DDIC payload row type'.",
        "          ev_version = '1.2'. RETURN.",
        "      ENDCASE.",
        "      IF <lv_component> IS NOT ASSIGNED.",
        "        ev_status = 'E'. ev_code = 'PROPERTY_INVALID'.",
        "        ev_message = 'Unknown DDIC payload property'.",
        "        ev_version = '1.2'. RETURN.",
        "      ENDIF.",
        "      <lv_component> = lv_value.",
        "    ENDLOOP.",
        "  ENDIF.",
        "  IF lv_settings = 'X'.",
        "    ls_requested_dd09v = ls_dd09v.",
        "  ENDIF.",
        "  IF lv_object_type = 'STRU'.",
        "    lv_tadir_type = 'TABL'.",
        "    lv_state_type = 'TABL'.",
        "  ELSE.",
        "    lv_tadir_type = lv_object_type.",
        "    lv_state_type = lv_object_type.",
        "  ENDIF.",
        "  IF lv_recover = 'X'.",
        "    IF lt_expected_tbatg[] IS INITIAL.",
        "      ev_status = 'E'. ev_code = 'WORKLIST_REQUIRED'.",
        "      ev_message = 'Expected conversion worklist is required'.",
        "      ev_version = '1.7'. RETURN.",
        "    ENDIF.",
        "    LOOP AT lt_expected_tbatg INTO ls_expected_tbatg.",
        "      IF ls_expected_tbatg-object <> 'TABL'",
        "         OR ls_expected_tbatg-tabname <> iv_object_name.",
        "        ev_status = 'E'. ev_code = 'WORKLIST_SCOPE_INVALID'.",
        "        ev_message = 'Conversion entry is outside target table'.",
        "        ev_version = '1.7'. RETURN.",
        "      ENDIF.",
        "    ENDLOOP.",
        "    SELECT SINGLE * FROM tadir INTO ls_tadir",
        "      WHERE pgmid = 'R3TR' AND object = 'TABL'",
        "        AND obj_name = iv_object_name.",
        "    IF sy-subrc <> 0.",
        "      ev_status = 'E'. ev_code = 'DDIC_OBJECT_NOT_FOUND'.",
        "      ev_message = 'Transparent table does not exist'.",
        "      ev_version = '1.7'. RETURN.",
        "    ENDIF.",
        "    IF ls_tadir-devclass <> iv_package.",
        "      ev_status = 'E'. ev_code = 'PACKAGE_CONFLICT'.",
        "      ev_message = 'Existing object belongs to another package'.",
        "      ev_version = '1.7'. RETURN.",
        "    ENDIF.",
        "    CLEAR ls_current_dd02v-tabclass.",
        "    SELECT SINGLE tabclass FROM dd02l",
        "      INTO ls_current_dd02v-tabclass",
        "      WHERE tabname = iv_object_name AND as4local = 'A'.",
        "    IF sy-subrc <> 0 OR ls_current_dd02v-tabclass <> 'TRANSP'.",
        "      ev_status = 'E'. ev_code = 'OBJECT_TYPE_MISMATCH'.",
        "      ev_message = 'Dictionary object is not a transparent table'.",
        "      ev_version = '1.7'. RETURN.",
        "    ENDIF.",
        "    SELECT * FROM tbatg INTO TABLE lt_current_tbatg",
        "      WHERE object = 'TABL' AND tabname = iv_object_name.",
        "    SORT lt_expected_tbatg BY object tabname indname tgorder",
        "      fct execmode severity gdate guser.",
        "    SORT lt_current_tbatg BY object tabname indname tgorder",
        "      fct execmode severity gdate guser.",
        "    DESCRIBE TABLE lt_expected_tbatg LINES lv_field_count.",
        "    DESCRIBE TABLE lt_current_tbatg LINES lv_current_field_count.",
        "    IF lv_field_count <> lv_current_field_count.",
        "      ev_status = 'E'. ev_code = 'WORKLIST_CONFLICT'.",
        "      ev_message = 'Native conversion worklist changed'.",
        "      ev_version = '1.7'. RETURN.",
        "    ENDIF.",
        "    LOOP AT lt_expected_tbatg INTO ls_expected_tbatg.",
        "      READ TABLE lt_current_tbatg INTO ls_current_tbatg",
        "        INDEX sy-tabix.",
        "      IF sy-subrc <> 0",
        "         OR ls_current_tbatg <> ls_expected_tbatg.",
        "        ev_status = 'E'. ev_code = 'WORKLIST_CONFLICT'.",
        "        ev_message = 'Native conversion worklist changed'.",
        "        ev_version = '1.7'. RETURN.",
        "      ENDIF.",
        "    ENDLOOP.",
        "    CLEAR: ls_corr_object, lv_recorded_request.",
        "    ls_corr_object-objtype = 'TABL'.",
        "    ls_corr_object-objname = iv_object_name.",
        "    CALL FUNCTION 'RS_CORR_INSERT'",
        "      EXPORTING object = ls_corr_object",
        "        object_class = 'DICT' mode = 'M'",
        "        devclass = iv_package korrnum = iv_request",
        "        use_korrnum_immediatedly = 'X'",
        "        master_language = sy-langu suppress_dialog = 'X'",
        "      IMPORTING korrnum = lv_recorded_request",
        "      EXCEPTIONS cancelled = 1 permission_failure = 2",
        "        unknown_objectclass = 3 OTHERS = 4.",
        "    IF sy-subrc <> 0.",
        "      ROLLBACK WORK.",
        "      ev_status = 'E'. ev_code = 'TRANSPORT_RECORD_FAILED'.",
        "      ev_message = 'Failed to record table on transport'.",
        "      ev_version = '1.7'. RETURN.",
        "    ENDIF.",
        "    REFRESH: lt_object_range, lt_tabname_range,",
        "      lt_indname_range, lt_tgorder_range, lt_fct_range,",
        "      lt_execmode_range, lt_severity_range, lt_gdate_range,",
        "      lt_guser_range.",
        "    LOOP AT lt_expected_tbatg INTO ls_expected_tbatg.",
        "      CLEAR ls_range.",
        "      ls_range-sign = 'I'. ls_range-option = 'EQ'.",
        "      ls_range-low = ls_expected_tbatg-object.",
        "      APPEND ls_range TO lt_object_range.",
        "      ls_range-low = ls_expected_tbatg-tabname.",
        "      APPEND ls_range TO lt_tabname_range.",
        "      ls_range-low = ls_expected_tbatg-indname.",
        "      APPEND ls_range TO lt_indname_range.",
        "      ls_range-low = ls_expected_tbatg-tgorder.",
        "      APPEND ls_range TO lt_tgorder_range.",
        "      ls_range-low = ls_expected_tbatg-fct.",
        "      APPEND ls_range TO lt_fct_range.",
        "      ls_range-low = ls_expected_tbatg-execmode.",
        "      APPEND ls_range TO lt_execmode_range.",
        "      ls_range-low = ls_expected_tbatg-severity.",
        "      APPEND ls_range TO lt_severity_range.",
        "      ls_range-low = ls_expected_tbatg-gdate.",
        "      APPEND ls_range TO lt_gdate_range.",
        "      ls_range-low = ls_expected_tbatg-guser.",
        "      APPEND ls_range TO lt_guser_range.",
        "    ENDLOOP.",
        "    SORT lt_object_range BY low.",
        "    SORT lt_tabname_range BY low.",
        "    SORT lt_indname_range BY low.",
        "    SORT lt_tgorder_range BY low.",
        "    SORT lt_fct_range BY low.",
        "    SORT lt_execmode_range BY low.",
        "    SORT lt_severity_range BY low.",
        "    SORT lt_gdate_range BY low.",
        "    SORT lt_guser_range BY low.",
        "    DELETE ADJACENT DUPLICATES FROM lt_object_range",
        "      COMPARING low.",
        "    DELETE ADJACENT DUPLICATES FROM lt_tabname_range",
        "      COMPARING low.",
        "    DELETE ADJACENT DUPLICATES FROM lt_indname_range",
        "      COMPARING low.",
        "    DELETE ADJACENT DUPLICATES FROM lt_tgorder_range",
        "      COMPARING low.",
        "    DELETE ADJACENT DUPLICATES FROM lt_fct_range",
        "      COMPARING low.",
        "    DELETE ADJACENT DUPLICATES FROM lt_execmode_range",
        "      COMPARING low.",
        "    DELETE ADJACENT DUPLICATES FROM lt_severity_range",
        "      COMPARING low.",
        "    DELETE ADJACENT DUPLICATES FROM lt_gdate_range",
        "      COMPARING low.",
        "    DELETE ADJACENT DUPLICATES FROM lt_guser_range",
        "      COMPARING low.",
        "    CALL FUNCTION 'DD_DB_CONVERTER'",
        "      EXPORTING parallel = ' ' asynchron = ' '",
        "        log_display = ' ' file_log = ' ' db_log = 'X'",
        "        pre_done = ' '",
        "      TABLES object = lt_object_range",
        "        tabname = lt_tabname_range indname = lt_indname_range",
        "        tgorder = lt_tgorder_range fct = lt_fct_range",
        "        execmode = lt_execmode_range severity = lt_severity_range",
        "        gdate = lt_gdate_range guser = lt_guser_range.",
        "    REFRESH lt_current_tbatg.",
        "    SELECT * FROM tbatg INTO TABLE lt_current_tbatg",
        "      WHERE object = 'TABL' AND tabname = iv_object_name.",
        "    IF lt_current_tbatg[] IS NOT INITIAL.",
        "      ev_status = 'E'. ev_code = 'CONVERSION_RECOVERY_PENDING'.",
        "      ev_message = 'Native conversion worklist remains'.",
        "      ev_version = '1.7'. RETURN.",
        "    ENDIF.",
        "    CLEAR lv_active_state.",
        "    CALL FUNCTION 'DDIF_STATE_GET'",
        "      EXPORTING type = 'TABL' name = lv_ddic_name state = 'A'",
        "      IMPORTING gotstate = lv_active_state",
        "      EXCEPTIONS OTHERS = 1.",
        "    IF sy-subrc <> 0 OR lv_active_state <> 'A'.",
        "      ev_status = 'E'. ev_code = 'CONVERSION_VERIFY_FAILED'.",
        "      ev_message = 'Active table unavailable after conversion'.",
        "      ev_version = '1.7'. RETURN.",
        "    ENDIF.",
        "    CALL FUNCTION 'DDIF_TABL_GET'",
        "      EXPORTING name = lv_ddic_name state = 'A'",
        "        langu = sy-langu",
        "      IMPORTING gotstate = lv_gotstate dd02v_wa = ls_dd02v",
        "        dd09l_wa = ls_dd09v",
        "      TABLES dd03p_tab = lt_dd03p",
        "      EXCEPTIONS OTHERS = 1.",
        "    IF sy-subrc <> 0 OR lv_gotstate <> 'A'.",
        "      ev_status = 'E'. ev_code = 'CONVERSION_VERIFY_FAILED'.",
        "      ev_message = 'Active table read failed after conversion'.",
        "      ev_version = '1.7'. RETURN.",
        "    ENDIF.",
        "    CONCATENATE ls_dd02v-as4date ls_dd02v-as4time",
        "      INTO lv_current_version.",
        "    REFRESH it_source.",
        "    add_payload 'M' '1' 'PACKAGE' ls_tadir-devclass.",
        "    add_payload 'M' '1' 'VERSION' lv_current_version.",
        "    add_payload 'M' '1' 'REQUEST' lv_recorded_request.",
        "    ev_status = 'S'. ev_code = 'DDIC_CONVERSION_RECOVERED'.",
        "    ev_message = 'Native table conversion completed and verified'.",
        "    ev_version = '1.7'. RETURN.",
        "  ENDIF.",
        "  CLEAR: lv_gotstate, lv_current_version, lv_existing.",
        "  CASE lv_object_type.",
        "    WHEN 'DOMA'.",
        "      CALL FUNCTION 'DDIF_DOMA_GET'",
        "        EXPORTING name = lv_ddic_name state = 'M'",
        "          langu = sy-langu",
        "        IMPORTING gotstate = lv_gotstate",
        "          dd01v_wa = ls_current_dd01v",
        "        TABLES dd07v_tab = lt_current_dd07v",
        "        EXCEPTIONS OTHERS = 1.",
        "    WHEN 'DTEL'.",
        "      CALL FUNCTION 'DDIF_DTEL_GET'",
        "        EXPORTING name = lv_ddic_name state = 'M'",
        "          langu = sy-langu",
        "        IMPORTING gotstate = lv_gotstate",
        "          dd04v_wa = ls_current_dd04v",
        "        EXCEPTIONS OTHERS = 1.",
        "    WHEN 'STRU'.",
        "      CALL FUNCTION 'DDIF_TABL_GET'",
        "        EXPORTING name = lv_ddic_name state = 'M'",
        "          langu = sy-langu",
        "        IMPORTING gotstate = lv_gotstate",
        "          dd02v_wa = ls_current_dd02v",
        "          dd09l_wa = ls_current_dd09v",
        "        TABLES dd03p_tab = lt_current_dd03p",
        "        EXCEPTIONS OTHERS = 1.",
        "    WHEN 'TABL'.",
        "      CALL FUNCTION 'DDIF_TABL_GET'",
        "        EXPORTING name = lv_ddic_name state = 'M'",
        "          langu = sy-langu",
        "        IMPORTING gotstate = lv_gotstate",
        "          dd02v_wa = ls_current_dd02v",
        "          dd09l_wa = ls_current_dd09v",
        "        TABLES dd03p_tab = lt_current_dd03p",
        "        EXCEPTIONS OTHERS = 1.",
        "    WHEN 'TTYP'.",
        "      CALL FUNCTION 'DDIF_TTYP_GET'",
        "        EXPORTING name = lv_ddic_name state = 'M'",
        "          langu = sy-langu",
        "        IMPORTING gotstate = lv_gotstate",
        "          dd40v_wa = ls_current_dd40v",
        "        TABLES dd42v_tab = lt_current_dd42v",
        "          dd43v_tab = lt_current_dd43v",
        "        EXCEPTIONS OTHERS = 1.",
        "    WHEN 'SHLP'.",
        "      CALL FUNCTION 'DDIF_SHLP_GET'",
        "        EXPORTING name = lv_ddic_name state = 'M'",
        "          langu = sy-langu",
        "        IMPORTING gotstate = lv_gotstate",
        "          dd30v_wa = ls_current_dd30v",
        "        TABLES dd31v_tab = lt_current_dd31v",
        "          dd32p_tab = lt_current_dd32p",
        "          dd33v_tab = lt_current_dd33v",
        "        EXCEPTIONS OTHERS = 1.",
        "    WHEN 'ENQU'.",
        "      CALL FUNCTION 'DDIF_ENQU_GET'",
        "        EXPORTING name = lv_ddic_name state = 'M'",
        "          langu = sy-langu",
        "        IMPORTING gotstate = lv_gotstate",
        "          dd25v_wa = ls_current_dd25v",
        "        TABLES dd26e_tab = lt_current_dd26v",
        "          dd27p_tab = lt_current_dd27p",
        "        EXCEPTIONS OTHERS = 1.",
        "  ENDCASE.",
        "  IF sy-subrc <> 0.",
        "    ev_status = 'E'. ev_code = 'DDIC_READ_FAILED'.",
        "    ev_message = 'DDIC read interface failed'.",
        "    ev_version = '1.2'. RETURN.",
        "  ENDIF.",
        "  IF lv_gotstate IS NOT INITIAL.",
        "    IF lv_gotstate <> 'A'.",
        # 1.13 恢复激活：目标就是这个非活动定义本身。它既不能落进下面的 INACTIVE_VERSION_EXISTS
        # 拒绝（那正是 resume_ddic_table_activation 要解决的处境），更不能落进 DDIF_OBJECT_DELETE
        # 重置——那个重置是给"创建时残留了旧非活动版本"用的，对恢复激活执行它会**删掉待激活的
        # 定义**。把对象视为已存在后继续，交给 4665 的 TRANSP 类型校验、5027 的包归属校验，以及
        # 5389 起本操作自己的 lv_resume 激活路径（DD_TABL_ACT）。
        "      IF lv_resume = 'X'.",
        "        lv_existing = 'X'.",
        "      ELSE.",
        "      IF lv_write IS INITIAL.",
        "        IF lv_describe = 'X'.",
        "          ev_status = 'S'. ev_code = 'INACTIVE_VERSION_DESCRIBED'.",
        "          ev_message =",
        "            'Inactive DDIC version described for inspection'.",
        "          ev_version = '1.10'.",
        "          add_payload 'M' '1' 'GOTSTATE' lv_gotstate.",
        "          add_payload 'M' '1' 'INACTIVE' 'X'.",
        # N-2：STRU 与 TABL 走的是同一个 DDIF_TABL_GET state = 'M' 读取（见上方 WHEN 'STRU'），
        # 三个数据源 ls_current_dd02v / ls_current_dd09v / lt_current_dd03p 完全同源；此处原先只
        # 放行 TABL，导致结构对象的非活动定义恒只发 M|GOTSTATE 与 M|INACTIVE、fields 恒为空，
        # 与 TABL 分支在 R2C 已修的行为不一致。同源即同发，一并放行 STRU。
        "          IF lv_object_type = 'TABL' OR lv_object_type = 'STRU'.",
        "            add_payload 'M' '1' 'TABNAME' iv_object_name.",
        # 非活动定义的表头属性必须取自 state = 'M' 读到的 ls_current_dd02v；ls_dd02v 装的是
        # 活动版本表头（见上方 DDIF_TABL_GET state = 'A' 的 IMPORTING），用它会让 INACTIVE 行
        # 配上活动版本的描述/类别。线上帮手已含此修复（1.10 载体），此处为回移。
        "            add_payload 'M' '1' 'DDTEXT' ls_current_dd02v-ddtext.",
        "            add_payload 'M' '1' 'TABCLASS' ls_current_dd02v-tabclass.",
        # 与活动分支同源同发：非活动定义的 append 关系同样取自这次 state = 'M' 读取的表头。
        "            add_payload 'M' '1' 'SQLTAB' ls_current_dd02v-sqltab.",
        "            add_payload 'M' '1' 'MAINFLAG' ls_current_dd02v-mainflag.",
        "            add_payload 'M' '1' 'CONTFLAG' ls_current_dd02v-contflag.",
        # 17:37 事件：非活动读取不报 DD09V 技术设置，调用方只能看到客户端默认的 dataClass = 空 /
        # sizeCategory = 0，无法区分"DD09L 里就是空"与"这条读路径看不到"，而按批准定义它应为
        # APPL1/1。技术设置与表头同出自这次 DDIF_TABL_GET state = 'M'，因此一并上报；客户端按
        # 载荷里这些键是否存在判断可信性，1.10 及更早不含这些键，仍按"未上报"处理。
        "            add_payload 'M' '1' 'TABART' ls_current_dd09v-tabart.",
        "            add_payload 'M' '1' 'TABKAT' ls_current_dd09v-tabkat.",
        "            add_payload 'M' '1' 'BUFALLOW' ls_current_dd09v-bufallow.",
        "            add_payload 'M' '1' 'PUFFERUNG' ls_current_dd09v-pufferung.",
        # 10:26 事件：这里原先 LOOP AT lt_dd03p（活动版本字段表），而 state = 'M' 读到的是
        # lt_current_dd03p。对只有非活动版本的对象，lt_dd03p 为空 → 非活动定义恒返回
        # fields = []，而 DD03L 里 AS4LOCAL = 'N' 的 29 行真实存在；对活动+非活动并存的对象
        # 更糟：会把活动版本的字段当成非活动定义上报。表头与 DD09V 已取自 ls_current_*，
        # 字段必须同源。
        "            LOOP AT lt_current_dd03p ASSIGNING <ls_field>.",
        "              lv_index = sy-tabix.",
        "              add_payload 'F' lv_index 'FIELDNAME'",
        "                <ls_field>-fieldname.",
        "              add_payload 'F' lv_index 'POSITION' <ls_field>-position.",
        "              add_payload 'F' lv_index 'ROLLNAME' <ls_field>-rollname.",
        "              add_payload 'F' lv_index 'KEYFLAG' <ls_field>-keyflag.",
        "              add_payload 'F' lv_index 'DATATYPE' <ls_field>-datatype.",
        "              add_payload 'F' lv_index 'LENG' <ls_field>-leng.",
        "              add_payload 'F' lv_index 'DECIMALS' <ls_field>-decimals.",
        "            ENDLOOP.",
        "          ENDIF.",
        "          RETURN.",
        "        ENDIF.",
        "        ev_status = 'E'. ev_code = 'INACTIVE_VERSION_EXISTS'.",
        "        ev_message = 'Inactive DDIC version must be resolved'.",
        "        ev_version = '1.2'. RETURN.",
        "      ENDIF.",
        "      IF iv_expected_version IS NOT INITIAL.",
        "        ev_status = 'E'. ev_code = 'INACTIVE_VERSION_EXISTS'.",
        "        ev_message = 'Inactive DDIC version must be resolved'.",
        "        ev_version = '1.2'. RETURN.",
        "      ENDIF.",
        "      CLEAR lv_active_state.",
        "      CALL FUNCTION 'DDIF_STATE_GET'",
        "        EXPORTING type = lv_state_type name = lv_ddic_name",
        "          state = 'A'",
        "        IMPORTING gotstate = lv_active_state",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc <> 0 OR lv_active_state IS NOT INITIAL.",
        "        ev_status = 'E'. ev_code = 'INACTIVE_VERSION_EXISTS'.",
        "        ev_message = 'Active object has inactive changes'.",
        "        ev_version = '1.2'. RETURN.",
        "      ENDIF.",
        "      CLEAR lv_deleted. REFRESH lt_object_refs.",
        "      CALL FUNCTION 'DDIF_OBJECT_DELETE'",
        "        EXPORTING type = lv_state_type name = lv_ddic_name",
        "          authority_check = 'X'",
        "        IMPORTING deleted = lv_deleted",
        "        TABLES objects_with_references = lt_object_refs",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc <> 0 OR lv_deleted IS INITIAL",
        "         OR lt_object_refs[] IS NOT INITIAL.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'INACTIVE_RESET_FAILED'.",
        "        ev_message = 'Failed to reset inactive new object'.",
        "        ev_version = '1.2'. RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      CLEAR lv_gotstate.",
        "      ENDIF.",
        "    ELSE.",
        "      lv_existing = 'X'.",
        "    ENDIF.",
        "  ENDIF.",
        "  IF lv_existing = 'X'.",
        "    CASE lv_object_type.",
        "      WHEN 'DOMA'.",
        "        CONCATENATE ls_current_dd01v-as4date",
        "          ls_current_dd01v-as4time",
        "          INTO lv_current_version.",
        "      WHEN 'DTEL'.",
        "        CONCATENATE ls_current_dd04v-as4date",
        "          ls_current_dd04v-as4time",
        "          INTO lv_current_version.",
        "      WHEN 'STRU'.",
        "        CONCATENATE ls_current_dd02v-as4date",
        "          ls_current_dd02v-as4time",
        "          INTO lv_current_version.",
        "      WHEN 'TABL'.",
        "        CONCATENATE ls_current_dd02v-as4date",
        "          ls_current_dd02v-as4time",
        "          INTO lv_current_version.",
        "      WHEN 'TTYP'.",
        "        SELECT SINGLE as4date as4time FROM dd40l",
        "          INTO (lv_as4date, lv_as4time)",
        "          WHERE typename = iv_object_name",
        "            AND as4local = 'A'.",
        "        CONCATENATE lv_as4date lv_as4time",
        "          INTO lv_current_version.",
        "      WHEN 'SHLP'.",
        "        CONCATENATE ls_current_dd30v-as4date",
        "          ls_current_dd30v-as4time",
        "          INTO lv_current_version.",
        "      WHEN 'ENQU'.",
        "        CONCATENATE ls_current_dd25v-as4date",
        "          ls_current_dd25v-as4time",
        "          INTO lv_current_version.",
        "    ENDCASE.",
        "  ENDIF.",
        "  IF lv_write IS INITIAL AND lv_existing = 'X'.",
        "    ls_dd01v = ls_current_dd01v.",
        "    lt_dd07v[] = lt_current_dd07v[].",
        "    ls_dd04v = ls_current_dd04v.",
        "    ls_dd02v = ls_current_dd02v.",
        "    ls_dd09v = ls_current_dd09v.",
        "    lt_dd03p[] = lt_current_dd03p[].",
        "    ls_dd40v = ls_current_dd40v.",
        "    lt_dd42v[] = lt_current_dd42v[].",
        "    lt_dd43v[] = lt_current_dd43v[].",
        "    ls_dd30v = ls_current_dd30v.",
        "    lt_dd31v[] = lt_current_dd31v[].",
        "    lt_dd32p[] = lt_current_dd32p[].",
        "    lt_dd33v[] = lt_current_dd33v[].",
        "    ls_dd25v = ls_current_dd25v.",
        "    lt_dd26v[] = lt_current_dd26v[].",
        "    lt_dd27p[] = lt_current_dd27p[].",
        "  ENDIF.",
        "  IF lv_write IS INITIAL AND lv_existing IS INITIAL.",
        "    ev_status = 'E'. ev_code = 'DDIC_OBJECT_NOT_FOUND'.",
        "    ev_message = 'DDIC object does not exist'.",
        "    ev_version = '1.2'. RETURN.",
        "  ENDIF.",
        "  IF lv_object_type = 'TABL' AND lv_existing = 'X'",
        "     AND ls_current_dd02v-tabclass <> 'TRANSP'.",
        "    ev_status = 'E'. ev_code = 'OBJECT_TYPE_MISMATCH'.",
        "    ev_message = 'Dictionary object is not a transparent table'.",
        "    ev_version = '1.3'. RETURN.",
        "  ENDIF.",
        # APPEND 结构也是结构：其字段可读，且 SQLTAB 指向激活目标基表。
        # 只认 INTTAB 会让 append 的读取侧完全不可达（读不到 baseTable / 版本令牌）。
        "  IF lv_object_type = 'STRU' AND lv_existing = 'X'",
        "     AND ls_current_dd02v-tabclass <> 'INTTAB'",
        "     AND ls_current_dd02v-tabclass <> 'APPEND'.",
        "    ev_status = 'E'. ev_code = 'OBJECT_TYPE_MISMATCH'.",
        "    ev_message = 'Dictionary object is not a structure'.",
        "    ev_version = '1.4'. RETURN.",
        "  ENDIF.",
        "  IF lv_write = 'X'.",
        # 1.13：以下三道闸门都假设"写入 = 提交一份新定义"，因此对恢复激活必须放行：
        #   * DDIC_OBJECT_EXISTS 拒绝的是**替换**已有表；恢复激活不提交定义，只激活已存的那份。
        #   * EXPECTED_VERSION_REQUIRED / VERSION_CONFLICT 比对的是活动版本的时间戳令牌
        #     （lv_current_version = AS4DATE + AS4TIME，14 位）。恢复激活没有活动版本可作令牌，
        #     服务端送的又是定义内容指纹（64 位十六进制），两者永不可能相等。恢复激活的陈旧读
        #     保护在服务端完成（expectedInactiveFingerprint 与它刚读到的存储定义比对），助手侧
        #     由下面的 NO_INACTIVE_VERSION 守卫兜底。
        "    IF lv_object_type = 'TABL' AND lv_existing = 'X'",
        "       AND lv_append IS INITIAL AND lv_patch IS INITIAL",
        "       AND lv_settings IS INITIAL AND lv_delete IS INITIAL",
        "       AND lv_resume IS INITIAL.",
        "      ev_status = 'E'. ev_code = 'DDIC_OBJECT_EXISTS'.",
        "      ev_message = 'Existing transparent tables cannot be replaced'.",
        "      ev_version = '1.3'. RETURN.",
        "    ENDIF.",
        "    IF lv_existing = 'X' AND iv_expected_version IS INITIAL",
        "       AND lv_resume IS INITIAL.",
        "      ev_status = 'E'. ev_code = 'EXPECTED_VERSION_REQUIRED'.",
        "      ev_message = 'Existing object requires version token'.",
        "      ev_version = '1.2'. RETURN.",
        "    ENDIF.",
        "    IF lv_existing = 'X'",
        "       AND iv_expected_version <> lv_current_version",
        "       AND lv_resume IS INITIAL.",
        "      ev_status = 'E'. ev_code = 'VERSION_CONFLICT'.",
        "      ev_message = 'DDIC object changed since it was read'.",
        "      ev_version = '1.2'. RETURN.",
        "    ENDIF.",
        "    IF lv_existing IS INITIAL",
        "       AND iv_expected_version IS NOT INITIAL.",
        "      ev_status = 'E'. ev_code = 'VERSION_CONFLICT'.",
        "      ev_message = 'Expected object version no longer exists'.",
        "      ev_version = '1.2'. RETURN.",
        "    ENDIF.",
        "    IF lv_settings = 'X'.",
        "      IF lv_existing IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'DDIC_OBJECT_NOT_FOUND'.",
        "        ev_message = 'Transparent table does not exist'.",
        "        ev_version = '1.7'. RETURN.",
        "      ENDIF.",
        "      ls_dd02v = ls_current_dd02v.",
        "      ls_dd09v = ls_current_dd09v.",
        "      lt_dd03p[] = lt_current_dd03p[].",
        "      ls_dd09v-tabart = ls_requested_dd09v-tabart.",
        "      ls_dd09v-tabkat = ls_requested_dd09v-tabkat.",
        "      ls_dd09v-bufallow = ls_requested_dd09v-bufallow.",
        "      ls_dd09v-pufferung = ls_requested_dd09v-pufferung.",
        "      ls_dd09v-schfeldanz = ls_requested_dd09v-schfeldanz.",
        "      ls_dd09v-protokoll = ls_requested_dd09v-protokoll.",
        "      IF ls_dd09v-bufallow = 'N'",
        "         AND ( ls_dd09v-pufferung IS NOT INITIAL",
        "           OR ls_dd09v-schfeldanz IS NOT INITIAL ).",
        "        ev_status = 'E'. ev_code = 'BUFFER_INVALID'.",
        "        ev_message = 'Disabled buffering has no mode or key count'.",
        "        ev_version = '1.7'. RETURN.",
        "      ENDIF.",
        "      IF ls_dd09v-bufallow = 'A'",
        "         AND ( ls_dd09v-pufferung IS NOT INITIAL",
        "           OR ls_dd09v-schfeldanz IS NOT INITIAL ).",
        "        ev_status = 'E'. ev_code = 'BUFFER_INVALID'.",
        "        ev_message = 'Inactive buffering has no mode or key count'.",
        "        ev_version = '1.7'. RETURN.",
        "      ENDIF.",
        "      IF ls_dd09v-bufallow = 'X'",
        "         AND ls_dd09v-pufferung <> 'P'",
        "         AND ls_dd09v-pufferung <> 'G'",
        "         AND ls_dd09v-pufferung <> 'X'.",
        "        ev_status = 'E'. ev_code = 'BUFFER_INVALID'.",
        "        ev_message = 'Enabled buffering requires a valid mode'.",
        "        ev_version = '1.7'. RETURN.",
        "      ENDIF.",
        "      IF ls_dd09v-pufferung <> 'G'",
        "         AND ls_dd09v-schfeldanz IS NOT INITIAL.",
        "        ev_status = 'E'. ev_code = 'BUFFER_INVALID'.",
        "        ev_message = 'Generic key count requires generic buffering'.",
        "        ev_version = '1.7'. RETURN.",
        "      ENDIF.",
        "      IF ls_dd09v-pufferung = 'G'.",
        "        CLEAR lv_field_count.",
        "        LOOP AT lt_current_dd03p INTO ls_compare_dd03p",
        "          WHERE keyflag = 'X'.",
        "          IF ls_compare_dd03p-fieldname NP '.INCLU*'.",
        "            lv_field_count = lv_field_count + 1.",
        "          ENDIF.",
        "        ENDLOOP.",
        "        IF ls_dd09v-schfeldanz IS INITIAL",
        "           OR ls_dd09v-schfeldanz > lv_field_count.",
        "          ev_status = 'E'. ev_code = 'BUFFER_INVALID'.",
        "          ev_message = 'Generic key count exceeds key fields'.",
        "          ev_version = '1.7'. RETURN.",
        "        ENDIF.",
        "      ENDIF.",
        "      IF ls_dd09v-tabart = ls_current_dd09v-tabart",
        "         AND ls_dd09v-tabkat = ls_current_dd09v-tabkat",
        "         AND ls_dd09v-bufallow = ls_current_dd09v-bufallow",
        "         AND ls_dd09v-pufferung = ls_current_dd09v-pufferung",
        "         AND ls_dd09v-schfeldanz = ls_current_dd09v-schfeldanz",
        "         AND ls_dd09v-protokoll = ls_current_dd09v-protokoll.",
        "        ev_status = 'E'. ev_code = 'NO_CHANGES'.",
        "        ev_message = 'Technical settings equal active definition'.",
        "        ev_version = '1.7'. RETURN.",
        "      ENDIF.",
        "    ENDIF.",
        "    IF lv_append = 'X'.",
        "      IF lv_existing IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'DDIC_OBJECT_NOT_FOUND'.",
        "        ev_message = 'Transparent table does not exist'.",
        "        ev_version = '1.5'. RETURN.",
        "      ENDIF.",
        "      IF lt_dd03p[] IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'FIELDS_REQUIRED'.",
        "        ev_message = 'Fields to append are required'.",
        "        ev_version = '1.5'. RETURN.",
        "      ENDIF.",
        "      lt_append_dd03p[] = lt_dd03p[].",
        "      lt_dd03p[] = lt_current_dd03p[].",
        "      CLEAR lv_index.",
        "      LOOP AT lt_dd03p INTO ls_compare_dd03p.",
        "        IF ls_compare_dd03p-fieldname CP '.INCLU--AP*'.",
        "          lv_index = sy-tabix. EXIT.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      LOOP AT lt_append_dd03p INTO ls_dd03p.",
        "        IF ls_dd03p-fieldname IS INITIAL",
        "           OR ls_dd03p-rollname IS INITIAL",
        "           OR ls_dd03p-fieldname = 'MANDT'",
        "           OR ls_dd03p-keyflag IS NOT INITIAL",
        "           OR ls_dd03p-notnull IS NOT INITIAL.",
        "          ev_status = 'E'. ev_code = 'UNSAFE_TABLE_CHANGE'.",
        "          ev_message = 'Only nullable non-key fields may append'.",
        "          ev_version = '1.5'. RETURN.",
        "        ENDIF.",
        "        READ TABLE lt_dd03p TRANSPORTING NO FIELDS",
        "          WITH KEY fieldname = ls_dd03p-fieldname.",
        "        IF sy-subrc = 0.",
        "          ev_status = 'E'. ev_code = 'FIELD_ALREADY_EXISTS'.",
        "          ev_message = 'Transparent table field already exists'.",
        "          ev_version = '1.5'. RETURN.",
        "        ENDIF.",
        "        CLEAR: ls_reference_dd04v, lv_reference_state.",
        "        CALL FUNCTION 'DDIF_DTEL_GET'",
        "          EXPORTING name = ls_dd03p-rollname state = 'A'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_reference_state",
        "            dd04v_wa = ls_reference_dd04v",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc <> 0 OR lv_reference_state <> 'A'.",
        "          ev_status = 'E'. ev_code = 'REFERENCE_NOT_FOUND'.",
        "          ev_message = 'Active data element reference not found'.",
        "          ev_version = '1.5'. RETURN.",
        "        ENDIF.",
        "        ls_dd03p-tabname = iv_object_name.",
        "        ls_dd03p-ddlanguage = sy-langu.",
        "        ls_dd03p-comptype = 'E'.",
        "        IF lv_index > 0.",
        "          INSERT ls_dd03p INTO lt_dd03p INDEX lv_index.",
        "          lv_index = lv_index + 1.",
        "        ELSE.",
        "          APPEND ls_dd03p TO lt_dd03p.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      LOOP AT lt_dd03p ASSIGNING <ls_field>.",
        "        <ls_field>-position = sy-tabix.",
        "      ENDLOOP.",
        "      ls_dd02v = ls_current_dd02v.",
        "      ls_dd09v = ls_current_dd09v.",
        "    ENDIF.",
        "    IF lv_patch = 'X'.",
        "      IF lv_existing IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'DDIC_OBJECT_NOT_FOUND'.",
        "        ev_message = 'Transparent table does not exist'.",
        "        ev_version = '1.6'. RETURN.",
        "      ENDIF.",
        "      IF lt_dd03p[] IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'FIELDS_REQUIRED'.",
        "        ev_message = 'Final table fields are required'.",
        "        ev_version = '1.6'. RETURN.",
        "      ENDIF.",
        "      CLEAR: lv_current_has_mandt, lv_final_has_mandt,",
        "        lv_changed, lv_key_closed, lv_current_complex_count,",
        "        lv_final_complex_count.",
        "      READ TABLE lt_current_dd03p TRANSPORTING NO FIELDS",
        "        WITH KEY fieldname = 'MANDT'.",
        "      IF sy-subrc = 0. lv_current_has_mandt = 'X'. ENDIF.",
        "      LOOP AT lt_current_dd03p INTO ls_compare_dd03p.",
        "        IF ls_compare_dd03p-fieldname CP '.INCLU*'",
        "           OR ( ls_compare_dd03p-adminfield IS NOT INITIAL",
        "             AND ls_compare_dd03p-adminfield <> '0' )",
        "           OR ( ls_compare_dd03p-comptype IS NOT INITIAL",
        "             AND ls_compare_dd03p-comptype <> 'E' ).",
        "          lv_current_complex_count = lv_current_complex_count + 1.",
        "          READ TABLE lt_dd03p TRANSPORTING NO FIELDS",
        "            WITH KEY fieldname = ls_compare_dd03p-fieldname",
        "              rollname = ls_compare_dd03p-rollname",
        "              precfield = ls_compare_dd03p-precfield",
        "              comptype = ls_compare_dd03p-comptype",
        "              adminfield = ls_compare_dd03p-adminfield",
        "              groupname = ls_compare_dd03p-groupname",
        "              exclass = ls_compare_dd03p-exclass",
        "              keyflag = ls_compare_dd03p-keyflag",
        "              notnull = ls_compare_dd03p-notnull.",
        "          IF sy-subrc <> 0.",
        "            ev_status = 'E'.",
        "            ev_code = 'COMPLEX_COMPONENT_CHANGE_FORBIDDEN'.",
        "            ev_message = 'Include and Append components are immutable'.",
        "            ev_version = '1.7'. RETURN.",
        "          ENDIF.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      REFRESH lt_checked_dd03p.",
        "      LOOP AT lt_dd03p INTO ls_dd03p.",
        "        lv_index = sy-tabix.",
        "        IF ls_dd03p-fieldname CP '.INCLU*'",
        "           OR ( ls_dd03p-adminfield IS NOT INITIAL",
        "             AND ls_dd03p-adminfield <> '0' )",
        "           OR ( ls_dd03p-comptype IS NOT INITIAL",
        "             AND ls_dd03p-comptype <> 'E' ).",
        "          lv_final_complex_count = lv_final_complex_count + 1.",
        "          READ TABLE lt_current_dd03p TRANSPORTING NO FIELDS",
        "            WITH KEY fieldname = ls_dd03p-fieldname",
        "              rollname = ls_dd03p-rollname",
        "              precfield = ls_dd03p-precfield",
        "              comptype = ls_dd03p-comptype",
        "              adminfield = ls_dd03p-adminfield",
        "              groupname = ls_dd03p-groupname",
        "              exclass = ls_dd03p-exclass",
        "              keyflag = ls_dd03p-keyflag",
        "              notnull = ls_dd03p-notnull.",
        "          IF sy-subrc <> 0.",
        "            ev_status = 'E'.",
        "            ev_code = 'COMPLEX_COMPONENT_CHANGE_FORBIDDEN'.",
        "            ev_message = 'Include and Append components are immutable'.",
        "            ev_version = '1.7'. RETURN.",
        "          ENDIF.",
        "          READ TABLE lt_current_dd03p INTO ls_compare_dd03p",
        "            INDEX lv_index.",
        "          IF sy-subrc <> 0",
        "             OR ls_compare_dd03p-fieldname <> ls_dd03p-fieldname",
        "             OR ls_compare_dd03p-precfield <> ls_dd03p-precfield",
        "             OR ls_compare_dd03p-adminfield <> ls_dd03p-adminfield.",
        "            lv_changed = 'X'.",
        "          ENDIF.",
        "          IF ls_dd03p-fieldname NP '.INCLU*'.",
        "            READ TABLE lt_checked_dd03p TRANSPORTING NO FIELDS",
        "              WITH KEY fieldname = ls_dd03p-fieldname.",
        "            IF sy-subrc = 0.",
        "              ev_status = 'E'. ev_code = 'DUPLICATE_FIELD'.",
        "              ev_message = 'Duplicate final field name'.",
        "              ev_version = '1.7'. RETURN.",
        "            ENDIF.",
        "            APPEND ls_dd03p TO lt_checked_dd03p.",
        "            IF ls_dd03p-keyflag IS INITIAL.",
        "              lv_key_closed = 'X'.",
        "            ELSEIF lv_key_closed = 'X'.",
        "              ev_status = 'E'. ev_code = 'KEY_ORDER_INVALID'.",
        "              ev_message = 'Key fields must be first'.",
        "              ev_version = '1.7'. RETURN.",
        "            ENDIF.",
        "          ENDIF.",
        "          ls_dd03p-tabname = iv_object_name.",
        "          ls_dd03p-ddlanguage = sy-langu.",
        "          ls_dd03p-position = lv_index.",
        "          MODIFY lt_dd03p FROM ls_dd03p INDEX lv_index.",
        "          CONTINUE.",
        "        ENDIF.",
        "        IF ls_dd03p-fieldname IS INITIAL",
        "           OR ls_dd03p-rollname IS INITIAL.",
        "          ev_status = 'E'. ev_code = 'FIELD_VALUE_INVALID'.",
        "          ev_message = 'Field and data element are required'.",
        "          ev_version = '1.6'. RETURN.",
        "        ENDIF.",
        "        READ TABLE lt_checked_dd03p TRANSPORTING NO FIELDS",
        "          WITH KEY fieldname = ls_dd03p-fieldname.",
        "        IF sy-subrc = 0.",
        "          ev_status = 'E'. ev_code = 'DUPLICATE_FIELD'.",
        "          ev_message = 'Duplicate final field name'.",
        "          ev_version = '1.6'. RETURN.",
        "        ENDIF.",
        "        IF ls_dd03p-keyflag IS INITIAL.",
        "          lv_key_closed = 'X'.",
        "        ELSEIF lv_key_closed = 'X'.",
        "          ev_status = 'E'. ev_code = 'KEY_ORDER_INVALID'.",
        "          ev_message = 'Key fields must be first'.",
        "          ev_version = '1.6'. RETURN.",
        "        ENDIF.",
        "        IF ls_dd03p-keyflag = 'X'",
        "           AND ls_dd03p-notnull IS INITIAL.",
        "          ev_status = 'E'. ev_code = 'KEY_NULLABLE'.",
        "          ev_message = 'Key fields must be not null'.",
        "          ev_version = '1.6'. RETURN.",
        "        ENDIF.",
        "        IF ls_dd03p-fieldname = 'MANDT'.",
        "          lv_final_has_mandt = 'X'.",
        "          IF lv_index <> 1 OR ls_dd03p-keyflag <> 'X'",
        "             OR ls_dd03p-notnull <> 'X'",
        "             OR ls_dd03p-rollname <> 'MANDT'.",
        "            ev_status = 'E'. ev_code = 'MANDT_CHANGE_FORBIDDEN'.",
        "            ev_message = 'MANDT definition cannot be changed'.",
        "            ev_version = '1.6'. RETURN.",
        "          ENDIF.",
        "        ENDIF.",
        "        CLEAR: ls_reference_dd04v, lv_reference_state.",
        "        CALL FUNCTION 'DDIF_DTEL_GET'",
        "          EXPORTING name = ls_dd03p-rollname state = 'A'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_reference_state",
        "            dd04v_wa = ls_reference_dd04v",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc <> 0 OR lv_reference_state <> 'A'.",
        "          ev_status = 'E'. ev_code = 'REFERENCE_NOT_FOUND'.",
        "          ev_message = 'Active data element reference not found'.",
        "          ev_version = '1.6'. RETURN.",
        "        ENDIF.",
        "        READ TABLE lt_current_dd03p INTO ls_compare_dd03p",
        "          INDEX lv_index.",
        "        IF sy-subrc <> 0",
        "           OR ls_compare_dd03p-fieldname <> ls_dd03p-fieldname",
        "           OR ls_compare_dd03p-rollname <> ls_dd03p-rollname",
        "           OR ls_compare_dd03p-keyflag <> ls_dd03p-keyflag",
        "           OR ls_compare_dd03p-notnull <> ls_dd03p-notnull.",
        "          lv_changed = 'X'.",
        "        ENDIF.",
        "        ls_dd03p-tabname = iv_object_name.",
        "        ls_dd03p-ddlanguage = sy-langu.",
        "        ls_dd03p-position = lv_index.",
        "        ls_dd03p-comptype = 'E'.",
        "        MODIFY lt_dd03p FROM ls_dd03p INDEX lv_index.",
        "        APPEND ls_dd03p TO lt_checked_dd03p.",
        "      ENDLOOP.",
        "      IF lv_current_complex_count <> lv_final_complex_count.",
        "        ev_status = 'E'.",
        "        ev_code = 'COMPLEX_COMPONENT_CHANGE_FORBIDDEN'.",
        "        ev_message = 'Include and Append components are immutable'.",
        "        ev_version = '1.7'. RETURN.",
        "      ENDIF.",
        "      IF lv_current_has_mandt <> lv_final_has_mandt.",
        "        ev_status = 'E'. ev_code = 'MANDT_CHANGE_FORBIDDEN'.",
        "        ev_message = 'MANDT definition cannot be changed'.",
        "        ev_version = '1.6'. RETURN.",
        "      ENDIF.",
        "      DESCRIBE TABLE lt_current_dd03p LINES lv_current_field_count.",
        "      DESCRIBE TABLE lt_dd03p LINES lv_field_count.",
        "      IF lv_current_field_count <> lv_field_count.",
        "        lv_changed = 'X'.",
        "      ENDIF.",
        "      IF lv_changed IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'NO_CHANGES'.",
        "        ev_message = 'Final fields equal active definition'.",
        "        ev_version = '1.6'. RETURN.",
        "      ENDIF.",
        "      ls_dd02v = ls_current_dd02v.",
        "      ls_dd09v = ls_current_dd09v.",
        "    ENDIF.",
        "    lv_mode = 'M'.",
        "    SELECT SINGLE * FROM tadir INTO ls_tadir",
        "      WHERE pgmid = 'R3TR' AND object = lv_tadir_type",
        "        AND obj_name = iv_object_name.",
        "    IF sy-subrc = 0 AND ls_tadir-devclass <> iv_package.",
        "      ev_status = 'E'. ev_code = 'PACKAGE_CONFLICT'.",
        "      ev_message = 'Existing object belongs to another package'.",
        "      ev_version = '1.2'. RETURN.",
        "    ENDIF.",
        "    IF sy-subrc <> 0.",
        "      lv_mode = 'I'.",
        "    ENDIF.",
        "    IF lv_delete = 'X'. lv_mode = 'D'. ENDIF.",
        # r22: RS_CORR_INSERT creates the TADIR entry itself, and that path runs the data-type /
        # GSUB package check (see GSUB_CHECK_OBJ_ATTR), which rejects lock objects with TO/142
        # "SAP object ENQU <name> cannot be assigned to package <pkg>" - verified 2026-09-23 in two
        # different customer packages while tables, views and number ranges succeed. Register lock
        # objects the way the number-range and view arms do - TADIR entry plus the request recorder -
        # and skip RS_CORR_INSERT for them. r23 fixes the actual dump cause, taken from the ST22
        # full content of 2026-09-23 09:04:49: "The call to the function module TR_TADIR_INTERFACE is
        # incorrect: ... only fields of a particular type under WI_TADIR_SRCSYSTEM" - sy-sysid is
        # SYSYSID (CHAR 8) while the formal is TADIR-SRCSYSTEM (CHAR 10). The number-range arm never
        # hit this because it passes TADIR fields, so the values are moved into a TADIR structure
        # first and only those fields are passed.
        "    CLEAR lv_recorded_request.",
        "    IF lv_delete IS INITIAL AND lv_object_type = 'ENQU'.",
        "      CLEAR: ls_corr_enqu_input, ls_corr_enqu_tadir.",
        "      ls_corr_enqu_input-pgmid = 'R3TR'.",
        "      ls_corr_enqu_input-object = 'ENQU'.",
        "      ls_corr_enqu_input-obj_name = iv_object_name.",
        "      ls_corr_enqu_input-srcsystem = sy-sysid.",
        "      ls_corr_enqu_input-author = sy-uname.",
        "      ls_corr_enqu_input-devclass = iv_package.",
        "      ls_corr_enqu_input-masterlang = sy-langu.",
        "      CALL FUNCTION 'TR_TADIR_INTERFACE'",
        "        EXPORTING wi_test_modus = space",
        "          wi_tadir_pgmid = ls_corr_enqu_input-pgmid",
        "          wi_tadir_object = ls_corr_enqu_input-object",
        "          wi_tadir_obj_name = ls_corr_enqu_input-obj_name",
        "          wi_tadir_srcsystem = ls_corr_enqu_input-srcsystem",
        "          wi_tadir_author = ls_corr_enqu_input-author",
        "          wi_tadir_devclass = ls_corr_enqu_input-devclass",
        "          wi_tadir_masterlang = ls_corr_enqu_input-masterlang",
        "          iv_no_pak_check = 'X'",
        "        IMPORTING new_tadir_entry = ls_corr_enqu_tadir",
        "        EXCEPTIONS others = 1.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'TADIR_ENTRY_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_corr_enqu_objects, lt_corr_enqu_recorded.",
        "      CLEAR ls_corr_enqu_object.",
        "      MOVE-CORRESPONDING ls_corr_enqu_tadir TO ls_corr_enqu_object.",
        "      APPEND ls_corr_enqu_object TO lt_corr_enqu_objects.",
        "      CALL FUNCTION 'TR_RECORD_OBJ_CHANGE_TO_REQ'",
        "        EXPORTING iv_request = iv_request",
        "          it_objects = lt_corr_enqu_objects",
        "        IMPORTING et_tadir = lt_corr_enqu_recorded",
        "        EXCEPTIONS cancel = 1.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'TRANSPORT_RECORD_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        CONCATENATE ev_message '[' sy-msgid '/' sy-msgno ']'",
        "          INTO ev_message SEPARATED BY space.",
        "        ev_version = '1.11'. RETURN.",
        "      ENDIF.",
        "      lv_recorded_request = iv_request.",
        "    ENDIF.",
        "    IF lv_recorded_request IS INITIAL.",
        "    ls_corr_object-objtype = lv_object_type.",
        "    ls_corr_object-objname = iv_object_name.",
        "    CALL FUNCTION 'RS_CORR_INSERT'",
        "      EXPORTING object = ls_corr_object",
        "        object_class = 'DICT' mode = lv_mode",
        "        devclass = iv_package korrnum = iv_request",
        "        use_korrnum_immediatedly = 'X'",
        "        master_language = sy-langu suppress_dialog = 'X'",
        "      IMPORTING korrnum = lv_recorded_request",
        "      EXCEPTIONS cancelled = 1 permission_failure = 2",
        "        unknown_objectclass = 3 OTHERS = 4.",
        "    IF sy-subrc <> 0.",
        "      ROLLBACK WORK.",
        "      ev_status = 'E'. ev_code = 'TRANSPORT_RECORD_FAILED'.",
        "      MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "        WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "        INTO ev_message.",
        # §8「可用时返回报文 ID/编号」：失败时把 SAP 报文类/编号附在文本后，否则调用方只看到
        # 本地化文本，无法定位是哪条检查拒绝（payload 行在错误路径上不会被返回给调用方）。
        "      CONCATENATE ev_message '[' sy-msgid '/' sy-msgno ']'",
        "        INTO ev_message SEPARATED BY space.",
        "      ev_version = '1.2'. RETURN.",
        "    ENDIF.",
        "    ENDIF.",
        "    IF lv_delete = 'X'.",
        "      CLEAR lv_deleted. REFRESH lt_object_refs.",
        "      CALL FUNCTION 'DDIF_OBJECT_DELETE'",
        "        EXPORTING type = lv_state_type name = lv_ddic_name",
        "          authority_check = 'X'",
        "        IMPORTING deleted = lv_deleted",
        "        TABLES objects_with_references = lt_object_refs",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF lt_object_refs[] IS NOT INITIAL.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'DEPENDENCIES_EXIST'.",
        "        ev_message = 'DDIC object is still referenced'.",
        "        ev_version = '1.4'. RETURN.",
        "      ENDIF.",
        "      IF sy-subrc <> 0 OR lv_deleted IS INITIAL.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'DDIC_DELETE_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.4'. RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      CLEAR lv_active_state.",
        "      CALL FUNCTION 'DDIF_STATE_GET'",
        "        EXPORTING type = lv_state_type name = lv_ddic_name",
        "          state = 'A'",
        "        IMPORTING gotstate = lv_active_state",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc = 0 AND lv_active_state IS NOT INITIAL.",
        "        ev_status = 'E'. ev_code = 'DDIC_DELETE_VERIFY_FAILED'.",
        "        ev_message = 'DDIC object still exists after delete'.",
        "        ev_version = '1.4'. RETURN.",
        "      ENDIF.",
        # 通用删除路径原先只删 DDIC 定义，遗留 TADIR 条目（DELFLAG 为空），与 NROB/VIEW 删除分支
        # 的既有约定不一致；这里补齐同样的 TADIR 移除，且只在 DDIC 定义确认已删之后执行。
        # 不新增 payload 行：delete_ddic_object 对 TABL 以「header 必须为空」判定删除干净，
        # 多一行 payload 会被判成残留定义，故仅做移除与提交。
        # r12/r13 两次实测：TR_TADIR_INTERFACE 调用后 TADIR 行仍在（DELFLAG 为空），且该分支既没有
        # 记录 sy-subrc 也没有复查，失败被静默吞掉。TRINT_TADIR_INTERFACE 的删除分支把入参当作完整
        # TADIR 行交给 delete_tadir__entry，故这里与 NROB/VIEW 分支对齐传全字段（VIEW 分支一直如此），
        # 再捕获返回值、复查移除结果。
        "      CLEAR ls_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = lv_tadir_type",
        "          AND obj_name = iv_object_name.",
        "      CLEAR: lv_tadir_entry_left, lv_tadir_rc, ev_message.",
        "      IF sy-subrc = 0.",
        # r17: creating a table through RS_CORR_INSERT leaves an order lock in TLOCK for this
        # object and request. TR_TADIR_INTERFACE then refuses to delete the directory entry with
        # exception 22 (OBJECT_LOCKED_FOR_ORDER, message TO/142); RS_CORR_INSERT with mode = 'D'
        # clears the request entries (E071) but not that lock. Release only the lock rows of this
        # request whose key range carries this object name, then delete the directory entry.
        # (Verified 2026-09-22: T01/T02 keep rc 22 while VIEW/NROB, which never take this lock,
        # delete cleanly.)
        "        IF iv_request IS NOT INITIAL.",
        "          CONCATENATE iv_object_name '%' INTO lv_lock_pattern.",
        "          DELETE FROM tlock WHERE trkorr = iv_request",
        "            AND ( hikey LIKE lv_lock_pattern",
        "            OR lokey LIKE lv_lock_pattern ).",
        "        ENDIF.",
        # 异常名按 TR_TADIR_INTERFACE 的声明列表编号（1 = 条目不存在、11 = 无删除权限、
        # 22 = 对象被请求锁定），其余归入 others，便于下一轮直接由 rc 判定拒绝原因；
        # 该 FM 的包装层用 CURRENT_MESSAGE_RAISING 抛出，故 sy-msg* 同时携带 SAP 原文。
        "        CALL FUNCTION 'TR_TADIR_INTERFACE'",
        "          EXPORTING wi_delete_tadir_entry = 'X'",
        "            wi_test_modus = space",
        "            wi_tadir_pgmid = ls_tadir-pgmid",
        "            wi_tadir_object = ls_tadir-object",
        "            wi_tadir_obj_name = ls_tadir-obj_name",
        "            wi_tadir_srcsystem = ls_tadir-srcsystem",
        "            wi_tadir_author = ls_tadir-author",
        "            wi_tadir_devclass = ls_tadir-devclass",
        "            wi_tadir_masterlang = ls_tadir-masterlang",
        "          EXCEPTIONS",
        "            tadir_entry_not_existing = 1",
        "            no_authorization_to_delete = 11",
        "            object_locked_for_order = 22",
        "            others = 99.",
        "        lv_tadir_rc = sy-subrc.",
        "        IF lv_tadir_rc = 0.",
        "          COMMIT WORK AND WAIT.",
        "        ELSE.",
        "          CLEAR lv_tadir_rc_text.",
        "          WRITE lv_tadir_rc TO lv_tadir_rc_text.",
        "          IF sy-msgid IS NOT INITIAL.",
        "            MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "              WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "              INTO ev_message.",
        "            CONCATENATE '[' sy-msgid '/' sy-msgno ']' ev_message",
        "              INTO ev_message SEPARATED BY space.",
        "          ENDIF.",
        "          CONCATENATE 'TR_TADIR_INTERFACE rc' lv_tadir_rc_text",
        "            ev_message INTO ev_message SEPARATED BY space.",
        "        ENDIF.",
        "        CLEAR ls_tadir.",
        "        SELECT SINGLE * FROM tadir INTO ls_tadir",
        "          WHERE pgmid = 'R3TR' AND object = lv_tadir_type",
        "            AND obj_name = iv_object_name.",
        "        IF sy-subrc = 0.",
        "          lv_tadir_entry_left = 'X'.",
        "        ENDIF.",
        "      ENDIF.",
        "      CLEAR: ls_dd01v, ls_dd04v, ls_dd02v, ls_dd09v,",
        "        ls_dd40v.",
        "      REFRESH: lt_dd07v, lt_dd03p, lt_dd42v, lt_dd43v.",
        # DDIC 定义已删但 TADIR 条目仍在，等于对象在资源库与传输里继续"存在"：这不是完整成功，
        # 而成功响应的 text 会被服务层丢弃，只有错误通道能把原因交回调用方，故按契约失败返回。
        "      IF lv_tadir_entry_left = 'X'.",
        "        ev_status = 'E'. ev_code = 'TADIR_ENTRY_NOT_REMOVED'.",
        "        CONCATENATE 'DDIC object deleted but its TADIR entry remains;'",
        "          ev_message INTO ev_message SEPARATED BY space.",
        "        ev_version = '1.4'. RETURN.",
        "      ENDIF.",
        "      ev_status = 'S'. ev_code = 'DDIC_OBJECT_DELETED'.",
        "      ev_message = 'DDIC object deleted after dependency check'.",
        "      ev_version = '1.4'. RETURN.",
        "    ENDIF.",
        "    CLEAR lv_rc.",
        "    CASE lv_object_type.",
        "      WHEN 'DOMA'.",
        "        ls_dd01v-domname = iv_object_name.",
        "        ls_dd01v-ddlanguage = sy-langu.",
        "        ls_dd01v-ddtext = iv_description.",
        "        IF ls_dd01v-outputlen IS INITIAL.",
        "          ls_dd01v-outputlen = ls_dd01v-leng.",
        "        ENDIF.",
        "        LOOP AT lt_dd07v ASSIGNING <ls_value>.",
        "          <ls_value>-domname = iv_object_name.",
        "          <ls_value>-ddlanguage = sy-langu.",
        "          <ls_value>-valpos = sy-tabix.",
        "        ENDLOOP.",
        "        IF lt_dd07v[] IS INITIAL.",
        "          CLEAR ls_dd01v-valexi.",
        "        ELSE.",
        "          ls_dd01v-valexi = 'X'.",
        "        ENDIF.",
        "        CALL FUNCTION 'DDIF_DOMA_PUT'",
        "          EXPORTING name = lv_ddic_name dd01v_wa = ls_dd01v",
        "          TABLES dd07v_tab = lt_dd07v",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc = 0.",
        "          CALL FUNCTION 'DDIF_DOMA_ACTIVATE'",
        "            EXPORTING name = lv_ddic_name auth_chk = 'X'",
        "            IMPORTING rc = lv_rc EXCEPTIONS OTHERS = 1.",
        "        ENDIF.",
        "      WHEN 'DTEL'.",
        "        ls_dd04v-rollname = iv_object_name.",
        "        ls_dd04v-ddlanguage = sy-langu.",
        "        ls_dd04v-ddtext = iv_description.",
        "        CLEAR: ls_domain_dd01v, lt_domain_dd07v.",
        "        CALL FUNCTION 'DDIF_DOMA_GET'",
        "          EXPORTING name = ls_dd04v-domname state = 'A'",
