        "            dd01v_wa = ls_domain_dd01v",
        "          TABLES dd07v_tab = lt_domain_dd07v",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc <> 0 OR lv_active_state <> 'A'.",
        "          ev_status = 'E'. ev_code = 'REFERENCE_NOT_FOUND'.",
        "          ev_message = 'Active domain reference not found'.",
        "          ev_version = '1.2'. RETURN.",
        "        ENDIF.",
        "        IF ls_dd04v-reptext IS NOT INITIAL.",
        "          lv_text_length = strlen( ls_dd04v-reptext ).",
        "          ls_dd04v-headlen = lv_text_length.",
        "          IF ls_domain_dd01v-outputlen > ls_dd04v-headlen.",
        "            IF ls_domain_dd01v-outputlen > 55.",
        "              ls_dd04v-headlen = 55.",
        "            ELSE.",
        "              ls_dd04v-headlen = ls_domain_dd01v-outputlen.",
        "            ENDIF.",
        "          ENDIF.",
        "        ENDIF.",
        "        IF ls_dd04v-scrtext_s IS NOT INITIAL.",
        "          lv_text_length = strlen( ls_dd04v-scrtext_s ).",
        "          IF lv_text_length < 10. lv_text_length = 10. ENDIF.",
        "          ls_dd04v-scrlen1 = lv_text_length.",
        "        ENDIF.",
        "        IF ls_dd04v-scrtext_m IS NOT INITIAL.",
        "          lv_text_length = strlen( ls_dd04v-scrtext_m ).",
        "          IF lv_text_length < 15. lv_text_length = 15. ENDIF.",
        "          ls_dd04v-scrlen2 = lv_text_length.",
        "        ENDIF.",
        "        IF ls_dd04v-scrtext_l IS NOT INITIAL.",
        "          lv_text_length = strlen( ls_dd04v-scrtext_l ).",
        "          IF lv_text_length < 20. lv_text_length = 20. ENDIF.",
        "          ls_dd04v-scrlen3 = lv_text_length.",
        "        ENDIF.",
        "        CALL FUNCTION 'DDIF_DTEL_PUT'",
        "          EXPORTING name = lv_ddic_name dd04v_wa = ls_dd04v",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc = 0.",
        "          CALL FUNCTION 'DDIF_DTEL_ACTIVATE'",
        "            EXPORTING name = lv_ddic_name auth_chk = 'X'",
        "            IMPORTING rc = lv_rc EXCEPTIONS OTHERS = 1.",
        "        ENDIF.",
        "      WHEN 'STRU'.",
        "        IF lt_dd03p[] IS INITIAL.",
        "          ev_status = 'E'. ev_code = 'FIELDS_REQUIRED'.",
        "          ev_message = 'Structure fields are required'.",
        "          ev_version = '1.2'. RETURN.",
        "        ENDIF.",
        "        CLEAR: ls_dd02v, ls_dd09v.",
        "        ls_dd02v-tabname = iv_object_name.",
        "        ls_dd02v-ddlanguage = sy-langu.",
        "        ls_dd02v-tabclass = 'INTTAB'.",
        "        ls_dd02v-masterlang = sy-langu.",
        "        ls_dd02v-ddtext = iv_description.",
        "        LOOP AT lt_dd03p ASSIGNING <ls_field>.",
        "          <ls_field>-tabname = iv_object_name.",
        "          <ls_field>-ddlanguage = sy-langu.",
        "          <ls_field>-position = sy-tabix.",
        "          <ls_field>-comptype = 'E'.",
        "        ENDLOOP.",
        "        CALL FUNCTION 'DDIF_TABL_PUT'",
        "          EXPORTING name = lv_ddic_name dd02v_wa = ls_dd02v",
        "            dd09l_wa = ls_dd09v",
        "          TABLES dd03p_tab = lt_dd03p",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc = 0.",
        "          CALL FUNCTION 'DDIF_TABL_ACTIVATE'",
        "            EXPORTING name = lv_ddic_name auth_chk = 'X'",
        "              excommit = 'X'",
        "            IMPORTING rc = lv_rc EXCEPTIONS OTHERS = 1.",
        "        ENDIF.",
        "      WHEN 'SHLP'.",
        # 这里原先有一句 CLEAR: lt_dd31v, lt_dd32p, lt_dd33v.，它在写入前把**解析好的入参**清空：
        # 这三张表由 IT_SOURCE 的 S1/S2/S3 行在上方解析填充，CLEAR 之后下面的三个 LOOP 全部空转，
        # DDIF_SHLP_PUT 收到三张空表；按 DDIF_*_PUT 的"整集替换"语义即**删除该搜索帮助的全部
        # DD31S/DD32P/DD33S 行**。这正是 D6-1 缺陷②（改 HIDEFLAG 导致子表被静默丢弃）的根因。
        # 三张表是函数模块局部变量，每次调用本就重新初始化，故该 CLEAR 既多余又有害，予以删除。
        "        ls_dd30v-shlpname = iv_object_name.",
        "        ls_dd30v-ddlanguage = sy-langu.",
        "        ls_dd30v-ddtext = iv_description.",
        "        lv_index = 0.",
        "        LOOP AT lt_dd31v ASSIGNING <ls_dd31v>.",
        "          lv_index = lv_index + 1.",
        "          <ls_dd31v>-shlpname = iv_object_name.",
        "          <ls_dd31v>-shposition = lv_index.",
        "        ENDLOOP.",
        "        LOOP AT lt_dd32p ASSIGNING <ls_dd32p>.",
        "          <ls_dd32p>-shlpname = iv_object_name.",
        "          <ls_dd32p>-flposition = sy-tabix.",
        "        ENDLOOP.",
        "        LOOP AT lt_dd33v ASSIGNING <ls_dd33v>.",
        "          <ls_dd33v>-shlpname = iv_object_name.",
        "        ENDLOOP.",
        "        CALL FUNCTION 'DDIF_SHLP_PUT'",
        "          EXPORTING name = lv_ddic_name dd30v_wa = ls_dd30v",
        "          TABLES dd31v_tab = lt_dd31v",
        "            dd32p_tab = lt_dd32p",
        "            dd33v_tab = lt_dd33v",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc = 0.",
        "          CALL FUNCTION 'DDIF_SHLP_ACTIVATE'",
        "            EXPORTING name = lv_ddic_name",
        "            IMPORTING rc = lv_rc",
        "            EXCEPTIONS OTHERS = 1.",
        "        ENDIF.",
        "      WHEN 'ENQU'.",
        "        ls_dd25v-viewname = iv_object_name.",
        "        ls_dd25v-ddlanguage = sy-langu.",
        "        ls_dd25v-ddtext = iv_description.",
        "        LOOP AT lt_dd26v ASSIGNING <ls_dd26v>.",
        "          <ls_dd26v>-viewname = iv_object_name.",
        "          <ls_dd26v>-tabpos = sy-tabix.",
        "        ENDLOOP.",
        "        LOOP AT lt_dd27p ASSIGNING <ls_dd27p>.",
        "          <ls_dd27p>-viewname = iv_object_name.",
        "          <ls_dd27p>-objpos = sy-tabix.",
        "        ENDLOOP.",
        "        CALL FUNCTION 'DDIF_ENQU_PUT'",
        "          EXPORTING name = lv_ddic_name dd25v_wa = ls_dd25v",
        "          TABLES dd26e_tab = lt_dd26v",
        "            dd27p_tab = lt_dd27p",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc = 0.",
        "          CALL FUNCTION 'DDIF_ENQU_ACTIVATE'",
        "            EXPORTING name = lv_ddic_name",
        "            IMPORTING rc = lv_rc",
        "            EXCEPTIONS OTHERS = 1.",
        "        ENDIF.",
        "      WHEN 'TABL'.",
        "        IF lv_resume = 'X'.",
        "          CLEAR lv_inactive_exists.",
        "          SELECT SINGLE as4local FROM dd02l INTO lv_inactive_exists",
        "            WHERE tabname = iv_object_name AND as4local = 'N'.",
        "          IF lv_inactive_exists <> 'N'.",
        "            ev_status = 'E'. ev_code = 'NO_INACTIVE_VERSION'.",
        "            ev_message = 'No inactive DDIC version exists to resume'.",
        # 1.14：该分支的 ev_version 跟随表里的 RESUME_TABLE_ACTIVATION|1.14 行。1.11 曾是对的值
        # （旧名 1.10 被 CHAR 32 截断、从未派发），1.11/1.12 能派发这个名字却走转换恢复路径，
        # 1.13 走到了本分支却因裸调 DD_TABL_ACT 从未激活过任何对象。首个真正可用的恢复激活
        # 就是本次修复所在的 1.14。1.16 起该行随写后激活判据抬到 1.16，本分支的回答版本同步。
        "            ev_version = '1.16'. RETURN.",
        "          ENDIF.",
        "          REFRESH lt_act_res.",
        # 1.14：透明表的激活必须走 DDIF 包装器，不能裸调 DD_TABL_ACT。DDIF_TABL_ACTIVATE 先
        # START_PROTOCOL 'TABL' 取得 GR_PRID，再以 DEVICE = ' ' 与 PRID = GR_PRID 调用
        # DD_TABL_ACT；裸调省略这些参数时 DEVICE 取默认 'F'、PRID = 0，mass_act_tabl 拿不到
        # 可用协议通道，于是不改写 ACT_RESULT——调用方读到的是第 121 行的初始化值 8、
        # act_res_tab 为空、sy-subrc = 0，表现成「激活失败但没有任何原因」。同臂的 STRU 分支
        # 与兄弟分支（DDIF_DOMA / DTEL / SHLP / ENQU / TTYP_ACTIVATE）都是这么调的，只有
        # TABL 臂的两处激活曾是例外。依据 .doc/d6-5-activation-sufficiency-20260922.md
        # §4 步骤 2：该文确认 DDIF_TABL_ACTIVATE 是标准单对象激活路径，且基表 ACTFLAG = ' '
        # 亦可（mode 1 的 '4U ' 允许）。NAME 是 DDOBJNAME（CHAR 30），与同臂 DDIF_TABL_PUT
        # 一致，因此也不再有 DD_TABL_ACT-TABNAME（DD02L-TABNAME，CHAR 30）对
        # IV_OBJECT_NAME（TADIR-OBJ_NAME，CHAR 40）的 CALL_FUNCTION_CONFLICT_TYPE 风险。
        # DDIF_TABL_ACTIVATE 不返回 ACT_RES_TAB，故 lt_act_res 保持为空；失败原因写入 ABAP/4
        # Dictionary 日志 ACTTABL<NAME>，不在本接口的回执里。
        "          CALL FUNCTION 'DDIF_TABL_ACTIVATE'",
        "            EXPORTING name = lv_ddic_name auth_chk = 'X'",
        "              excommit = 'X'",
        "            IMPORTING rc = lv_rc",
        "            EXCEPTIONS not_found = 1 put_failure = 2",
        "              OTHERS = 3.",
        # 必须在激活调用之后立刻取 sy-subrc：紧随其后的诊断性 READ TABLE 会把 sy-subrc 改成 4
        # （DDIF_TABL_ACTIVATE 不返回 ACT_RES_TAB，lt_act_res 恒为空），从而把成功激活误判为失败。
        "          lv_activation_subrc = sy-subrc.",
        "          READ TABLE lt_act_res INTO ls_act_res",
        "            WITH KEY tabname = lv_ddic_name.",
        "        ELSE.",
        "        IF lt_dd03p[] IS INITIAL.",
        "          ev_status = 'E'. ev_code = 'FIELDS_REQUIRED'.",
        "          ev_message = 'Transparent table fields are required'.",
        "          ev_version = '1.3'. RETURN.",
        "        ENDIF.",
        "        ls_dd02v-tabname = iv_object_name.",
        "        ls_dd02v-ddlanguage = sy-langu.",
        "        ls_dd02v-tabclass = 'TRANSP'.",
        "        ls_dd02v-masterlang = sy-langu.",
        "        ls_dd02v-ddtext = iv_description.",
        "        ls_dd09v-tabname = iv_object_name.",
        "        LOOP AT lt_dd03p ASSIGNING <ls_field>.",
        "          IF lv_append IS INITIAL AND lv_patch IS INITIAL",
        "             AND lv_settings IS INITIAL.",
        "            <ls_field>-tabname = iv_object_name.",
        "            <ls_field>-ddlanguage = sy-langu.",
        "            <ls_field>-position = sy-tabix.",
        "            <ls_field>-comptype = 'E'.",
        "            <ls_field>-notnull = 'X'.",
        "          ENDIF.",
        "        ENDLOOP.",
        "        IF lv_settings = 'X'.",
        "          CALL FUNCTION 'DDIF_TABT_PUT'",
        "            EXPORTING name = lv_ddic_name dd09l_wa = ls_dd09v",
        "            EXCEPTIONS OTHERS = 1.",
        "        ELSE.",
        "          CALL FUNCTION 'DDIF_TABL_PUT'",
        "            EXPORTING name = lv_ddic_name dd02v_wa = ls_dd02v",
        "              dd09l_wa = ls_dd09v",
        "            TABLES dd03p_tab = lt_dd03p",
        "            EXCEPTIONS OTHERS = 1.",
        "        ENDIF.",
        "        lv_put_subrc = sy-subrc.",
        "        CLEAR lv_rc.",
        "        IF lv_put_subrc <> 0.",
        "          CLEAR: lv_msg_class, lv_msg_type, lv_msg_number, lv_msg_text.",
        "          lv_msg_class = sy-msgid.",
        "          lv_msg_type = sy-msgty.",
        "          lv_msg_number = sy-msgno.",
        "          IF lv_msg_class IS NOT INITIAL AND",
        "             lv_msg_number IS NOT INITIAL.",
        "            MESSAGE ID lv_msg_class TYPE lv_msg_type",
        "              NUMBER lv_msg_number",
        "              WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "              INTO lv_msg_text.",
        "          ENDIF.",
        "        ENDIF.",
        "        IF lv_put_subrc = 0.",
        "          REFRESH lt_act_res.",
        # 1.14：透明表的激活必须走 DDIF 包装器，不能裸调 DD_TABL_ACT。DDIF_TABL_ACTIVATE 先
        # START_PROTOCOL 'TABL' 取得 GR_PRID，再以 DEVICE = ' ' 与 PRID = GR_PRID 调用
        # DD_TABL_ACT；裸调省略这些参数时 DEVICE 取默认 'F'、PRID = 0，mass_act_tabl 拿不到
        # 可用协议通道，于是不改写 ACT_RESULT——调用方读到的是第 121 行的初始化值 8、
        # act_res_tab 为空、sy-subrc = 0，表现成「激活失败但没有任何原因」。同臂的 STRU 分支
        # 与兄弟分支（DDIF_DOMA / DTEL / SHLP / ENQU / TTYP_ACTIVATE）都是这么调的，只有
        # TABL 臂的两处激活曾是例外。依据 .doc/d6-5-activation-sufficiency-20260922.md
        # §4 步骤 2：该文确认 DDIF_TABL_ACTIVATE 是标准单对象激活路径，且基表 ACTFLAG = ' '
        # 亦可（mode 1 的 '4U ' 允许）。NAME 是 DDOBJNAME（CHAR 30），与同臂 DDIF_TABL_PUT
        # 一致，因此也不再有 DD_TABL_ACT-TABNAME（DD02L-TABNAME，CHAR 30）对
        # IV_OBJECT_NAME（TADIR-OBJ_NAME，CHAR 40）的 CALL_FUNCTION_CONFLICT_TYPE 风险。
        # DDIF_TABL_ACTIVATE 不返回 ACT_RES_TAB，故 lt_act_res 保持为空；失败原因写入 ABAP/4
        # Dictionary 日志 ACTTABL<NAME>，不在本接口的回执里。
        "          CALL FUNCTION 'DDIF_TABL_ACTIVATE'",
        "            EXPORTING name = lv_ddic_name auth_chk = 'X'",
        "              excommit = 'X'",
        "            IMPORTING rc = lv_rc",
        "            EXCEPTIONS not_found = 1 put_failure = 2",
        "              OTHERS = 3.",
        # 必须在激活调用之后立刻取 sy-subrc：紧随其后的诊断性 READ TABLE 会把 sy-subrc 改成 4
        # （DDIF_TABL_ACTIVATE 不返回 ACT_RES_TAB，lt_act_res 恒为空），从而把成功激活误判为失败。
        "          lv_activation_subrc = sy-subrc.",
        "          READ TABLE lt_act_res INTO ls_act_res",
        "            WITH KEY tabname = lv_ddic_name.",
        "        ELSE.",
        # PUT 失败时不会调用 DD_TABL_ACT，激活子返回码必须显式取自 PUT 的 sy-subrc，
        # 否则 TABL 分支会漏报失败（旧语义靠 ENDCASE 之后的 sy-subrc 兜底，现已改为显式赋值）。
        "          lv_activation_subrc = lv_put_subrc.",
        "        ENDIF.",
        "        ENDIF.",
        "      WHEN 'TTYP'.",
        "        CLEAR: lt_dd42v, lt_dd43v.",
        "        ls_dd40v-typename = iv_object_name.",
        "        ls_dd40v-ddlanguage = sy-langu.",
        "        ls_dd40v-rowkind = 'S'.",
        "        ls_dd40v-datatype = 'STRU'.",
        "        ls_dd40v-accessmode = 'T'.",
        "        ls_dd40v-keydef = 'D'.",
        "        ls_dd40v-keykind = 'N'.",
        "        ls_dd40v-ddtext = iv_description.",
        "        CALL FUNCTION 'DDIF_TTYP_PUT'",
        "          EXPORTING name = lv_ddic_name dd40v_wa = ls_dd40v",
        "          TABLES dd42v_tab = lt_dd42v dd43v_tab = lt_dd43v",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc = 0.",
        "          CALL FUNCTION 'DDIF_TTYP_ACTIVATE'",
        "            EXPORTING name = lv_ddic_name",
        "            IMPORTING rc = lv_rc EXCEPTIONS OTHERS = 1.",
        "        ENDIF.",
        "    ENDCASE.",
        # 只有非 TABL 类型继续沿用"取分支最后一条语句的 sy-subrc"这一旧语义。TABL 分支的
        # DD_TABL_ACT 之后紧跟一条诊断性 READ TABLE（成功激活时 ACT_RES_TAB 为空，sy-subrc=4），
        # 该取值曾把"已激活"误判为 DDIC_SAVE_FAILED 并执行 ROLLBACK WORK（2026-09-22 运行时回归）。
        # TABL 的 sy-subrc 已在调用点显式捕获，这里不得覆盖。
        "    IF lv_object_type <> 'TABL'.",
        "      lv_activation_subrc = sy-subrc.",
        "    ENDIF.",
        "    IF lv_object_type = 'TABL'",
        "       AND ( lv_activation_subrc <> 0 OR lv_rc <> 0 ).",
        "      CLEAR lv_append_count.",
        "      SELECT COUNT(*) FROM tbatg INTO lv_append_count",
        "        WHERE object = 'TABL' AND tabname = iv_object_name.",
        "      IF lv_append_count > 0.",
        "        REFRESH it_source.",
        "        add_payload 'M' '1' 'PACKAGE' iv_package.",
        "        add_payload 'M' '1' 'REQUEST' lv_recorded_request.",
        "        add_payload 'M' '1' 'CONVERSION_ACTION'",
        "          ls_act_res-action.",
        "        add_payload 'M' '1' 'CONVERSION_MODE'",
        "          ls_act_res-modeflag.",
        "        add_payload 'M' '1' 'CONVERSION_DATA_LOSS'",
        "          ls_act_res-dataloss_d.",
        "        ev_status = 'E'. ev_code = 'DDIC_CONVERSION_PENDING'.",
        "        ev_message = 'Native table conversion requires recovery'.",
        "        ev_version = '1.7'. RETURN.",
        "      ENDIF.",
        "    ENDIF.",
        "    IF lv_activation_subrc = 0 AND lv_rc <> 0.",
        "      CLEAR lv_active_state.",
        "      CALL FUNCTION 'DDIF_STATE_GET'",
        "        EXPORTING type = lv_state_type name = lv_ddic_name",
        "          state = 'A'",
        "        IMPORTING gotstate = lv_active_state",
        "        EXCEPTIONS OTHERS = 1.",
        "    ENDIF.",
        "    IF lv_activation_subrc <> 0.",
        "      ROLLBACK WORK.",
        "      ev_status = 'E'. ev_code = 'DDIC_SAVE_FAILED'.",
        "      IF lv_msg_text IS NOT INITIAL.",
        "        ev_message = lv_msg_text.",
        "      ELSEIF lv_put_subrc <> 0.",
        "        CLEAR lv_put_subrc_text.",
        "        WRITE lv_put_subrc TO lv_put_subrc_text.",
        "        CONCATENATE 'DDIF_TABL_PUT failed with sy-subrc'",
        "          lv_put_subrc_text INTO ev_message SEPARATED BY ' '.",
        "      ELSE.",
        "        ev_message = 'DDIC put or activation failed'.",
        "      ENDIF.",
        "      IF lv_object_type = 'TABL'.",
        "        CLEAR: lv_inactive_exists, lv_tadir_exists.",
        "        SELECT SINGLE as4local FROM dd02l INTO lv_inactive_exists",
        "          WHERE tabname = iv_object_name AND as4local = 'N'.",
        "        SELECT SINGLE pgmid FROM tadir INTO lv_tadir_exists",
        "          WHERE pgmid = 'R3TR' AND object = 'TABL'",
        "            AND obj_name = iv_object_name.",
        "        IF lv_inactive_exists = 'N'.",
        "          lv_phase = 'inactive_saved'.",
        "        ELSE.",
        "          lv_phase = 'save_rejected'.",
        "        ENDIF.",
        "        CLEAR it_source.",
        "        add_payload 'M' '1' 'PACKAGE' iv_package.",
        "        add_payload 'M' '1' 'REQUEST' lv_recorded_request.",
        "        add_payload 'M' '1' 'PHASE' lv_phase.",
        "        add_payload 'M' '1' 'PUT_SUBRC' lv_put_subrc.",
        "        add_payload 'M' '1' 'ACT_SUBRC' lv_activation_subrc.",
        "        add_payload 'M' '1' 'ACT_RC' lv_rc.",
        "        add_payload 'M' '1' 'INACTIVE_EXISTS' lv_inactive_exists.",
        "        add_payload 'M' '1' 'TADIR_EXISTS' lv_tadir_exists.",
        "        IF lv_inactive_exists = 'N'.",
        "          add_payload 'M' '1' 'RECOVERY_OPERATION'",
        "            'RESUME_TABLE_ACTIVATION'.",
        "        ENDIF.",
        "        add_payload 'M' '1' 'MSG_CLASS' lv_msg_class.",
        "        add_payload 'M' '1' 'MSG_NUMBER' lv_msg_number.",
        "      ENDIF.",
        "      ev_version = '1.2'. RETURN.",
        "    ENDIF.",
        "    COMMIT WORK AND WAIT.",
        "    CLEAR: lv_gotstate, lv_current_version.",
        "    CASE lv_object_type.",
        "      WHEN 'DOMA'.",
        "        REFRESH lt_dd07v.",
        "        CALL FUNCTION 'DDIF_DOMA_GET'",
        "          EXPORTING name = lv_ddic_name state = 'A'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_gotstate dd01v_wa = ls_dd01v",
        "          TABLES dd07v_tab = lt_dd07v",
        "          EXCEPTIONS OTHERS = 1.",
        "        CONCATENATE ls_dd01v-as4date ls_dd01v-as4time",
        "          INTO lv_current_version.",
        "      WHEN 'SHLP'.",
        "        REFRESH: lt_dd31v, lt_dd32p, lt_dd33v.",
        "        CALL FUNCTION 'DDIF_SHLP_GET'",
        "          EXPORTING name = lv_ddic_name state = 'A'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_gotstate dd30v_wa = ls_dd30v",
        "          TABLES dd31v_tab = lt_dd31v",
        "            dd32p_tab = lt_dd32p",
        "            dd33v_tab = lt_dd33v",
        "          EXCEPTIONS OTHERS = 1.",
        "        CONCATENATE ls_dd30v-as4date ls_dd30v-as4time",
        "          INTO lv_current_version.",
        "      WHEN 'ENQU'.",
        "        REFRESH: lt_dd26v, lt_dd27p.",
        "        CALL FUNCTION 'DDIF_ENQU_GET'",
        "          EXPORTING name = lv_ddic_name state = 'A'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_gotstate dd25v_wa = ls_dd25v",
        "          TABLES dd26e_tab = lt_dd26v",
        "            dd27p_tab = lt_dd27p",
        "          EXCEPTIONS OTHERS = 1.",
        "        CONCATENATE ls_dd25v-as4date ls_dd25v-as4time",
        "          INTO lv_current_version.",
        "      WHEN 'DTEL'.",
        "        CALL FUNCTION 'DDIF_DTEL_GET'",
        "          EXPORTING name = lv_ddic_name state = 'A'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_gotstate dd04v_wa = ls_dd04v",
        "          EXCEPTIONS OTHERS = 1.",
        "        CONCATENATE ls_dd04v-as4date ls_dd04v-as4time",
        "          INTO lv_current_version.",
        "      WHEN 'STRU'.",
        "        REFRESH lt_dd03p.",
        "        CALL FUNCTION 'DDIF_TABL_GET'",
        "          EXPORTING name = lv_ddic_name state = 'A'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_gotstate dd02v_wa = ls_dd02v",
        "            dd09l_wa = ls_dd09v",
        "          TABLES dd03p_tab = lt_dd03p",
        "          EXCEPTIONS OTHERS = 1.",
        "        CONCATENATE ls_dd02v-as4date ls_dd02v-as4time",
        "          INTO lv_current_version.",
        "      WHEN 'TABL'.",
        "        REFRESH lt_dd03p.",
        "        IF lv_describe = 'X'.",
        "          CALL FUNCTION 'DDIF_TABL_GET'",
        "            EXPORTING name = lv_ddic_name state = 'N'",
        "              langu = sy-langu",
        "            IMPORTING gotstate = lv_gotstate dd02v_wa = ls_dd02v",
        "              dd09l_wa = ls_dd09v",
        "            TABLES dd03p_tab = lt_dd03p",
        "            EXCEPTIONS OTHERS = 1.",
        "        ELSE.",
        "        CALL FUNCTION 'DDIF_TABL_GET'",
        "          EXPORTING name = lv_ddic_name state = 'A'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_gotstate dd02v_wa = ls_dd02v",
        "            dd09l_wa = ls_dd09v",
        "          TABLES dd03p_tab = lt_dd03p",
        "          EXCEPTIONS OTHERS = 1.",
        "        ENDIF.",
        "        CONCATENATE ls_dd02v-as4date ls_dd02v-as4time",
        "          INTO lv_current_version.",
        "      WHEN 'TTYP'.",
        "        CALL FUNCTION 'DDIF_TTYP_GET'",
        "          EXPORTING name = lv_ddic_name state = 'A'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_gotstate dd40v_wa = ls_dd40v",
        "          TABLES dd42v_tab = lt_dd42v dd43v_tab = lt_dd43v",
        "          EXCEPTIONS OTHERS = 1.",
        "        SELECT SINGLE as4date as4time FROM dd40l",
        "          INTO (lv_as4date, lv_as4time)",
        "          WHERE typename = iv_object_name",
        "            AND as4local = 'A'.",
        "        CONCATENATE lv_as4date lv_as4time",
        "          INTO lv_current_version.",
        "    ENDCASE.",
        "    IF sy-subrc <> 0 OR lv_gotstate <> 'A'.",
        "      ev_status = 'E'. ev_code = 'VERIFY_FAILED'.",
        "      ev_message = 'Activated DDIC object could not be read'.",
        # 只回一句"读不到"无法归因：TABL 的激活子返回码、act_res_tab 行数与 DD_TABL_ACT
        # 给出的 action/mode/dataloss 才是判据。2026-09-23 实测该分支时这三项全部被丢弃。
        "      IF lv_object_type = 'TABL'.",
        "        DESCRIBE TABLE lt_act_res LINES lv_act_rows.",
        "        WRITE lv_activation_subrc TO lv_act_subrc_text.",
        "        WRITE lv_rc TO lv_act_rc_text.",
        "        WRITE lv_act_rows TO lv_act_rows_text.",
        "        CONCATENATE 'subrc' lv_act_subrc_text 'rc'",
        "          lv_act_rc_text 'actres_rows' lv_act_rows_text",
        "          INTO lv_verify_detail SEPARATED BY space.",
        "        CLEAR lv_verify_action.",
        "        IF ls_act_res-action IS NOT INITIAL.",
        "          CONCATENATE 'action' ls_act_res-action",
        "            'mode' ls_act_res-modeflag",
        "            INTO lv_verify_action SEPARATED BY space.",
        "        ENDIF.",
        "* 目标字段不得同时作为 CONCATENATE 的操作数，故此处以 ev_message 为唯一目标。",
        "        CONCATENATE 'Activated DDIC object could not be read'",
        "          '(' lv_verify_detail ')' lv_verify_action",
        "          INTO ev_message SEPARATED BY space.",
        "        CLEAR it_source.",
        "        add_payload 'M' '1' 'PHASE' 'verify_failed'.",
        "        add_payload 'M' '1' 'ACT_SUBRC' lv_activation_subrc.",
        "        add_payload 'M' '1' 'ACT_RC' lv_rc.",
        "        add_payload 'M' '1' 'ACT_ROWS' lv_act_rows.",
        "        add_payload 'M' '1' 'ACT_ACTION' ls_act_res-action.",
        "        add_payload 'M' '1' 'ACT_MODE' ls_act_res-modeflag.",
        "        add_payload 'M' '1' 'ACT_DATALOSS'",
        "          ls_act_res-dataloss_d.",
        "        add_payload 'M' '1' 'GOTSTATE' lv_gotstate.",
        "        add_payload 'M' '1' 'RESUME' lv_resume.",
        "      ENDIF.",
        "      ev_version = '1.2'. RETURN.",
        "    ENDIF.",
        # 1.16：写入成功的判据不能只是"存在活动版本"。对象原本就活动时，上面那次
        # state = 'A' 读取与本次写入是否激活无关，必然成功——这正是 2026-09-25
        # 锁对象假成功事件的机制。真正的不变量是"没有残留的维护版本"：保存
        # （DDIF_*_PUT）产生的非活动版本必须已被激活消费掉。判定方式与读路径的
        # INACTIVE_VERSION_EXISTS 同源：以 state = 'M' 读取，gotstate 为 'A' 才算
        # 没有非活动版本。此处不得用 DDIF_STATE_GET（其 state = 'M' 语义未验证），
        # 各类型均用读路径已在用的同一批 DDIF_*_GET 调用。
        "    CLEAR lv_leftover_state.",
        "    CASE lv_object_type.",
        "      WHEN 'DOMA'.",
        "        CALL FUNCTION 'DDIF_DOMA_GET'",
        "          EXPORTING name = lv_ddic_name state = 'M'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_leftover_state",
        "          EXCEPTIONS OTHERS = 1.",
        "      WHEN 'DTEL'.",
        "        CALL FUNCTION 'DDIF_DTEL_GET'",
        "          EXPORTING name = lv_ddic_name state = 'M'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_leftover_state",
        "          EXCEPTIONS OTHERS = 1.",
        "      WHEN 'STRU' OR 'TABL'.",
        "        CALL FUNCTION 'DDIF_TABL_GET'",
        "          EXPORTING name = lv_ddic_name state = 'M'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_leftover_state",
        "          EXCEPTIONS OTHERS = 1.",
        "      WHEN 'TTYP'.",
        "        CALL FUNCTION 'DDIF_TTYP_GET'",
        "          EXPORTING name = lv_ddic_name state = 'M'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_leftover_state",
        "          EXCEPTIONS OTHERS = 1.",
        "      WHEN 'SHLP'.",
        "        CALL FUNCTION 'DDIF_SHLP_GET'",
        "          EXPORTING name = lv_ddic_name state = 'M'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_leftover_state",
        "          EXCEPTIONS OTHERS = 1.",
        "      WHEN 'ENQU'.",
        "        CALL FUNCTION 'DDIF_ENQU_GET'",
        "          EXPORTING name = lv_ddic_name state = 'M'",
        "            langu = sy-langu",
        "          IMPORTING gotstate = lv_leftover_state",
        "          EXCEPTIONS OTHERS = 1.",
        "    ENDCASE.",
        "    IF sy-subrc <> 0 OR lv_leftover_state <> 'A'.",
        # 失败原因必须是可执行的：把激活返回码、调用返回码与探针状态一起交回，调用方
        # 据此区分"激活被 SAP 拒绝"（rc <> 0）与"保存本身没留下可激活版本"。真正的
        # 激活日志在 DDIC 日志（如 ACTTABL<NAME>）与 SE11 激活日志里，不在本接口回执。
        "      CLEAR it_source.",
        "      add_payload 'M' '1' 'PHASE' 'activation_incomplete'.",
        "      add_payload 'M' '1' 'ACT_RC' lv_rc.",
        "      add_payload 'M' '1' 'ACT_SUBRC' lv_activation_subrc.",
        "      add_payload 'M' '1' 'GOTSTATE' lv_leftover_state.",
        "      add_payload 'M' '1' 'VERSION' lv_current_version.",
        "      ev_status = 'E'. ev_code = 'DDIC_ACTIVATION_INCOMPLETE'.",
        "      ev_message = 'The saved definition is still not active'.",
        "      ev_version = '1.16'. RETURN.",
        "    ENDIF.",
        "  ENDIF.",
        "  SELECT SINGLE * FROM tadir INTO ls_tadir",
        "    WHERE pgmid = 'R3TR' AND object = lv_tadir_type",
        "      AND obj_name = iv_object_name.",
        "  REFRESH it_source.",
        "  add_payload 'M' '1' 'PACKAGE' ls_tadir-devclass.",
        "  add_payload 'M' '1' 'VERSION' lv_current_version.",
        "  add_payload 'M' '1' 'REQUEST' lv_recorded_request.",
        "  IF ls_act_res-action IS NOT INITIAL.",
        "    add_payload 'M' '1' 'CONVERSION_ACTION' ls_act_res-action.",
        "    add_payload 'M' '1' 'CONVERSION_MODE' ls_act_res-modeflag.",
        "    add_payload 'M' '1' 'CONVERSION_DATA_LOSS'",
        "      ls_act_res-dataloss_d.",
        "  ENDIF.",
        "  CASE lv_object_type.",
        "    WHEN 'DOMA'.",
        "      add_payload 'H' '1' 'DOMNAME' ls_dd01v-domname.",
        "      add_payload 'H' '1' 'DDTEXT' ls_dd01v-ddtext.",
        "      add_payload 'H' '1' 'DATATYPE' ls_dd01v-datatype.",
        "      add_payload 'H' '1' 'LENG' ls_dd01v-leng.",
        "      add_payload 'H' '1' 'OUTPUTLEN' ls_dd01v-outputlen.",
        "      add_payload 'H' '1' 'DECIMALS' ls_dd01v-decimals.",
        "      add_payload 'H' '1' 'LOWERCASE' ls_dd01v-lowercase.",
        "      add_payload 'H' '1' 'SIGNFLAG' ls_dd01v-signflag.",
        "      add_payload 'H' '1' 'ENTITYTAB' ls_dd01v-entitytab.",
        "      add_payload 'H' '1' 'CONVEXIT' ls_dd01v-convexit.",
        "      LOOP AT lt_dd07v INTO ls_dd07v.",
        "        lv_index = sy-tabix.",
        "        add_payload 'V' lv_index 'DOMVALUE_L'",
        "          ls_dd07v-domvalue_l.",
        "        add_payload 'V' lv_index 'DOMVALUE_H'",
        "          ls_dd07v-domvalue_h.",
        "        add_payload 'V' lv_index 'DDTEXT' ls_dd07v-ddtext.",
        "      ENDLOOP.",
        "    WHEN 'SHLP'.",
        "      add_payload 'H' '1' 'SHLPNAME' ls_dd30v-shlpname.",
        "      add_payload 'H' '1' 'DDTEXT' ls_dd30v-ddtext.",
        "      add_payload 'H' '1' 'ISSIMPLE' ls_dd30v-issimple.",
        "      add_payload 'H' '1' 'SELMETHOD' ls_dd30v-selmethod.",
        "      add_payload 'H' '1' 'SELMTYPE' ls_dd30v-selmtype.",
        "      add_payload 'H' '1' 'TEXTTAB' ls_dd30v-texttab.",
        "      add_payload 'H' '1' 'SELMEXIT' ls_dd30v-selmexit.",
        "      add_payload 'H' '1' 'HOTKEY' ls_dd30v-hotkey.",
        "      add_payload 'H' '1' 'DIALOGTYPE' ls_dd30v-dialogtype.",
        "      add_payload 'H' '1' 'AS4USER' ls_dd30v-as4user.",
        "      add_payload 'H' '1' 'AS4DATE' ls_dd30v-as4date.",
        "      add_payload 'H' '1' 'AS4TIME' ls_dd30v-as4time.",
        "      LOOP AT lt_dd31v INTO ls_dd31v.",
        "        lv_index = sy-tabix.",
        "        add_payload 'S1' lv_index 'SUBSHLP' ls_dd31v-subshlp.",
        "        add_payload 'S1' lv_index 'VIASHLP' ls_dd31v-viashlp.",
        "        add_payload 'S1' lv_index 'HIDEFLAG' ls_dd31v-hideflag.",
        "      ENDLOOP.",
        "      LOOP AT lt_dd32p INTO ls_dd32p.",
        "        lv_index = sy-tabix.",
        "        add_payload 'S2' lv_index 'FIELDNAME' ls_dd32p-fieldname.",
        "        add_payload 'S2' lv_index 'ROLLNAME' ls_dd32p-rollname.",
        "        add_payload 'S2' lv_index 'DOMNAME' ls_dd32p-domname.",
        "        add_payload 'S2' lv_index 'DATATYPE' ls_dd32p-datatype.",
        "        add_payload 'S2' lv_index 'LENG' ls_dd32p-leng.",
        "        add_payload 'S2' lv_index 'DECIMALS' ls_dd32p-decimals.",
        "        add_payload 'S2' lv_index 'HEADLEN' ls_dd32p-headlen.",
        "        add_payload 'S2' lv_index 'SCRLEN1' ls_dd32p-scrlen1.",
        "        add_payload 'S2' lv_index 'SCRLEN2' ls_dd32p-scrlen2.",
        "        add_payload 'S2' lv_index 'SCRLEN3' ls_dd32p-scrlen3.",
        "        add_payload 'S2' lv_index 'OUTPUTLEN' ls_dd32p-outputlen.",
        "        add_payload 'S2' lv_index 'CONVEXIT' ls_dd32p-convexit.",
        "        add_payload 'S2' lv_index 'LOWERCASE' ls_dd32p-lowercase.",
        "        add_payload 'S2' lv_index 'SIGNFLAG' ls_dd32p-signflag.",
        "        add_payload 'S2' lv_index 'DEFAULTTYP' ls_dd32p-defaulttyp.",
        "        add_payload 'S2' lv_index 'DEFAULTVAL' ls_dd32p-defaultval.",
        "        add_payload 'S2' lv_index 'SHLPINPUT' ls_dd32p-shlpinput.",
        "        add_payload 'S2' lv_index 'SHLPOUTPUT' ls_dd32p-shlpoutput.",
        "        add_payload 'S2' lv_index 'SHLPSELDIS' ls_dd32p-shlpseldis.",
        "        add_payload 'S2' lv_index 'SHLPSELPOS' ls_dd32p-shlpselpos.",
        "        add_payload 'S2' lv_index 'SHLPLISPOS' ls_dd32p-shlplispos.",
        "        add_payload 'S2' lv_index 'SHLPUPPER' ls_dd32p-shlpupper.",
        "        add_payload 'S2' lv_index 'PROXYTYPE' ls_dd32p-proxytype.",
        "        add_payload 'S2' lv_index 'ROLLCHANGE' ls_dd32p-rollchange.",
        "        add_payload 'S2' lv_index 'INDEXNAME' ls_dd32p-indexname.",
        "        add_payload 'S2' lv_index 'SQLTAB' ls_dd32p-sqltab.",
        "      ENDLOOP.",
        "      LOOP AT lt_dd33v INTO ls_dd33v.",
        "        lv_index = sy-tabix.",
        "        add_payload 'S3' lv_index 'FIELDNAME' ls_dd33v-fieldname.",
        "        add_payload 'S3' lv_index 'SUBFIELD' ls_dd33v-subfield.",
        "        add_payload 'S3' lv_index 'SUBSHLP' ls_dd33v-subshlp.",
        "        add_payload 'S3' lv_index 'DEFAULTTYP' ls_dd33v-defaulttyp.",
        "        add_payload 'S3' lv_index 'DEFAULTVAL' ls_dd33v-defaultval.",
        "        add_payload 'S3' lv_index 'VALUEDIREC' ls_dd33v-valuedirec.",
        "      ENDLOOP.",
        "    WHEN 'ENQU'.",
        "      add_payload 'H' '1' 'VIEWNAME' ls_dd25v-viewname.",
        "      add_payload 'H' '1' 'DDTEXT' ls_dd25v-ddtext.",
        "      add_payload 'H' '1' 'AGGTYPE' ls_dd25v-aggtype.",
        "      add_payload 'H' '1' 'ROOTTAB' ls_dd25v-roottab.",
        "      add_payload 'H' '1' 'AS4USER' ls_dd25v-as4user.",
        "      add_payload 'H' '1' 'AS4DATE' ls_dd25v-as4date.",
        "      add_payload 'H' '1' 'AS4TIME' ls_dd25v-as4time.",
        "      LOOP AT lt_dd26v INTO ls_dd26v.",
        "        lv_index = sy-tabix.",
        "        add_payload 'L1' lv_index 'TABNAME' ls_dd26v-tabname.",
        "        add_payload 'L1' lv_index 'FORTABNAME' ls_dd26v-fortabname.",
        "        add_payload 'L1' lv_index 'FORFIELD' ls_dd26v-forfield.",
        "        add_payload 'L1' lv_index 'FORDIR' ls_dd26v-fordir.",
        # 锁定模式（ENQMODE）是 dd26e 的关键属性之一：少了它，read_lock_object 的行虽然有表/
        # 字段/FORDIR，却无法说明是 E/S/X 哪种锁模式。线上帮手已含此行（1.10 载体），此处为回移。
        "        add_payload 'L1' lv_index 'ENQMODE' ls_dd26v-enqmode.",
        "      ENDLOOP.",
        "      LOOP AT lt_dd27p INTO ls_dd27p.",
        "        lv_index = sy-tabix.",
        "        add_payload 'L2' lv_index 'VIEWFIELD' ls_dd27p-viewfield.",
        "        add_payload 'L2' lv_index 'TABNAME' ls_dd27p-tabname.",
        "        add_payload 'L2' lv_index 'FIELDNAME' ls_dd27p-fieldname.",
        "        add_payload 'L2' lv_index 'ENQMODE' ls_dd27p-enqmode.",
        "        add_payload 'L2' lv_index 'ROLLNAME' ls_dd27p-rollname.",
        "        add_payload 'L2' lv_index 'KEYFLAG' ls_dd27p-keyflag.",
        "        add_payload 'L2' lv_index 'CHECKTABLE' ls_dd27p-checktable.",
        "      ENDLOOP.",
        "    WHEN 'DTEL'.",
        "      add_payload 'H' '1' 'ROLLNAME' ls_dd04v-rollname.",
        "      add_payload 'H' '1' 'DDTEXT' ls_dd04v-ddtext.",
        "      add_payload 'H' '1' 'DOMNAME' ls_dd04v-domname.",
        "      add_payload 'H' '1' 'REPTEXT' ls_dd04v-reptext.",
        "      add_payload 'H' '1' 'SCRTEXT_S' ls_dd04v-scrtext_s.",
        "      add_payload 'H' '1' 'SCRTEXT_M' ls_dd04v-scrtext_m.",
        "      add_payload 'H' '1' 'SCRTEXT_L' ls_dd04v-scrtext_l.",
        "    WHEN 'STRU'.",
        "      add_payload 'H' '1' 'TABNAME' ls_dd02v-tabname.",
        "      add_payload 'H' '1' 'DDTEXT' ls_dd02v-ddtext.",
        "      add_payload 'H' '1' 'TABCLASS' ls_dd02v-tabclass.",
        # D6-5 读取侧前置：append 结构在 DD02L/DD02V 里是 TABCLASS='APPEND' 且 SQLTAB 指向基表。
        # 此前 SQLTAB 从不外发，调用方读了 append 结构也无法知道它挂在哪张基表上，因而无法安全地
        # 规划字段级追加（追加必须"写 append 自身的行 + 激活基表"）。空值即普通结构，不丢信息。
        "      add_payload 'H' '1' 'SQLTAB' ls_dd02v-sqltab.",
        "      LOOP AT lt_dd03p INTO ls_dd03p.",
        "        lv_index = sy-tabix.",
        "        add_payload 'F' lv_index 'FIELDNAME'",
        "          ls_dd03p-fieldname.",
        "        add_payload 'F' lv_index 'POSITION'",
        "          ls_dd03p-position.",
        "        add_payload 'F' lv_index 'ROLLNAME'",
        "          ls_dd03p-rollname.",
        "        add_payload 'F' lv_index 'DDTEXT' ls_dd03p-ddtext.",
        "        add_payload 'F' lv_index 'DATATYPE' ls_dd03p-datatype.",
        "        add_payload 'F' lv_index 'LENG' ls_dd03p-leng.",
        "        add_payload 'F' lv_index 'COMPTYPE' ls_dd03p-comptype.",
        "      ENDLOOP.",
        # D-4：发布字段集指纹，供调用方作为 expectedVersion 回传，实现字段级并发保护。
        # 与写入路径同构：同一 state='A' 读取、同一排序与拼接、同一 SHA1。
        "      REFRESH lt_ap_fp.",
        "      CLEAR lv_ap_fp_source.",
        "      LOOP AT lt_dd03p INTO ls_dd03p.",
        "        CONCATENATE ls_dd03p-position ls_dd03p-fieldname",
        "          ls_dd03p-rollname INTO lv_ap_fp_line SEPARATED BY ':'.",
        "        APPEND lv_ap_fp_line TO lt_ap_fp.",
        "      ENDLOOP.",
        "      SORT lt_ap_fp.",
        "      CLEAR lv_ap_fp_line.",
        "      LOOP AT lt_ap_fp INTO lv_ap_fp_line.",
        "        IF lv_ap_fp_source IS INITIAL.",
        "          lv_ap_fp_source = lv_ap_fp_line.",
        "        ELSE.",
        "          CONCATENATE lv_ap_fp_source lv_ap_fp_line",
        "            INTO lv_ap_fp_source SEPARATED BY '|'.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      CLEAR lv_ap_fingerprint.",
        "      CALL FUNCTION 'CALCULATE_HASH_FOR_CHAR'",
        "        EXPORTING alg = 'SHA1' data = lv_ap_fp_source",
        "        IMPORTING hash = lv_ap_fingerprint",
        "        EXCEPTIONS OTHERS = 1.",
        "      add_payload 'M' '1' 'FINGERPRINT' lv_ap_fingerprint.",
        "    WHEN 'TABL'.",
        "      add_payload 'H' '1' 'TABNAME' ls_dd02v-tabname.",
        "      add_payload 'H' '1' 'DDTEXT' ls_dd02v-ddtext.",
        "      add_payload 'H' '1' 'TABCLASS' ls_dd02v-tabclass.",
        "      add_payload 'H' '1' 'SQLTAB' ls_dd02v-sqltab.",
        "      add_payload 'H' '1' 'CONTFLAG' ls_dd02v-contflag.",
        "      add_payload 'H' '1' 'MAINFLAG' ls_dd02v-mainflag.",
        "      add_payload 'H' '1' 'TABKAT' ls_dd09v-tabkat.",
        "      add_payload 'H' '1' 'TABART' ls_dd09v-tabart.",
        "      add_payload 'H' '1' 'BUFALLOW' ls_dd09v-bufallow.",
        "      add_payload 'H' '1' 'PUFFERUNG' ls_dd09v-pufferung.",
        "      add_payload 'H' '1' 'SCHFELDANZ' ls_dd09v-schfeldanz.",
        "      add_payload 'H' '1' 'PROTOKOLL' ls_dd09v-protokoll.",
        "      LOOP AT lt_dd03p INTO ls_dd03p.",
        "        lv_index = sy-tabix.",
        "        add_payload 'F' lv_index 'FIELDNAME'",
        "          ls_dd03p-fieldname.",
        "        add_payload 'F' lv_index 'POSITION'",
        "          ls_dd03p-position.",
        "        add_payload 'F' lv_index 'ROLLNAME'",
        "          ls_dd03p-rollname.",
        "        add_payload 'F' lv_index 'DDTEXT' ls_dd03p-ddtext.",
        "        add_payload 'F' lv_index 'DATATYPE' ls_dd03p-datatype.",
        "        add_payload 'F' lv_index 'LENG' ls_dd03p-leng.",
        "        add_payload 'F' lv_index 'COMPTYPE' ls_dd03p-comptype.",
        "        add_payload 'F' lv_index 'PRECFIELD' ls_dd03p-precfield.",
        "        add_payload 'F' lv_index 'ADMINFIELD'",
        "          ls_dd03p-adminfield.",
        "        add_payload 'F' lv_index 'GROUPNAME' ls_dd03p-groupname.",
        "        add_payload 'F' lv_index 'EXCLASS' ls_dd03p-exclass.",
        "        add_payload 'F' lv_index 'KEYFLAG'",
        "          ls_dd03p-keyflag.",
        "        add_payload 'F' lv_index 'NOTNULL'",
        "          ls_dd03p-notnull.",
        "      ENDLOOP.",
        "    WHEN 'TTYP'.",
        "      add_payload 'H' '1' 'TYPENAME' ls_dd40v-typename.",
        "      add_payload 'H' '1' 'DDTEXT' ls_dd40v-ddtext.",
        "      add_payload 'H' '1' 'ROWTYPE' ls_dd40v-rowtype.",
        "      add_payload 'H' '1' 'ROWKIND' ls_dd40v-rowkind.",
        "      add_payload 'H' '1' 'DATATYPE' ls_dd40v-datatype.",
        "      add_payload 'H' '1' 'ACCESSMODE' ls_dd40v-accessmode.",
        "      add_payload 'H' '1' 'KEYDEF' ls_dd40v-keydef.",
        "      add_payload 'H' '1' 'KEYKIND' ls_dd40v-keykind.",
        "  ENDCASE.",
        "  ev_status = 'S'.",
        "  IF lv_write = 'X'.",
        "    ev_code = 'DDIC_OBJECT_SAVED'.",
        "    ev_message = 'DDIC object saved activated and verified'.",
        "  ELSE.",
        "    ev_code = 'DDIC_OBJECT_READ'.",
        "    ev_message = 'DDIC object read successfully'.",
        "  ENDIF.",
        "  ev_version = '1.7'."
    )
}

function New-InstallProgram {
    param(
        [switch]$ReplaceExisting,
        [string]$FunctionName = "Z_ORVANTA_MCP_EXECUTE"
    )

    $existingObjectLines = if ($ReplaceExisting) {
        @(
            "IF sy-subrc = 0.",
            "  CALL FUNCTION 'FUNCTION_DELETE'",
            "    EXPORTING",
            "      funcname = '$FunctionName'",
            "      suppress_success_message = 'X'",
            "    EXCEPTIONS error_message = 1.",
            "  IF sy-subrc <> 0.",
            "    WRITE: / 'DELETE_ERROR', sy-subrc, sy-msgid, sy-msgno.",
            "    ROLLBACK WORK.",
            "    STOP.",
            "  ENDIF.",
            "  COMMIT WORK AND WAIT.",
            "  WRITE / 'DELETED $FunctionName'.",
            "ELSEIF sy-subrc <> 1.",
            "  WRITE: / 'EXISTENCE_CHECK_ERROR', sy-subrc.",
            "  STOP.",
            "ENDIF."
        )
    }
    else {
        @(
            "IF sy-subrc = 0.",
            "  WRITE / 'ALREADY_EXISTS'.",
            "  STOP.",
            "ELSEIF sy-subrc <> 1.",
            "  WRITE: / 'EXISTENCE_CHECK_ERROR', sy-subrc.",
            "  STOP.",
            "ENDIF."
        )
    }

    # CAPABILITIES payload rows (docs/helper-capabilities-protocol.md). $FunctionName
    # is interpolated because this body is shared by Z_ORVANTA_MCP_EXECUTE and
    # Z_ORVANTA_MCP_DYNPRO_API. Package/transport values are escaped here, at
    # generation time; the runtime values (hash, sy-sysid/sy-mandt, sy-datum/sy-uzeit,
    # the sy-tzone offset) cannot contain the payload separators.
    # Only character-like fields (C/N/D/T/STRING) may be CONCATENATE operands and
    # WRITE ... TO rejects STRING targets, so the numeric sy-tzone offset is assigned
    # to a STRING work field first (GENERATE_ERROR 943/944 otherwise). The converted
    # digits cannot contain the payload separators, so no REPLACE is needed there.
    # >>> ORVANTA-CAPABILITIES-SOURCE
    $capabilityHashSlots = @(
        "ORVANTAHASHSLOT1",
        "ORVANTAHASHSLOT2",
        "ORVANTAHASHSLOT3",
        "ORVANTAHASHSLOT4"
    )
    $capabilityPackageValue = ([string]$PackageName).Replace("%", "%25").Replace("|", "%7C")
    $capabilityTransportValue = (
        @([string]$TransportNumber, [string]$TransportTask) | ForEach-Object {
            $_.Replace("%", "%25").Replace("|", "%7C")
        }
    ) -join "|"
    $capabilityBranchLines = @(
        "    WHEN 'CAPABILITIES'.",
        "      CLEAR ls_source.",
        "      ls_source-line = 'HELPER|$FunctionName'.",
        "      APPEND ls_source TO it_source.",
        "      ls_source-line = 'PROTOCOL|MIN|$helperCapabilityMinVersion'.",
        "      APPEND ls_source TO it_source.",
        "      ls_source-line = 'PROTOCOL|MAX|$helperCapabilityMaxVersion'.",
        "      APPEND ls_source TO it_source."
    )
    foreach ($capabilityOperation in $helperCapabilityOperations) {
        $capabilityOperationParts = $capabilityOperation -split "\|"
        $capabilityBranchLines += @(
            "      CONCATENATE 'OPERATION|$($capabilityOperationParts[0])' '$($capabilityOperationParts[1])|$($capabilityOperationParts[2])'",
            "        INTO ls_source-line SEPARATED BY '|'.",
            "      APPEND ls_source TO it_source."
        )
    }
    foreach ($capabilityScope in $helperCapabilityScopes) {
        $capabilityBranchLines += @(
            "      ls_source-line = 'SCOPE|$capabilityScope'.",
            "      APPEND ls_source TO it_source."
        )
    }
    $capabilityBranchLines += @(
        "      CLEAR ls_source.",
        "      CONCATENATE 'SOURCE|HASH|' '$($capabilityHashSlots[0])' '$($capabilityHashSlots[1])'",
        "        '$($capabilityHashSlots[2])' '$($capabilityHashSlots[3])' INTO ls_source-line.",
        "      APPEND ls_source TO it_source.",
        "      ls_source-line = 'SOURCE|PACKAGE|$capabilityPackageValue'.",
        "      APPEND ls_source TO it_source.",
        "      ls_source-line = 'SOURCE|TRANSPORT|$capabilityTransportValue'.",
        "      APPEND ls_source TO it_source.",
        "      CONCATENATE sy-sysid sy-mandt INTO lv_payload_value",
        "        SEPARATED BY '/'.",
        "      REPLACE ALL OCCURRENCES OF '%' IN lv_payload_value WITH '%25'.",
        "      REPLACE ALL OCCURRENCES OF '|' IN lv_payload_value WITH '%7C'.",
        "      CONCATENATE 'RUNTIME|HOST' lv_payload_value INTO ls_source-line",
        "        SEPARATED BY '|'.",
        "      APPEND ls_source TO it_source.",
        "      CONCATENATE sy-datum sy-uzeit INTO lv_payload_value.",
        "      REPLACE ALL OCCURRENCES OF '%' IN lv_payload_value WITH '%25'.",
        "      REPLACE ALL OCCURRENCES OF '|' IN lv_payload_value WITH '%7C'.",
        "      lv_payload_index_text = sy-tzone.",
        "      CONDENSE lv_payload_index_text NO-GAPS.",
        "      CONCATENATE 'RUNTIME|TIME' lv_payload_value lv_payload_index_text",
        "        INTO ls_source-line SEPARATED BY '|'.",
        "      APPEND ls_source TO it_source.",
        "      ev_status = 'S'.",
        "      ev_code = 'CAPABILITIES'.",
        "      ev_version = '$helperCapabilityMaxVersion'.",
        "      ev_message = 'ORVANTA helper capabilities'.",
        "      RETURN."
    )
