        "  DATA lv_d7_include_source TYPE c LENGTH 1.",
        "  DATA lv_d7_source_status TYPE c LENGTH 13.",
        # A delivered form keeps its ID_DEF definition in the form's own original language, which
        # need not be the language the form text was read in (MEDRUCK: text TDSPRAS=1, TDOSPRAS=D).
        "  DATA lv_d7_source_language TYPE spras.",
        "  DATA lv_d7_index TYPE i.",
        "  DATA lv_d7_descr TYPE REF TO cl_abap_structdescr.",
        "  DATA lt_d7_components TYPE abap_component_tab.",
        "  DATA ls_d7_component TYPE abap_componentdescr.",
        # D7-4 read_smartstyle. Storage form S reads STXS* through SSF_READ_STYLE; form P converts a
        # SAPscript style through SSF_READ_SAPSCRIPT_STYLE. Both return SSFCATS plus SSF* rows, so one
        # emit path serves both. TSFSTBODY is a table type whose row is the predefined type STRG
        # (rowKind E), i.e. a table of strings - not a structure, so the CSS body arrives as lines.
        #
        # The three row tables must be declared with the table types the function modules declare
        # themselves, not with an equivalent "TYPE TABLE OF <row>". SSF_READ_SAPSCRIPT_STYLE exports
        # E_PARAGRAPHS/E_STRINGS/E_TABS as pass-by-value parameters, and a pass-by-value table
        # parameter requires the actual parameter to be that very table type; an anonymous table with
        # the same row type is rejected at runtime with "Type conflict when calling a function module"
        # (RABAX_STATE), which made every mode=P read fail. TSFPARAS/TSFSTRINGS/TSFTABS are row-
        # compatible with SSF_READ_STYLE's TABLES parameters (SSFPARAS/SSFSTRINGS/STXSTAB), so the
        # same declarations still serve form S.
        "  DATA lv_d7_style_name TYPE tdssname.",
        "  DATA lv_d7_style_mode TYPE tdchar1.",
        "  DATA lv_d7_style_active TYPE tdactivate.",
        "  DATA lv_d7_style_variant TYPE tdvariant.",
        "  DATA lv_d7_style_language TYPE spras.",
        "  DATA ls_d7_style_header TYPE ssfcats.",
        "  DATA lt_d7_style_header_one TYPE TABLE OF ssfcats.",
        "  DATA ls_d7_style_header_row TYPE ssfcats.",
        "  DATA lt_d7_style_headers TYPE TABLE OF ssfcats.",
        "  DATA lt_d7_style_paras TYPE tsfparas.",
        "  DATA ls_d7_style_para TYPE ssfparas.",
        "  DATA lt_d7_style_strings TYPE tsfstrings.",
        "  DATA ls_d7_style_string TYPE ssfstrings.",
        "  DATA lt_d7_style_tabs TYPE tsftabs.",
        "  DATA ls_d7_style_tab TYPE stxstab.",
        # SSF_READ_SAPSCRIPT_STYLE passes I_NAME/I_OBJECT/I_LANGUAGE by value and declares them as
        # TDOBNAME/TDOBJECT/TDSPRAS. The SmartStyle path holds a TDSSNAME name and an SPRAS
        # language, so passing those fields straight in aborts the call with
        # CALL_FUNCTION_CONFLICT_TYPE at runtime - the same trap the CSS name widening above
        # documents. The three bridge fields below carry the formal parameter's own type.
        "  DATA lv_d7_ss_name TYPE tdobname.",
        "  DATA lv_d7_ss_object TYPE tdobject.",
        "  DATA lv_d7_ss_language TYPE tdspras.",
        "  DATA lv_d7_css_status TYPE string.",
        "  DATA lv_d7_css_mime TYPE sfhttptype.",
        "  DATA lv_d7_css_length TYPE i.",
        # SSF_CONVERT_STYLE_TO_CSS declares VALUE(STYLENAME) TYPE STRING. Passing the fixed
        # length TDSSNAME field straight in raises CX_SY_DYN_CALL_ILLEGAL_TYPE (short dump
        # CALL_FUNCTION_CONFLICT_TYPE) on 7.31, so the name is widened first.
        "  DATA lv_d7_css_style_name TYPE string.",
        # Every count and length that reaches the payload channel is converted by assignment,
        # never by WRITE. WRITE applies the calling user's number format, so a value of 1000 or
        # more arrives grouped ("5,056") and the service would read it as 5.
        "  DATA lv_d7_css_length_text TYPE c LENGTH 10.",
        "  DATA lt_d7_css TYPE tsfstbody.",
        "  DATA lv_d7_css_line TYPE string.",
        "  DATA lv_d7_css_chunk TYPE string.",
        "  DATA lv_d7_css_offset TYPE i.",
        "  DATA lv_d7_css_rest TYPE i.",
        "  DATA lv_d7_css_take TYPE i.",
        "  DATA lv_d7_css_index TYPE i.",
        "  DATA lv_d7_css_chunk_size TYPE i.",
        "  DATA lv_d7_adobe_name TYPE fpname.",
        "  DATA lv_d7_adobe_lang TYPE langu.",
        "  DATA lv_d7_adobe_master TYPE langu.",
        "  DATA lv_d7_adobe_subrc TYPE sysubrc.",
        "  DATA lv_d7_adobe_xdp TYPE xstring.",
        "  DATA lv_d7_adobe_xdp_len TYPE i.",
        "  DATA lv_d7_adobe_ret_len TYPE i.",
        "  DATA lv_d7_adobe_trunc TYPE tdchar1.",
        "  DATA lv_d7_adobe_max TYPE i.",
        "  DATA lv_d7_adobe_b64 TYPE string.",
        "  DATA lv_d7_adobe_b64_len TYPE i.",
        "  DATA lv_d7_adobe_index TYPE i.",
        "  DATA lv_d7_adobe_offset TYPE i.",
        "  DATA lv_d7_adobe_rest TYPE i.",
        "  DATA lv_d7_adobe_take TYPE i.",
        "  DATA lv_d7_adobe_chunk_size TYPE i.",
        "  DATA lv_d7_adobe_chunk TYPE string.",
        "  DATA lv_d7_adobe_number_text TYPE c LENGTH 10.",
        "  DATA lv_d7_adobe_error_text TYPE string.",
        "  DATA ls_d7_adobe_layout TYPE fplayoutt.",
        "  DATA lx_d7_adobe_error TYPE REF TO cx_root.",
        # create_transport_request. TRWBO_REQUEST_HEADER(S) are declared only as call targets:
        # the service side cannot resolve those types, so no field of them is read except TRKORR,
        # which TR_INSERT_REQUEST_WITH_TASKS provably fills (MOVE-CORRESPONDING ls_e070 ...).
        "  DATA lv_d9_request_type TYPE trfunction.",
        "  DATA lv_d9_request_text TYPE as4text.",
        "  DATA lv_d9_request_owner TYPE as4user.",
        "  DATA lv_d9_request_target TYPE tr_target.",
        "  DATA lv_d9_request_allow_dup TYPE trboolean.",
        "  DATA lv_d9_request_existing TYPE trkorr.",
        "  DATA lv_d9_request_candidate TYPE trkorr.",
        "  DATA lv_d9_request_trkorr TYPE trkorr.",
        "  DATA lv_d9_request_task TYPE trkorr.",
        "  DATA lv_d9_request_subrc TYPE sysubrc.",
        "  DATA lv_d9_request_index TYPE i.",
        "  DATA lv_d9_request_tasks TYPE i.",
        "  DATA lv_d9_request_count_text TYPE c LENGTH 10.",
        "  DATA lv_d9_request_error_text TYPE string.",
        "  DATA ls_d9_request_header TYPE trwbo_request_header.",
        "  DATA ls_d9_request_task TYPE trwbo_request_header.",
        "  DATA lt_d9_request_tasks TYPE trwbo_request_headers.",
        "  DATA ls_d9_request_user TYPE scts_user.",
        "  DATA lt_d9_request_users TYPE scts_users.",
        "  DATA ls_d9_request_db TYPE e070.",
        "  DATA ls_d9_request_text_db TYPE e07t.",
        "  DATA lt_d9_request_candidates TYPE STANDARD TABLE OF trkorr.",
        # add_objects_to_transport. TRINT_OBJECTS_CHECK_AND_INSERT owns the enqueue and issues
        # ROLLBACK WORK on nine failure paths but never commits, so this branch commits at the top
        # level and proves persistence by reading E071 back. CTS_OBJ_ENTRIES/CTS_OBJ_ENTRY are DDIC
        # (package SCTS_OBJ) and carry the flat object list; SCTSA_S_API_CALL is deliberately not
        # used, because iv_with_dialog = 'D' already sets ls_g-suppress_dialog inside the callee.
        "  DATA lv_d9_add_order_in TYPE trkorr.",
        "  DATA lv_d9_add_order TYPE trkorr.",
        "  DATA lv_d9_add_task TYPE trkorr.",
        "  DATA lv_d9_add_subrc TYPE sysubrc.",
        "  DATA lv_d9_add_index TYPE i.",
        "  DATA lv_d9_add_expected TYPE i.",
        "  DATA lv_d9_add_inserted TYPE i.",
        "  DATA lv_d9_add_count_text TYPE c LENGTH 10.",
        "  DATA lv_d9_add_error_text TYPE string.",
        "  DATA ls_d9_add_object TYPE cts_obj_entry.",
        "  DATA lt_d9_add_objects TYPE cts_obj_entries.",
        # E071 itself starts with MANDT, so a partial column list selected INTO a table of the
        # full E071 structure lands in the wrong fields: trkorr (CHAR 20) was written into the
        # leading MANDT (CLNT 3) and the read raised DBIF_RSQL_INVALID_RSQL. The read-back uses a
        # flat type holding exactly the selected columns in the selected order.
        "  TYPES: BEGIN OF ty_d9_add_e071,",
        "           trkorr TYPE e071-trkorr,",
        "           pgmid TYPE e071-pgmid,",
        "           object TYPE e071-object,",
        "           obj_name TYPE e071-obj_name,",
        "         END OF ty_d9_add_e071.",
        "  DATA ls_d9_add_e071 TYPE ty_d9_add_e071.",
        "  DATA lt_d9_add_e071 TYPE STANDARD TABLE OF ty_d9_add_e071.",
        "  FIELD-SYMBOLS <ls_d9_add_object> TYPE cts_obj_entry.",
        "  DEFINE add_repo_payload.",
        "    CLEAR ls_source.",
        "    lv_payload_index_text = &2.",
        "    CONDENSE lv_payload_index_text NO-GAPS.",
        "    lv_payload_value = &4.",
        "    REPLACE ALL OCCURRENCES OF '%'",
        "      IN lv_payload_value WITH '%25'.",
        "    REPLACE ALL OCCURRENCES OF '|'",
        "      IN lv_payload_value WITH '%7C'.",
        "    CONCATENATE &1 lv_payload_index_text &3",
        "      lv_payload_value INTO ls_source-line",
        "      SEPARATED BY '|'.",
        "    APPEND ls_source TO it_source.",
        "  END-OF-DEFINITION.",
        "  DEFINE add_repo_component.",
        "    ASSIGN COMPONENT &3 OF STRUCTURE &4",
        "      TO <lv_payload_component>.",
        "    IF sy-subrc = 0.",
        "      add_repo_payload &1 &2 &3 <lv_payload_component>.",
        "    ENDIF.",
        "  END-OF-DEFINITION.",
        "  DEFINE add_repo_alias.",
        "    ASSIGN COMPONENT &4 OF STRUCTURE &5",
        "      TO <lv_payload_component>.",
        "    IF sy-subrc = 0.",
        "      add_repo_payload &1 &2 &3 <lv_payload_component>.",
        "    ENDIF.",
        "  END-OF-DEFINITION.",
        "* Emit each row of &1 under kind &2 via the row type's own RTTI",
        "* description, so includes resolve and real DDIC names are used.",
        "* No hand-copied field list that can rot out of step.",
        "  DEFINE emit_d7_rows.",
        "    CLEAR lt_d7_components.",
        "    lv_d7_descr ?= cl_abap_typedescr=>describe_by_data( &3 ).",
        "    lt_d7_components = lv_d7_descr->get_components( ).",
        "    CLEAR lv_d7_index.",
        "    LOOP AT &1 INTO &3.",
        "      ADD 1 TO lv_d7_index.",
        "      LOOP AT lt_d7_components INTO ls_d7_component.",
        "        add_repo_component &2 lv_d7_index",
        "          ls_d7_component-name &3.",
        "      ENDLOOP.",
        "    ENDLOOP.",
        "  END-OF-DEFINITION.",
        "  DEFINE add_bte_application.",
        "    CLEAR: lv_bte_application, ls_tbe11.",
        "    ASSIGN COMPONENT 'APPLK' OF STRUCTURE &3",
        "      TO <lv_payload_component>.",
        "    IF sy-subrc = 0.",
        "      IF <lv_payload_component> IS NOT INITIAL.",
        "        lv_bte_application = <lv_payload_component>.",
        "        SELECT SINGLE * FROM tbe11 INTO ls_tbe11",
        "          WHERE applk = lv_bte_application.",
        "        IF sy-subrc = 0.",
        "          add_repo_alias &1 &2 'APPLICATION_ACTIVE'",
        "            'AKTIV' ls_tbe11.",
        "          add_repo_alias &1 &2 'APPLICATION_TEXT'",
        "            'TXTSU' ls_tbe11.",
        "        ENDIF.",
        "      ENDIF.",
        "    ENDIF.",
        "  END-OF-DEFINITION.",
        "  DEFINE add_bte_product.",
        "    CLEAR: lv_bte_product, ls_tbe24.",
        "    ASSIGN COMPONENT 'PRDKT' OF STRUCTURE &3",
        "      TO <lv_payload_component>.",
        "    IF sy-subrc <> 0.",
        "      ASSIGN COMPONENT 'PRODUCT' OF STRUCTURE &3",
        "        TO <lv_payload_component>.",
        "    ENDIF.",
        "    IF sy-subrc = 0.",
        "      IF <lv_payload_component> IS NOT INITIAL.",
        "        lv_bte_product = <lv_payload_component>.",
        "        SELECT SINGLE * FROM tbe24 INTO ls_tbe24",
        "          WHERE prdkt = lv_bte_product.",
        "        IF sy-subrc = 0.",
        "        ASSIGN COMPONENT 'AKTIV' OF STRUCTURE ls_tbe24",
        "          TO <lv_payload_component>.",
        "        IF sy-subrc <> 0.",
        "          ASSIGN COMPONENT 'ACTIVE' OF STRUCTURE ls_tbe24",
        "            TO <lv_payload_component>.",
        "        ENDIF.",
        "        IF sy-subrc = 0.",
        "          add_repo_payload &1 &2 'PRODUCT_ACTIVE'",
        "            <lv_payload_component>.",
        "        ENDIF.",
        "        UNASSIGN <lv_payload_component>.",
        "        ASSIGN COMPONENT 'TEXT1' OF STRUCTURE ls_tbe24",
        "          TO <lv_payload_component>.",
        "        IF sy-subrc <> 0.",
        "          ASSIGN COMPONENT 'TEXT' OF STRUCTURE ls_tbe24",
        "            TO <lv_payload_component>.",
        "        ENDIF.",
        "        IF sy-subrc <> 0.",
        "          ASSIGN COMPONENT 'TXTSU' OF STRUCTURE ls_tbe24",
        "            TO <lv_payload_component>.",
        "        ENDIF.",
        "        IF sy-subrc = 0.",
        "          add_repo_payload &1 &2 'PRODUCT_TEXT'",
        "            <lv_payload_component>.",
        "        ENDIF.",
        "          add_repo_alias &1 &2 'PRODUCT_RFC_DESTINATION'",
        "            'RFCDS' ls_tbe24.",
        "        ENDIF.",
        "      ENDIF.",
        "    ENDIF.",
        "  END-OF-DEFINITION.",
        "  DEFINE emit_gui_payload.",
        "    REFRESH it_source.",
        "    add_repo_payload 'M' '1' 'VERSION'",
        "      lv_gui_current_version.",
        "    add_repo_payload 'M' '1' 'LANGUAGE' lv_gui_language.",
        "    add_repo_payload 'M' '1' 'AUTHOR' lv_gui_author.",
        "    add_repo_payload 'M' '1' 'DATE' lv_gui_date.",
        "    add_repo_payload 'M' '1' 'TIME' lv_gui_time.",
        "    add_repo_payload 'M' '1' 'CAUTHOR' lv_gui_cauthor.",
        "    add_repo_payload 'M' '1' 'CDATE' lv_gui_cdate.",
        "    add_repo_payload 'M' '1' 'CTIME' lv_gui_ctime.",
        "    add_repo_payload 'M' '1' 'GDATE' lv_gui_gdate.",
        "    add_repo_payload 'M' '1' 'GTIME' lv_gui_gtime.",
        "    add_repo_payload 'M' '1' 'PACKAGE' ls_tadir-devclass.",
        "    add_repo_component 'ADM' '1' 'ACTCODE' ls_gui_adm.",
        "    add_repo_component 'ADM' '1' 'MENCODE' ls_gui_adm.",
        "    add_repo_component 'ADM' '1' 'PFKCODE' ls_gui_adm.",
        "    add_repo_component 'ADM' '1' 'DEFAULTACT' ls_gui_adm.",
        "    add_repo_component 'ADM' '1' 'DEFAULTPFK' ls_gui_adm.",
        "    add_repo_component 'ADM' '1' 'MOD_LANGU' ls_gui_adm.",
        "    LOOP AT lt_gui_sta INTO ls_gui_sta.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'STA' lv_payload_index 'CODE' ls_gui_sta.",
        "      add_repo_component 'STA' lv_payload_index 'MODAL' ls_gui_sta.",
        "      add_repo_component 'STA' lv_payload_index 'ACTCODE' ls_gui_sta.",
        "      add_repo_component 'STA' lv_payload_index 'PFKCODE' ls_gui_sta.",
        "      add_repo_component 'STA' lv_payload_index 'BUTCODE' ls_gui_sta.",
        "      add_repo_component 'STA' lv_payload_index 'INT_NOTE' ls_gui_sta.",
        "      add_repo_component 'STA' lv_payload_index 'CTXCODE' ls_gui_sta.",
        "    ENDLOOP.",
        "    LOOP AT lt_gui_fun INTO ls_gui_fun.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'FUN' lv_payload_index 'CODE' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'TEXTNO' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'TYPE' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'MODIF' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'TEXT_TYPE' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'TEXT_NAME' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'ICON_ID' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'FUN_TEXT' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'ICON_TEXT' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'INFO_TEXT' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'PATH' ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'SFW_SWITCHID'",
        "        ls_gui_fun.",
        "      add_repo_component 'FUN' lv_payload_index 'SFW_SHOWHIDE'",
        "        ls_gui_fun.",
        "    ENDLOOP.",
        "    LOOP AT lt_gui_men INTO ls_gui_men.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'MEN' lv_payload_index 'CODE' ls_gui_men.",
        "      add_repo_component 'MEN' lv_payload_index 'NO' ls_gui_men.",
        "      add_repo_component 'MEN' lv_payload_index 'REF_TYPE' ls_gui_men.",
        "      add_repo_component 'MEN' lv_payload_index 'REF_CODE' ls_gui_men.",
        "      add_repo_component 'MEN' lv_payload_index 'REF_NO' ls_gui_men.",
        "    ENDLOOP.",
        "    LOOP AT lt_gui_mtx INTO ls_gui_mtx.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'MTX' lv_payload_index 'CODE' ls_gui_mtx.",
        "      add_repo_component 'MTX' lv_payload_index 'TEXT_TYPE' ls_gui_mtx.",
        "      add_repo_component 'MTX' lv_payload_index 'TEXT_NAME' ls_gui_mtx.",
        "      add_repo_component 'MTX' lv_payload_index 'INC_PROG' ls_gui_mtx.",
        "      add_repo_component 'MTX' lv_payload_index 'INC_STATUS'",
        "        ls_gui_mtx.",
        "      add_repo_component 'MTX' lv_payload_index 'SFW_SWITCHID'",
        "        ls_gui_mtx.",
        "      add_repo_component 'MTX' lv_payload_index 'SFW_SHOWHIDE'",
        "        ls_gui_mtx.",
        "      add_repo_component 'MTX' lv_payload_index 'TEXT' ls_gui_mtx.",
        "      add_repo_component 'MTX' lv_payload_index 'PATH' ls_gui_mtx.",
        "      add_repo_component 'MTX' lv_payload_index 'INT_NOTE' ls_gui_mtx.",
        "    ENDLOOP.",
        "    LOOP AT lt_gui_act INTO ls_gui_act.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'ACT' lv_payload_index 'CODE' ls_gui_act.",
        "      add_repo_component 'ACT' lv_payload_index 'NO' ls_gui_act.",
        "      add_repo_component 'ACT' lv_payload_index 'MENUCODE' ls_gui_act.",
        "    ENDLOOP.",
        "    LOOP AT lt_gui_but INTO ls_gui_but.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'BUT' lv_payload_index 'PFK_CODE' ls_gui_but.",
        "      add_repo_component 'BUT' lv_payload_index 'CODE' ls_gui_but.",
        "      add_repo_component 'BUT' lv_payload_index 'NO' ls_gui_but.",
        "      add_repo_component 'BUT' lv_payload_index 'PFNO' ls_gui_but.",
        "    ENDLOOP.",
        "    LOOP AT lt_gui_pfk INTO ls_gui_pfk.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'PFK' lv_payload_index 'CODE' ls_gui_pfk.",
        "      add_repo_component 'PFK' lv_payload_index 'PFNO' ls_gui_pfk.",
        "      add_repo_component 'PFK' lv_payload_index 'FUNCODE' ls_gui_pfk.",
        "      add_repo_component 'PFK' lv_payload_index 'FUNNO' ls_gui_pfk.",
        "    ENDLOOP.",
        "    LOOP AT lt_gui_set INTO ls_gui_set.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'SET' lv_payload_index 'STATUS' ls_gui_set.",
        "      add_repo_component 'SET' lv_payload_index 'FUNCTION'",
        "        ls_gui_set.",
        "    ENDLOOP.",
        "    LOOP AT lt_gui_doc INTO ls_gui_doc.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'DOC' lv_payload_index 'OBJ_TYPE' ls_gui_doc.",
        "      add_repo_component 'DOC' lv_payload_index 'OBJ_CODE' ls_gui_doc.",
        "      add_repo_component 'DOC' lv_payload_index 'SUB_CODE' ls_gui_doc.",
        "      add_repo_component 'DOC' lv_payload_index 'MODAL' ls_gui_doc.",
        "      add_repo_component 'DOC' lv_payload_index 'NORM' ls_gui_doc.",
        "      add_repo_component 'DOC' lv_payload_index 'INT_NOTE' ls_gui_doc.",
        "    ENDLOOP.",
        "    LOOP AT lt_gui_tit INTO ls_gui_tit.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'TIT' lv_payload_index 'CODE' ls_gui_tit.",
        "      add_repo_component 'TIT' lv_payload_index 'TEXT' ls_gui_tit.",
        "    ENDLOOP.",
        "    LOOP AT lt_gui_biv INTO ls_gui_biv.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'BIV' lv_payload_index 'OBJ_CODE' ls_gui_biv.",
        "      add_repo_component 'BIV' lv_payload_index 'SUB_CODE' ls_gui_biv.",
        "      add_repo_component 'BIV' lv_payload_index 'FCODE' ls_gui_biv.",
        "    ENDLOOP.",
        "  END-OF-DEFINITION.",
        "  DEFINE add_repo_passvalue.",
        "    ASSIGN COMPONENT 'REFERENCE' OF STRUCTURE &3",
        "      TO <lv_payload_component>.",
        "    IF sy-subrc = 0.",
        "      CLEAR lv_payload_value.",
        "      IF <lv_payload_component> IS INITIAL.",
        "        lv_payload_value = 'X'.",
        "      ENDIF.",
        "      add_repo_payload &1 &2 'PASSVALUE' lv_payload_value.",
        "    ENDIF.",
        "  END-OF-DEFINITION.",
        "  DEFINE validate_enh_transport.",
        "    IF iv_package IS INITIAL OR iv_package = '`$TMP'",
        "       OR iv_request IS INITIAL.",
        "      ev_status = 'E'. ev_code = 'ENH_WRITE_INPUT_REQUIRED'.",
        "      ev_message = 'Transportable package and request required'.",
        "      ev_version = '2.6'. RETURN.",
        "    ENDIF.",
        "    CLEAR: ls_package, ls_request, ls_task.",
        "    SELECT SINGLE * FROM tdevc INTO ls_package",
        "      WHERE devclass = iv_package.",
        "    IF sy-subrc <> 0.",
        "      ev_status = 'E'. ev_code = 'PACKAGE_NOT_FOUND'.",
        "      ev_message = 'Transportable package does not exist'.",
        "      ev_version = '2.6'. RETURN.",
        "    ENDIF.",
        "    SELECT SINGLE * FROM e070 INTO ls_request",
        "      WHERE trkorr = iv_request.",
        "    IF sy-subrc <> 0.",
        "      ev_status = 'E'. ev_code = 'TRANSPORT_NOT_FOUND'.",
        "      ev_message = 'Transport request or task does not exist'.",
        "      ev_version = '2.6'. RETURN.",
        "    ENDIF.",
        "    IF ls_request-strkorr IS NOT INITIAL.",
        "      ls_task = ls_request.",
        "      SELECT SINGLE * FROM e070 INTO ls_request",
        "        WHERE trkorr = ls_task-strkorr.",
        "    ELSE.",
        "      SELECT SINGLE * FROM e070 INTO ls_task",
        "        WHERE strkorr = ls_request-trkorr",
        "          AND as4user = sy-uname AND trstatus = 'D'.",
        "    ENDIF.",
        "    IF ls_request-trfunction <> 'K'",
        "       OR ls_request-trstatus <> 'D'",
        "       OR ls_task-trstatus <> 'D'",
        "       OR ls_task-as4user <> sy-uname.",
        "      ev_status = 'E'. ev_code = 'TRANSPORT_NOT_MODIFIABLE'.",
        "      ev_message = 'Open workbench task for user is required'.",
        "      ev_version = '2.6'. RETURN.",
        "    ENDIF.",
        "    lv_enh_devclass = iv_package.",
        "    lv_enh_trkorr = ls_task-trkorr.",
        "  END-OF-DEFINITION.",
        "  DEFINE emit_fm_difference.",
        "* One native difference per section; values bounded to 60 chars.",
        "    IF &2[] <> &3[].",
        "      ADD 1 TO lv_fm_diff_id.",
        "      add_repo_payload 'D' lv_fm_diff_id 'SECTION' &1.",
        "      lv_fm_diff_count = lines( &2 ).",
        "      add_repo_payload 'D' lv_fm_diff_id 'EXPECTED_ROWS'",
        "        lv_fm_diff_count.",
        "      lv_fm_diff_count = lines( &3 ).",
        "      add_repo_payload 'D' lv_fm_diff_id 'ACTUAL_ROWS'",
        "        lv_fm_diff_count.",
        "      LOOP AT &2 ASSIGNING <ls_fm_diff_expected>.",
        "        lv_fm_diff_row = sy-tabix.",
        "        READ TABLE &3 ASSIGNING <ls_fm_diff_actual>",
        "          INDEX lv_fm_diff_row.",
        "        IF sy-subrc <> 0.",
        "          add_repo_payload 'D' lv_fm_diff_id 'ROW'",
        "            lv_fm_diff_row.",
        "          add_repo_payload 'D' lv_fm_diff_id 'FIELD'",
        "            'MISSING_ROW'.",
        "          EXIT.",
        "        ENDIF.",
        "        IF <ls_fm_diff_expected> = <ls_fm_diff_actual>.",
        "          CONTINUE.",
        "        ENDIF.",
        "        add_repo_payload 'D' lv_fm_diff_id 'ROW'",
        "          lv_fm_diff_row.",
        "        lo_fm_diff ?= cl_abap_typedescr=>describe_by_data(",
        "          <ls_fm_diff_expected> ).",
        "        lt_fm_diff_components = lo_fm_diff->get_components( ).",
        "        LOOP AT lt_fm_diff_components INTO ls_fm_diff_component.",
        "          ASSIGN COMPONENT ls_fm_diff_component-name",
        "            OF STRUCTURE <ls_fm_diff_expected>",
        "            TO <lv_fm_diff_expected>.",
        "          IF sy-subrc <> 0. CONTINUE. ENDIF.",
        "          ASSIGN COMPONENT ls_fm_diff_component-name",
        "            OF STRUCTURE <ls_fm_diff_actual>",
        "            TO <lv_fm_diff_actual>.",
        "          IF sy-subrc <> 0. CONTINUE. ENDIF.",
        "          IF <lv_fm_diff_expected> = <lv_fm_diff_actual>.",
        "            CONTINUE.",
        "          ENDIF.",
        "          add_repo_payload 'D' lv_fm_diff_id 'FIELD'",
        "            ls_fm_diff_component-name.",
        "          lv_fm_diff_text = <lv_fm_diff_expected>.",
        "          add_repo_payload 'D' lv_fm_diff_id 'EXPECTED'",
        "            lv_fm_diff_text.",
        "          lv_fm_diff_text = <lv_fm_diff_actual>.",
        "          add_repo_payload 'D' lv_fm_diff_id 'ACTUAL'",
        "            lv_fm_diff_text.",
        "          EXIT.",
        "        ENDLOOP.",
        "        EXIT.",
        "      ENDLOOP.",
        "    ENDIF.",
        "  END-OF-DEFINITION.",
        "  DEFINE fm_guard_section.",
        "* Arguments: direction text, payload kind, key field, payload",
        "* rows and live rows. Rows are matched by parameter name and",
        "* only the properties the payload names are compared, so a",
        "* read-back-only field cannot fail the guard. A parameter",
        "* without a live row is the addition being requested.",
        "    IF lv_fm_guard_error IS INITIAL.",
        "      LOOP AT &4 ASSIGNING <ls_fm_guard_expected>.",
        "        lv_fm_guard_index = sy-tabix.",
        "        CLEAR: lv_fm_guard_key, lv_fm_guard_found,",
        "          lv_fm_guard_mismatch.",
        "        ASSIGN COMPONENT &3 OF STRUCTURE <ls_fm_guard_expected>",
        "          TO <lv_fm_guard_name>.",
        "        IF sy-subrc <> 0.",
        "          CONTINUE.",
        "        ENDIF.",
        "        IF <lv_fm_guard_name> IS INITIAL.",
        "          CONTINUE.",
        "        ENDIF.",
        "        lv_fm_guard_key = <lv_fm_guard_name>.",
        "        LOOP AT &5 ASSIGNING <ls_fm_guard_current>.",
        "          ASSIGN COMPONENT &3 OF STRUCTURE <ls_fm_guard_current>",
        "            TO <lv_fm_guard_live_name>.",
        "          IF sy-subrc <> 0.",
        "            CONTINUE.",
        "          ENDIF.",
        "          IF <lv_fm_guard_live_name> <> lv_fm_guard_key.",
        "            CONTINUE.",
        "          ENDIF.",
        "          lv_fm_guard_found = 'X'.",
        "          LOOP AT lt_fm_field INTO ls_fm_field",
        "            WHERE kind = &2 AND position = lv_fm_guard_index.",
        "            ASSIGN COMPONENT ls_fm_field-property",
        "              OF STRUCTURE <ls_fm_guard_expected>",
        "              TO <lv_fm_guard_expected_value>.",
        "            IF sy-subrc <> 0.",
        "              CONTINUE.",
        "            ENDIF.",
        "            ASSIGN COMPONENT ls_fm_field-property",
        "              OF STRUCTURE <ls_fm_guard_current>",
        "              TO <lv_fm_guard_live_value>.",
        "            IF sy-subrc <> 0.",
        "              CONTINUE.",
        "            ENDIF.",
        "            IF <lv_fm_guard_expected_value>",
        "               = <lv_fm_guard_live_value>.",
        "              CONTINUE.",
        "            ENDIF.",
        "            lv_fm_guard_mismatch = 'X'.",
        "            lv_fm_guard_property = ls_fm_field-property.",
        "            lv_fm_guard_expected_text =",
        "              <lv_fm_guard_expected_value>.",
        "            lv_fm_guard_actual_text =",
        "              <lv_fm_guard_live_value>.",
        "            EXIT.",
        "          ENDLOOP.",
        "          EXIT.",
        "        ENDLOOP.",
        "        IF lv_fm_guard_found IS INITIAL.",
        "          CONTINUE.",
        "        ENDIF.",
        "        IF lv_fm_guard_mismatch IS NOT INITIAL.",
        "          lv_fm_guard_error = 'X'.",
        "          lv_fm_guard_direction = &1.",
        "          CLEAR lv_fm_diff_id.",
        "          emit_fm_difference &1 &4 &5.",
        "          EXIT.",
        "        ENDIF.",
        "      ENDLOOP.",
        "    ENDIF.",
        "  END-OF-DEFINITION.",
        "  DEFINE fm_guard_no_removal.",
        "* Arguments: direction text, key field, payload rows, live rows.",
        "* A live parameter the payload never names would be removed or",
        "* renamed, which this opcode must never do silently.",
        "    IF lv_fm_guard_removal IS INITIAL.",
        "      LOOP AT &4 ASSIGNING <ls_fm_guard_current>.",
        "        CLEAR: lv_fm_guard_key, lv_fm_guard_found.",
        "        ASSIGN COMPONENT &2 OF STRUCTURE <ls_fm_guard_current>",
        "          TO <lv_fm_guard_live_name>.",
        "        IF sy-subrc <> 0.",
        "          CONTINUE.",
        "        ENDIF.",
        "        IF <lv_fm_guard_live_name> IS INITIAL.",
        "          CONTINUE.",
        "        ENDIF.",
        "        lv_fm_guard_key = <lv_fm_guard_live_name>.",
        "        LOOP AT &3 ASSIGNING <ls_fm_guard_expected>.",
        "          ASSIGN COMPONENT &2 OF STRUCTURE <ls_fm_guard_expected>",
        "            TO <lv_fm_guard_name>.",
        "          IF sy-subrc <> 0.",
        "            CONTINUE.",
        "          ENDIF.",
        "          IF <lv_fm_guard_name> = lv_fm_guard_key.",
        "            lv_fm_guard_found = 'X'.",
        "            EXIT.",
        "          ENDIF.",
        "        ENDLOOP.",
        "        IF lv_fm_guard_found IS INITIAL.",
        "          lv_fm_guard_removal = 'X'.",
        "          lv_fm_guard_direction = &1.",
        "          EXIT.",
        "        ENDIF.",
        "      ENDLOOP.",
        "    ENDIF.",
        "  END-OF-DEFINITION.",
        "  DEFINE emit_fm_payload.",
        "    REFRESH it_source.",
        "    add_repo_payload 'M' '1' 'FUNCTION_GROUP'",
        "      lv_function_pool.",
        "    add_repo_payload 'M' '1' 'SHORT_TEXT' lv_short_text.",
        "    add_repo_payload 'M' '1' 'REMOTE_ENABLED'",
        "      lv_remote_call.",
        "    add_repo_payload 'M' '1' 'UPDATE_TASK' lv_update_task.",
        "    add_repo_payload 'M' '1' 'GLOBAL_INTERFACE'",
        "      lv_global_flag.",
        "    LOOP AT lt_fm_import INTO ls_fm_import.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'I' lv_payload_index 'PARAMETER'",
        "        ls_fm_import.",
        "      add_repo_component 'I' lv_payload_index 'TYP'",
        "        ls_fm_import.",
        "      add_repo_component 'I' lv_payload_index 'DBFIELD'",
        "        ls_fm_import.",
        "      add_repo_component 'I' lv_payload_index 'OPTIONAL'",
        "        ls_fm_import.",
        "      add_repo_passvalue 'I' lv_payload_index ls_fm_import.",
        "      CLEAR ls_fm_documentation.",
        "      READ TABLE lt_fm_documentation",
        "        INTO ls_fm_documentation",
        "        WITH KEY parameter = ls_fm_import-parameter",
        "          kind = 'P'.",
        "      add_repo_payload 'I' lv_payload_index 'TEXT'",
        "        ls_fm_documentation-stext.",
        "    ENDLOOP.",
        "    LOOP AT lt_fm_export INTO ls_fm_export.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'E' lv_payload_index 'PARAMETER'",
        "        ls_fm_export.",
        "      add_repo_component 'E' lv_payload_index 'TYP'",
        "        ls_fm_export.",
        "      add_repo_component 'E' lv_payload_index 'DBFIELD'",
        "        ls_fm_export.",
        "      add_repo_component 'E' lv_payload_index 'OPTIONAL'",
        "        ls_fm_export.",
        "      add_repo_passvalue 'E' lv_payload_index ls_fm_export.",
        "      CLEAR ls_fm_documentation.",
        "      READ TABLE lt_fm_documentation",
        "        INTO ls_fm_documentation",
        "        WITH KEY parameter = ls_fm_export-parameter",
        "          kind = 'P'.",
        "      add_repo_payload 'E' lv_payload_index 'TEXT'",
        "        ls_fm_documentation-stext.",
        "    ENDLOOP.",
        "    LOOP AT lt_fm_changing INTO ls_fm_changing.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'C' lv_payload_index 'PARAMETER'",
        "        ls_fm_changing.",
        "      add_repo_component 'C' lv_payload_index 'TYP'",
        "        ls_fm_changing.",
        "      add_repo_component 'C' lv_payload_index 'DBFIELD'",
        "        ls_fm_changing.",
        "      add_repo_component 'C' lv_payload_index 'OPTIONAL'",
        "        ls_fm_changing.",
        "      add_repo_passvalue 'C' lv_payload_index ls_fm_changing.",
        "      CLEAR ls_fm_documentation.",
        "      READ TABLE lt_fm_documentation",
        "        INTO ls_fm_documentation",
        "        WITH KEY parameter = ls_fm_changing-parameter",
        "          kind = 'P'.",
        "      add_repo_payload 'C' lv_payload_index 'TEXT'",
        "        ls_fm_documentation-stext.",
        "    ENDLOOP.",
        "    LOOP AT lt_fm_tables INTO ls_fm_table.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'T' lv_payload_index 'PARAMETER'",
        "        ls_fm_table.",
        "      add_repo_component 'T' lv_payload_index 'TYP'",
        "        ls_fm_table.",
        "      add_repo_component 'T' lv_payload_index 'DBSTRUCT'",
        "        ls_fm_table.",
        "      add_repo_component 'T' lv_payload_index 'OPTIONAL'",
        "        ls_fm_table.",
        "      CLEAR ls_fm_documentation.",
        "      READ TABLE lt_fm_documentation",
        "        INTO ls_fm_documentation",
        "        WITH KEY parameter = ls_fm_table-parameter",
        "          kind = 'P'.",
        "      add_repo_payload 'T' lv_payload_index 'TEXT'",
        "        ls_fm_documentation-stext.",
        "    ENDLOOP.",
        "    LOOP AT lt_fm_exceptions INTO ls_fm_exception.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_component 'X' lv_payload_index 'EXCEPTION'",
        "        ls_fm_exception.",
        "      CLEAR ls_fm_documentation.",
        "      READ TABLE lt_fm_documentation",
        "        INTO ls_fm_documentation",
        "        WITH KEY parameter = ls_fm_exception-exception",
        "          kind = 'X'.",
        "      add_repo_payload 'X' lv_payload_index 'TEXT'",
        "        ls_fm_documentation-stext.",
        "    ENDLOOP.",
        "    LOOP AT lt_fm_source INTO ls_fm_source.",
        "      lv_payload_index = sy-tabix.",
        "      add_repo_payload 'S' lv_payload_index 'LINE'",
        "        ls_fm_source-line.",
        "    ENDLOOP.",
        "  END-OF-DEFINITION.",
        "  IF iv_operation = 'UPSERT_SCREEN'",
        "     OR iv_operation = 'PATCH_SCREEN'",
        "     OR iv_operation = 'PATCH_GUI_DEFINITION'",
        "     OR iv_operation = 'CREATE_MODULE_POOL'",
        "     OR iv_operation = 'DELETE_MODULE_POOL'",
        "     OR iv_operation = 'MERGE_TEXT_ELEMENTS'",
        "     OR iv_operation = 'CREATE_REPORT_TRANSACTION'.",
        "    IF iv_program IS INITIAL",
        "       OR ( iv_program(1) <> 'Z' AND iv_program(1) <> 'Y' ).",
        "      ev_status = 'E'.",
        "      ev_code = 'CUSTOMER_PROGRAM_REQUIRED'.",
        "      ev_message = 'Only Z or Y programs are allowed'.",
        "      ev_version = '1.1'.",
        "      RETURN.",
        "    ENDIF.",
        "  ENDIF.",
        "  IF iv_operation = 'READ_SCREEN'",
        "     OR iv_operation = 'READ_GUI_DEFINITION'.",
        "    IF iv_program IS INITIAL.",
        "      ev_status = 'E'.",
        "      ev_code = 'PROGRAM_REQUIRED'.",
        "      ev_message = 'Program name is required'.",
        "      ev_version = '2.2'.",
        "      RETURN.",
        "    ENDIF.",
        "  ENDIF.",
        "  IF iv_operation = 'CREATE_TRANSACTION'",
        "     OR iv_operation = 'DELETE_TRANSACTION'",
        "     OR iv_operation = 'CREATE_REPORT_TRANSACTION'.",
        "    IF iv_transaction IS INITIAL",
        "       OR ( iv_transaction(1) <> 'Z'",
        "       AND iv_transaction(1) <> 'Y' ).",
        "      ev_status = 'E'.",
        "      ev_code = 'CUSTOMER_TRANSACTION_REQUIRED'.",
        "      ev_message = 'Only Z or Y transactions are allowed'.",
        "      ev_version = '1.1'.",
        "      RETURN.",
        "    ENDIF.",
        "  ENDIF.",
        "  IF iv_operation = 'READ_TRANSACTION'.",
        "    IF iv_transaction IS INITIAL.",
        "      ev_status = 'E'.",
        "      ev_code = 'TRANSACTION_REQUIRED'.",
        "      ev_message = 'Transaction name is required'.",
        "      ev_version = '1.2'.",
        "      RETURN.",
        "    ENDIF.",
        "  ENDIF.",
        "  IF iv_operation = 'CREATE_MESSAGE_CLASS'",
        "     OR iv_operation = 'UPDATE_MESSAGE_CLASS'",
        "     OR iv_operation = 'DELETE_MESSAGE_CLASS'.",
        "    IF iv_object_name IS INITIAL",
        "       OR ( iv_object_name(1) <> 'Z'",
        "       AND iv_object_name(1) <> 'Y' ).",
        "      ev_status = 'E'.",
        "      ev_code = 'CUSTOMER_MESSAGE_CLASS_REQUIRED'.",
        "      ev_message = 'Only Z or Y message classes are allowed'.",
        "      ev_version = '1.2'.",
        "      RETURN.",
        "    ENDIF.",
        "  ENDIF.",
        "  IF iv_operation = 'CREATE_FUNCTION_GROUP'.",
        "    IF iv_object_name IS INITIAL",
        "       OR ( iv_object_name(1) <> 'Z'",
        "       AND iv_object_name(1) <> 'Y' ).",
        "      ev_status = 'E'.",
        "      ev_code = 'CUSTOMER_FUNCTION_GROUP_REQUIRED'.",
        "      ev_message = 'Only Z or Y function groups are allowed'.",
        "      ev_version = '1.3'.",
        "      RETURN.",
        "    ENDIF.",
        "  ENDIF.",
        "  IF iv_operation = 'CREATE_FUNCTION_INCLUDE'.",
        "    IF iv_program IS INITIAL",
        "       OR ( iv_program(1) <> 'Z' AND iv_program(1) <> 'Y' )",
        "       OR iv_object_name IS INITIAL.",
        "      ev_status = 'E'.",
        "      ev_code = 'CUSTOMER_FUNCTION_INCLUDE_REQUIRED'.",
        "      ev_message = 'Only Z or Y function group Includes allowed'.",
        "      ev_version = '1.7'.",
        "      RETURN.",
        "    ENDIF.",
        "  ENDIF.",
        "  CASE iv_operation."
    ) + $capabilityBranchLines + @(
        "    WHEN 'READ_ENHANCEMENT_IMPL'.",
        "      IF iv_object_name IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'ENHANCEMENT_IMPLEMENTATION_REQUIRED'.",
        "        ev_message = 'Exact enhancement name is required'.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      CLEAR ls_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'ENHO'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'ENHANCEMENT_IMPLEMENTATION_NOT_FOUND'.",
        "        ev_message = 'Enhancement implementation not found'.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      lv_enh_name = iv_object_name.",
        "      TRY.",
        "          li_enh_tool = cl_enh_factory=>get_enhancement(",
        "            enhancement_id = lv_enh_name",
        "            run_dark = 'X' bypassing_buffer = 'X' ).",
        "          li_enh_object ?= li_enh_tool.",
        "          li_enh_docu ?= li_enh_tool.",
        "          lv_enh_tool_type = li_enh_tool->get_tool( ).",
        "          lv_enh_shorttext =",
        "            li_enh_docu->get_shorttext( ).",
        "          lv_enh_active =",
        "            li_enh_object->has_active_version( ).",
        "          lv_enh_inactive =",
        "            li_enh_object->has_inactive_version( ).",
        "          lv_enh_saved_inactive =",
        "            li_enh_object->has_saved_inactive_version( ).",
        "          lv_enh_unsaved_inactive =",
        "            li_enh_object->has_not_saved_inactive_version( ).",
        "        CATCH cx_enh_root INTO lx_enh_root.",
        "          ev_status = 'E'. ev_code = 'ENHANCEMENT_READ_FAILED'.",
        "          ev_message = lx_enh_root->get_text( ).",
        "          ev_version = '2.5'. RETURN.",
        "      ENDTRY.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'NAME' iv_object_name.",
        "      add_repo_payload 'M' '1' 'TOOL' lv_enh_tool_type.",
        "      add_repo_payload 'M' '1' 'SHORT_TEXT' lv_enh_shorttext.",
        "      add_repo_payload 'M' '1' 'ACTIVE' lv_enh_active.",
        "      add_repo_payload 'M' '1' 'INACTIVE' lv_enh_inactive.",
        "      add_repo_payload 'M' '1' 'SAVED_INACTIVE'",
        "        lv_enh_saved_inactive.",
        "      add_repo_payload 'M' '1' 'UNSAVED_INACTIVE'",
        "        lv_enh_unsaved_inactive.",
        "      add_repo_payload 'M' '1' 'PACKAGE' ls_tadir-devclass.",
        "      IF lv_enh_tool_type = cl_enh_tool_hook_impl=>tooltype.",
        "        lo_enh_hook ?= li_enh_tool.",
        "        CLEAR ls_enh_hook_admin.",
        "        lo_enh_hook->get_original_object(",
        "          IMPORTING pgmid = ls_enh_hook_admin-pgmid",
        "            obj_name = ls_enh_hook_admin-org_obj_name",
        "            obj_type = ls_enh_hook_admin-org_obj_type",
        "            main_type = ls_enh_hook_admin-org_main_type",
        "            main_name = ls_enh_hook_admin-org_main_name",
        "            program = ls_enh_hook_admin-programname ).",
        "        add_repo_payload 'M' '1' 'ORIGINAL_OBJECT_TYPE'",
        "          ls_enh_hook_admin-org_obj_type.",
        "        add_repo_payload 'M' '1' 'ORIGINAL_OBJECT_NAME'",
        "          ls_enh_hook_admin-org_obj_name.",
        "        add_repo_payload 'M' '1' 'MAIN_OBJECT_TYPE'",
        "          ls_enh_hook_admin-org_main_type.",
        "        add_repo_payload 'M' '1' 'MAIN_OBJECT_NAME'",
        "          ls_enh_hook_admin-org_main_name.",
        "        add_repo_payload 'M' '1' 'PROGRAM_NAME'",
        "          ls_enh_hook_admin-programname.",
        "        lt_enh_hooks = lo_enh_hook->get_hook_impls( ).",
        "        CLEAR: lv_enh_row_count, lv_badi_class_index.",
        "        LOOP AT lt_enh_hooks INTO ls_enh_hook.",
        "          lv_payload_index = sy-tabix.",
        "          add_repo_payload 'H' lv_payload_index 'SPOT_NAME'",
        "            ls_enh_hook-spotname.",
        "          add_repo_payload 'H' lv_payload_index 'PROGRAM_NAME'",
        "            ls_enh_hook-programname.",
        "          add_repo_payload 'H' lv_payload_index 'EXTID'",
        "            ls_enh_hook-extid.",
        "          add_repo_payload 'H' lv_payload_index 'ID'",
        "            ls_enh_hook-id.",
        "          add_repo_payload 'H' lv_payload_index 'OVERWRITE'",
        "            ls_enh_hook-overwrite.",
        "          add_repo_payload 'H' lv_payload_index 'METHOD'",
        "            ls_enh_hook-method.",
        "          add_repo_payload 'H' lv_payload_index 'MODE'",
        "            ls_enh_hook-enhmode.",
        "          add_repo_payload 'H' lv_payload_index 'FULL_NAME'",
        "            ls_enh_hook-full_name.",
        "          add_repo_payload 'H' lv_payload_index",
        "            'PARENT_FULL_NAME' ls_enh_hook-parent_full_name.",
        "          DESCRIBE TABLE ls_enh_hook-source",
        "            LINES lv_enh_row_count.",
        "          add_repo_payload 'H' lv_payload_index 'SOURCE_COUNT'",
        "            lv_enh_row_count.",
        "          LOOP AT ls_enh_hook-source INTO lv_enh_source_line.",
        "            lv_enh_source_index = sy-tabix.",
        "            ADD 1 TO lv_badi_class_index.",
        "            add_repo_payload 'S' lv_badi_class_index",
        "              'HOOK_INDEX' lv_payload_index.",
        "            add_repo_payload 'S' lv_badi_class_index",
        "              'LINE_NUMBER' lv_enh_source_index.",
        "            add_repo_payload 'S' lv_badi_class_index 'LINE'",
        "              lv_enh_source_line.",
        "          ENDLOOP.",
        "        ENDLOOP.",
        "      ELSEIF lv_enh_tool_type =",
        "             cl_enh_tool_badi_impl=>tooltype.",
        "        lo_enh_badi ?= li_enh_tool.",
        "        lv_enh_spot_name = lo_enh_badi->get_spot_name( ).",
        "        add_repo_payload 'M' '1' 'SPOT_NAME' lv_enh_spot_name.",
        "        lt_enh_badis = lo_enh_badi->get_implementations( ).",
        "        CLEAR lv_badi_class_index.",
        "        LOOP AT lt_enh_badis INTO ls_enh_badi.",
        "          lv_payload_index = sy-tabix.",
        "          add_repo_payload 'B' lv_payload_index 'SPOT_NAME'",
        "            ls_enh_badi-spot_name.",
        "          add_repo_payload 'B' lv_payload_index 'BADI_NAME'",
        "            ls_enh_badi-badi_name.",
        "          add_repo_payload 'B' lv_payload_index 'IMPL_NAME'",
        "            ls_enh_badi-impl_name.",
        "          add_repo_payload 'B' lv_payload_index 'IMPL_CLASS'",
        "            ls_enh_badi-impl_class.",
        "          add_repo_payload 'B' lv_payload_index 'ACTIVE'",
        "            ls_enh_badi-active.",
        "          add_repo_payload 'B' lv_payload_index 'IS_DEFAULT'",
        "            ls_enh_badi-is_default.",
        "          add_repo_payload 'B' lv_payload_index 'SHORT_TEXT'",
        "            ls_enh_badi-impl_shorttext.",
        "          ASSIGN COMPONENT 'FILTERS' OF STRUCTURE ls_enh_badi",
        "            TO <lt_enh_filters>.",
        "          IF sy-subrc = 0.",
        "            LOOP AT <lt_enh_filters> ASSIGNING <ls_enh_filter>.",
        "              ADD 1 TO lv_badi_class_index.",
        "              add_repo_payload 'F' lv_badi_class_index",
        "                'IMPLEMENTATION_NAME' ls_enh_badi-impl_name.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'DISJ_IDX' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'CONJ_IDX' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'FILTER_NAME' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'FILTER_TYPE' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'COMPARE' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'FILTER_CHAR_VALUE1' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'FILTER_CHAR_VALUE2' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'FILTER_INT_VALUE1' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'FILTER_INT_VALUE2' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'FILTER_NUMERIC_VALUE1' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'FILTER_NUMERIC_VALUE2' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'FILTER_STRING_VALUE1' <ls_enh_filter>.",
        "              add_repo_component 'F' lv_badi_class_index",
        "                'FILTER_STRING_VALUE2' <ls_enh_filter>.",
        "            ENDLOOP.",
        "          ENDIF.",
        "        ENDLOOP.",
        "      ENDIF.",
        "      ev_status = 'S'.",
        "      ev_code = 'ENHANCEMENT_IMPLEMENTATION_READ'.",
        "      ev_message = 'Enhancement implementation read'.",
        "      ev_version = '2.6'. RETURN.",
        "    WHEN 'CREATE_HOOK_ENHANCEMENT'",
        "      OR 'CREATE_BADI_ENHANCEMENT'.",
        "      IF iv_object_name IS INITIAL",
        "         OR ( iv_object_name(1) <> 'Z'",
        "           AND iv_object_name(1) <> 'Y' )",
        "         OR iv_description IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'ENH_CREATE_INPUT_REQUIRED'.",
        "        ev_message = 'Customer name and description required'.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      validate_enh_transport.",
        "      CLEAR ls_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'ENHO'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc = 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'ENHANCEMENT_IMPLEMENTATION_EXISTS'.",
        "        ev_message = 'Enhancement implementation exists'.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_enh_hook_admin, ls_enh_badi,",
        "        lv_enh_full_name, lv_enh_mode, lv_enh_overwrite,",
        "        lv_enh_spot_name, lv_enh_badi_name,",
        "        lv_enh_impl_name, lv_enh_impl_class, lv_enh_default.",
        "      REFRESH lt_enh_source.",
        "      LOOP AT it_source INTO ls_source.",
        "        CLEAR: lv_payload_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_payload_kind",
        "          lv_payload_index_text lv_payload_property",
        "          lv_payload_value.",
        "        IF lv_payload_index_text IS INITIAL",
        "           OR lv_payload_index_text CN '0123456789'.",
        "          ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "          ev_message = 'Enhancement payload index invalid'.",
        "          ev_version = '2.5'. RETURN.",
        "        ENDIF.",
        "        lv_payload_index = lv_payload_index_text.",
        "        TRANSLATE lv_payload_property TO UPPER CASE.",
        "        REPLACE ALL OCCURRENCES OF '%7C'",
        "          IN lv_payload_value WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25'",
        "          IN lv_payload_value WITH '%'.",
        "        IF lv_payload_kind = 'M'.",
        "          CASE lv_payload_property.",
        "            WHEN 'ORIGINAL_OBJECT_TYPE'.",
        "              ls_enh_hook_admin-org_obj_type = lv_payload_value.",
        "            WHEN 'ORIGINAL_OBJECT_NAME'.",
        "              ls_enh_hook_admin-org_obj_name = lv_payload_value.",
        "            WHEN 'MAIN_OBJECT_TYPE'.",
        "              ls_enh_hook_admin-org_main_type = lv_payload_value.",
        "            WHEN 'MAIN_OBJECT_NAME'.",
        "              ls_enh_hook_admin-org_main_name = lv_payload_value.",
        "            WHEN 'PROGRAM_NAME'.",
        "              ls_enh_hook_admin-programname = lv_payload_value.",
        "            WHEN 'FULL_NAME'.",
        "              lv_enh_full_name = lv_payload_value.",
        "            WHEN 'MODE'. lv_enh_mode = lv_payload_value.",
        "            WHEN 'REPLACEMENT'.",
        "              lv_enh_overwrite = lv_payload_value.",
        "            WHEN 'SPOT_NAME'.",
        "              lv_enh_spot_name = lv_payload_value.",
        "            WHEN 'BADI_NAME'.",
        "              lv_enh_badi_name = lv_payload_value.",
        "            WHEN 'IMPLEMENTATION_NAME'.",
        "              lv_enh_impl_name = lv_payload_value.",
        "            WHEN 'IMPLEMENTATION_CLASS'.",
        "              lv_enh_impl_class = lv_payload_value.",
        "            WHEN 'DEFAULT_IMPLEMENTATION'.",
        "              lv_enh_default = lv_payload_value.",
        "            WHEN OTHERS.",
        "              ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "              ev_message = 'Enhancement property not allowed'.",
        "              ev_version = '2.5'. RETURN.",
        "          ENDCASE.",
        "        ELSEIF lv_payload_kind = 'S'",
        "          AND iv_operation = 'CREATE_HOOK_ENHANCEMENT'",
        "          AND lv_payload_property = 'LINE'.",
        "          APPEND lv_payload_value TO lt_enh_source.",
        "        ELSEIF lv_payload_kind = 'F'",
        "          AND iv_operation = 'CREATE_BADI_ENHANCEMENT'.",
        "          ASSIGN COMPONENT 'FILTERS' OF STRUCTURE ls_enh_badi",
        "            TO <lt_enh_filters>.",
        "          IF sy-subrc <> 0.",
        "            ev_status = 'E'. ev_code = 'FILTER_TYPE_INVALID'.",
        "            ev_message = 'BAdI filter structure unavailable'.",
        "            ev_version = '2.5'. RETURN.",
        "          ENDIF.",
        "          DESCRIBE TABLE <lt_enh_filters>",
        "            LINES lv_enh_row_count.",
        "          WHILE lv_enh_row_count < lv_payload_index.",
        "            APPEND INITIAL LINE TO <lt_enh_filters>.",
        "            ADD 1 TO lv_enh_row_count.",
        "          ENDWHILE.",
        "          READ TABLE <lt_enh_filters>",
        "            ASSIGNING <ls_enh_filter> INDEX lv_payload_index.",
        "          ASSIGN COMPONENT lv_payload_property",
        "            OF STRUCTURE <ls_enh_filter>",
        "            TO <lv_payload_component>.",
        "          IF sy-subrc <> 0.",
        "            ev_status = 'E'. ev_code = 'FILTER_PROPERTY_INVALID'.",
        "            ev_message = 'Unknown New BAdI filter property'.",
        "            ev_version = '2.5'. RETURN.",
        "          ENDIF.",
        "          <lv_payload_component> = lv_payload_value.",
        "        ELSE.",
        "          ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "          ev_message = 'Unexpected enhancement payload row'.",
        "          ev_version = '2.5'. RETURN.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      ls_enh_hook_admin-pgmid = 'R3TR'.",
        "      lv_enh_name = iv_object_name.",
        "      TRY.",
        "          IF iv_operation = 'CREATE_HOOK_ENHANCEMENT'.",
        "            IF ls_enh_hook_admin-org_obj_type IS INITIAL",
        "               OR ls_enh_hook_admin-org_obj_name IS INITIAL",
        "               OR ls_enh_hook_admin-org_main_type IS INITIAL",
        "               OR ls_enh_hook_admin-org_main_name IS INITIAL",
        "               OR ls_enh_hook_admin-programname IS INITIAL",
        "               OR lv_enh_full_name IS INITIAL",
        "               OR lv_enh_mode IS INITIAL.",
        "              ev_status = 'E'.",
        "              ev_code = 'HOOK_CREATE_INPUT_REQUIRED'.",
        "              ev_message = 'Complete hook identity required'.",
        "              ev_version = '2.5'. RETURN.",
        "            ENDIF.",
        "            cl_enh_factory=>create_enhancement(",
        "              EXPORTING enhname = lv_enh_name",
        "                enhtype =",
        "                  cl_abstract_enh_tool_redef=>credefinition",
        "                enhtooltype = cl_enh_tool_hook_impl=>tooltype",
        "                dark = 'X'",
        "              IMPORTING enhancement = li_enh_tool",
        "              CHANGING trkorr = lv_enh_trkorr",
        "                devclass = lv_enh_devclass ).",
        "            li_enh_object ?= li_enh_tool.",
        "            lo_enh_hook ?= li_enh_tool.",
        "            lv_enh_shorttext = iv_description.",
        "            lo_enh_hook->if_enh_object_docu~set_shorttext(",
        "              lv_enh_shorttext ).",
        "            lo_enh_hook->set_original_object(",
        "              pgmid = ls_enh_hook_admin-pgmid",
        "              obj_name = ls_enh_hook_admin-org_obj_name",
        "              obj_type = ls_enh_hook_admin-org_obj_type",
        "              program = ls_enh_hook_admin-programname",
        "              main_type = ls_enh_hook_admin-org_main_type",
        "              main_name = ls_enh_hook_admin-org_main_name ).",
        "            lo_enh_hook->add_hook_impl(",
        "              overwrite = lv_enh_overwrite method = space",
        "              enhmode = lv_enh_mode full_name = lv_enh_full_name",
        "              source = lt_enh_source ).",
        "          ELSE.",
        "            IF lv_enh_spot_name IS INITIAL",
        "               OR lv_enh_badi_name IS INITIAL",
        "               OR lv_enh_impl_name IS INITIAL",
        "               OR lv_enh_impl_class IS INITIAL.",
        "              ev_status = 'E'.",
        "              ev_code = 'BADI_CREATE_INPUT_REQUIRED'.",
        "              ev_message = 'Complete New BAdI identity required'.",
        "              ev_version = '2.5'. RETURN.",
        "            ENDIF.",
        "            cl_enh_factory=>create_enhancement(",
        "              EXPORTING enhname = lv_enh_name",
        "                enhtype =",
        "                  cl_abstract_enh_tool_redef=>credefinition",
        "                enhtooltype = cl_enh_tool_badi_impl=>tooltype",
        "                dark = 'X'",
        "              IMPORTING enhancement = li_enh_tool",
        "              CHANGING trkorr = lv_enh_trkorr",
        "                devclass = lv_enh_devclass ).",
        "            li_enh_object ?= li_enh_tool.",
        "            lo_enh_badi ?= li_enh_tool.",
        "            lo_enh_badi->set_spot_name( lv_enh_spot_name ).",
        "            lv_enh_shorttext = iv_description.",
        "            lo_enh_badi->if_enh_object_docu~set_shorttext(",
        "              lv_enh_shorttext ).",
        "            ls_enh_badi-spot_name = lv_enh_spot_name.",
        "            ls_enh_badi-badi_name = lv_enh_badi_name.",
        "            ls_enh_badi-impl_name = lv_enh_impl_name.",
        "            ls_enh_badi-impl_class = lv_enh_impl_class.",
        "            ls_enh_badi-active = 'X'.",
        "            ls_enh_badi-is_default = lv_enh_default.",
        "            ls_enh_badi-impl_shorttext = iv_description.",
        "            lo_enh_badi->add_implementation( ls_enh_badi ).",
        "          ENDIF.",
        "          li_enh_object->save(",
        "            EXPORTING run_dark = 'X'",
        "            CHANGING devclass = lv_enh_devclass",
        "              trkorr = lv_enh_trkorr ).",
        "          li_enh_object->activate(",
        "            EXPORTING run_dark = 'X'",
        "            CHANGING devclass = lv_enh_devclass",
        "              trkorr = lv_enh_trkorr ).",
        "          li_enh_object->unlock( ).",
        "          COMMIT WORK AND WAIT.",
        "        CATCH cx_enh_root INTO lx_enh_root.",
        "          ROLLBACK WORK.",
        "          IF li_enh_object IS BOUND.",
        "            TRY.",
        "                li_enh_object->unlock( ).",
        "              CATCH cx_root.",
        "            ENDTRY.",
        "          ENDIF.",
        "          ev_status = 'E'. ev_code = 'ENHANCEMENT_CREATE_FAILED'.",
        "          ev_message = lx_enh_root->get_text( ).",
        "          ev_version = '2.5'. RETURN.",
        "      ENDTRY.",
        "      ev_status = 'S'.",
        "      IF iv_operation = 'CREATE_HOOK_ENHANCEMENT'.",
        "        ev_code = 'HOOK_ENHANCEMENT_CREATED'.",
        "      ELSE.",
        "        ev_code = 'BADI_ENHANCEMENT_CREATED'.",
        "      ENDIF.",
        "      ev_message = 'Enhancement created and activated'.",
        "      ev_version = '2.5'. RETURN.",
        "    WHEN 'UPDATE_HOOK_ENHANCEMENT'",
        "      OR 'UPDATE_BADI_ENHANCEMENT'.",
        "      IF iv_object_name IS INITIAL",
        "         OR ( iv_object_name(1) <> 'Z'",
        "           AND iv_object_name(1) <> 'Y' ).",
        "        ev_status = 'E'.",
        "        ev_code = 'CUSTOMER_ENHANCEMENT_REQUIRED'.",
        "        ev_message = 'Only Z or Y enhancements are writable'.",
        "        ev_version = '2.6'. RETURN.",
        "      ENDIF.",
        "      validate_enh_transport.",
        "      CLEAR ls_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'ENHO'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'ENHANCEMENT_IMPLEMENTATION_NOT_FOUND'.",
        "        ev_message = 'Enhancement implementation not found'.",
        "        ev_version = '2.6'. RETURN.",
        "      ENDIF.",
        "      IF ls_tadir-devclass <> iv_package.",
        "        ev_status = 'E'. ev_code = 'PACKAGE_CONFLICT'.",
        "        ev_message = 'Enhancement belongs to another package'.",
        "        ev_version = '2.6'. RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_enh_badi, ls_enh_badi_existing,",
        "        lv_enh_extid, lv_enh_impl_name,",
        "        lv_enh_impl_class, lv_enh_impl_active,",
        "        lv_enh_default.",
        "      REFRESH lt_enh_source.",
        "      LOOP AT it_source INTO ls_source.",
        "        CLEAR: lv_payload_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_payload_kind",
        "          lv_payload_index_text lv_payload_property",
        "          lv_payload_value.",
        "        IF lv_payload_index_text IS INITIAL",
        "           OR lv_payload_index_text CN '0123456789'.",
        "          ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "          ev_message = 'Enhancement payload index invalid'.",
        "          ev_version = '2.6'. RETURN.",
        "        ENDIF.",
        "        lv_payload_index = lv_payload_index_text.",
        "        TRANSLATE lv_payload_property TO UPPER CASE.",
        "        REPLACE ALL OCCURRENCES OF '%7C'",
        "          IN lv_payload_value WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25'",
        "          IN lv_payload_value WITH '%'.",
        "        IF lv_payload_kind = 'M'.",
        "          CASE lv_payload_property.",
        "            WHEN 'EXTID'. lv_enh_extid = lv_payload_value.",
        "            WHEN 'IMPLEMENTATION_NAME'.",
        "              lv_enh_impl_name = lv_payload_value.",
        "            WHEN 'IMPLEMENTATION_CLASS'.",
        "              lv_enh_impl_class = lv_payload_value.",
        "            WHEN 'ACTIVE'.",
        "              lv_enh_impl_active = lv_payload_value.",
        "            WHEN 'DEFAULT_IMPLEMENTATION'.",
        "              lv_enh_default = lv_payload_value.",
        "            WHEN OTHERS.",
        "              ev_status = 'E'. ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "              ev_message = 'Enhancement property not allowed'.",
        "              ev_version = '2.6'. RETURN.",
        "          ENDCASE.",
        "        ELSEIF lv_payload_kind = 'S'",
        "          AND iv_operation = 'UPDATE_HOOK_ENHANCEMENT'",
        "          AND lv_payload_property = 'LINE'.",
        "          APPEND lv_payload_value TO lt_enh_source.",
        "        ELSEIF lv_payload_kind = 'F'",
        "          AND iv_operation = 'UPDATE_BADI_ENHANCEMENT'.",
        "          ASSIGN COMPONENT 'FILTERS' OF STRUCTURE ls_enh_badi",
        "            TO <lt_enh_filters>.",
        "          IF sy-subrc <> 0.",
        "            ev_status = 'E'. ev_code = 'FILTER_TYPE_INVALID'.",
        "            ev_message = 'BAdI filter structure unavailable'.",
        "            ev_version = '2.6'. RETURN.",
        "          ENDIF.",
        "          DESCRIBE TABLE <lt_enh_filters>",
        "            LINES lv_enh_row_count.",
        "          WHILE lv_enh_row_count < lv_payload_index.",
        "            APPEND INITIAL LINE TO <lt_enh_filters>.",
        "            ADD 1 TO lv_enh_row_count.",
        "          ENDWHILE.",
        "          READ TABLE <lt_enh_filters>",
        "            ASSIGNING <ls_enh_filter> INDEX lv_payload_index.",
        "          ASSIGN COMPONENT lv_payload_property",
        "            OF STRUCTURE <ls_enh_filter>",
        "            TO <lv_payload_component>.",
        "          IF sy-subrc <> 0.",
        "            ev_status = 'E'. ev_code = 'FILTER_PROPERTY_INVALID'.",
        "            ev_message = 'Unknown New BAdI filter property'.",
        "            ev_version = '2.6'. RETURN.",
        "          ENDIF.",
        "          <lv_payload_component> = lv_payload_value.",
        "        ELSE.",
        "          ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "          ev_message = 'Unexpected enhancement payload row'.",
        "          ev_version = '2.6'. RETURN.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      IF iv_operation = 'UPDATE_HOOK_ENHANCEMENT'",
        "         AND lv_enh_extid IS INITIAL.",
        "        ev_status = 'E'. ev_code = 'HOOK_UPDATE_INPUT_REQUIRED'.",
        "        ev_message = 'Exact hook extId is required'.",
        "        ev_version = '2.6'. RETURN.",
        "      ENDIF.",
        "      IF iv_operation = 'UPDATE_BADI_ENHANCEMENT'",
        "         AND ( lv_enh_impl_name IS INITIAL",
        "           OR lv_enh_impl_class IS INITIAL ).",
        "        ev_status = 'E'. ev_code = 'BADI_UPDATE_INPUT_REQUIRED'.",
        "        ev_message = 'Implementation name and class required'.",
        "        ev_version = '2.6'. RETURN.",
        "      ENDIF.",
        "      lv_enh_name = iv_object_name.",
        "      TRY.",
        "          li_enh_tool = cl_enh_factory=>get_enhancement(",
        "            enhancement_id = lv_enh_name run_dark = 'X'",
        "            lock = 'X' bypassing_buffer = 'X' ).",
        "          li_enh_object ?= li_enh_tool.",
        "          li_enh_docu ?= li_enh_tool.",
        "          lv_enh_inactive =",
        "            li_enh_object->has_inactive_version( ).",
        "          IF lv_enh_inactive = 'X'.",
        "            li_enh_object->unlock( ).",
        "            ev_status = 'E'.",
        "            ev_code = 'ENHANCEMENT_INACTIVE_VERSION_EXISTS'.",
        "            ev_message = 'Resolve inactive version before update'.",
        "            ev_version = '2.6'. RETURN.",
        "          ENDIF.",
        "          lv_enh_tool_type = li_enh_tool->get_tool( ).",
        "          IF iv_operation = 'UPDATE_HOOK_ENHANCEMENT'.",
        "            IF lv_enh_tool_type <> cl_enh_tool_hook_impl=>tooltype.",
        "              li_enh_object->unlock( ).",
        "              ev_status = 'E'.",
        "              ev_code = 'ENHANCEMENT_TOOL_TYPE_MISMATCH'.",
        "              ev_message = 'ENHO is not a hook implementation'.",
        "              ev_version = '2.6'. RETURN.",
        "            ENDIF.",
        "            lo_enh_hook ?= li_enh_tool.",
        "            lt_enh_hooks = lo_enh_hook->get_hook_impls( 'A' ).",
        "            READ TABLE lt_enh_hooks INTO ls_enh_hook",
        "              WITH KEY extid = lv_enh_extid.",
        "            IF sy-subrc <> 0.",
        "              li_enh_object->unlock( ).",
        "              ev_status = 'E'. ev_code = 'ENHANCEMENT_HOOK_NOT_FOUND'.",
        "              ev_message = 'Hook extId not found'.",
        "              ev_version = '2.6'. RETURN.",
        "            ENDIF.",
        "            lo_enh_hook->modify_hook_impl(",
        "              overwrite = ls_enh_hook-overwrite",
        "              method = ls_enh_hook-method",
        "              enhmode = ls_enh_hook-enhmode",
        "              full_name = ls_enh_hook-full_name",
        "              source = lt_enh_source extid = lv_enh_extid",
        "              spot = ls_enh_hook-spotname",
        "              parent_full_name = ls_enh_hook-parent_full_name ).",
        "          ELSE.",
        "            IF lv_enh_tool_type <> cl_enh_tool_badi_impl=>tooltype.",
        "              li_enh_object->unlock( ).",
        "              ev_status = 'E'.",
        "              ev_code = 'ENHANCEMENT_TOOL_TYPE_MISMATCH'.",
        "              ev_message = 'ENHO is not a BAdI implementation'.",
        "              ev_version = '2.6'. RETURN.",
        "            ENDIF.",
        "            lo_enh_badi ?= li_enh_tool.",
        "            ls_enh_badi_existing = lo_enh_badi->get_implementation(",
        "              impl_name = lv_enh_impl_name version = 'A' ).",
        "            ls_enh_badi_existing-impl_class = lv_enh_impl_class.",
        "            ls_enh_badi_existing-active = lv_enh_impl_active.",
        "            ls_enh_badi_existing-is_default = lv_enh_default.",
        "            IF iv_description IS NOT INITIAL.",
        "              ls_enh_badi_existing-impl_shorttext =",
        "                iv_description.",
        "            ENDIF.",
        "            ASSIGN COMPONENT 'FILTERS'",
        "              OF STRUCTURE ls_enh_badi_existing",
        "              TO <lt_enh_existing_filters>.",
        "            ASSIGN COMPONENT 'FILTERS' OF STRUCTURE ls_enh_badi",
        "              TO <lt_enh_filters>.",
        "            IF sy-subrc <> 0",
        "               OR <lt_enh_existing_filters> IS NOT ASSIGNED.",
        "              li_enh_object->unlock( ).",
        "              ev_status = 'E'. ev_code = 'FILTER_TYPE_INVALID'.",
        "              ev_message = 'BAdI filter structure unavailable'.",
        "              ev_version = '2.6'. RETURN.",
        "            ENDIF.",
        "            <lt_enh_existing_filters> = <lt_enh_filters>.",
        "            lo_enh_badi->delete_implementation( lv_enh_impl_name ).",
        "            lo_enh_badi->add_implementation(",
        "              ls_enh_badi_existing ).",
        "          ENDIF.",
        "          IF iv_description IS NOT INITIAL.",
        "            lv_enh_shorttext = iv_description.",
        "            li_enh_docu->set_shorttext(",
        "              lv_enh_shorttext ).",
        "          ENDIF.",
        "          li_enh_object->save(",
        "            EXPORTING run_dark = 'X'",
        "            CHANGING devclass = lv_enh_devclass",
        "              trkorr = lv_enh_trkorr ).",
        "          li_enh_object->activate(",
        "            EXPORTING run_dark = 'X'",
        "            CHANGING devclass = lv_enh_devclass",
        "              trkorr = lv_enh_trkorr ).",
        "          li_enh_object->unlock( ).",
        "          COMMIT WORK AND WAIT.",
        "        CATCH cx_enh_root INTO lx_enh_root.",
        "          ROLLBACK WORK.",
        "          IF li_enh_object IS BOUND.",
        "            TRY.",
        "                li_enh_object->unlock( ).",
        "              CATCH cx_root.",
        "            ENDTRY.",
        "          ENDIF.",
        "          ev_status = 'E'. ev_code = 'ENHANCEMENT_UPDATE_FAILED'.",
        "          ev_message = lx_enh_root->get_text( ).",
        "          ev_version = '2.6'. RETURN.",
        "      ENDTRY.",
        "      ev_status = 'S'.",
        "      IF iv_operation = 'UPDATE_HOOK_ENHANCEMENT'.",
        "        ev_code = 'HOOK_ENHANCEMENT_UPDATED'.",
        "      ELSE.",
        "        ev_code = 'BADI_ENHANCEMENT_UPDATED'.",
        "      ENDIF.",
        "      ev_message = 'Enhancement updated and activated'.",
        "      ev_version = '2.6'. RETURN.",
        "    WHEN 'MANAGE_ENHANCEMENT_STATE'.",
        "      IF iv_object_name IS INITIAL",
        "         OR ( iv_object_name(1) <> 'Z'",
        "           AND iv_object_name(1) <> 'Y' )",
        "         OR ( iv_object_type <> 'ACTIVATE'",
        "           AND iv_object_type <> 'DISCARD_INACTIVE' ).",
        "        ev_status = 'E'. ev_code = 'ENH_STATE_INPUT_INVALID'.",
        "        ev_message = 'Customer enhancement and action required'.",
        "        ev_version = '2.6'. RETURN.",
        "      ENDIF.",
        "      validate_enh_transport.",
        "      CLEAR ls_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'ENHO'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'ENHANCEMENT_IMPLEMENTATION_NOT_FOUND'.",
        "        ev_message = 'Enhancement implementation not found'.",
        "        ev_version = '2.6'. RETURN.",
        "      ENDIF.",
        "      IF ls_tadir-devclass <> iv_package.",
        "        ev_status = 'E'. ev_code = 'PACKAGE_CONFLICT'.",
        "        ev_message = 'Enhancement belongs to another package'.",
        "        ev_version = '2.6'. RETURN.",
        "      ENDIF.",
        "      lv_enh_name = iv_object_name.",
        "      TRY.",
        "          li_enh_tool = cl_enh_factory=>get_enhancement(",
        "            enhancement_id = lv_enh_name run_dark = 'X'",
        "            lock = 'X' bypassing_buffer = 'X' ).",
        "          li_enh_object ?= li_enh_tool.",
        "          lv_enh_inactive =",
        "            li_enh_object->has_inactive_version( ).",
        "          IF lv_enh_inactive IS INITIAL.",
        "            li_enh_object->unlock( ).",
        "            IF iv_object_type = 'ACTIVATE'.",
        "              ev_status = 'S'. ev_code = 'ENHANCEMENT_ALREADY_ACTIVE'.",
        "              ev_message = 'No inactive version to activate'.",
        "            ELSE.",
        "              ev_status = 'E'.",
        "              ev_code = 'ENHANCEMENT_NO_INACTIVE_VERSION'.",
        "              ev_message = 'No inactive version to discard'.",
        "            ENDIF.",
        "            ev_version = '2.6'. RETURN.",
        "          ENDIF.",
        "          IF iv_object_type = 'ACTIVATE'.",
        "            li_enh_object->activate(",
        "              EXPORTING run_dark = 'X'",
        "              CHANGING devclass = lv_enh_devclass",
        "                trkorr = lv_enh_trkorr ).",
        "          ELSE.",
        "            li_enh_object->reset_to_active_version(",
        "              CHANGING devclass = lv_enh_devclass",
        "                trkorr = lv_enh_trkorr ).",
        "          ENDIF.",
        "          li_enh_object->unlock( ).",
        "          COMMIT WORK AND WAIT.",
        "        CATCH cx_enh_root INTO lx_enh_root.",
        "          ROLLBACK WORK.",
        "          IF li_enh_object IS BOUND.",
        "            TRY.",
        "                li_enh_object->unlock( ).",
        "              CATCH cx_root.",
        "            ENDTRY.",
        "          ENDIF.",
        "          ev_status = 'E'. ev_code = 'ENH_STATE_CHANGE_FAILED'.",
        "          ev_message = lx_enh_root->get_text( ).",
        "          ev_version = '2.6'. RETURN.",
        "      ENDTRY.",
        "      ev_status = 'S'.",
        "      IF iv_object_type = 'ACTIVATE'.",
        "        ev_code = 'ENHANCEMENT_IMPLEMENTATION_ACTIVATED'.",
        "        ev_message = 'Enhancement implementation activated'.",
        "      ELSE.",
        "        ev_code = 'ENHANCEMENT_INACTIVE_VERSION_DISCARDED'.",
        "        ev_message = 'Inactive enhancement version discarded'.",
        "      ENDIF.",
        "      ev_version = '2.6'. RETURN.",
        "    WHEN 'DELETE_ENHANCEMENT_IMPL'.",
        "      IF iv_object_name IS INITIAL",
        "         OR ( iv_object_name(1) <> 'Z'",
        "           AND iv_object_name(1) <> 'Y' ).",
        "        ev_status = 'E'.",
        "        ev_code = 'CUSTOMER_ENHANCEMENT_REQUIRED'.",
        "        ev_message = 'Only Z or Y enhancements are writable'.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      validate_enh_transport.",
        "      CLEAR ls_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'ENHO'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'ENHANCEMENT_IMPLEMENTATION_NOT_FOUND'.",
        "        ev_message = 'Enhancement implementation not found'.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      IF ls_tadir-devclass <> iv_package.",
        "        ev_status = 'E'. ev_code = 'PACKAGE_CONFLICT'.",
        "        ev_message = 'Enhancement belongs to another package'.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      lv_enh_name = iv_object_name.",
        "      TRY.",
        "          li_enh_tool = cl_enh_factory=>get_enhancement(",
        "            enhancement_id = lv_enh_name run_dark = 'X'",
        "            lock = 'X' bypassing_buffer = 'X' ).",
        "          li_enh_object ?= li_enh_tool.",
        "          li_enh_object->delete(",
        "            EXPORTING nevertheless_delete = 'X' run_dark = 'X'",
        "            CHANGING devclass = lv_enh_devclass",
        "              trkorr = lv_enh_trkorr ).",
        "          li_enh_object->unlock( ).",
        "          COMMIT WORK AND WAIT.",
        "        CATCH cx_enh_root INTO lx_enh_root.",
        "          ROLLBACK WORK.",
        "          IF li_enh_object IS BOUND.",
        "            TRY.",
        "                li_enh_object->unlock( ).",
        "              CATCH cx_root.",
        "            ENDTRY.",
        "          ENDIF.",
        "          ev_status = 'E'. ev_code = 'ENHANCEMENT_DELETE_FAILED'.",
        "          ev_message = lx_enh_root->get_text( ).",
        "          ev_version = '2.5'. RETURN.",
        "      ENDTRY.",
        "      CLEAR ls_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'ENHO'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc = 0.",
        "        ev_status = 'E'. ev_code = 'ENHANCEMENT_DELETE_PARTIAL'.",
        "        ev_message = 'Enhancement still exists after delete'.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      REFRESH it_source.",
        "      ev_status = 'S'.",
        "      ev_code = 'ENHANCEMENT_IMPLEMENTATION_DELETED'.",
        "      ev_message = 'Enhancement implementation deleted'.",
        "      ev_version = '2.5'. RETURN.",
        "    WHEN 'MANAGE_CLASSIC_BADI_IMPL'.",
        "      IF iv_object_name IS INITIAL",
        "         OR ( iv_object_name(1) <> 'Z'",
        "           AND iv_object_name(1) <> 'Y' )",
        "         OR ( iv_object_type <> 'CREATE'",
        "           AND iv_object_type <> 'ACTIVATE'",
        "           AND iv_object_type <> 'DEACTIVATE'",
        "           AND iv_object_type <> 'DELETE' ).",
        "        ev_status = 'E'. ev_code = 'CLASSIC_BADI_INPUT_INVALID'.",
        "        ev_message = 'Customer implementation and action required'.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      validate_enh_transport.",
        "      CLEAR: ls_classic_impl, lv_classic_action.",
        "      REFRESH: lt_classic_filters, lt_classic_methods,",
        "        lt_classic_protocol.",
        "      LOOP AT it_source INTO ls_source.",
        "        CLEAR: lv_payload_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_payload_kind",
        "          lv_payload_index_text lv_payload_property",
        "          lv_payload_value.",
        "        IF lv_payload_index_text IS INITIAL",
        "           OR lv_payload_index_text CN '0123456789'.",
        "          ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "          ev_message = 'Classic BAdI payload index invalid'.",
        "          ev_version = '2.5'. RETURN.",
        "        ENDIF.",
        "        lv_payload_index = lv_payload_index_text.",
        "        TRANSLATE lv_payload_property TO UPPER CASE.",
        "        REPLACE ALL OCCURRENCES OF '%7C'",
        "          IN lv_payload_value WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25'",
        "          IN lv_payload_value WITH '%'.",
        "        CASE lv_payload_kind.",
        "          WHEN 'M'.",
        "            CASE lv_payload_property.",
        "              WHEN 'ACTION'.",
        "                lv_classic_action = lv_payload_value.",
        "              WHEN 'DEFINITION_NAME'.",
        "                ls_classic_impl-exit_name = lv_payload_value.",
        "              WHEN 'INTERFACE_NAME'.",
        "                ls_classic_impl-inter_name = lv_payload_value.",
        "              WHEN 'IMPLEMENTATION_CLASS'.",
        "                ls_classic_impl-imp_class = lv_payload_value.",
        "              WHEN OTHERS.",
        "                ev_status = 'E'.",
        "                ev_code = 'PROPERTY_NOT_ALLOWED'.",
        "                ev_message = 'Classic BAdI property invalid'.",
        "                ev_version = '2.5'. RETURN.",
        "            ENDCASE.",
        "          WHEN 'F'.",
        "            DESCRIBE TABLE lt_classic_filters",
        "              LINES lv_enh_row_count.",
        "            WHILE lv_enh_row_count < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_classic_filters.",
        "              ADD 1 TO lv_enh_row_count.",
        "            ENDWHILE.",
        "            READ TABLE lt_classic_filters",
        "              ASSIGNING <ls_classic_filter>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_classic_filter>",
        "              TO <lv_payload_component>.",
        "            IF sy-subrc <> 0.",
        "              ev_status = 'E'.",
        "              ev_code = 'FILTER_PROPERTY_INVALID'.",
        "              ev_message = 'Unknown Classic BAdI filter field'.",
        "              ev_version = '2.5'. RETURN.",
        "            ENDIF.",
        "            <lv_payload_component> = lv_payload_value.",
        "          WHEN 'N'.",
        "            IF lv_payload_property <> 'METHOD_NAME'.",
        "              ev_status = 'E'. ev_code = 'METHOD_INVALID'.",
        "              ev_message = 'Classic BAdI method name required'.",
        "              ev_version = '2.5'. RETURN.",
        "            ENDIF.",
        "            DESCRIBE TABLE lt_classic_methods",
        "              LINES lv_enh_row_count.",
        "            WHILE lv_enh_row_count < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_classic_methods.",
        "              ADD 1 TO lv_enh_row_count.",
        "            ENDWHILE.",
        "            READ TABLE lt_classic_methods",
        "              ASSIGNING <ls_classic_method>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT 'METHODNAME'",
        "              OF STRUCTURE <ls_classic_method>",
        "              TO <lv_payload_component>.",
        "            IF sy-subrc <> 0.",
        "              ev_status = 'E'. ev_code = 'METHOD_INVALID'.",
        "              ev_message = 'Method structure unavailable'.",
        "              ev_version = '2.5'. RETURN.",
        "            ENDIF.",
        "            <lv_payload_component> = lv_payload_value.",
        "          WHEN 'S'.",
        "            READ TABLE lt_classic_methods",
        "              ASSIGNING <ls_classic_method>",
        "              INDEX lv_payload_index.",
        "            IF sy-subrc <> 0.",
        "              ev_status = 'E'. ev_code = 'METHOD_INVALID'.",
        "              ev_message = 'Method source precedes method name'.",
        "              ev_version = '2.5'. RETURN.",
        "            ENDIF.",
        "            ASSIGN COMPONENT 'SOURCE'",
        "              OF STRUCTURE <ls_classic_method>",
        "              TO <lt_classic_source>.",
        "            IF sy-subrc <> 0.",
        "              ev_status = 'E'. ev_code = 'METHOD_INVALID'.",
        "              ev_message = 'Method source structure unavailable'.",
        "              ev_version = '2.5'. RETURN.",
        "            ENDIF.",
        "            APPEND lv_payload_value TO <lt_classic_source>.",
        "          WHEN OTHERS.",
        "            ev_status = 'E'. ev_code = 'PAYLOAD_INVALID'.",
        "            ev_message = 'Unexpected Classic BAdI payload row'.",
        "            ev_version = '2.5'. RETURN.",
        "        ENDCASE.",
        "      ENDLOOP.",
        "      IF lv_classic_action <> iv_object_type.",
        "        ev_status = 'E'. ev_code = 'ACTION_CONFLICT'.",
        "        ev_message = 'Classic BAdI action payload conflicts'.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      ls_classic_impl-imp_name = iv_object_name.",
        "      CLEAR ls_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'SXCI'",
        "          AND obj_name = iv_object_name.",
        "      IF iv_object_type = 'CREATE'.",
        "        IF sy-subrc = 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'CLASSIC_BADI_IMPLEMENTATION_EXISTS'.",
        "          ev_message = 'Classic BAdI implementation exists'.",
        "          ev_version = '2.5'. RETURN.",
        "        ENDIF.",
        "        IF ls_classic_impl-exit_name IS INITIAL",
        "           OR ls_classic_impl-inter_name IS INITIAL",
        "           OR ls_classic_impl-imp_class IS INITIAL.",
        "          ev_status = 'E'.",
        "          ev_code = 'CLASSIC_BADI_CREATE_INPUT_REQUIRED'.",
        "          ev_message = 'Definition interface and class required'.",
        "          ev_version = '2.5'. RETURN.",
        "        ENDIF.",
        "      ELSE.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'CLASSIC_BADI_IMPLEMENTATION_NOT_FOUND'.",
        "          ev_message = 'Classic BAdI implementation not found'.",
        "          ev_version = '2.5'. RETURN.",
        "        ENDIF.",
        "        IF ls_tadir-devclass <> iv_package.",
        "          ev_status = 'E'. ev_code = 'PACKAGE_CONFLICT'.",
        "          ev_message = 'Implementation belongs to another package'.",
        "          ev_version = '2.5'. RETURN.",
        "        ENDIF.",
        "      ENDIF.",
        "      lv_classic_language = sy-langu.",
        "      IF iv_object_type = 'CREATE'.",
        "        CALL FUNCTION 'SXO_IMPL_CREATE'",
        "          EXPORTING impl = ls_classic_impl active = 'X'",
        "          CHANGING mast_langu = lv_classic_language",
        "            filters = lt_classic_filters",
        "            korrnum = lv_enh_trkorr",
        "            devclass = lv_enh_devclass",
        "            method_implements = lt_classic_methods",
        "          EXCEPTIONS OTHERS = 1.",
        "      ELSEIF iv_object_type = 'ACTIVATE'.",
        "        CALL FUNCTION 'SXO_IMPL_ACTIVE'",
        "          EXPORTING imp_name = iv_object_name no_dialog = 'X'",
        "          CHANGING protocol = lt_classic_protocol",
        "          EXCEPTIONS OTHERS = 1.",
        "      ELSEIF iv_object_type = 'DEACTIVATE'.",
        "        CALL FUNCTION 'SXO_IMPL_DACTVE'",
        "          EXPORTING imp_name = iv_object_name no_dialog = 'X'",
        "          CHANGING protocol = lt_classic_protocol",
        "          EXCEPTIONS OTHERS = 1.",
        "      ELSE.",
        "        CALL FUNCTION 'SXO_IMPL_DELETE'",
        "          EXPORTING imp_name = iv_object_name no_dialog = 'X'",
        "          CHANGING korr_num = lv_enh_trkorr",
        "          EXCEPTIONS OTHERS = 1.",
        "      ENDIF.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'CLASSIC_BADI_CHANGE_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '2.5'. RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      REFRESH it_source.",
        "      ev_status = 'S'.",
        "      ev_code = 'CLASSIC_BADI_IMPLEMENTATION_CHANGED'.",
        "      ev_message = 'Classic BAdI implementation changed'.",
        "      ev_version = '2.5'. RETURN.",
        "    WHEN 'READ_CLASSIC_BADI_DEFINITION'.",
        "      IF iv_object_name IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'CLASSIC_BADI_DEFINITION_REQUIRED'.",
        "        ev_message = 'Exact Classic BAdI definition name required'.",
        "        ev_version = '2.4'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_sxs_attr, ls_sxs_attrt,",
        "        lv_badi_implementation, lv_badi_assignment_index,",
        "        lv_badi_class_index.",
        "      REFRESH: lt_sxs_inter, lt_sxc_exit, it_source.",
        "      SELECT SINGLE * FROM sxs_attr INTO ls_sxs_attr",
        "        WHERE exit_name = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'CLASSIC_BADI_DEFINITION_NOT_FOUND'.",
        "        ev_message = 'Classic BAdI definition does not exist'.",
        "        ev_version = '2.4'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM sxs_attrt INTO ls_sxs_attrt",
        "        WHERE exit_name = iv_object_name",
        "          AND sprsl = sy-langu.",
        "      SELECT * FROM sxs_inter INTO TABLE lt_sxs_inter",
        "        WHERE exit_name = iv_object_name.",
        "      SORT lt_sxs_inter BY inter_name.",
        "      SELECT * FROM sxc_exit INTO TABLE lt_sxc_exit",
        "        WHERE exit_name = iv_object_name.",
        "      SORT lt_sxc_exit BY imp_name flt_val.",
        "      add_repo_payload 'M' '1' 'NAME' iv_object_name.",
        "      add_repo_alias 'M' '1' 'DESCRIPTION' 'TEXT'",
        "        ls_sxs_attrt.",
        "      add_repo_alias 'M' '1' 'VERSION' 'VERSION'",
        "        ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'FILTER_TYPE' 'FLT_TYPE'",
        "        ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'FILTER_EXTENSION' 'FLT_EXT'",
        "        ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'MULTIPLE_USE' 'MLTP_USE'",
        "        ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'PACKAGE' 'DEVCLASS'",
        "        ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'MASTER_LANGUAGE' 'MST_LANG'",
        "        ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'DEFAULT_CLASS' 'DEF_CLNAME'",
        "        ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'EXAMPLE_CLASS' 'EXM_CLNAME'",
        "        ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'CHECK_CLASS' 'COC_CLNAME'",
        "        ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'INTERNAL' 'INTERNAL'",
        "        ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'MIGRATION_ENHANCEMENT_SPOT'",
        "        'MIG_ENHSPOTNAME' ls_sxs_attr.",
        "      add_repo_alias 'M' '1' 'MIGRATION_BADI_NAME'",
        "        'MIG_BADI_NAME' ls_sxs_attr.",
        "      LOOP AT lt_sxs_inter INTO ls_sxs_inter.",
        "        lv_payload_index = sy-tabix.",
        "        add_repo_alias 'I' lv_payload_index 'INTERFACE_NAME'",
        "          'INTER_NAME' ls_sxs_inter.",
        "      ENDLOOP.",
        "      LOOP AT lt_sxc_exit INTO ls_sxc_exit.",
        "        ADD 1 TO lv_badi_assignment_index.",
        "        lv_payload_index = lv_badi_assignment_index.",
        "        IF lv_badi_implementation <> ls_sxc_exit-imp_name.",
        "          lv_badi_implementation = ls_sxc_exit-imp_name.",
        "          CLEAR: ls_sxc_attr, ls_sxc_attrt.",
        "          SELECT SINGLE * FROM sxc_attr INTO ls_sxc_attr",
        "            WHERE imp_name = lv_badi_implementation.",
        "          SELECT SINGLE * FROM sxc_attrt INTO ls_sxc_attrt",
        "            WHERE imp_name = lv_badi_implementation",
        "              AND sprsl = sy-langu.",
        "          REFRESH lt_sxc_class.",
        "          SELECT * FROM sxc_class INTO TABLE lt_sxc_class",
        "            WHERE imp_name = lv_badi_implementation.",
        "          SORT lt_sxc_class BY inter_name imp_class.",
        "          CLEAR ls_tadir.",
        "          SELECT SINGLE * FROM tadir INTO ls_tadir",
        "            WHERE pgmid = 'R3TR' AND object = 'SXCI'",
        "              AND obj_name = lv_badi_implementation.",
        "          LOOP AT lt_sxc_class INTO ls_sxc_class.",
        "            ADD 1 TO lv_badi_class_index.",
        "            add_repo_alias 'C' lv_badi_class_index",
        "              'IMPLEMENTATION_NAME' 'IMP_NAME' ls_sxc_class.",
        "            add_repo_alias 'C' lv_badi_class_index",
        "              'INTERFACE_NAME' 'INTER_NAME' ls_sxc_class.",
        "            add_repo_alias 'C' lv_badi_class_index",
        "              'IMPLEMENTATION_CLASS' 'IMP_CLASS' ls_sxc_class.",
        "          ENDLOOP.",
        "        ENDIF.",
        "        add_repo_alias 'A' lv_payload_index",
        "          'IMPLEMENTATION_NAME' 'IMP_NAME' ls_sxc_exit.",
        "        add_repo_alias 'A' lv_payload_index 'FILTER_VALUE'",
        "          'FLT_VAL' ls_sxc_exit.",
        "        add_repo_alias 'A' lv_payload_index 'ACTIVE' 'ACTIVE'",
        "          ls_sxc_attr.",
        "        add_repo_alias 'A' lv_payload_index 'DESCRIPTION' 'TEXT'",
        "          ls_sxc_attrt.",
        "        add_repo_alias 'A' lv_payload_index 'VERSION' 'VERSION'",
        "          ls_sxc_attr.",
        "        add_repo_alias 'A' lv_payload_index 'MASTER_LANGUAGE'",
        "          'MST_LANG' ls_sxc_attr.",
        "        add_repo_alias 'A' lv_payload_index 'LAYER' 'LAYER'",
        "          ls_sxc_attr.",
        "        add_repo_payload 'A' lv_payload_index 'PACKAGE'",
        "          ls_tadir-devclass.",
        "        add_repo_alias 'A' lv_payload_index",
        "          'MIGRATION_ENHANCEMENT' 'MIG_ENHNAME' ls_sxc_attr.",
        "      ENDLOOP.",
        "      ev_status = 'S'.",
        "      ev_code = 'CLASSIC_BADI_DEFINITION_READ'.",
        "      ev_message = 'Classic BAdI definition and implementations read'.",
        "      ev_version = '2.4'.",
        "      RETURN.",
        "    WHEN 'READ_BTE_CONFIGURATION'.",
        "      IF iv_object_name IS INITIAL",
        "         OR ( iv_object_type <> 'E' AND iv_object_type <> 'P' ).",
        "        ev_status = 'E'.",
        "        ev_code = 'BTE_CONFIGURATION_INPUT_REQUIRED'.",
        "        ev_message = 'Exact BTE identifier and kind required'.",
        "        ev_version = '2.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_tbe31, lt_tbe34, lt_tps31, lt_tps34, it_source.",
        "      CLEAR: lv_tbe01_event, ls_tbe01t, ls_tps01, ls_tps01t.",
        "      IF iv_object_type = 'E'.",
        "        SELECT SINGLE event FROM tbe01 INTO lv_tbe01_event",
        "          WHERE event = iv_object_name.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'BTE_DEFINITION_NOT_FOUND'.",
        "          ev_message = 'BTE Event definition does not exist'.",
        "          ev_version = '2.3'.",
        "          RETURN.",
        "        ENDIF.",
        "        SELECT SINGLE text1 FROM tbe01t INTO ls_tbe01t-text1",
        "          WHERE event = iv_object_name AND spras = sy-langu.",
        "        SELECT * FROM tbe31 INTO TABLE lt_tbe31",
        "          WHERE event = iv_object_name.",
        "        SELECT * FROM tbe34 INTO TABLE lt_tbe34",
        "          WHERE event = iv_object_name.",
        "        add_repo_payload 'M' '1' 'IDENTIFIER' iv_object_name.",
        "        add_repo_payload 'M' '1' 'KIND' 'E'.",
        "        add_repo_alias 'M' '1' 'DESCRIPTION' 'TEXT1' ls_tbe01t.",
        "        LOOP AT lt_tbe31 INTO ls_tbe31.",
        "          lv_payload_index = sy-tabix.",
        "          add_repo_alias 'S' lv_payload_index 'COUNTRY' 'LAND' ls_tbe31.",
        "          add_repo_alias 'S' lv_payload_index 'APPLICATION'",
        "            'APPLK' ls_tbe31.",
        "          add_repo_alias 'S' lv_payload_index 'FUNCTION_MODULE'",
        "            'FUNCT' ls_tbe31.",
        "          add_bte_application 'S' lv_payload_index ls_tbe31.",
        "        ENDLOOP.",
        "        LOOP AT lt_tbe34 INTO ls_tbe34.",
        "          lv_payload_index = sy-tabix.",
        "          add_repo_alias 'C' lv_payload_index 'COUNTRY' 'LAND' ls_tbe34.",
        "          add_repo_alias 'C' lv_payload_index 'APPLICATION'",
        "            'APPLK' ls_tbe34.",
        "          add_repo_alias 'C' lv_payload_index 'FUNCTION_MODULE'",
        "            'FUNCT' ls_tbe34.",
        "          add_repo_alias 'C' lv_payload_index 'PRODUCT'",
        "            'PRDKT' ls_tbe34.",
        "          add_bte_application 'C' lv_payload_index ls_tbe34.",
        "          add_bte_product 'C' lv_payload_index ls_tbe34.",
        "        ENDLOOP.",
        "      ELSE.",
        "        SELECT SINGLE * FROM tps01 INTO ls_tps01",
        "          WHERE procs = iv_object_name.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'BTE_DEFINITION_NOT_FOUND'.",
        "          ev_message = 'BTE Process definition does not exist'.",
        "          ev_version = '2.3'.",
        "          RETURN.",
        "        ENDIF.",
        "        SELECT SINGLE * FROM tps01t INTO ls_tps01t",
        "          WHERE procs = iv_object_name AND spras = sy-langu.",
        "        SELECT * FROM tps31 INTO TABLE lt_tps31",
        "          WHERE procs = iv_object_name.",
        "        SELECT * FROM tps34 INTO TABLE lt_tps34",
        "          WHERE procs = iv_object_name.",
        "        add_repo_payload 'M' '1' 'IDENTIFIER' iv_object_name.",
        "        add_repo_payload 'M' '1' 'KIND' 'P'.",
        "        add_repo_alias 'M' '1' 'DESCRIPTION' 'TEXT1' ls_tps01t.",
        "        LOOP AT lt_tps31 INTO ls_tps31.",
        "          lv_payload_index = sy-tabix.",
        "          add_repo_alias 'S' lv_payload_index 'COUNTRY' 'LAND' ls_tps31.",
        "          add_repo_alias 'S' lv_payload_index 'APPLICATION'",
        "            'APPLK' ls_tps31.",
        "          add_repo_alias 'S' lv_payload_index 'FUNCTION_MODULE'",
        "            'FUNCT' ls_tps31.",
        "          add_bte_application 'S' lv_payload_index ls_tps31.",
        "        ENDLOOP.",
        "        LOOP AT lt_tps34 INTO ls_tps34.",
        "          lv_payload_index = sy-tabix.",
        "          add_repo_alias 'C' lv_payload_index 'COUNTRY' 'LAND' ls_tps34.",
        "          add_repo_alias 'C' lv_payload_index 'APPLICATION'",
        "            'APPLK' ls_tps34.",
        "          add_repo_alias 'C' lv_payload_index 'FUNCTION_MODULE'",
        "            'FUNCT' ls_tps34.",
        "          add_repo_alias 'C' lv_payload_index 'PRODUCT'",
        "            'PRDKT' ls_tps34.",
        "          add_bte_application 'C' lv_payload_index ls_tps34.",
        "          add_bte_product 'C' lv_payload_index ls_tps34.",
        "        ENDLOOP.",
        "      ENDIF.",
        "      ev_status = 'S'.",
        "      ev_code = 'BTE_CONFIGURATION_READ'.",
        "      ev_message = 'BTE definition and configured handlers read'.",
        "      ev_version = '2.3'.",
        "      RETURN.",
        "    WHEN 'READ_CUSTOMER_EXIT_DEFINITION'.",
        "      IF iv_object_name IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'CUSTOMER_EXIT_DEFINITION_REQUIRED'.",
        "        ev_message = 'Exact SMOD enhancement name is required'.",
        "        ev_version = '2.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT * FROM modsap INTO TABLE lt_modsap",
        "        WHERE name = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'CUSTOMER_EXIT_DEFINITION_NOT_FOUND'.",
        "        ev_message = 'SMOD enhancement definition does not exist'.",
        "        ev_version = '2.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM modsapt INTO ls_modsapt",
        "        WHERE name = iv_object_name AND sprsl = sy-langu.",
        "      SORT lt_modsap BY typ member.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'NAME' iv_object_name.",
        "      add_repo_payload 'M' '1' 'DESCRIPTION'",
        "        ls_modsapt-modtext.",
        "      LOOP AT lt_modsap INTO ls_modsap.",
        "        lv_payload_index = sy-tabix.",
        "        add_repo_payload 'C' lv_payload_index 'TYPE'",
        "          ls_modsap-typ.",
        "        add_repo_payload 'C' lv_payload_index 'MEMBER'",
        "          ls_modsap-member.",
        "      ENDLOOP.",
        "      ev_status = 'S'.",
        "      ev_code = 'CUSTOMER_EXIT_DEFINITION_READ'.",
        "      ev_message = 'SMOD enhancement definition read'.",
        "      ev_version = '2.2'.",
        "      RETURN.",
        "    WHEN 'READ_CUSTOMER_EXIT_PROJECT'.",
        "      IF iv_object_name IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'CUSTOMER_EXIT_PROJECT_REQUIRED'.",
        "        ev_message = 'Exact CMOD project name is required'.",
        "        ev_version = '2.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM modattr INTO ls_modattr",
        "        WHERE name = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'CUSTOMER_EXIT_PROJECT_NOT_FOUND'.",
        "        ev_message = 'CMOD enhancement project does not exist'.",
        "        ev_version = '2.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT * FROM modact INTO TABLE lt_modact",
        "        WHERE name = iv_object_name AND typ = space.",
        "      SORT lt_modact BY member.",
        "      CLEAR ls_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'CMOD'",
        "          AND obj_name = iv_object_name.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'NAME' ls_modattr-name.",
        "      add_repo_payload 'M' '1' 'STATUS' ls_modattr-status.",
        "      add_repo_payload 'M' '1' 'CHANGED_BY' ls_modattr-anam.",
        "      add_repo_payload 'M' '1' 'CHANGED_ON' ls_modattr-adat.",
        "      add_repo_payload 'M' '1' 'PACKAGE' ls_tadir-devclass.",
        "      LOOP AT lt_modact INTO ls_modact.",
        "        lv_payload_index = sy-tabix.",
        "        add_repo_payload 'A' lv_payload_index 'TYPE'",
        "          ls_modact-typ.",
        "        add_repo_payload 'A' lv_payload_index 'MEMBER'",
        "          ls_modact-member.",
        "      ENDLOOP.",
        "      ev_status = 'S'.",
        "      ev_code = 'CUSTOMER_EXIT_PROJECT_READ'.",
        "      ev_message = 'CMOD enhancement project read'.",
        "      ev_version = '2.2'.",
        "      RETURN.",
        "    WHEN 'CREATE_FUNCTION_GROUP'.",
        "      IF iv_package IS INITIAL OR iv_package = '`$TMP'",
        "         OR iv_request IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_GROUP_INPUT_REQUIRED'.",
        "        ev_message = 'Transportable package request required'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tdevc INTO ls_package",
        "        WHERE devclass = iv_package.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'PACKAGE_NOT_FOUND'.",
        "        ev_message = 'Transportable package does not exist'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc = 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_GROUP_EXISTS'.",
        "        ev_message = 'Function group already exists'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_request, ls_task.",
        "      SELECT SINGLE * FROM e070 INTO ls_request",
        "        WHERE trkorr = iv_request.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_FOUND'.",
        "        ev_message = 'Transport request or task does not exist'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF ls_request-strkorr IS NOT INITIAL.",
        "        ls_task = ls_request.",
        "        SELECT SINGLE * FROM e070 INTO ls_request",
        "          WHERE trkorr = ls_task-strkorr.",
        "      ELSE.",
        "        SELECT SINGLE * FROM e070 INTO ls_task",
        "          WHERE strkorr = ls_request-trkorr",
        "            AND as4user = sy-uname AND trstatus = 'D'.",
        "      ENDIF.",
        "      IF ls_request-trfunction <> 'K'",
        "         OR ls_request-trstatus <> 'D'",
        "         OR ls_task-trstatus <> 'D'",
        "         OR ls_task-as4user <> sy-uname.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_MODIFIABLE'.",
        "        ev_message = 'Open workbench task for user is required'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      lv_function_pool = iv_object_name.",
        "      lv_short_text = iv_description.",
        "      lv_recorded_request = ls_task-trkorr.",
        "      CLEAR lv_group_corrnum.",
        "      CALL FUNCTION 'RS_FUNCTION_POOL_INSERT'",
        "        EXPORTING function_pool = lv_function_pool",
        "          short_text = lv_short_text",
        "          responsible = sy-uname",
        "          devclass = iv_package",
        "          corrnum = lv_recorded_request",
        "          suppress_corr_check = space",
        "        IMPORTING corrnum = lv_group_corrnum",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc <> 0.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ROLLBACK WORK.",
        "        SELECT SINGLE * FROM tadir INTO ls_tadir",
        "          WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "            AND obj_name = iv_object_name.",
        "        ev_status = 'E'.",
        "        IF sy-subrc = 0.",
        "          ev_code = 'CREATE_PARTIAL'.",
        "          ev_message = 'Function group exists after failure'.",
        "        ELSE.",
        "          ev_code = 'FUNCTION_GROUP_CREATE_FAILED'.",
        "        ENDIF.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "          AND obj_name = iv_object_name",
        "          AND devclass = iv_package.",
        "      SELECT SINGLE * FROM tlibg INTO ls_tlibg",
        "        WHERE area = iv_object_name.",
        "      CONCATENATE 'SAPL' iv_object_name",
        "        INTO lv_group_program.",
        "      SELECT SINGLE * FROM trdir INTO ls_trdir",
        "        WHERE name = lv_group_program.",
        "      IF ls_tadir-obj_name IS INITIAL",
        "         OR ls_tlibg-area IS INITIAL",
        "         OR ls_trdir-name IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'CREATE_PARTIAL'.",
        "        ev_message = 'Function group verification failed'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR ls_e071.",
        "      SELECT SINGLE * FROM e071 INTO ls_e071",
        "        WHERE trkorr = ls_task-trkorr",
        "          AND pgmid = 'R3TR' AND object = 'FUGR'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'CREATE_PARTIAL'.",
        "        ev_message = 'Function group transport missing'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'PACKAGE' iv_package.",
        "      add_repo_payload 'M' '1' 'REQUEST'",
        "        ls_request-trkorr.",
        "      add_repo_payload 'M' '1' 'TASK' ls_task-trkorr.",
        "      add_repo_payload 'M' '1' 'ACTIVE' 'X'.",
        "      add_repo_payload 'M' '1' 'GENERATED' 'X'.",
        "      ev_status = 'S'.",
        "      ev_code = 'FUNCTION_GROUP_CREATED'.",
        "      ev_message = 'Function group created and verified'.",
        "      ev_version = '1.3'.",
        "      RETURN.",
        "    WHEN 'CREATE_FUNCTION_INCLUDE'.",
        "      IF iv_package IS INITIAL OR iv_package = '`$TMP'",
        "         OR iv_request IS INITIAL OR it_source[] IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_INCLUDE_INPUT_REQUIRED'.",
        "        ev_message = 'Package request and source are required'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      CONCATENATE 'L' iv_program '*' INTO lv_group_program.",
        "      IF iv_object_name NP lv_group_program.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_INCLUDE_NAME_INVALID'.",
        "        ev_message = 'Include must belong to the function group'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "          AND obj_name = iv_program",
        "          AND devclass = iv_package.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_GROUP_NOT_FOUND'.",
        "        ev_message = 'Parent function group package mismatch'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM trdir INTO ls_trdir",
        "        WHERE name = iv_object_name.",
        "      IF sy-subrc = 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_INCLUDE_EXISTS'.",
        "        ev_message = 'Function group Include already exists'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_request, ls_task.",
        "      SELECT SINGLE * FROM e070 INTO ls_request",
        "        WHERE trkorr = iv_request.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_FOUND'.",
        "        ev_message = 'Transport request or task does not exist'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF ls_request-strkorr IS NOT INITIAL.",
        "        ls_task = ls_request.",
        "        SELECT SINGLE * FROM e070 INTO ls_request",
        "          WHERE trkorr = ls_task-strkorr.",
        "      ELSE.",
        "        SELECT SINGLE * FROM e070 INTO ls_task",
        "          WHERE strkorr = ls_request-trkorr",
        "            AND as4user = sy-uname AND trstatus = 'D'.",
        "      ENDIF.",
        "      IF ls_request-trfunction <> 'K'",
        "         OR ls_request-trstatus <> 'D'",
        "         OR ls_task-trstatus <> 'D'",
        "         OR ls_task-as4user <> sy-uname.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_MODIFIABLE'.",
        "        ev_message = 'Open workbench task for user is required'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR ls_e071.",
        "      SELECT SINGLE * FROM e071 INTO ls_e071",
        "        WHERE trkorr = ls_task-trkorr",
        "          AND pgmid = 'R3TR' AND object = 'FUGR'",
        "          AND obj_name = iv_program.",
        "      IF sy-subrc <> 0.",
        "        SELECT SINGLE * FROM e071 INTO ls_e071",
        "          WHERE trkorr = ls_request-trkorr",
        "            AND pgmid = 'R3TR' AND object = 'FUGR'",
        "            AND obj_name = iv_program.",
        "      ENDIF.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_GROUP_TRANSPORT_MISMATCH'.",
        "        ev_message = 'Parent function group is not in the request'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      INSERT REPORT iv_object_name FROM it_source",
        "        PROGRAM TYPE 'I'.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_INCLUDE_CREATE_FAILED'.",
        "        ev_message = 'Function group Include source write failed'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      SELECT SINGLE * FROM trdir INTO ls_trdir",
        "        WHERE name = iv_object_name AND subc = 'I'.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_INCLUDE_VERIFY_FAILED'.",
        "        ev_message = 'Created Include metadata is inconsistent'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'PACKAGE' iv_package.",
        "      add_repo_payload 'M' '1' 'REQUEST' ls_task-trkorr.",
        "      add_repo_payload 'M' '1' 'PARENT' iv_program.",
        "      ev_status = 'S'.",
        "      ev_code = 'FUNCTION_INCLUDE_CREATED'.",
        "      ev_message = 'Function group Include created and verified'.",
        "      ev_version = '1.7'.",
        "      RETURN.",
        "    WHEN 'READ_FUNCTION_INTERFACE'.",
        "      lv_function_name = iv_object_name.",
        "      REFRESH lt_fm_long_source.",
        "      REFRESH: lt_fm_import, lt_fm_export,",
        "        lt_fm_changing, lt_fm_tables,",
        "        lt_fm_exceptions, lt_fm_documentation,",
        "        lt_fm_source.",
        "      CLEAR: lv_global_flag, lv_remote_call,",
        "        lv_update_task, lv_short_text, lv_function_pool.",
        "      CALL FUNCTION 'RPY_FUNCTIONMODULE_READ_NEW'",
        "        EXPORTING functionname = lv_function_name",
        "        IMPORTING global_flag = lv_global_flag",
        "          remote_call = lv_remote_call",
        "          update_task = lv_update_task",
        "          short_text = lv_short_text",
        "          function_pool = lv_function_pool",
        "        TABLES import_parameter = lt_fm_import",
        "          changing_parameter = lt_fm_changing",
        "          export_parameter = lt_fm_export",
        "          tables_parameter = lt_fm_tables",
        "          exception_list = lt_fm_exceptions",
        "          documentation = lt_fm_documentation",
        "          source = lt_fm_source",
        "        CHANGING new_source = lt_fm_long_source",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_READ_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF lt_fm_long_source[] IS NOT INITIAL.",
        "        IF iv_object_type <> 'SRC1'.",
        "          ev_status = 'E'.",
        "          ev_code = 'SOURCE_CLIENT_UPGRADE_REQUIRED'.",
        "          ev_message = 'Long source requires SRC1 client'.",
        "          ev_version = '2.1'. RETURN.",
        "        ENDIF.",
        "        LOOP AT lt_fm_long_source INTO lv_fm_long_line.",
        "          IF strlen( lv_fm_long_line ) > 255.",
        "            ev_status = 'E'.",
        "            ev_code = 'SOURCE_LINE_TOO_LONG'.",
        "            ev_message = 'Source line exceeds 255 characters'.",
        "            ev_version = '2.1'. RETURN.",
        "          ENDIF.",
        "        ENDLOOP.",
        "* The short-source table may contain only a partial read.",
        "        REFRESH lt_fm_source.",
        "      ENDIF.",
        "      emit_fm_payload.",
        "      IF lt_fm_long_source[] IS NOT INITIAL.",
        "        add_repo_payload 'M' '1' 'SOURCE_FORMAT' 'CHUNKS_V1'.",
        "        lv_fm_source_length = lines( lt_fm_long_source ).",
        "        add_repo_payload 'M' '1' 'SOURCE_LINES'",
        "          lv_fm_source_length.",
        "        LOOP AT lt_fm_long_source INTO lv_fm_long_line.",
        "          lv_payload_index = sy-tabix.",
        "          lv_fm_source_length = strlen( lv_fm_long_line ).",
        "          add_repo_payload 'S' lv_payload_index 'LENGTH'",
        "            lv_fm_source_length.",
        "          CLEAR: lv_fm_source_offset, lv_fm_chunk_number.",
        "          WHILE lv_fm_source_offset < lv_fm_source_length.",
        "            lv_fm_chunk_length = lv_fm_source_length -",
        "              lv_fm_source_offset.",
        "            IF lv_fm_chunk_length > 60.",
        "              lv_fm_chunk_length = 60.",
        "            ENDIF.",
        "            ADD 1 TO lv_fm_chunk_number.",
        "            lv_fm_chunk_number_text = lv_fm_chunk_number.",
        "            CONDENSE lv_fm_chunk_number_text NO-GAPS.",
        "            CONCATENATE 'PART' lv_fm_chunk_number_text",
        "              INTO lv_fm_chunk_property.",
        "            lv_fm_source_chunk =",
        "              lv_fm_long_line+lv_fm_source_offset(lv_fm_chunk_length).",
        "            add_repo_payload 'S' lv_payload_index",
        "              lv_fm_chunk_property lv_fm_source_chunk.",
        "            ADD lv_fm_chunk_length TO lv_fm_source_offset.",
        "          ENDWHILE.",
        "        ENDLOOP.",
        "      ENDIF.",
        "      ev_status = 'S'.",
        "      ev_code = 'FUNCTION_INTERFACE_READ'.",
        "      ev_message = 'Function interface read successfully'.",
        "      ev_version = '2.1'.",
        "      RETURN.",
        "    WHEN 'CREATE_FUNCTION_MODULE'.",
        "      lv_function_name = iv_object_name.",
        "      IF iv_object_name IS INITIAL",
        "         OR ( iv_object_name(1) <> 'Z'",
        "         AND iv_object_name(1) <> 'Y' )",
        "         OR iv_program IS INITIAL",
        "         OR ( iv_program(1) <> 'Z'",
        "         AND iv_program(1) <> 'Y' )",
        "         OR iv_package IS INITIAL OR iv_package = '`$TMP'",
        "         OR iv_request IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_CREATE_INPUT_REQUIRED'.",
        "        ev_message = 'Customer function group package request required'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tdevc INTO ls_package",
        "        WHERE devclass = iv_package.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'PACKAGE_NOT_FOUND'.",
        "        ev_message = 'Transportable package does not exist'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "          AND obj_name = iv_program",
        "          AND devclass = iv_package.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_GROUP_PACKAGE_MISMATCH'.",
        "        ev_message = 'Function group package does not match'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_request, ls_task.",
        "      SELECT SINGLE * FROM e070 INTO ls_request",
        "        WHERE trkorr = iv_request.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_FOUND'.",
        "        ev_message = 'Transport request or task does not exist'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF ls_request-strkorr IS NOT INITIAL.",
        "        ls_task = ls_request.",
        "        SELECT SINGLE * FROM e070 INTO ls_request",
        "          WHERE trkorr = ls_task-strkorr.",
        "      ELSE.",
        "        SELECT SINGLE * FROM e070 INTO ls_task",
        "          WHERE strkorr = ls_request-trkorr",
        "            AND as4user = sy-uname AND trstatus = 'D'.",
        "      ENDIF.",
        "      IF ls_request-trfunction <> 'K'",
        "         OR ls_request-trstatus <> 'D'",
        "         OR ls_task-trstatus <> 'D'",
        "         OR ls_task-as4user <> sy-uname.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_MODIFIABLE'.",
        "        ev_message = 'Open workbench task for user is required'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tfdir INTO ls_tfdir",
        "        WHERE funcname = iv_object_name.",
        "      IF sy-subrc = 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_EXISTS'.",
        "        ev_message = 'Function module already exists'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_fm_import, lt_fm_export,",
        "        lt_fm_changing, lt_fm_tables,",
        "        lt_fm_exceptions, lt_fm_documentation,",
        "        lt_fm_source.",
        "      LOOP AT it_source INTO ls_source.",
        "        CLEAR: lv_payload_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_payload_kind",
        "          lv_payload_index_text lv_payload_property",
        "          lv_payload_value.",
        "        IF lv_payload_index_text IS INITIAL",
        "           OR lv_payload_index_text CN '0123456789'.",
        "          ev_status = 'E'.",
        "          ev_code = 'FUNCTION_PAYLOAD_INVALID'.",
        "          ev_message = 'Function payload index is invalid'.",
        "          ev_version = '1.3'.",
        "          RETURN.",
        "        ENDIF.",
        "        lv_payload_index = lv_payload_index_text.",
        "        REPLACE ALL OCCURRENCES OF '%7C'",
        "          IN lv_payload_value WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25'",
        "          IN lv_payload_value WITH '%'.",
        "        IF lv_payload_property = 'PASSVALUE'",
        "           AND lv_payload_kind <> 'T'.",
        "          lv_payload_property = 'REFERENCE'.",
        "          IF lv_payload_value = 'X'.",
        "            CLEAR lv_payload_value.",
        "          ELSE.",
        "            lv_payload_value = 'X'.",
        "          ENDIF.",
        "        ENDIF.",
        "        IF lv_payload_index <= 0",
        "           OR lv_payload_property IS INITIAL.",
        "          ev_status = 'E'.",
        "          ev_code = 'FUNCTION_PAYLOAD_INVALID'.",
        "          ev_message = 'Serialized function payload is invalid'.",
        "          ev_version = '1.3'.",
        "          RETURN.",
        "        ENDIF.",
        "        IF lv_payload_property = 'TEXT'",
        "           AND lv_payload_kind CA 'IECT'.",
        "          CLEAR ls_fm_documentation.",
        "          CASE lv_payload_kind.",
        "            WHEN 'I'.",
        "              READ TABLE lt_fm_import INTO ls_fm_import",
        "                INDEX lv_payload_index.",
        "              ls_fm_documentation-parameter =",
        "                ls_fm_import-parameter.",
        "            WHEN 'E'.",
        "              READ TABLE lt_fm_export INTO ls_fm_export",
        "                INDEX lv_payload_index.",
        "              ls_fm_documentation-parameter =",
        "                ls_fm_export-parameter.",
        "            WHEN 'C'.",
        "              READ TABLE lt_fm_changing INTO ls_fm_changing",
        "                INDEX lv_payload_index.",
        "              ls_fm_documentation-parameter =",
        "                ls_fm_changing-parameter.",
        "            WHEN 'T'.",
        "              READ TABLE lt_fm_tables INTO ls_fm_table",
        "                INDEX lv_payload_index.",
        "              ls_fm_documentation-parameter =",
        "                ls_fm_table-parameter.",
        "          ENDCASE.",
        "          IF sy-subrc <> 0",
        "             OR ls_fm_documentation-parameter IS INITIAL.",
        "            ev_status = 'E'.",
        "            ev_code = 'FUNCTION_PAYLOAD_INVALID'.",
        "            ev_message = 'Parameter text precedes its name'.",
        "            ev_version = '2.0'.",
        "            RETURN.",
        "          ENDIF.",
        "          ls_fm_documentation-kind = 'P'.",
        "          ls_fm_documentation-stext = lv_payload_value.",
        "          ls_fm_documentation-index = lv_payload_index.",
        "          APPEND ls_fm_documentation",
        "            TO lt_fm_documentation.",
        "          CONTINUE.",
        "        ENDIF.",
        "        CASE lv_payload_kind.",
        "          WHEN 'I'.",
        "            WHILE lines( lt_fm_import ) < lv_payload_index.",
        "              CLEAR ls_fm_import.",
        "              APPEND ls_fm_import TO lt_fm_import.",
        "            ENDWHILE.",
        "            READ TABLE lt_fm_import ASSIGNING <ls_fm_import>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_fm_import>",
        "              TO <lv_payload_component>.",
        "          WHEN 'E'.",
        "            WHILE lines( lt_fm_export ) < lv_payload_index.",
        "              CLEAR ls_fm_export.",
        "              APPEND ls_fm_export TO lt_fm_export.",
        "            ENDWHILE.",
        "            READ TABLE lt_fm_export ASSIGNING <ls_fm_export>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_fm_export>",
        "              TO <lv_payload_component>.",
        "          WHEN 'C'.",
        "            WHILE lines( lt_fm_changing ) < lv_payload_index.",
        "              CLEAR ls_fm_changing.",
        "              APPEND ls_fm_changing TO lt_fm_changing.",
        "            ENDWHILE.",
        "            READ TABLE lt_fm_changing",
        "              ASSIGNING <ls_fm_changing>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_fm_changing>",
        "              TO <lv_payload_component>.",
        "          WHEN 'T'.",
        "            WHILE lines( lt_fm_tables ) < lv_payload_index.",
        "              CLEAR ls_fm_table.",
        "              APPEND ls_fm_table TO lt_fm_tables.",
        "            ENDWHILE.",
        "            READ TABLE lt_fm_tables ASSIGNING <ls_fm_table>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_fm_table>",
        "              TO <lv_payload_component>.",
        "          WHEN 'X'.",
        "            WHILE lines( lt_fm_exceptions )",
        "              < lv_payload_index.",
        "              CLEAR ls_fm_exception.",
        "              APPEND ls_fm_exception TO lt_fm_exceptions.",
        "            ENDWHILE.",
        "            READ TABLE lt_fm_exceptions",
        "              ASSIGNING <ls_fm_exception>",
        "              INDEX lv_payload_index.",
        "            IF lv_payload_property = 'TEXT'.",
        "              CLEAR ls_fm_documentation.",
        "              ls_fm_documentation-parameter =",
        "                <ls_fm_exception>-exception.",
        "              ls_fm_documentation-kind = 'X'.",
        "              ls_fm_documentation-stext = lv_payload_value.",
        "              ls_fm_documentation-index = lv_payload_index.",
        "              APPEND ls_fm_documentation",
        "                TO lt_fm_documentation.",
        "              CONTINUE.",
        "            ENDIF.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_fm_exception>",
        "              TO <lv_payload_component>.",
        "          WHEN 'S'.",
        "            IF lv_payload_property <> 'LINE'.",
        "              ev_status = 'E'.",
        "              ev_code = 'FUNCTION_PROPERTY_INVALID'.",
        "              ev_message = 'Unknown source payload property'.",
        "              ev_version = '1.3'.",
        "              RETURN.",
        "            ENDIF.",
        "            CLEAR ls_fm_source.",
        "            ls_fm_source-line = lv_payload_value.",
        "            APPEND ls_fm_source TO lt_fm_source.",
        "            CONTINUE.",
        "          WHEN OTHERS.",
        "            ev_status = 'E'.",
        "            ev_code = 'FUNCTION_PAYLOAD_INVALID'.",
        "            ev_message = 'Unknown function payload row type'.",
        "            ev_version = '1.3'.",
        "            RETURN.",
        "        ENDCASE.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'FUNCTION_PROPERTY_INVALID'.",
        "          ev_message = 'Unknown function payload property'.",
        "          ev_version = '1.3'.",
        "          RETURN.",
        "        ENDIF.",
        "        <lv_payload_component> = lv_payload_value.",
        "      ENDLOOP.",
        "      IF lt_fm_source[] IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_SOURCE_REQUIRED'.",
        "        ev_message = 'Function source is required'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      lv_function_pool = iv_program.",
        "      lv_short_text = iv_description.",
        "      lv_remote_call = iv_object_type.",
        "      CALL FUNCTION 'RPY_FUNCTIONMODULE_INSERT'",
        "        EXPORTING funcname = lv_function_name",
        "          function_pool = lv_function_pool",
        "          remote_call = lv_remote_call",
        "          short_text = lv_short_text",
        "          corrnum = iv_request",
        "        TABLES import_parameter = lt_fm_import",
        "          changing_parameter = lt_fm_changing",
        "          export_parameter = lt_fm_export",
        "          tables_parameter = lt_fm_tables",
        "          exception_list = lt_fm_exceptions",
        "          parameter_docu = lt_fm_documentation",
        "          source = lt_fm_source",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        SELECT SINGLE * FROM tfdir INTO ls_tfdir",
        "          WHERE funcname = iv_object_name.",
        "        ev_status = 'E'.",
        "        IF sy-subrc = 0.",
        "          ev_code = 'CREATE_PARTIAL'.",
        "          ev_message = 'Function exists after failed create'.",
        "        ELSE.",
        "          ev_code = 'FUNCTION_CREATE_FAILED'.",
        "          MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "            WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "            INTO ev_message.",
        "        ENDIF.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      REFRESH: lt_fm_import, lt_fm_export,",
        "        lt_fm_changing, lt_fm_tables,",
        "        lt_fm_exceptions, lt_fm_documentation,",
        "        lt_fm_source.",
        "      CLEAR: lv_global_flag, lv_remote_call,",
        "        lv_update_task, lv_short_text, lv_function_pool.",
        "      CALL FUNCTION 'RPY_FUNCTIONMODULE_READ'",
        "        EXPORTING functionname = lv_function_name",
        "        IMPORTING global_flag = lv_global_flag",
        "          remote_call = lv_remote_call",
        "          update_task = lv_update_task",
        "          short_text = lv_short_text",
        "          function_pool = lv_function_pool",
        "        TABLES import_parameter = lt_fm_import",
        "          changing_parameter = lt_fm_changing",
        "          export_parameter = lt_fm_export",
        "          tables_parameter = lt_fm_tables",
        "          exception_list = lt_fm_exceptions",
        "          documentation = lt_fm_documentation",
        "          source = lt_fm_source",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'CREATE_PARTIAL'.",
        "        ev_message = 'Function created but re-read failed'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      emit_fm_payload.",
        "      ev_status = 'S'.",
        "      ev_code = 'FUNCTION_MODULE_CREATED'.",
        "      ev_message = 'Function created and verified'.",
        "      ev_version = '1.3'.",
        "      RETURN.",
        "    WHEN 'PATCH_FUNCTION_INTERFACE'.",
        "      lv_function_name = iv_object_name.",
        "      IF iv_object_name IS INITIAL",
        "         OR ( iv_object_name(1) <> 'Z'",
        "         AND iv_object_name(1) <> 'Y' )",
        "         OR iv_package IS INITIAL OR iv_package = '`$TMP'",
        "         OR iv_request IS INITIAL OR it_source[] IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_PATCH_INPUT_REQUIRED'.",
        "        ev_message = 'Function package and request are required'.",
        "        ev_version = '2.0'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tdevc INTO ls_package",
        "        WHERE devclass = iv_package.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'PACKAGE_NOT_FOUND'.",
        "        ev_message = 'Transportable package does not exist'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tfdir INTO ls_tfdir",
        "        WHERE funcname = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'FUNCTION_NOT_FOUND'.",
        "        ev_message = 'Function module does not exist'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      lv_function_pool = ls_tfdir-pname+4.",
        "      IF lv_function_pool IS INITIAL",
        "         OR ( lv_function_pool(1) <> 'Z'",
        "         AND lv_function_pool(1) <> 'Y' ).",
        "        ev_status = 'E'.",
        "        ev_code = 'CUSTOMER_FUNCTION_REQUIRED'.",
        "        ev_message = 'Only customer function groups are valid'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "          AND obj_name = lv_function_pool",
        "          AND devclass = iv_package.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_GROUP_PACKAGE_MISMATCH'.",
        "        ev_message = 'Function group package does not match'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_request, ls_task.",
        "      SELECT SINGLE * FROM e070 INTO ls_request",
        "        WHERE trkorr = iv_request.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'TRANSPORT_NOT_FOUND'.",
        "        ev_message = 'Transport request or task was not found'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      IF ls_request-strkorr IS NOT INITIAL.",
        "        ls_task = ls_request.",
        "        SELECT SINGLE * FROM e070 INTO ls_request",
        "          WHERE trkorr = ls_task-strkorr.",
        "      ELSE.",
        "        SELECT SINGLE * FROM e070 INTO ls_task",
        "          WHERE strkorr = ls_request-trkorr",
        "            AND as4user = sy-uname AND trstatus = 'D'.",
        "      ENDIF.",
        "      IF ls_request-trfunction <> 'K'",
        "         OR ls_request-trstatus <> 'D'",
        "         OR ls_task-trstatus <> 'D'",
        "         OR ls_task-as4user <> sy-uname.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_MODIFIABLE'.",
        "        ev_message = 'Open user workbench task is required'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      CLEAR ls_e071.",
        "      SELECT SINGLE * FROM e071 INTO ls_e071",
        "        WHERE trkorr = ls_task-trkorr",
        "          AND pgmid = 'R3TR' AND object = 'FUGR'",
        "          AND obj_name = lv_function_pool.",
        "      IF sy-subrc <> 0.",
        "        SELECT SINGLE * FROM e071 INTO ls_e071",
        "          WHERE trkorr = ls_request-trkorr",
        "            AND pgmid = 'R3TR' AND object = 'FUGR'",
        "            AND obj_name = lv_function_pool.",
        "      ENDIF.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_GROUP_TRANSPORT_MISMATCH'.",
        "        ev_message = 'Function group is not in the request'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_fm_expected_payload,",
        "        lt_fm_desired_payload, lt_fm_field.",
        "      LOOP AT it_source INTO ls_source.",
        "        IF ls_source-line(1) CA 'miectxs'.",
        "          ls_fm_expected_line = ls_source.",
        "          TRANSLATE ls_fm_expected_line-line(1)",
        "            TO UPPER CASE.",
        "          APPEND ls_fm_expected_line",
        "            TO lt_fm_expected_payload.",
        "        ELSE.",
        "          APPEND ls_source TO lt_fm_desired_payload.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      IF lt_fm_expected_payload[] IS INITIAL",
        "         OR lt_fm_desired_payload[] IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_PATCH_PAYLOAD_INVALID'.",
        "        ev_message = 'Both function snapshots are required'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      CALL FUNCTION 'ENQUEUE_ESFUNCTION'",
        "        EXPORTING funcname = lv_function_name",
        "          mode_tfdir = lv_fm_lock_mode",
        "        EXCEPTIONS foreign_lock = 1 OTHERS = 2.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'FUNCTION_LOCKED'.",
        "        ev_message = 'Function module is locked'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_fm_current_import, lt_fm_current_export,",
        "        lt_fm_current_changing, lt_fm_current_tables,",
        "        lt_fm_current_exceptions,",
        "        lt_fm_current_documentation,",
        "        lt_fm_current_source.",
        "      CLEAR: lv_global_flag, lv_remote_call, lv_update_task,",
        "        lv_short_text, lv_function_pool.",
        "      CALL FUNCTION 'RPY_FUNCTIONMODULE_READ'",
        "        EXPORTING functionname = lv_function_name",
        "        IMPORTING global_flag = lv_global_flag",
        "          remote_call = lv_remote_call",
        "          update_task = lv_update_task",
        "          short_text = lv_short_text",
        "          function_pool = lv_function_pool",
        "        TABLES import_parameter = lt_fm_current_import",
        "          changing_parameter = lt_fm_current_changing",
        "          export_parameter = lt_fm_current_export",
        "          tables_parameter = lt_fm_current_tables",
        "          exception_list = lt_fm_current_exceptions",
        "          documentation = lt_fm_current_documentation",
        "          source = lt_fm_current_source",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc <> 0.",
        "        CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "          EXPORTING funcname = lv_function_name.",
        "        ev_status = 'E'. ev_code = 'FUNCTION_READ_FAILED'.",
        "        ev_message = 'Locked function could not be read'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      lt_fm_import[] = lt_fm_current_import[].",
        "      lt_fm_export[] = lt_fm_current_export[].",
        "      lt_fm_changing[] = lt_fm_current_changing[].",
        "      lt_fm_tables[] = lt_fm_current_tables[].",
        "      lt_fm_exceptions[] = lt_fm_current_exceptions[].",
        "      lt_fm_documentation[] = lt_fm_current_documentation[].",
        "      lt_fm_source[] = lt_fm_current_source[].",
        "      REFRESH: lt_fm_import, lt_fm_export,",
        "        lt_fm_changing, lt_fm_tables, lt_fm_exceptions,",
        "        lt_fm_documentation.",
        "      LOOP AT lt_fm_desired_payload INTO ls_source.",
        "        CLEAR: lv_fm_payload_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_fm_payload_kind",
        "          lv_payload_index_text lv_payload_property",
        "          lv_payload_value.",
        "        IF lv_payload_index_text IS INITIAL",
        "           OR lv_payload_index_text CN '0123456789'.",
        "          CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "            EXPORTING funcname = lv_function_name.",
        "          ev_status = 'E'.",
        "          ev_code = 'FUNCTION_PATCH_PAYLOAD_INVALID'.",
        "          ev_message = 'Function payload index is invalid'.",
        "          ev_version = '2.0'. RETURN.",
        "        ENDIF.",
        "        lv_payload_index = lv_payload_index_text.",
        "        REPLACE ALL OCCURRENCES OF '%7C'",
        "          IN lv_payload_value WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25'",
        "          IN lv_payload_value WITH '%'.",
        "        IF lv_payload_property = 'PASSVALUE'",
        "           AND lv_fm_payload_kind <> 'T'.",
        "          lv_payload_property = 'REFERENCE'.",
        "          IF lv_payload_value = 'X'.",
        "            CLEAR lv_payload_value.",
        "          ELSE.",
        "            lv_payload_value = 'X'.",
        "          ENDIF.",
        "        ENDIF.",
        "        IF lv_payload_index <= 0",
        "           OR lv_payload_property IS INITIAL.",
        "          CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "            EXPORTING funcname = lv_function_name.",
        "          ev_status = 'E'.",
        "          ev_code = 'FUNCTION_PATCH_PAYLOAD_INVALID'.",
        "          ev_message = 'Function payload is invalid'.",
        "          ev_version = '2.0'. RETURN.",
        "        ENDIF.",
        "        IF lv_payload_property = 'TEXT'",
        "           AND lv_fm_payload_kind CA 'IECT'.",
        "          CLEAR ls_fm_documentation.",
        "          CASE lv_fm_payload_kind.",
        "            WHEN 'I'.",
        "              READ TABLE lt_fm_import INTO ls_fm_import",
        "                INDEX lv_payload_index.",
        "              ls_fm_documentation-parameter =",
        "                ls_fm_import-parameter.",
        "            WHEN 'E'.",
        "              READ TABLE lt_fm_export INTO ls_fm_export",
        "                INDEX lv_payload_index.",
        "              ls_fm_documentation-parameter =",
        "                ls_fm_export-parameter.",
        "            WHEN 'C'.",
        "              READ TABLE lt_fm_changing INTO ls_fm_changing",
        "                INDEX lv_payload_index.",
        "              ls_fm_documentation-parameter =",
        "                ls_fm_changing-parameter.",
        "            WHEN 'T'.",
        "              READ TABLE lt_fm_tables INTO ls_fm_table",
        "                INDEX lv_payload_index.",
        "              ls_fm_documentation-parameter =",
        "                ls_fm_table-parameter.",
        "          ENDCASE.",
        "          IF sy-subrc <> 0",
        "             OR ls_fm_documentation-parameter IS INITIAL.",
        "            CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "              EXPORTING funcname = lv_function_name.",
        "            ev_status = 'E'.",
        "            ev_code = 'FUNCTION_PATCH_PAYLOAD_INVALID'.",
        "            ev_message = 'Parameter text precedes its name'.",
        "            ev_version = '2.0'. RETURN.",
        "          ENDIF.",
        "          ls_fm_documentation-kind = 'P'.",
        "          ls_fm_documentation-stext = lv_payload_value.",
        "          ls_fm_documentation-index = lv_payload_index.",
        "          APPEND ls_fm_documentation TO lt_fm_documentation.",
        "          CONTINUE.",
        "        ENDIF.",
        "        CASE lv_fm_payload_kind.",
        "          WHEN 'I'.",
        "            WHILE lines( lt_fm_import ) < lv_payload_index.",
        "              CLEAR ls_fm_import.",
        "              APPEND ls_fm_import TO lt_fm_import.",
        "            ENDWHILE.",
        "            READ TABLE lt_fm_import ASSIGNING <ls_fm_import>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_fm_import>",
        "              TO <lv_payload_component>.",
        "          WHEN 'E'.",
        "            WHILE lines( lt_fm_export ) < lv_payload_index.",
        "              CLEAR ls_fm_export.",
        "              APPEND ls_fm_export TO lt_fm_export.",
        "            ENDWHILE.",
        "            READ TABLE lt_fm_export ASSIGNING <ls_fm_export>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_fm_export>",
        "              TO <lv_payload_component>.",
        "          WHEN 'C'.",
        "            WHILE lines( lt_fm_changing ) < lv_payload_index.",
        "              CLEAR ls_fm_changing.",
        "              APPEND ls_fm_changing TO lt_fm_changing.",
        "            ENDWHILE.",
        "            READ TABLE lt_fm_changing",
        "              ASSIGNING <ls_fm_changing>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_fm_changing>",
        "              TO <lv_payload_component>.",
        "          WHEN 'T'.",
        "            WHILE lines( lt_fm_tables ) < lv_payload_index.",
        "              CLEAR ls_fm_table.",
        "              APPEND ls_fm_table TO lt_fm_tables.",
        "            ENDWHILE.",
        "            READ TABLE lt_fm_tables ASSIGNING <ls_fm_table>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_fm_table>",
        "              TO <lv_payload_component>.",
        "          WHEN 'X'.",
        "            WHILE lines( lt_fm_exceptions )",
        "              < lv_payload_index.",
        "              CLEAR ls_fm_exception.",
        "              APPEND ls_fm_exception TO lt_fm_exceptions.",
        "            ENDWHILE.",
        "            READ TABLE lt_fm_exceptions",
        "              ASSIGNING <ls_fm_exception>",
        "              INDEX lv_payload_index.",
        "            IF lv_payload_property = 'TEXT'.",
        "              CLEAR ls_fm_documentation.",
        "              ls_fm_documentation-parameter =",
        "                <ls_fm_exception>-exception.",
        "              ls_fm_documentation-kind = 'X'.",
        "              ls_fm_documentation-stext = lv_payload_value.",
        "              ls_fm_documentation-index = lv_payload_index.",
        "              APPEND ls_fm_documentation",
        "                TO lt_fm_documentation.",
        "              CONTINUE.",
        "            ENDIF.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_fm_exception>",
        "              TO <lv_payload_component>.",
        "          WHEN 'S'.",
        "            IF lv_payload_property <> 'LINE'.",
        "              CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "                EXPORTING funcname = lv_function_name.",
        "              ev_status = 'E'.",
        "              ev_code = 'FUNCTION_PROPERTY_INVALID'.",
        "              ev_message = 'Unknown source payload property'.",
        "              ev_version = '2.0'. RETURN.",
        "            ENDIF.",
        "* Source rows describe the pre-ADT snapshot. Preserve the",
        "* active post-ADT source and verify it after doc update.",
        "            CONTINUE.",
        "          WHEN OTHERS.",
        "            CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "              EXPORTING funcname = lv_function_name.",
        "            ev_status = 'E'.",
        "            ev_code = 'FUNCTION_PATCH_PAYLOAD_INVALID'.",
        "            ev_message = 'Unknown function payload row type'.",
        "            ev_version = '2.0'. RETURN.",
        "        ENDCASE.",
        "        IF sy-subrc <> 0.",
        "          CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "            EXPORTING funcname = lv_function_name.",
        "          ev_status = 'E'.",
        "          ev_code = 'FUNCTION_PROPERTY_INVALID'.",
        "          ev_message = 'Unknown function payload property'.",
        "          ev_version = '2.0'. RETURN.",
        "        ENDIF.",
        "        <lv_payload_component> = lv_payload_value.",
        "* Record the property this row names so the pre-write guard",
        "* compares exactly that property and nothing else.",
        "        CLEAR ls_fm_field.",
        "        ls_fm_field-kind = lv_fm_payload_kind(1).",
        "        ls_fm_field-position = lv_payload_index.",
        "        ls_fm_field-property = lv_payload_property.",
        "        APPEND ls_fm_field TO lt_fm_field.",
        "      ENDLOOP.",
        "      IF lt_fm_source[] <> lt_fm_current_source[].",
        "        CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "          EXPORTING funcname = lv_function_name.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_SOURCE_CHANGE_REJECTED'.",
        "        ev_message = 'Interface patch cannot change source'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "* Pre-write guard: the payload may add parameters, but every",
        "* parameter it keeps must still carry the values the payload",
        "* names, and a live parameter the payload no longer names would",
        "* be removed or renamed. The positional index only orders the",
        "* payload rows; rows themselves are matched by parameter name.",
        "      CLEAR: lv_fm_guard_error, lv_fm_guard_removal.",
        "      REFRESH it_source.",
        "      fm_guard_section 'IMPORT' 'I' 'PARAMETER'",
        "        lt_fm_import lt_fm_current_import.",
        "      fm_guard_section 'EXPORT' 'E' 'PARAMETER'",
        "        lt_fm_export lt_fm_current_export.",
        "      fm_guard_section 'CHANGING' 'C' 'PARAMETER'",
        "        lt_fm_changing lt_fm_current_changing.",
        "      fm_guard_section 'TABLES' 'T' 'PARAMETER'",
        "        lt_fm_tables lt_fm_current_tables.",
        "      fm_guard_section 'EXCEPTIONS' 'X' 'EXCEPTION'",
        "        lt_fm_exceptions lt_fm_current_exceptions.",
        "      fm_guard_no_removal 'IMPORT' 'PARAMETER'",
        "        lt_fm_import lt_fm_current_import.",
        "      fm_guard_no_removal 'EXPORT' 'PARAMETER'",
        "        lt_fm_export lt_fm_current_export.",
        "      fm_guard_no_removal 'CHANGING' 'PARAMETER'",
        "        lt_fm_changing lt_fm_current_changing.",
        "      fm_guard_no_removal 'TABLES' 'PARAMETER'",
        "        lt_fm_tables lt_fm_current_tables.",
        "      fm_guard_no_removal 'EXCEPTIONS' 'EXCEPTION'",
        "        lt_fm_exceptions lt_fm_current_exceptions.",
        "      IF lv_fm_guard_error IS NOT INITIAL.",
        "        CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "          EXPORTING funcname = lv_function_name.",
        "        CLEAR lv_fm_diff_id.",
        "        ADD 1 TO lv_fm_diff_id.",
        "        add_repo_payload 'D' lv_fm_diff_id 'DIRECTION'",
        "          lv_fm_guard_direction.",
        "        add_repo_payload 'D' lv_fm_diff_id 'PARAMETER'",
        "          lv_fm_guard_key.",
        "        add_repo_payload 'D' lv_fm_diff_id 'PROPERTY'",
        "          lv_fm_guard_property.",
        "        add_repo_payload 'D' lv_fm_diff_id 'EXPECTED'",
        "          lv_fm_guard_expected_text.",
        "        add_repo_payload 'D' lv_fm_diff_id 'ACTUAL'",
        "          lv_fm_guard_actual_text.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_ADT_PATCH_NOT_OBSERVED'.",
        "        ev_message = 'ADT interface does not match the request'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      IF lv_fm_guard_removal IS NOT INITIAL.",
        "        CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "          EXPORTING funcname = lv_function_name.",
        "        CLEAR lv_fm_diff_id.",
        "        ADD 1 TO lv_fm_diff_id.",
        "        add_repo_payload 'D' lv_fm_diff_id 'DIRECTION'",
        "          lv_fm_guard_direction.",
        "        add_repo_payload 'D' lv_fm_diff_id 'PARAMETER'",
        "          lv_fm_guard_key.",
        "        add_repo_payload 'D' lv_fm_diff_id 'REASON'",
        "          'LIVE_PARAMETER_NOT_IN_REQUEST'.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_PATCH_PARAMETER_REMOVAL'.",
        "        ev_message = 'Patch must not remove or rename a parameter'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "* Preserve native cross-direction indices and row order.",
        "      lt_fm_requested_documentation[] = lt_fm_documentation[].",
        "      lt_fm_documentation[] = lt_fm_current_documentation[].",
        "      LOOP AT lt_fm_documentation ASSIGNING <ls_fm_documentation>.",
        "        READ TABLE lt_fm_requested_documentation",
        "          INTO ls_fm_documentation",
        "          WITH KEY parameter = <ls_fm_documentation>-parameter",
        "            kind = <ls_fm_documentation>-kind.",
        "        IF sy-subrc <> 0.",
        "          CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "            EXPORTING funcname = lv_function_name.",
        "          ev_status = 'E'.",
        "          ev_code = 'FUNCTION_PATCH_DOCUMENTATION_MISMATCH'.",
        "          ev_message = 'Native parameter text missing in request'.",
        "          ev_version = '2.0'. RETURN.",
        "        ENDIF.",
        "        DELETE lt_fm_requested_documentation INDEX sy-tabix.",
        "        <ls_fm_documentation>-stext = ls_fm_documentation-stext.",
        "      ENDLOOP.",
        "      IF lt_fm_requested_documentation IS NOT INITIAL.",
        "        CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "          EXPORTING funcname = lv_function_name.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_PATCH_DOCUMENTATION_MISMATCH'.",
        "        ev_message = 'Duplicate or unknown parameter text'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      PERFORM fu_modification_globals_init(SAPMS38L)",
        "        USING 'X' sy-langu.",
        "      PERFORM do_read_docu_r3_new(SAPMS38L)",
        "        TABLES lt_fm_current_documentation",
        "        USING lv_function_name.",
        "      PERFORM do_update_docu_r3_new(SAPMS38L)",
        "        TABLES lt_fm_documentation",
        "        USING lv_function_name.",
        "      COMMIT WORK AND WAIT.",
        "      CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "        EXPORTING funcname = lv_function_name.",
        "      REFRESH: lt_fm_current_import, lt_fm_current_export,",
        "        lt_fm_current_changing, lt_fm_current_tables,",
        "        lt_fm_current_exceptions,",
        "        lt_fm_current_documentation, lt_fm_current_source.",
        "      CLEAR: lv_global_flag, lv_remote_call, lv_update_task,",
        "        lv_short_text, lv_function_pool.",
        "      CALL FUNCTION 'RPY_FUNCTIONMODULE_READ'",
        "        EXPORTING functionname = lv_function_name",
        "        IMPORTING global_flag = lv_global_flag",
        "          remote_call = lv_remote_call",
        "          update_task = lv_update_task",
        "          short_text = lv_short_text",
        "          function_pool = lv_function_pool",
        "        TABLES import_parameter = lt_fm_current_import",
        "          changing_parameter = lt_fm_current_changing",
        "          export_parameter = lt_fm_current_export",
        "          tables_parameter = lt_fm_current_tables",
        "          exception_list = lt_fm_current_exceptions",
        "          documentation = lt_fm_current_documentation",
        "          source = lt_fm_current_source",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'FUNCTION_PATCH_PARTIAL'.",
        "        ev_message = 'Function patched but re-read failed'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      IF lt_fm_current_import[] <> lt_fm_import[]",
        "         OR lt_fm_current_export[] <> lt_fm_export[]",
        "         OR lt_fm_current_changing[] <> lt_fm_changing[]",
        "         OR lt_fm_current_tables[] <> lt_fm_tables[]",
        "         OR lt_fm_current_exceptions[] <> lt_fm_exceptions[]",
        "         OR lt_fm_current_documentation[]",
        "           <> lt_fm_documentation[]",
        "         OR lt_fm_current_source[] <> lt_fm_source[].",
        "        ev_status = 'E'.",
        "        REFRESH it_source.",
        "        CLEAR lv_fm_diff_id.",
        "        emit_fm_difference 'IMPORT' lt_fm_import",
        "          lt_fm_current_import.",
        "        emit_fm_difference 'EXPORT' lt_fm_export",
        "          lt_fm_current_export.",
        "        emit_fm_difference 'CHANGING' lt_fm_changing",
        "          lt_fm_current_changing.",
        "        emit_fm_difference 'TABLES' lt_fm_tables",
        "          lt_fm_current_tables.",
        "        emit_fm_difference 'EXCEPTIONS' lt_fm_exceptions",
        "          lt_fm_current_exceptions.",
        "        emit_fm_difference 'DOCUMENTATION' lt_fm_documentation",
        "          lt_fm_current_documentation.",
        "        emit_fm_difference 'SOURCE' lt_fm_source",
        "          lt_fm_current_source.",
        "        ev_code = 'FUNCTION_PATCH_SAVE_NOT_OBSERVED'.",
        "        ev_message = 'Active function does not match the save'.",
        "        ev_version = '2.0'. RETURN.",
        "      ENDIF.",
        "      lt_fm_import[] = lt_fm_current_import[].",
        "      lt_fm_export[] = lt_fm_current_export[].",
        "      lt_fm_changing[] = lt_fm_current_changing[].",
        "      lt_fm_tables[] = lt_fm_current_tables[].",
        "      lt_fm_exceptions[] = lt_fm_current_exceptions[].",
        "      lt_fm_documentation[] = lt_fm_current_documentation[].",
        "      lt_fm_source[] = lt_fm_current_source[].",
        "      emit_fm_payload.",
        "      ev_status = 'S'.",
        "      ev_code = 'FUNCTION_INTERFACE_PATCHED'.",
        "      ev_message = 'Function interface patched and verified'.",
        "      ev_version = '2.0'. RETURN.",
        "    WHEN 'INSPECT_REPOSITORY_ASSIGNMENT'.",
        "      CLEAR: ls_tadir, ls_tfdir, ls_enlfdir,",
        "        lv_parent_object, lv_transport_task,",
        "        lv_transport_request, lv_transport_status,",
        "        lv_active, lv_generated.",
        "      CASE iv_object_type.",
        "        WHEN 'CLAS'.",
        "          lv_transport_pgmid = 'R3TR'.",
        "          lv_transport_object = 'CLAS'.",
        "          lv_transport_name = iv_object_name.",
        "          SELECT SINGLE * FROM tadir INTO ls_tadir",
        "            WHERE pgmid = 'R3TR' AND object = 'CLAS'",
        "              AND obj_name = iv_object_name.",
        "          IF sy-subrc = 0. lv_active = 'X'. ENDIF.",
        "        WHEN 'INTF'.",
        "          lv_transport_pgmid = 'R3TR'.",
        "          lv_transport_object = 'INTF'.",
        "          lv_transport_name = iv_object_name.",
        "          SELECT SINGLE * FROM tadir INTO ls_tadir",
        "            WHERE pgmid = 'R3TR' AND object = 'INTF'",
        "              AND obj_name = iv_object_name.",
        "          IF sy-subrc = 0. lv_active = 'X'. ENDIF.",
        "        WHEN 'FGRP'.",
        "          lv_parent_object = iv_object_name.",
        "          lv_transport_pgmid = 'R3TR'.",
        "          lv_transport_object = 'FUGR'.",
        "          lv_transport_name = iv_object_name.",
        "          SELECT SINGLE * FROM tadir INTO ls_tadir",
        "            WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "              AND obj_name = iv_object_name.",
        "          IF sy-subrc = 0. lv_active = 'X'. ENDIF.",
        "        WHEN 'FUNC'.",
        "          SELECT SINGLE * FROM tfdir INTO ls_tfdir",
        "            WHERE funcname = iv_object_name.",
        "          IF sy-subrc <> 0.",
        "            ev_status = 'E'.",
        "            ev_code = 'REPOSITORY_OBJECT_NOT_FOUND'.",
        "            ev_message = 'Function module does not exist'.",
        "            ev_version = '1.3'.",
        "            RETURN.",
        "          ENDIF.",
        "          lv_parent_object = ls_tfdir-pname+4.",
        "          lv_transport_pgmid = 'LIMU'.",
        "          lv_transport_object = 'FUNC'.",
        "          lv_transport_name = iv_object_name.",
        "          SELECT SINGLE * FROM tadir INTO ls_tadir",
        "            WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "              AND obj_name = lv_parent_object.",
        "          SELECT SINGLE * FROM enlfdir INTO ls_enlfdir",
        "            WHERE funcname = iv_object_name.",
        "          IF sy-subrc = 0.",
        "            lv_active = ls_enlfdir-active.",
        "            lv_generated = ls_enlfdir-generated.",
        "          ENDIF.",
        "        WHEN 'PROG'.",
        "          lv_transport_pgmid = 'R3TR'.",
        "          lv_transport_object = 'PROG'.",
        "          lv_transport_name = iv_object_name.",
        "          SELECT SINGLE * FROM tadir INTO ls_tadir",
        "            WHERE pgmid = 'R3TR' AND object = 'PROG'",
        "              AND obj_name = iv_object_name.",
        "          SELECT SINGLE * FROM trdir INTO ls_trdir",
        "            WHERE name = iv_object_name.",
        "          IF sy-subrc = 0. lv_active = 'X'. ENDIF.",
        "        WHEN 'TRAN'.",
        "          lv_transport_pgmid = 'R3TR'.",
        "          lv_transport_object = 'TRAN'.",
        "          lv_transport_name = iv_object_name.",
        "          SELECT SINGLE * FROM tadir INTO ls_tadir",
        "            WHERE pgmid = 'R3TR' AND object = 'TRAN'",
        "              AND obj_name = iv_object_name.",
        "          SELECT SINGLE tcode FROM tstc",
        "            INTO lv_existing_tcode",
        "            WHERE tcode = iv_object_name.",
        "          IF sy-subrc = 0. lv_active = 'X'. ENDIF.",
        "        WHEN OTHERS.",
        "          ev_status = 'E'.",
        "          ev_code = 'REPOSITORY_TYPE_UNSUPPORTED'.",
        "          ev_message = 'Repository object type is unsupported'.",
        "          ev_version = '1.3'.",
        "          RETURN.",
        "      ENDCASE.",
        "      IF ls_tadir-obj_name IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'REPOSITORY_OBJECT_NOT_FOUND'.",
        "        ev_message = 'Repository object does not exist'.",
        "        ev_version = '1.3'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT e071~trkorr e070~strkorr e070~trstatus",
        "        INTO (lv_transport_task, lv_transport_request,",
        "          lv_transport_status)",
        "        FROM e071 INNER JOIN e070",
        "          ON e070~trkorr = e071~trkorr",
        "        UP TO 1 ROWS",
        "        WHERE e071~pgmid = lv_transport_pgmid",
        "          AND e071~object = lv_transport_object",
        "          AND e071~obj_name = lv_transport_name",
        "          AND e070~trstatus <> 'R'.",
        "      ENDSELECT.",
      "      IF lv_transport_task IS INITIAL",
        "         AND iv_object_type = 'FUNC'.",
        "        lv_transport_pgmid = 'R3TR'.",
        "        lv_transport_object = 'FUGR'.",
        "        lv_transport_name = lv_parent_object.",
        "        SELECT e071~trkorr e070~strkorr e070~trstatus",
        "          INTO (lv_transport_task, lv_transport_request,",
        "            lv_transport_status)",
        "          FROM e071 INNER JOIN e070",
        "            ON e070~trkorr = e071~trkorr",
        "          UP TO 1 ROWS",
        "          WHERE e071~pgmid = lv_transport_pgmid",
        "            AND e071~object = lv_transport_object",
        "            AND e071~obj_name = lv_transport_name",
        "            AND e070~trstatus <> 'R'.",
        "        ENDSELECT.",
        "      ENDIF.",
        "      IF lv_transport_request IS INITIAL.",
        "        lv_transport_request = lv_transport_task.",
        "        CLEAR lv_transport_task.",
        "      ENDIF.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'PARENT_OBJECT'",
        "        lv_parent_object.",
        "      add_repo_payload 'M' '1' 'PACKAGE' ls_tadir-devclass.",
        "      add_repo_payload 'M' '1' 'REQUEST'",
        "        lv_transport_request.",
        "      add_repo_payload 'M' '1' 'TASK' lv_transport_task.",
        "      add_repo_payload 'M' '1' 'TRANSPORT_STATUS'",
        "        lv_transport_status.",
        "      add_repo_payload 'M' '1' 'ACTIVE' lv_active.",
        "      add_repo_payload 'M' '1' 'GENERATED' lv_generated.",
        "      add_repo_payload 'M' '1' 'ORIGINAL_SYSTEM'",
        "        ls_tadir-srcsystem.",
        "      ev_status = 'S'.",
        "      ev_code = 'REPOSITORY_ASSIGNMENT_READ'.",
        "      ev_message = 'Repository assignment read successfully'.",
        "      ev_version = '1.3'.",
        "      RETURN.",
        "    WHEN 'READ_GUI_DEFINITION'.",
        "      REFRESH: lt_gui_sta, lt_gui_fun, lt_gui_men,",
        "        lt_gui_mtx, lt_gui_act, lt_gui_but, lt_gui_pfk,",
        "        lt_gui_set, lt_gui_doc, lt_gui_tit, lt_gui_biv.",
        "      CLEAR: ls_gui_adm, lv_gui_language, lv_gui_author,",
        "        lv_gui_cauthor, lv_gui_date, lv_gui_time,",
        "        lv_gui_cdate, lv_gui_ctime, lv_gui_gdate,",
        "        lv_gui_gtime, lv_gui_current_version.",
        "      CALL FUNCTION 'RS_CUA_INTERNAL_FETCH'",
        "        EXPORTING program = iv_program language = sy-langu",
        "          state = 'A'",
        "        IMPORTING adm = ls_gui_adm",
        "          langu = lv_gui_language author = lv_gui_author",
        "          date = lv_gui_date time = lv_gui_time",
        "          cauthor = lv_gui_cauthor cdate = lv_gui_cdate",
        "          ctime = lv_gui_ctime gdate = lv_gui_gdate",
        "          gtime = lv_gui_gtime",
        "        TABLES sta = lt_gui_sta fun = lt_gui_fun",
        "          men = lt_gui_men mtx = lt_gui_mtx",
        "          act = lt_gui_act but = lt_gui_but",
        "          pfk = lt_gui_pfk set = lt_gui_set",
        "          doc = lt_gui_doc tit = lt_gui_tit",
        "          biv = lt_gui_biv",
        "        EXCEPTIONS not_found = 1 unknown_version = 2",
        "          OTHERS = 3.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'GUI_DEFINITION_READ_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        IF ev_message IS INITIAL.",
        "          ev_message = 'Active GUI definition could not be read'.",
        "        ENDIF.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      CONCATENATE lv_gui_cdate lv_gui_ctime",
        "        INTO lv_gui_current_version.",
        "      IF lv_gui_current_version IS INITIAL.",
        "        CONCATENATE lv_gui_date lv_gui_time",
        "          INTO lv_gui_current_version.",
        "      ENDIF.",
        "      IF lv_gui_current_version IS INITIAL.",
        "        lv_gui_current_version = '00000000000000'.",
        "      ENDIF.",
        "      CLEAR ls_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'PROG'",
        "          AND obj_name = iv_program.",
        "      emit_gui_payload.",
        "      ev_status = 'S'.",
        "      ev_code = 'GUI_DEFINITION_READ'.",
        "      ev_message = 'Active GUI definition read successfully'.",
        "      ev_version = '1.5'.",
        "      RETURN.",
        "    WHEN 'PATCH_GUI_DEFINITION'.",
        "      IF iv_request IS INITIAL OR it_source[] IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'GUI_PATCH_INPUT_REQUIRED'.",
        "        ev_message = 'Transport and GUI payload are required'.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      lt_gui_payload[] = it_source[].",
        "      CLEAR lv_gui_expected_version.",
        "      LOOP AT lt_gui_payload INTO ls_source.",
        "        CLEAR: lv_gui_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_gui_kind",
        "          lv_payload_index_text lv_payload_property",
        "          lv_payload_value.",
        "        IF lv_gui_kind = 'M'",
        "           AND lv_payload_property = 'EXPECTED_VERSION'.",
        "          REPLACE ALL OCCURRENCES OF '%7C'",
        "            IN lv_payload_value WITH '|'.",
        "          REPLACE ALL OCCURRENCES OF '%25'",
        "            IN lv_payload_value WITH '%'.",
        "          lv_gui_expected_version = lv_payload_value.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      IF lv_gui_expected_version IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'GUI_EXPECTED_VERSION_REQUIRED'.",
        "        ev_message = 'GUI version token is required'.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_gui_sta, lt_gui_fun, lt_gui_men,",
        "        lt_gui_mtx, lt_gui_act, lt_gui_but, lt_gui_pfk,",
        "        lt_gui_set, lt_gui_doc, lt_gui_tit, lt_gui_biv.",
        "      CLEAR: ls_gui_adm, lv_gui_language, lv_gui_author,",
        "        lv_gui_cauthor, lv_gui_date, lv_gui_time,",
        "        lv_gui_cdate, lv_gui_ctime, lv_gui_gdate,",
        "        lv_gui_gtime, lv_gui_current_version.",
        "      CALL FUNCTION 'RS_CUA_INTERNAL_FETCH'",
        "        EXPORTING program = iv_program language = sy-langu",
        "          state = 'A'",
        "        IMPORTING adm = ls_gui_adm",
        "          langu = lv_gui_language author = lv_gui_author",
        "          date = lv_gui_date time = lv_gui_time",
        "          cauthor = lv_gui_cauthor cdate = lv_gui_cdate",
        "          ctime = lv_gui_ctime gdate = lv_gui_gdate",
        "          gtime = lv_gui_gtime",
        "        TABLES sta = lt_gui_sta fun = lt_gui_fun",
        "          men = lt_gui_men mtx = lt_gui_mtx",
        "          act = lt_gui_act but = lt_gui_but",
        "          pfk = lt_gui_pfk set = lt_gui_set",
        "          doc = lt_gui_doc tit = lt_gui_tit",
        "          biv = lt_gui_biv",
        "        EXCEPTIONS not_found = 1 unknown_version = 2",
        "          OTHERS = 3.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'GUI_DEFINITION_READ_FAILED'.",
        "        ev_message = 'Active GUI definition could not be read'.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      CONCATENATE lv_gui_cdate lv_gui_ctime",
        "        INTO lv_gui_current_version.",
        "      IF lv_gui_current_version IS INITIAL.",
        "        CONCATENATE lv_gui_date lv_gui_time",
        "          INTO lv_gui_current_version.",
        "      ENDIF.",
        "      IF lv_gui_current_version IS INITIAL.",
        "        lv_gui_current_version = '00000000000000'.",
        "      ENDIF.",
        "      IF lv_gui_expected_version <> lv_gui_current_version.",
        "        ev_status = 'E'.",
        "        ev_code = 'GUI_VERSION_CONFLICT'.",
        "        ev_message = 'GUI definition changed since it was read'.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_gui_sta, lt_gui_fun, lt_gui_men,",
        "        lt_gui_mtx, lt_gui_act, lt_gui_but, lt_gui_pfk,",
        "        lt_gui_set, lt_gui_doc, lt_gui_tit, lt_gui_biv.",
        "      CLEAR ls_gui_adm.",
        "      LOOP AT lt_gui_payload INTO ls_source.",
        "        CLEAR: lv_gui_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_gui_kind",
        "          lv_payload_index_text lv_payload_property",
        "          lv_payload_value.",
        "        IF lv_gui_kind = 'M'. CONTINUE. ENDIF.",
        "        IF lv_payload_index_text IS INITIAL",
        "           OR lv_payload_index_text CN '0123456789'.",
        "          ev_status = 'E'.",
        "          ev_code = 'GUI_PAYLOAD_INVALID'.",
        "          ev_message = 'GUI payload index is invalid'.",
        "          ev_version = '1.5'.",
        "          RETURN.",
        "        ENDIF.",
        "        lv_payload_index = lv_payload_index_text.",
        "        IF lv_payload_index < 1 OR lv_payload_index > 2000.",
        "          ev_status = 'E'.",
        "          ev_code = 'GUI_PAYLOAD_LIMIT'.",
        "          ev_message = 'GUI payload row limit exceeded'.",
        "          ev_version = '1.5'.",
        "          RETURN.",
        "        ENDIF.",
        "        REPLACE ALL OCCURRENCES OF '%7C'",
        "          IN lv_payload_value WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25'",
        "          IN lv_payload_value WITH '%'.",
        "        CASE lv_gui_kind.",
        "          WHEN 'ADM'.",
        "            IF lv_payload_index <> 1.",
        "              ev_status = 'E'.",
        "              ev_code = 'GUI_PAYLOAD_INVALID'.",
        "              ev_message = 'GUI ADM row index must be one'.",
        "              ev_version = '1.5'.",
        "              RETURN.",
        "            ENDIF.",
        "            ASSIGN ls_gui_adm TO <ls_gui_row>.",
        "          WHEN 'STA'.",
        "            WHILE lines( lt_gui_sta ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_sta.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_sta ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN 'FUN'.",
        "            WHILE lines( lt_gui_fun ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_fun.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_fun ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN 'MEN'.",
        "            WHILE lines( lt_gui_men ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_men.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_men ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN 'MTX'.",
        "            WHILE lines( lt_gui_mtx ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_mtx.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_mtx ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN 'ACT'.",
        "            WHILE lines( lt_gui_act ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_act.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_act ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN 'BUT'.",
        "            WHILE lines( lt_gui_but ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_but.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_but ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN 'PFK'.",
        "            WHILE lines( lt_gui_pfk ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_pfk.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_pfk ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN 'SET'.",
        "            WHILE lines( lt_gui_set ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_set.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_set ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN 'DOC'.",
        "            WHILE lines( lt_gui_doc ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_doc.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_doc ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN 'TIT'.",
        "            WHILE lines( lt_gui_tit ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_tit.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_tit ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN 'BIV'.",
        "            WHILE lines( lt_gui_biv ) < lv_payload_index.",
        "              APPEND INITIAL LINE TO lt_gui_biv.",
        "            ENDWHILE.",
        "            READ TABLE lt_gui_biv ASSIGNING <ls_gui_row>",
        "              INDEX lv_payload_index.",
        "          WHEN OTHERS.",
        "            ev_status = 'E'.",
        "            ev_code = 'GUI_SECTION_INVALID'.",
        "            ev_message = 'Unknown GUI payload section'.",
        "            ev_version = '1.5'.",
        "            RETURN.",
        "        ENDCASE.",
        "        ASSIGN COMPONENT lv_payload_property",
        "          OF STRUCTURE <ls_gui_row>",
        "          TO <lv_payload_component>.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'GUI_PROPERTY_INVALID'.",
        "          ev_message = 'Unknown GUI payload property'.",
        "          ev_version = '1.5'.",
        "          RETURN.",
        "        ENDIF.",
        "        <lv_payload_component> = lv_payload_value.",
        "      ENDLOOP.",
        "      CLEAR: ls_tadir, ls_request, ls_task.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'PROG'",
        "          AND obj_name = iv_program.",
        "      IF sy-subrc <> 0 OR ls_tadir-devclass = '`$TMP'.",
        "        ev_status = 'E'.",
        "        ev_code = 'GUI_PROGRAM_NOT_TRANSPORTABLE'.",
        "        ev_message = 'Transportable customer program required'.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM e070 INTO ls_request",
        "        WHERE trkorr = iv_request.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_FOUND'.",
        "        ev_message = 'Transport request or task does not exist'.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF ls_request-strkorr IS NOT INITIAL.",
        "        ls_task = ls_request.",
        "        SELECT SINGLE * FROM e070 INTO ls_request",
        "          WHERE trkorr = ls_task-strkorr.",
        "      ELSE.",
        "        SELECT SINGLE * FROM e070 INTO ls_task",
        "          WHERE strkorr = ls_request-trkorr",
        "            AND as4user = sy-uname AND trstatus = 'D'.",
        "      ENDIF.",
        "      IF ls_request-trfunction <> 'K'",
        "         OR ls_request-trstatus <> 'D'",
        "         OR ls_task-trstatus <> 'D'",
        "         OR ls_task-as4user <> sy-uname.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_MODIFIABLE'.",
        "        ev_message = 'Open workbench task for user is required'.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_gui_tr_key, lv_gui_corrnum.",
        "      CALL FUNCTION 'RS_CORR_INSERT'",
        "        EXPORTING object = iv_program",
        "          object_class = 'SCUA' mode = 'M'",
        "          devclass = ls_tadir-devclass",
        "          korrnum = ls_request-trkorr",
        "          use_korrnum_immediatedly = 'X'",
        "          master_language = sy-langu suppress_dialog = 'X'",
        "        IMPORTING korrnum = lv_gui_corrnum",
        "          transport_key = ls_gui_tr_key",
        "        EXCEPTIONS cancelled = 1 permission_failure = 2",
        "          unknown_objectclass = 3 OTHERS = 4.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'GUI_TRANSPORT_RECORD_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      lv_gui_tcode = sy-tcode.",
        "      sy-tcode = 'SE41'.",
        "      CALL FUNCTION 'RS_CUA_INTERNAL_WRITE'",
        "        EXPORTING program = iv_program language = sy-langu",
        "          tr_key = ls_gui_tr_key adm = ls_gui_adm state = 'A'",
        "        TABLES sta = lt_gui_sta fun = lt_gui_fun",
        "          men = lt_gui_men mtx = lt_gui_mtx",
        "          act = lt_gui_act but = lt_gui_but",
        "          pfk = lt_gui_pfk set = lt_gui_set",
        "          doc = lt_gui_doc tit = lt_gui_tit",
        "          biv = lt_gui_biv",
        "        EXCEPTIONS not_found = 1 OTHERS = 2.",
        "      lv_gui_subrc = sy-subrc.",
        "      sy-tcode = lv_gui_tcode.",
        "      IF lv_gui_subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'GUI_DEFINITION_WRITE_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      REFRESH: lt_gui_sta, lt_gui_fun, lt_gui_men,",
        "        lt_gui_mtx, lt_gui_act, lt_gui_but, lt_gui_pfk,",
        "        lt_gui_set, lt_gui_doc, lt_gui_tit, lt_gui_biv.",
        "      CLEAR: ls_gui_adm, lv_gui_language, lv_gui_author,",
        "        lv_gui_cauthor, lv_gui_date, lv_gui_time,",
        "        lv_gui_cdate, lv_gui_ctime, lv_gui_gdate,",
        "        lv_gui_gtime, lv_gui_current_version.",
        "      CALL FUNCTION 'RS_CUA_INTERNAL_FETCH'",
        "        EXPORTING program = iv_program language = sy-langu",
        "          state = 'A'",
        "        IMPORTING adm = ls_gui_adm",
        "          langu = lv_gui_language author = lv_gui_author",
        "          date = lv_gui_date time = lv_gui_time",
        "          cauthor = lv_gui_cauthor cdate = lv_gui_cdate",
        "          ctime = lv_gui_ctime gdate = lv_gui_gdate",
        "          gtime = lv_gui_gtime",
        "        TABLES sta = lt_gui_sta fun = lt_gui_fun",
        "          men = lt_gui_men mtx = lt_gui_mtx",
        "          act = lt_gui_act but = lt_gui_but",
        "          pfk = lt_gui_pfk set = lt_gui_set",
        "          doc = lt_gui_doc tit = lt_gui_tit",
        "          biv = lt_gui_biv",
        "        EXCEPTIONS OTHERS = 3.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'GUI_DEFINITION_VERIFY_FAILED'.",
        "        ev_message = 'GUI definition saved but re-read failed'.",
        "        ev_version = '1.5'.",
        "        RETURN.",
        "      ENDIF.",
        "      CONCATENATE lv_gui_cdate lv_gui_ctime",
        "        INTO lv_gui_current_version.",
        "      IF lv_gui_current_version IS INITIAL.",
        "        CONCATENATE lv_gui_date lv_gui_time",
        "          INTO lv_gui_current_version.",
        "      ENDIF.",
        "      IF lv_gui_current_version IS INITIAL.",
        "        lv_gui_current_version = '00000000000000'.",
        "      ENDIF.",
        "      emit_gui_payload.",
        "      ev_status = 'S'.",
        "      ev_code = 'GUI_DEFINITION_PATCHED'.",
        "      ev_message = 'GUI definition saved and verified'.",
        "      ev_version = '1.5'.",
        "      RETURN.",
        "    WHEN 'READ_SCREEN'.",
        "      REFRESH: ct_fields, ct_flowlogic, ct_params.",
        "      CALL FUNCTION 'RPY_DYNPRO_READ_NATIVE'",
        "        EXPORTING progname = iv_program dynnr = iv_screen",
        "        IMPORTING header = es_header",
        "          dynprotext = ev_dynprotext",
        "        TABLES fieldlist = ct_fields",
        "          flowlogic = ct_flowlogic params = ct_params",
        "          fieldtexts = lt_fieldtexts",
        "        EXCEPTIONS cancelled = 1 not_found = 2",
        "          permission_error = 3 OTHERS = 4.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'SCREEN_READ_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "      ELSE.",
        "        ev_status = 'S'.",
        "        ev_code = 'SCREEN_READ'.",
        "        ev_message = 'Screen read successfully'.",
        "      ENDIF.",
        "      ev_version = '1.1'.",
        "      RETURN.",
        "    WHEN 'PATCH_SCREEN'.",
        "      IF iv_request IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_REQUIRED'.",
        "        ev_message = 'An existing transport is required'.",
        "        ev_version = '1.4'.",
        "        RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_containers, lt_screen_fields,",
        "        lt_screen_flow, lt_screen_params.",
        "      CLEAR ls_rpy_header.",
        "      CALL FUNCTION 'RPY_DYNPRO_READ'",
        "        EXPORTING progname = iv_program dynnr = iv_screen",
        "          suppress_exist_checks = space",
        "          suppress_corr_checks = space",
        "        IMPORTING header = ls_rpy_header",
        "        TABLES containers = lt_containers",
        "          fields_to_containers = lt_screen_fields",
        "          flow_logic = lt_screen_flow",
        "          params = lt_screen_params",
        "        EXCEPTIONS cancelled = 1 not_found = 2",
        "          permission_error = 3 OTHERS = 4.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'SCREEN_READ_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.4'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR: lv_patch_count, lv_patch_flow,",
        "        lv_patch_params, lv_patch_header,",
        "        lv_patch_description.",
        "      LOOP AT it_source INTO ls_source.",
        "        CLEAR: lv_payload_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_payload_kind",
        "          lv_payload_index_text lv_payload_property",
        "          lv_payload_value.",
        "        IF lv_payload_index_text IS INITIAL",
        "           OR lv_payload_index_text CN '0123456789'.",
        "          ev_status = 'E'.",
        "          ev_code = 'SCREEN_PATCH_INVALID'.",
        "          ev_message = 'Patch payload index is invalid'.",
        "          ev_version = '1.4'.",
        "          RETURN.",
        "        ENDIF.",
        "        lv_payload_index = lv_payload_index_text.",
        "        REPLACE ALL OCCURRENCES OF '%7C'",
        "          IN lv_payload_value WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25'",
        "          IN lv_payload_value WITH '%'.",
        "        IF lv_payload_kind = 'O'",
        "           AND lv_payload_index > lv_patch_count.",
        "          lv_patch_count = lv_payload_index.",
        "        ELSEIF lv_payload_kind = 'M'.",
        "          CASE lv_payload_property.",
        "            WHEN 'FLOW_REPLACE'. lv_patch_flow = 'X'.",
        "            WHEN 'PARAMS_REPLACE'. lv_patch_params = 'X'.",
        "            WHEN 'HEADER_PATCH'. lv_patch_header = 'X'.",
        "            WHEN 'DESCRIPTION_PATCH'.",
        "              lv_patch_description = 'X'.",
        "          ENDCASE.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      IF lv_patch_description = 'X'.",
        "        ls_rpy_header-descript = iv_description.",
        "      ENDIF.",
        "      IF lv_patch_header = 'X'.",
        "        IF is_header-noli IS NOT INITIAL.",
        "          ls_rpy_header-lines = is_header-noli.",
        "        ENDIF.",
        "        IF is_header-noco IS NOT INITIAL.",
        "          ls_rpy_header-columns = is_header-noco.",
        "        ENDIF.",
        "      ENDIF.",
        "      IF lv_patch_flow = 'X'.",
        "        REFRESH lt_screen_flow.",
        "      ENDIF.",
        "      IF lv_patch_params = 'X'.",
        "        REFRESH lt_screen_params.",
        "      ENDIF.",
        "      LOOP AT it_source INTO ls_source.",
        "        CLEAR: lv_payload_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_payload_kind",
        "          lv_payload_index_text lv_payload_property",
        "          lv_payload_value.",
        "        lv_payload_index = lv_payload_index_text.",
        "        REPLACE ALL OCCURRENCES OF '%7C'",
        "          IN lv_payload_value WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25'",
        "          IN lv_payload_value WITH '%'.",
        "        IF lv_payload_kind = 'L'",
        "           AND lv_patch_flow = 'X'.",
        "          WHILE lines( lt_screen_flow ) < lv_payload_index.",
        "            CLEAR ls_screen_flow.",
        "            APPEND ls_screen_flow TO lt_screen_flow.",
        "          ENDWHILE.",
        "          READ TABLE lt_screen_flow",
        "            ASSIGNING <ls_screen_flow>",
        "            INDEX lv_payload_index.",
        "          ASSIGN COMPONENT lv_payload_property",
        "            OF STRUCTURE <ls_screen_flow>",
        "            TO <lv_payload_component>.",
        "        ELSEIF lv_payload_kind = 'P'",
        "           AND lv_patch_params = 'X'.",
        "          WHILE lines( lt_screen_params ) < lv_payload_index.",
        "            CLEAR ls_screen_param.",
        "            APPEND ls_screen_param TO lt_screen_params.",
        "          ENDWHILE.",
        "          READ TABLE lt_screen_params",
        "            ASSIGNING <ls_screen_param>",
        "            INDEX lv_payload_index.",
        "          ASSIGN COMPONENT lv_payload_property",
        "            OF STRUCTURE <ls_screen_param>",
        "            TO <lv_payload_component>.",
        "        ELSE.",
        "          CONTINUE.",
        "        ENDIF.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'SCREEN_PROPERTY_INVALID'.",
        "          ev_message = 'Unknown screen patch property'.",
        "          ev_version = '1.4'.",
        "          RETURN.",
        "        ENDIF.",
        "        <lv_payload_component> = lv_payload_value.",
        "      ENDLOOP.",
        "      DO lv_patch_count TIMES.",
        "        lv_patch_index = sy-index.",
        "        CLEAR: lv_patch_operation, lv_patch_name,",
        "          lv_patch_row_index.",
        "        LOOP AT it_source INTO ls_source.",
        "          CLEAR: lv_payload_kind, lv_payload_index_text,",
        "            lv_payload_property, lv_payload_value.",
        "          SPLIT ls_source-line AT '|' INTO lv_payload_kind",
        "            lv_payload_index_text lv_payload_property",
        "            lv_payload_value.",
        "          lv_payload_index = lv_payload_index_text.",
        "          IF lv_payload_kind <> 'O'",
        "             OR lv_payload_index <> lv_patch_index.",
        "            CONTINUE.",
        "          ENDIF.",
        "          REPLACE ALL OCCURRENCES OF '%7C'",
        "            IN lv_payload_value WITH '|'.",
        "          REPLACE ALL OCCURRENCES OF '%25'",
        "            IN lv_payload_value WITH '%'.",
        "          CASE lv_payload_property.",
        "            WHEN 'OP'. lv_patch_operation = lv_payload_value.",
        "            WHEN 'NAME'. lv_patch_name = lv_payload_value.",
        "          ENDCASE.",
        "        ENDLOOP.",
        "        IF lv_patch_operation IS INITIAL",
        "           OR lv_patch_name IS INITIAL.",
        "          ev_status = 'E'.",
        "          ev_code = 'SCREEN_PATCH_INVALID'.",
        "          ev_message = 'Patch operation and name are required'.",
        "          ev_version = '1.4'.",
        "          RETURN.",
        "        ENDIF.",
        "        LOOP AT lt_screen_fields ASSIGNING <ls_screen_field>.",
        "          ASSIGN COMPONENT 'NAME' OF STRUCTURE",
        "            <ls_screen_field> TO <lv_payload_component>.",
        "          IF sy-subrc = 0",
        "             AND <lv_payload_component> = lv_patch_name.",
        "            lv_patch_row_index = sy-tabix.",
        "            EXIT.",
        "          ENDIF.",
        "        ENDLOOP.",
        "        IF lv_patch_operation = 'ADD'.",
        "          IF lv_patch_row_index > 0.",
        "            ev_status = 'E'.",
        "            ev_code = 'SCREEN_COMPONENT_EXISTS'.",
        "            ev_message = 'Screen component already exists'.",
        "            ev_version = '1.4'.",
        "            RETURN.",
        "          ENDIF.",
        "          CLEAR ls_screen_field.",
        "          APPEND ls_screen_field TO lt_screen_fields.",
        "          lv_patch_row_index = lines( lt_screen_fields ).",
        "        ELSEIF lv_patch_row_index = 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'SCREEN_COMPONENT_NOT_FOUND'.",
        "          ev_message = 'Screen component does not exist'.",
        "          ev_version = '1.4'.",
        "          RETURN.",
        "        ELSEIF lv_patch_operation = 'REMOVE'.",
        "          DELETE lt_screen_fields INDEX lv_patch_row_index.",
        "          CONTINUE.",
        "        ELSEIF lv_patch_operation <> 'UPDATE'.",
        "          ev_status = 'E'.",
        "          ev_code = 'SCREEN_PATCH_OPERATION_INVALID'.",
        "          ev_message = 'Screen patch operation is invalid'.",
        "          ev_version = '1.4'.",
        "          RETURN.",
        "        ENDIF.",
        "        READ TABLE lt_screen_fields",
        "          ASSIGNING <ls_screen_field>",
        "          INDEX lv_patch_row_index.",
        "        LOOP AT it_source INTO ls_source.",
        "          CLEAR: lv_payload_kind, lv_payload_index_text,",
        "            lv_payload_property, lv_payload_value.",
        "          SPLIT ls_source-line AT '|' INTO lv_payload_kind",
        "            lv_payload_index_text lv_payload_property",
        "            lv_payload_value.",
        "          lv_payload_index = lv_payload_index_text.",
        "          IF lv_payload_kind <> 'O'",
        "             OR lv_payload_index <> lv_patch_index",
        "             OR lv_payload_property NP 'FIELD_*'.",
        "            CONTINUE.",
        "          ENDIF.",
        "          lv_payload_property = lv_payload_property+6.",
        "          REPLACE ALL OCCURRENCES OF '%7C'",
        "            IN lv_payload_value WITH '|'.",
        "          REPLACE ALL OCCURRENCES OF '%25'",
        "            IN lv_payload_value WITH '%'.",
        "          ASSIGN COMPONENT lv_payload_property",
        "            OF STRUCTURE <ls_screen_field>",
        "            TO <lv_payload_component>.",
        "          IF sy-subrc <> 0.",
        "            ev_status = 'E'.",
        "            ev_code = 'SCREEN_PROPERTY_INVALID'.",
        "            ev_message = 'Unknown screen component property'.",
        "            ev_version = '1.4'.",
        "            RETURN.",
        "          ENDIF.",
        "          <lv_payload_component> = lv_payload_value.",
        "        ENDLOOP.",
        "      ENDDO.",
        "      IF lt_screen_fields[] IS INITIAL",
        "         OR lt_screen_flow[] IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'SCREEN_PAYLOAD_REQUIRED'.",
        "        ev_message = 'Fields and flow logic are required'.",
        "        ev_version = '1.4'.",
        "        RETURN.",
        "      ENDIF.",
        "      LOOP AT lt_screen_fields ASSIGNING <ls_screen_field>.",
        "        IF <ls_screen_field>-cont_type IS INITIAL.",
        "          <ls_screen_field>-cont_type = 'SCREEN'.",
        "        ENDIF.",
        "        IF <ls_screen_field>-cont_name IS INITIAL.",
        "          <ls_screen_field>-cont_name = 'SCREEN'.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      CALL FUNCTION 'RPY_DYNPRO_INSERT'",
        "        EXPORTING corrnum = iv_request",
        "          header = ls_rpy_header",
        "          suppress_exist_checks = 'X'",
        "          use_corrnum_immediatedly = 'X'",
        "          suppress_commit_work = 'X'",
        "        TABLES containers = lt_containers",
        "          fields_to_containers = lt_screen_fields",
        "          flow_logic = lt_screen_flow",
        "          params = lt_screen_params",
        "        EXCEPTIONS cancelled = 1 already_exists = 2",
        "          program_not_exists = 3 not_executed = 4",
        "          missing_required_field = 5",
        "          illegal_field_value = 6 field_not_allowed = 7",
        "          not_generated = 8 illegal_field_position = 9",
        "          OTHERS = 10.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'SCREEN_PATCH_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.4'.",
        "        RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      REFRESH: ct_fields, ct_flowlogic, ct_params.",
        "      CALL FUNCTION 'RPY_DYNPRO_READ_NATIVE'",
        "        EXPORTING progname = iv_program dynnr = iv_screen",
        "        IMPORTING header = es_header",
        "          dynprotext = ev_dynprotext",
        "        TABLES fieldlist = ct_fields",
        "          flowlogic = ct_flowlogic params = ct_params",
        "          fieldtexts = lt_fieldtexts",
        "        EXCEPTIONS OTHERS = 4.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'SCREEN_VERIFY_FAILED'.",
        "        ev_message = 'Screen patched but re-read failed'.",
        "      ELSE.",
        "        ev_status = 'S'.",
        "        ev_code = 'SCREEN_PATCHED'.",
        "        ev_message = 'Screen patched and re-read successfully'.",
        "      ENDIF.",
        "      ev_version = '1.4'.",
        "      RETURN.",
        "    WHEN 'UPSERT_SCREEN'.",
        "      IF iv_request IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_REQUIRED'.",
        "        ev_message = 'An existing transport is required'.",
        "        ev_version = '1.1'.",
        "        RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_screen_fields, lt_screen_flow,",
        "        lt_screen_params.",
        "      LOOP AT it_source INTO ls_source.",
        "        CLEAR: lv_payload_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_payload_kind",
        "          lv_payload_index_text lv_payload_property",
        "          lv_payload_value.",
        "        IF lv_payload_index_text IS INITIAL",
        "           OR lv_payload_index_text CN '0123456789'.",
        "          ev_status = 'E'.",
        "          ev_code = 'SCREEN_PAYLOAD_INVALID'.",
        "          ev_message = 'Screen payload index is invalid'.",
        "          ev_version = '1.1'.",
        "          RETURN.",
        "        ENDIF.",
        "        lv_payload_index = lv_payload_index_text.",
        "        REPLACE ALL OCCURRENCES OF '%7C'",
        "          IN lv_payload_value WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25'",
        "          IN lv_payload_value WITH '%'.",
        "        IF lv_payload_index <= 0",
        "           OR lv_payload_property IS INITIAL.",
        "          ev_status = 'E'.",
        "          ev_code = 'SCREEN_PAYLOAD_INVALID'.",
        "          ev_message = 'Serialized screen payload is invalid'.",
        "          ev_version = '1.1'.",
        "          RETURN.",
        "        ENDIF.",
        "        CASE lv_payload_kind.",
        "          WHEN 'F'.",
        "            WHILE lines( lt_screen_fields )",
        "              < lv_payload_index.",
        "              CLEAR ls_screen_field.",
        "              APPEND ls_screen_field TO lt_screen_fields.",
        "            ENDWHILE.",
        "            READ TABLE lt_screen_fields",
        "              ASSIGNING <ls_screen_field>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_screen_field>",
        "              TO <lv_payload_component>.",
        "          WHEN 'L'.",
        "            WHILE lines( lt_screen_flow )",
        "              < lv_payload_index.",
        "              CLEAR ls_screen_flow.",
        "              APPEND ls_screen_flow TO lt_screen_flow.",
        "            ENDWHILE.",
        "            READ TABLE lt_screen_flow",
        "              ASSIGNING <ls_screen_flow>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_screen_flow>",
        "              TO <lv_payload_component>.",
        "          WHEN 'P'.",
        "            WHILE lines( lt_screen_params )",
        "              < lv_payload_index.",
        "              CLEAR ls_screen_param.",
        "              APPEND ls_screen_param TO lt_screen_params.",
        "            ENDWHILE.",
        "            READ TABLE lt_screen_params",
        "              ASSIGNING <ls_screen_param>",
        "              INDEX lv_payload_index.",
        "            ASSIGN COMPONENT lv_payload_property",
        "              OF STRUCTURE <ls_screen_param>",
        "              TO <lv_payload_component>.",
        "          WHEN OTHERS.",
        "            ev_status = 'E'.",
        "            ev_code = 'SCREEN_PAYLOAD_INVALID'.",
        "            ev_message = 'Unknown screen payload row type'.",
        "            ev_version = '1.1'.",
        "            RETURN.",
        "        ENDCASE.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'SCREEN_PROPERTY_INVALID'.",
        "          ev_message = 'Unknown screen payload property'.",
        "          ev_version = '1.1'.",
        "          RETURN.",
        "        ENDIF.",
        "        <lv_payload_component> = lv_payload_value.",
        "      ENDLOOP.",
        "      IF lt_screen_fields[] IS INITIAL",
        "         OR lt_screen_flow[] IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'SCREEN_PAYLOAD_REQUIRED'.",
        "        ev_message = 'Fields and flow logic are required'.",
        "        ev_version = '1.1'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM trdir INTO ls_trdir",
        "        WHERE name = iv_program.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'PROGRAM_NOT_FOUND'.",
        "        ev_message = 'Target program does not exist'.",
        "        ev_version = '1.1'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_rpy_header, ls_container.",
        "      REFRESH lt_containers.",
        "      ls_rpy_header-program = iv_program.",
        "      ls_rpy_header-screen = iv_screen.",
        "      ls_rpy_header-language = sy-langu.",
        "      ls_rpy_header-descript = iv_description.",
        "      ls_rpy_header-type = 'N'.",
        "      ls_rpy_header-nextscreen = iv_screen.",
        "      ls_rpy_header-lines = is_header-noli.",
        "      ls_rpy_header-columns = is_header-noco.",
        "      IF ls_rpy_header-lines IS INITIAL.",
        "        ls_rpy_header-lines = 20.",
        "      ENDIF.",
        "      IF ls_rpy_header-columns IS INITIAL.",
        "        ls_rpy_header-columns = 100.",
        "      ENDIF.",
        "      ls_container-type = 'SCREEN'.",
        "      ls_container-name = 'SCREEN'.",
        "      APPEND ls_container TO lt_containers.",
        "      LOOP AT lt_screen_fields ASSIGNING <ls_screen_field>.",
        "        IF <ls_screen_field>-cont_type IS INITIAL.",
        "          <ls_screen_field>-cont_type = 'SCREEN'.",
        "        ENDIF.",
        "        IF <ls_screen_field>-cont_name IS INITIAL.",
        "          <ls_screen_field>-cont_name = 'SCREEN'.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      CALL FUNCTION 'RPY_DYNPRO_INSERT'",
        "        EXPORTING corrnum = iv_request",
        "          header = ls_rpy_header",
        "          suppress_exist_checks = 'X'",
        "          use_corrnum_immediatedly = 'X'",
        "          suppress_commit_work = 'X'",
        "        TABLES containers = lt_containers",
        "          fields_to_containers = lt_screen_fields",
        "          flow_logic = lt_screen_flow",
        "          params = lt_screen_params",
        "        EXCEPTIONS cancelled = 1 already_exists = 2",
        "          program_not_exists = 3 not_executed = 4",
        "          missing_required_field = 5",
        "          illegal_field_value = 6 field_not_allowed = 7",
        "          not_generated = 8 illegal_field_position = 9",
        "          OTHERS = 10.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'SCREEN_SAVE_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.1'.",
        "        RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      REFRESH: ct_fields, ct_flowlogic, ct_params.",
        "      CALL FUNCTION 'RPY_DYNPRO_READ_NATIVE'",
        "        EXPORTING progname = iv_program dynnr = iv_screen",
        "        IMPORTING header = es_header",
        "          dynprotext = ev_dynprotext",
        "        TABLES fieldlist = ct_fields",
        "          flowlogic = ct_flowlogic params = ct_params",
        "          fieldtexts = lt_fieldtexts",
        "        EXCEPTIONS OTHERS = 4.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'SCREEN_VERIFY_FAILED'.",
        "        ev_message = 'Screen saved but re-read failed'.",
        "      ELSE.",
        "        ev_status = 'S'.",
        "        ev_code = 'SCREEN_SAVED'.",
        "        ev_message = 'Screen saved and re-read successfully'.",
        "      ENDIF.",
        "      ev_version = '1.1'.",
        "      RETURN.",
        "    WHEN 'DELETE_TRANSACTION'.",
        "      IF iv_package IS INITIAL OR iv_package = '`$TMP'",
        "         OR iv_request IS INITIAL OR iv_program IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'DELETE_TRANSACTION_INPUT_REQUIRED'.",
        "        ev_message = 'Program package and request are required'.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR ls_tadir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'TRAN'",
        "          AND obj_name = iv_transaction",
        "          AND devclass = iv_package.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSACTION_ASSIGNMENT_MISMATCH'.",
        "        ev_message = 'Transaction package does not match'.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR lv_group_program.",
        "      SELECT SINGLE pgmna FROM tstc INTO lv_group_program",
        "        WHERE tcode = iv_transaction.",
        "      IF sy-subrc <> 0 OR lv_group_program <> iv_program.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSACTION_PROGRAM_MISMATCH'.",
        "        ev_message = 'Transaction program does not match'.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      CALL FUNCTION 'RPY_TRANSACTION_DELETE'",
        "        EXPORTING transaction = iv_transaction",
        "          transport_number = iv_request",
        "          suppress_authority_check = space",
        "          suppress_corr_insert = space",
        "        EXCEPTIONS not_executed = 1 OTHERS = 2.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSACTION_DELETE_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      SELECT SINGLE tcode FROM tstc INTO lv_existing_tcode",
        "        WHERE tcode = iv_transaction.",
        "      IF sy-subrc = 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSACTION_DELETE_VERIFY_FAILED'.",
        "        ev_message = 'Transaction still exists after delete'.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      ev_status = 'S'.",
        "      ev_code = 'TRANSACTION_DELETED'.",
        "      ev_message = 'Transaction deleted and absence verified'.",
        "      ev_version = '1.6'.",
        "      RETURN.",
        "    WHEN 'DELETE_MODULE_POOL'.",
        "      IF iv_package IS INITIAL OR iv_package = '`$TMP'",
        "         OR iv_request IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'DELETE_PROGRAM_INPUT_REQUIRED'.",
        "        ev_message = 'Package and request are required'.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      CLEAR: ls_tadir, ls_trdir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'PROG'",
        "          AND obj_name = iv_program",
        "          AND devclass = iv_package.",
        "      SELECT SINGLE * FROM trdir INTO ls_trdir",
        "        WHERE name = iv_program.",
        "      IF ls_tadir-obj_name IS INITIAL",
        "         OR ( ls_trdir-name IS NOT INITIAL",
        "              AND ls_trdir-subc <> 'M' ).",
        "        ev_status = 'E'.",
        "        ev_code = 'MODULE_POOL_ASSIGNMENT_MISMATCH'.",
        "        ev_message = 'Module pool package or type mismatch'.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR lv_existing_tcode.",
        "      SELECT SINGLE tcode FROM tstc INTO lv_existing_tcode",
        "        WHERE pgmna = iv_program.",
        "      IF sy-subrc = 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'MODULE_POOL_TRANSACTION_EXISTS'.",
        "        ev_message = 'Delete dialog transactions first'.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_request, ls_task, lv_delete_corrnum.",
        "      SELECT SINGLE * FROM e070 INTO ls_request",
        "        WHERE trkorr = iv_request.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_FOUND'.",
        "        ev_message = 'Transport request does not exist'.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF ls_request-strkorr IS NOT INITIAL.",
        "        ls_task = ls_request.",
        "        SELECT SINGLE * FROM e070 INTO ls_request",
        "          WHERE trkorr = ls_task-strkorr.",
        "      ELSE.",
        "        SELECT SINGLE * FROM e070 INTO ls_task",
        "          WHERE strkorr = ls_request-trkorr",
        "            AND as4user = sy-uname AND trstatus = 'D'.",
        "      ENDIF.",
        "      IF ls_request-trfunction <> 'K'",
        "         OR ls_request-trstatus <> 'D'",
        "         OR ls_task-trkorr IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_TASK_NOT_FOUND'.",
        "        ev_message = 'Modifiable user task is required'.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF ls_trdir-name IS INITIAL.",
        "        CLEAR ls_e071.",
        "        SELECT SINGLE * FROM e071 INTO ls_e071",
        "          WHERE trkorr = ls_task-trkorr",
        "            AND pgmid = 'R3TR' AND object = 'PROG'",
        "            AND obj_name = iv_program.",
        "        IF sy-subrc = 0.",
        "          ev_status = 'S'.",
        "          ev_code = 'MODULE_POOL_DELETED'.",
        "          ev_message = 'Task record and repository absence verified'.",
        "        ELSE.",
        "          ev_status = 'E'.",
        "          ev_code = 'MODULE_POOL_DELETE_STATE_INVALID'.",
        "          ev_message = 'Repository absent without a task record'.",
        "        ENDIF.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF ls_trdir-name IS NOT INITIAL.",
        "        lv_delete_program = iv_program.",
        "        lv_delete_corrnum = ls_task-trkorr.",
        "        DELETE REPORT iv_program STATE 'I'.",
        "        CALL FUNCTION 'RS_DELETE_PROGRAM'",
        "          EXPORTING corrnumber = lv_delete_corrnum",
        "            program = lv_delete_program",
        "            suppress_checks = space",
        "            suppress_commit = space suppress_popup = 'X'",
        "            mass_delete_call = space with_cua = 'X'",
        "            with_documentation = 'X' with_dynpro = 'X'",
        "            with_includes = 'X' with_textpool = 'X'",
        "            with_variants = 'X' tadir_devclass = iv_package",
        "            skip_progress_ind = 'X'",
        "          IMPORTING corrnumber = lv_delete_corrnum",
        "            program = lv_delete_program",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc <> 0.",
        "          ROLLBACK WORK.",
        "          ev_status = 'E'.",
        "          ev_code = 'MODULE_POOL_DELETE_FAILED'.",
        "          MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "            WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "            INTO ev_message.",
        "          ev_version = '1.6'.",
        "          RETURN.",
        "        ENDIF.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      CLEAR: ls_tadir, ls_trdir.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'PROG'",
        "          AND obj_name = iv_program.",
        "      SELECT SINGLE * FROM trdir INTO ls_trdir",
        "        WHERE name = iv_program.",
        "      CLEAR ls_e071.",
        "      SELECT SINGLE * FROM e071 INTO ls_e071",
        "        WHERE trkorr = ls_task-trkorr",
        "          AND pgmid = 'R3TR' AND object = 'PROG'",
        "          AND obj_name = iv_program.",
        "      IF ls_trdir-name IS NOT INITIAL",
        "         OR ls_e071-obj_name IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'MODULE_POOL_DELETE_VERIFY_FAILED'.",
        "        CONCATENATE 'Residual TRDIR=' ls_trdir-name",
        "          'TASK=' ls_e071-trkorr INTO ev_message",
        "          SEPARATED BY space.",
        "        ev_version = '1.6'.",
        "        RETURN.",
        "      ENDIF.",
        "      ev_status = 'S'.",
        "      ev_code = 'MODULE_POOL_DELETED'.",
        "      ev_message = 'Task record and repository absence verified'.",
        "      ev_version = '1.6'.",
        "      RETURN.",
        "    WHEN 'CREATE_MODULE_POOL'.",
        "      IF iv_package IS INITIAL OR iv_package = '`$TMP'",
        "         OR iv_request IS INITIAL OR it_source[] IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'CREATE_INPUT_REQUIRED'.",
        "        ev_message = 'Package request and source are required'.",
        "        ev_version = '1.1'.",
        "        RETURN.",
        "      ENDIF.",
        "      lv_title = iv_description.",
        "      CALL FUNCTION 'RPY_PROGRAM_INSERT'",
        "        EXPORTING development_class = iv_package",
        "          program_name = iv_program program_type = 'M'",
        "          title_string = lv_title",
        "          transport_number = iv_request",
        "          suppress_dialog = 'X'",
        "        TABLES source_extended = it_source",
        "        EXCEPTIONS already_exists = 1 cancelled = 2",
        "          name_not_allowed = 3 permission_error = 4",
        "          OTHERS = 5.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'MODULE_POOL_CREATE_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.1'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM trdir INTO ls_trdir",
        "        WHERE name = iv_program AND subc = 'M'.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'PROG'",
        "          AND obj_name = iv_program",
        "          AND devclass = iv_package.",
        "      IF sy-subrc <> 0 OR ls_trdir-name IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'MODULE_POOL_VERIFY_FAILED'.",
        "        ev_message = 'Created program metadata is inconsistent'.",
        "        ev_version = '1.1'.",
        "        RETURN.",
        "      ENDIF.",
        "      GENERATE REPORT iv_program",
        "        MESSAGE lv_message LINE lv_line WORD lv_word.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'MODULE_POOL_GENERATE_FAILED'.",
        "        ev_message = lv_message.",
        "      ELSE.",
        "        ev_status = 'S'.",
        "        ev_code = 'MODULE_POOL_CREATED'.",
        "        ev_message = 'Module pool created and generated'.",
        "      ENDIF.",
        "      ev_version = '1.1'.",
        "      RETURN.",
        "    WHEN 'READ_TRANSPORT_DETAILS'.",
        "      IF iv_request IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_REQUIRED'.",
        "        ev_message = 'Transport number is required'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_request, ls_transport_text.",
        "      SELECT SINGLE * FROM e070 INTO ls_request",
        "        WHERE trkorr = iv_request.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_FOUND'.",
        "        ev_message = 'Transport request or task does not exist'.",
        "        ev_version = '1.7'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM e07t INTO ls_transport_text",
        "        WHERE trkorr = ls_request-trkorr",
        "          AND langu = sy-langu.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'NUMBER' ls_request-trkorr.",
        "      add_repo_payload 'M' '1' 'OWNER' ls_request-as4user.",
        "      add_repo_payload 'M' '1' 'DESC'",
        "        ls_transport_text-as4text.",
        "      add_repo_payload 'M' '1' 'STATUS' ls_request-trstatus.",
        "      REFRESH lt_transport_objects.",
        "      SELECT * FROM e071 INTO TABLE lt_transport_objects",
        "        WHERE trkorr = ls_request-trkorr.",
        "      CLEAR lv_payload_index.",
        "      LOOP AT lt_transport_objects INTO ls_transport_object.",
        "        ADD 1 TO lv_payload_index.",
        "        add_repo_payload 'T' lv_payload_index 'TASK'",
        "          ls_transport_object-trkorr.",
        "        add_repo_payload 'T' lv_payload_index 'PGMID'",
        "          ls_transport_object-pgmid.",
        "        add_repo_payload 'T' lv_payload_index 'TYPE'",
        "          ls_transport_object-object.",
        "        add_repo_payload 'T' lv_payload_index 'NAME'",
        "          ls_transport_object-obj_name.",
        "        add_repo_payload 'T' lv_payload_index 'POSITION'",
        "          ls_transport_object-as4pos.",
        "        add_repo_payload 'T' lv_payload_index 'OBJ_INFO' ''.",
        "      ENDLOOP.",
        "      REFRESH lt_transport_tasks.",
      "      SELECT * FROM e070 INTO TABLE lt_transport_tasks",
      "        WHERE strkorr = ls_request-trkorr.",
      "      CLEAR lv_transport_task_index.",
      "      LOOP AT lt_transport_tasks INTO ls_transport_task.",
      "        ADD 1 TO lv_transport_task_index.",
      "        CLEAR ls_transport_text.",
        "        SELECT SINGLE * FROM e07t INTO ls_transport_text",
        "          WHERE trkorr = ls_transport_task-trkorr",
        "            AND langu = sy-langu.",
      "        add_repo_payload 'F' lv_transport_task_index 'NUMBER'",
      "          ls_transport_task-trkorr.",
      "        add_repo_payload 'F' lv_transport_task_index 'OWNER'",
      "          ls_transport_task-as4user.",
      "        add_repo_payload 'F' lv_transport_task_index 'DESC'",
      "          ls_transport_text-as4text.",
      "        add_repo_payload 'F' lv_transport_task_index 'STATUS'",
      "          ls_transport_task-trstatus.",
        "        REFRESH lt_transport_objects.",
        "        SELECT * FROM e071 INTO TABLE lt_transport_objects",
        "          WHERE trkorr = ls_transport_task-trkorr.",
        "        LOOP AT lt_transport_objects INTO ls_transport_object.",
        "          ADD 1 TO lv_payload_index.",
        "          add_repo_payload 'T' lv_payload_index 'TASK'",
        "            ls_transport_object-trkorr.",
        "          add_repo_payload 'T' lv_payload_index 'PGMID'",
        "            ls_transport_object-pgmid.",
        "          add_repo_payload 'T' lv_payload_index 'TYPE'",
        "            ls_transport_object-object.",
        "          add_repo_payload 'T' lv_payload_index 'NAME'",
        "            ls_transport_object-obj_name.",
        "          add_repo_payload 'T' lv_payload_index 'POSITION'",
        "            ls_transport_object-as4pos.",
        "          add_repo_payload 'T' lv_payload_index 'OBJ_INFO' ''.",
        "        ENDLOOP.",
        "      ENDLOOP.",
        "      ev_status = 'S'.",
        "      ev_code = 'TRANSPORT_DETAILS_READ'.",
        "      ev_message = 'Transport details read successfully'.",
        "      ev_version = '1.7'.",
        "      RETURN.",
        "    WHEN 'READ_SAPSCRIPT_FORM'.",
        "      CLEAR: lv_d7_form_name, lv_d7_form_status,",
        "        lv_d7_language, lv_d7_tdname.",
        "      lv_d7_form_name = iv_object_name.",
        "      IF lv_d7_form_name IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'FORM_NAME_REQUIRED'.",
        "        ev_message = 'SAPscript form name is required'.",
        "        ev_version = '2.8'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF strlen( lv_d7_form_name ) > 16.",
        "        ev_status = 'E'.",
        "        ev_code = 'FORM_NAME_TOO_LONG'.",
        "        ev_message = 'SAPscript form name exceeds 16 characters'.",
        "        ev_version = '2.8'.",
        "        RETURN.",
        "      ENDIF.",
        "      lv_d7_form_status = iv_text_status.",
        "      IF lv_d7_form_status <> '' AND lv_d7_form_status <> 'SAP'",
        "        AND lv_d7_form_status <> 'CUS'.",
        "        ev_status = 'E'.",
        "        ev_code = 'FORM_STATUS_INVALID'.",
        "        ev_message = 'Form status must be empty, SAP or CUS'.",
        "        ev_version = '2.8'.",
        "        RETURN.",
        "      ENDIF.",
        "      lv_d7_language = iv_text_language.",
        "      IF lv_d7_language IS INITIAL.",
        "        lv_d7_language = sy-langu.",
        "      ENDIF.",
        "      IF lv_d7_language CA 'abcdefghijklmnopqrstuvwxyz'.",
        "        ev_status = 'E'.",
        "        ev_code = 'FORM_LANGUAGE_INVALID'.",
        "        ev_message = 'Form language must be upper case'.",
        "        ev_version = '2.8'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF iv_text_version IS NOT INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'FORM_VERSION_UNSUPPORTED'.",
        "        ev_message = 'Reading one form version is not supported'.",
        "        ev_version = '2.8'.",
        "        RETURN.",
        "      ENDIF.",
        "* TDNAME is the form name padded to 16 characters plus the status.",
        "      CONCATENATE lv_d7_form_name lv_d7_form_status",
        "        INTO lv_d7_tdname.",
        "      CLEAR: ls_d7_form_header, ls_d7_text_header, lv_d7_found.",
        "      REFRESH: lt_d7_form_lines, lt_d7_form_pages,",
        "        lt_d7_form_page_windows, lt_d7_form_paragraphs,",
        "        lt_d7_form_strings, lt_d7_form_tabs,",
        "        lt_d7_form_windows.",
        # A delivered form keeps its STXH rows in client 000, so searching only the logon
        # client reports NOT_FOUND for every standard form. THROUGHCLIENT makes READ_FORM
        # search the logon client first and fall back to SAP_ORIGINAL_CLIENT (000) itself.
        "      CALL FUNCTION 'READ_FORM'",
        "        EXPORTING",
        "          client = sy-mandt",
        "          throughclient = 'X'",
        "          form = lv_d7_form_name",
        "          language = lv_d7_language",
        "          status = lv_d7_form_status",
        "        IMPORTING",
        "          form_header = ls_d7_form_header",
        "          found = lv_d7_found",
        "          header = ls_d7_text_header",
        "        TABLES",
        "          form_lines = lt_d7_form_lines",
        "          pages = lt_d7_form_pages",
        "          page_windows = lt_d7_form_page_windows",
        "          paragraphs = lt_d7_form_paragraphs",
        "          strings = lt_d7_form_strings",
        "          tabs = lt_d7_form_tabs",
        "          windows = lt_d7_form_windows.",
        "* FOUND is empty when the STXH definition row does not exist.",
        "* FORM_HEADER is then still pre-filled with READ_FORM defaults, so it",
        "* must never be returned as a successful result.",
        "      IF lv_d7_found IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'NOT_FOUND'.",
        "        ev_message = 'SAPscript form does not exist'.",
        "        ev_version = '2.8'.",
        "        RETURN.",
        "      ENDIF.",
        "      lv_d7_include_source = iv_include_source.",
        "      lv_d7_source_status = 'NOT_REQUESTED'.",
        "      REFRESH lt_d7_definition_lines.",
        "      IF lv_d7_include_source IS NOT INITIAL.",
        "* ID_DEF holds the layout definition. It is deliberately not ID_TXT:",
        "* FORM_LINES above is the text fragment only.",
        "* READ_TEXT gets no THROUGHCLIENT, so the client 000 fallback that",
        "* READ_FORM performs for the form is repeated here explicitly.",
        "        lv_d7_source_language = ls_d7_text_header-tdospras.",
        "        IF lv_d7_source_language IS INITIAL.",
        "          lv_d7_source_language = lv_d7_language.",
        "        ENDIF.",
        "        CLEAR ls_d7_definition_header.",
        "        REFRESH lt_d7_definition_lines.",
        "        CALL FUNCTION 'READ_TEXT'",
        "          EXPORTING",
        "            client = sy-mandt",
        "            id = 'DEF'",
        "            language = lv_d7_source_language",
        "            name = lv_d7_tdname",
        "            object = 'FORM'",
        "          IMPORTING",
        "            header = ls_d7_definition_header",
        "          TABLES",
        "            lines = lt_d7_definition_lines",
        "          EXCEPTIONS",
        "            id = 1",
        "            language = 2",
        "            name = 3",
        "            not_found = 4",
        "            object = 5",
        "            reference_check = 6",
        "            wrong_access_to_archive = 7",
        "            OTHERS = 8.",
        "        IF sy-subrc = 4 AND sy-mandt <> '000'.",
        "          CLEAR ls_d7_definition_header.",
        "          CALL FUNCTION 'READ_TEXT'",
        "            EXPORTING",
        "              client = '000'",
        "              id = 'DEF'",
        "              language = lv_d7_source_language",
        "              name = lv_d7_tdname",
        "              object = 'FORM'",
        "            IMPORTING",
        "              header = ls_d7_definition_header",
        "            TABLES",
        "              lines = lt_d7_definition_lines",
        "            EXCEPTIONS",
        "              id = 1",
        "              language = 2",
        "              name = 3",
        "              not_found = 4",
        "              object = 5",
        "              reference_check = 6",
        "              wrong_access_to_archive = 7",
        "              OTHERS = 8.",
        "        ENDIF.",
        "        IF sy-subrc <> 0.",
        "          REFRESH lt_d7_definition_lines.",
        "          lv_d7_source_status = 'FAILED'.",
        "        ELSE.",
        "          lv_d7_source_status = 'OK'.",
        "        ENDIF.",
        "      ENDIF.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'FORM_NAME' lv_d7_form_name.",
        "      add_repo_payload 'M' '1' 'FORM_STATUS' lv_d7_form_status.",
        "      add_repo_payload 'M' '1' 'LANGUAGE' lv_d7_language.",
        "      add_repo_payload 'M' '1' 'TDNAME' lv_d7_tdname.",
        "      add_repo_payload 'M' '1' 'INCLUDE_SOURCE'",
        "        lv_d7_include_source.",
        "      add_repo_payload 'M' '1' 'SOURCE_STATUS'",
        "        lv_d7_source_status.",
        "      add_repo_component 'H' '1' 'TDFORM' ls_d7_form_header.",
        "      add_repo_component 'H' '1' 'TDSTATUS' ls_d7_form_header.",
        "      add_repo_component 'H' '1' 'TDVERSION' ls_d7_form_header.",
        "      add_repo_component 'H' '1' 'TDFUSER' ls_d7_form_header.",
        "      add_repo_component 'H' '1' 'TDFDATE' ls_d7_form_header.",
        "      add_repo_component 'H' '1' 'TDFTIME' ls_d7_form_header.",
        "      add_repo_component 'H' '1' 'TDLUSER' ls_d7_form_header.",
        "      add_repo_component 'H' '1' 'TDLDATE' ls_d7_form_header.",
        "      add_repo_component 'H' '1' 'TDLTIME' ls_d7_form_header.",
        "      add_repo_component 'H' '1' 'TDSPRAS' ls_d7_form_header.",
        "      add_repo_component 'H' '1' 'TDOSPRAS' ls_d7_form_header.",
        "      add_repo_component 'H' '1' 'TDTEXT' ls_d7_form_header.",
        "      add_repo_component 'T' '1' 'TDOBJECT' ls_d7_text_header.",
        "      add_repo_component 'T' '1' 'TDNAME' ls_d7_text_header.",
        "      add_repo_component 'T' '1' 'TDID' ls_d7_text_header.",
        "      add_repo_component 'T' '1' 'TDSPRAS' ls_d7_text_header.",
        "      add_repo_component 'T' '1' 'TDTITLE' ls_d7_text_header.",
        "      add_repo_component 'T' '1' 'TDVERSION' ls_d7_text_header.",
        "      add_repo_component 'T' '1' 'TDLINESIZE'",
        "        ls_d7_text_header.",
        "      add_repo_component 'T' '1' 'TDTXTLINES'",
        "        ls_d7_text_header.",
        "      emit_d7_rows lt_d7_form_lines 'L' ls_d7_line.",
        "      emit_d7_rows lt_d7_form_pages 'P' ls_d7_page.",
        "      emit_d7_rows lt_d7_form_page_windows 'W'",
        "        ls_d7_page_window.",
        "      emit_d7_rows lt_d7_form_windows 'X' ls_d7_window.",
        "      emit_d7_rows lt_d7_form_paragraphs 'A' ls_d7_paragraph.",
        "      emit_d7_rows lt_d7_form_strings 'S' ls_d7_string.",
        "      emit_d7_rows lt_d7_form_tabs 'B' ls_d7_tab.",
        "      IF lv_d7_include_source IS NOT INITIAL.",
        "        emit_d7_rows lt_d7_definition_lines 'D' ls_d7_line.",
        "      ENDIF.",
        "      ev_status = 'S'.",
        "      ev_code = 'SAPSCRIPT_FORM_READ'.",
        "      ev_message = 'SAPscript form read successfully'.",
        "      ev_version = '2.8'.",
        "      RETURN.",
        "    WHEN 'READ_SMARTSTYLE'.",
        "* read_smartstyle: the two storage forms are never mixed. Form S reads",
        "* the STXS* SmartStyle family through SSF_READ_STYLE; form P converts a",
        "* legacy SAPscript style through SSF_READ_SAPSCRIPT_STYLE, whose",
        "* I_OBJECT defaults to STYLE. Both return SSFCATS plus SSF* rows, so a",
        "* single emit path covers both.",
        "      CLEAR: lv_d7_style_name, lv_d7_style_mode,",
        "        lv_d7_style_active, lv_d7_style_variant,",
        "        lv_d7_style_language, lv_d7_css_status.",
        "      lv_d7_style_name = iv_object_name.",
        "      IF lv_d7_style_name IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'STYLE_NAME_REQUIRED'.",
        "        ev_message = 'Smart style name is required'.",
        "        ev_version = '2.8'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF strlen( lv_d7_style_name ) > 30.",
        "        ev_status = 'E'.",
        "        ev_code = 'STYLE_NAME_TOO_LONG'.",
        "        ev_message = 'Smart style name exceeds 30 characters'.",
        "        ev_version = '2.8'.",
        "        RETURN.",
        "      ENDIF.",
        "      lv_d7_style_mode = iv_style_mode.",
        "      IF lv_d7_style_mode IS INITIAL.",
        "        lv_d7_style_mode = 'S'.",
        "      ENDIF.",
        "      IF lv_d7_style_mode <> 'S' AND lv_d7_style_mode <> 'P'.",
        "        ev_status = 'E'.",
        "        ev_code = 'STYLE_MODE_INVALID'.",
        "        ev_message = 'Style mode must be S or P'.",
        "        ev_version = '2.8'.",
        "        RETURN.",
        "      ENDIF.",
        "      lv_d7_style_active = iv_style_active.",
        "      IF lv_d7_style_active IS INITIAL.",
        "        lv_d7_style_active = 'A'.",
        "      ENDIF.",
        "      IF lv_d7_style_active <> 'A'",
        "        AND lv_d7_style_active <> 'I'.",
        "        ev_status = 'E'.",
        "        ev_code = 'STYLE_ACTIVE_INVALID'.",
        "        ev_message = 'Style active flag must be A or I'.",
        "        ev_version = '2.8'.",
        "        RETURN.",
        "      ENDIF.",
        "      lv_d7_style_variant = iv_style_variant.",
        "      lv_d7_style_language = iv_text_language.",
        "      IF lv_d7_style_language IS INITIAL.",
        "        lv_d7_style_language = sy-langu.",
        "      ENDIF.",
        "      IF lv_d7_style_language",
        "        CA 'abcdefghijklmnopqrstuvwxyz'.",
        "        ev_status = 'E'.",
        "        ev_code = 'STYLE_LANGUAGE_INVALID'.",
        "        ev_message = 'Style language must be upper case'.",
        "        ev_version = '2.8'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF iv_text_version IS NOT INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'STYLE_VERSION_UNSUPPORTED'.",
        "        ev_message = 'Reading one style version is not supported'.",
        "        ev_version = '2.8'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR ls_d7_style_header.",
        "      REFRESH: lt_d7_style_headers, lt_d7_style_paras,",
        "        lt_d7_style_strings, lt_d7_style_tabs.",
        "      IF lv_d7_style_mode = 'S'.",
        "        CALL FUNCTION 'SSF_READ_STYLE'",
        "          EXPORTING",
        "            i_style_name = lv_d7_style_name",
        "            i_style_active_flag = lv_d7_style_active",
        "            i_style_variant = lv_d7_style_variant",
        "            i_style_language = lv_d7_style_language",
        "          IMPORTING",
        "            e_header = ls_d7_style_header",
        "          TABLES",
        "            e_paragraphs = lt_d7_style_paras",
        "            e_strings = lt_d7_style_strings",
        "            e_tabstops = lt_d7_style_tabs",
        "          EXCEPTIONS",
        "            no_name = 1 no_style = 2",
        "            active_style_not_found = 3",
        "            inactive_style_not_found = 4",
        "            no_variant = 5 no_main_variant = 6",
        "            cancelled = 7 no_access_permission = 8",
        "            OTHERS = 9.",
        "        IF sy-subrc <> 0.",
        "* SSF_READ_STYLE reports why it failed only through sy-subrc. Folding",
        "* every exception into one code told the caller nothing it could act",
        "* on: a missing variant, a style with no active version and a missing",
        "* style all looked identical. Map each exception to its own code so the",
        "* caller can tell them apart, and keep OTHERS distinct from all of them.",
        "          ev_status = 'E'.",
        "          ev_version = '2.8'.",
        "          CASE sy-subrc.",
        "            WHEN 1 OR 2.",
        "              ev_code = 'STYLE_NOT_FOUND'.",
        "              ev_message = 'Smart style does not exist'.",
        "            WHEN 3.",
        "              ev_code = 'STYLE_ACTIVE_NOT_FOUND'.",
        "              ev_message = 'Smart style has no active version'.",
        "            WHEN 4.",
        "              ev_code = 'STYLE_INACTIVE_NOT_FOUND'.",
        "              ev_message = 'Smart style has no inactive version'.",
        "            WHEN 5.",
        "              ev_code = 'STYLE_VARIANT_NOT_FOUND'.",
        "              ev_message = 'Smart style variant does not exist'.",
        "            WHEN 6.",
        "              ev_code = 'STYLE_MAIN_VARIANT_NOT_FOUND'.",
        "              ev_message = 'Smart style has no main variant'.",
        "            WHEN 7.",
        "              ev_code = 'STYLE_READ_CANCELLED'.",
        "              ev_message = 'Smart style read was cancelled'.",
        "            WHEN 8.",
        "              ev_code = 'STYLE_NO_ACCESS_PERMISSION'.",
        "              ev_message = 'No permission to read the smart style'.",
        "            WHEN OTHERS.",
        "              ev_code = 'STYLE_READ_FAILED'.",
        "              ev_message = 'Smart style could not be read'.",
        "          ENDCASE.",
        "          RETURN.",
        "        ENDIF.",
        "* The variant list only matters when no variant was asked for.",
        "        IF lv_d7_style_variant IS INITIAL.",
        "          CALL FUNCTION 'SSF_READ_STYLE_ALL_VARIANTS'",
        "            EXPORTING",
        "              i_style_name = lv_d7_style_name",
        "              i_style_active_flag =",
        "                lv_d7_style_active",
        "              i_style_language =",
        "                lv_d7_style_language",
        "            TABLES",
        "              e_headers = lt_d7_style_headers",
        "            EXCEPTIONS",
        "              no_name = 1 no_style = 2",
        "              active_style_not_found = 3",
        "              inactive_style_not_found = 4",
        "              no_main_variant = 5",
        "              cancelled = 6 no_access_permission = 7",
        "              OTHERS = 8.",
        "          IF sy-subrc <> 0.",
        "            REFRESH lt_d7_style_headers.",
        "          ENDIF.",
        "        ENDIF.",
        "      ELSE.",
        "* SSF_READ_SAPSCRIPT_STYLE passes I_NAME/I_OBJECT/I_LANGUAGE by",
        "* value: each actual parameter must carry the formal parameter's own",
        "* type. TDSSNAME/SPRAS differ from TDOBNAME/TDSPRAS, so the bridge",
        "* fields widen them before the call.",
        "        lv_d7_ss_name = lv_d7_style_name.",
        "        lv_d7_ss_object = 'STYLE'.",
        "        lv_d7_ss_language = lv_d7_style_language.",
        "        CALL FUNCTION 'SSF_READ_SAPSCRIPT_STYLE'",
        "          EXPORTING",
        "            i_name = lv_d7_ss_name",
        "            i_object = lv_d7_ss_object",
        "            i_language = lv_d7_ss_language",
        "          IMPORTING",
        "            e_header = ls_d7_style_header",
        "            e_paragraphs = lt_d7_style_paras",
        "            e_strings = lt_d7_style_strings",
        "            e_tabs = lt_d7_style_tabs",
        "          EXCEPTIONS",
        "            no_name = 1 not_found = 2",
        "            illegal_object = 3 OTHERS = 4.",
        "        IF sy-subrc <> 0.",
        "* SSF_READ_SAPSCRIPT_STYLE also reports only sy-subrc. A missing style",
        "* and a rejected object name are different caller mistakes, so they get",
        "* different codes instead of one STYLE_NOT_FOUND.",
        "          ev_status = 'E'.",
        "          ev_version = '2.8'.",
        "          CASE sy-subrc.",
        "            WHEN 1 OR 2.",
        "              ev_code = 'STYLE_NOT_FOUND'.",
        "              ev_message = 'SAPscript style does not exist'.",
        "            WHEN 3.",
        "              ev_code = 'STYLE_OBJECT_INVALID'.",
        "              ev_message = 'SAPscript style object must be STYLE'.",
        "            WHEN OTHERS.",
        "              ev_code = 'STYLE_READ_FAILED'.",
        "              ev_message = 'SAPscript style could not be read'.",
        "          ENDCASE.",
        "          RETURN.",
        "        ENDIF.",
        "      ENDIF.",
        "      lv_d7_css_status = 'NOT_REQUESTED'.",
        "      IF iv_include_css IS NOT INITIAL.",
        "        REFRESH lt_d7_css.",
        "        CLEAR: lv_d7_css_mime, lv_d7_css_length.",
        "        lv_d7_css_style_name = lv_d7_style_name.",
        "        CALL FUNCTION 'SSF_CONVERT_STYLE_TO_CSS'",
        "          EXPORTING",
        "            stylename = lv_d7_css_style_name",
        "          IMPORTING",
        "            fmtcontent = lt_d7_css",
        "            fmttype = lv_d7_css_mime",
        "            fmtlength = lv_d7_css_length",
        "          EXCEPTIONS",
        "            error = 1 OTHERS = 2.",
        "        IF sy-subrc <> 0.",
        "          lv_d7_css_status = 'FAILED'.",
        "          REFRESH lt_d7_css.",
        "        ELSE.",
        "          lv_d7_css_status = 'OK'.",
        "        ENDIF.",
        "      ENDIF.",
        "      REFRESH it_source.",
        "* CSS goes through the payload channel, so every line is split",
        "* into chunks that still fit one ABAPTXT255 payload line.",
        "      IF lv_d7_css_status = 'OK'.",
        "        lv_d7_css_chunk_size = 200.",
        "        CLEAR lv_d7_css_index.",
        "        LOOP AT lt_d7_css INTO lv_d7_css_line.",
        "          ADD 1 TO lv_d7_css_index.",
        "          lv_d7_css_offset = 0.",
        "          lv_d7_css_rest = strlen( lv_d7_css_line ).",
        "          WHILE lv_d7_css_rest > 0.",
        "            IF lv_d7_css_rest > lv_d7_css_chunk_size.",
        "              lv_d7_css_take = lv_d7_css_chunk_size.",
        "            ELSE.",
        "              lv_d7_css_take = lv_d7_css_rest.",
        "            ENDIF.",
        "            lv_d7_css_chunk =",
        "              lv_d7_css_line+lv_d7_css_offset(lv_d7_css_take).",
        "            add_repo_payload 'C' lv_d7_css_index 'LINE'",
        "              lv_d7_css_chunk.",
        "            ADD lv_d7_css_take TO lv_d7_css_offset.",
        "            SUBTRACT lv_d7_css_take FROM lv_d7_css_rest.",
        "          ENDWHILE.",
        "        ENDLOOP.",
        "      ENDIF.",
        "      add_repo_payload 'M' '1' 'STYLE_NAME'",
        "        lv_d7_style_name.",
        "      add_repo_payload 'M' '1' 'STYLE_MODE'",
        "        lv_d7_style_mode.",
        "      add_repo_payload 'M' '1' 'STYLE_ACTIVE'",
        "        lv_d7_style_active.",
        "      add_repo_payload 'M' '1' 'STYLE_VARIANT'",
        "        lv_d7_style_variant.",
        "      add_repo_payload 'M' '1' 'LANGUAGE'",
        "        lv_d7_style_language.",
        "      add_repo_payload 'M' '1' 'CSS_STATUS'",
        "        lv_d7_css_status.",
        "      add_repo_payload 'M' '1' 'CSS_MIME' lv_d7_css_mime.",
        "      lv_d7_css_length_text = lv_d7_css_length.",
        "      CONDENSE lv_d7_css_length_text.",
        "      add_repo_payload 'M' '1' 'CSS_LENGTH'",
        "        lv_d7_css_length_text.",
        "      CLEAR lt_d7_style_header_one.",
        "      APPEND ls_d7_style_header",
        "        TO lt_d7_style_header_one.",
        "      emit_d7_rows lt_d7_style_header_one 'H'",
        "        ls_d7_style_header_row.",
        "      emit_d7_rows lt_d7_style_paras 'A'",
        "        ls_d7_style_para.",
        "      emit_d7_rows lt_d7_style_strings 'S'",
        "        ls_d7_style_string.",
        "      emit_d7_rows lt_d7_style_tabs 'B'",
        "        ls_d7_style_tab.",
        "      emit_d7_rows lt_d7_style_headers 'V'",
        "        ls_d7_style_header_row.",
        "      ev_status = 'S'.",
        "      ev_code = 'SMARTSTYLE_READ'.",
        "      ev_message = 'Smart style read successfully'.",
        "      ev_version = '2.8'.",
        "      RETURN.",
        "    WHEN 'READ_ADOBE_FORM'.",
        "* read_adobe_form: the runtime XDP is FPLAYOUTT-LAYOUT for the",
        "* active state and the empty ID. SEL_LT_BY_NAME_LANG returns",
        "* sy-subrc, so a missing form is a clean not-found, and the",
        "* wrapper raises the FP API exceptions, which must not escape.",
        "      CLEAR: lv_d7_adobe_name, lv_d7_adobe_lang,",
        "        lv_d7_adobe_master, lv_d7_adobe_subrc,",
        "        lv_d7_adobe_xdp, lv_d7_adobe_b64,",
        "        lv_d7_adobe_xdp_len, lv_d7_adobe_ret_len,",
        "        lv_d7_adobe_trunc, lv_d7_adobe_error_text,",
        "        ls_d7_adobe_layout.",
        "      lv_d7_adobe_name = iv_object_name.",
        "      IF lv_d7_adobe_name IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'ADOBE_FORM_NAME_REQUIRED'.",
        "        ev_message = 'Adobe form name is required'.",
        "        ev_version = '2.8'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF strlen( lv_d7_adobe_name ) > 30.",
        "        ev_status = 'E'.",
        "        ev_code = 'ADOBE_FORM_NAME_TOO_LONG'.",
        "        ev_message = 'Adobe form name exceeds 30 characters'.",
        "        ev_version = '2.8'.",
        "        RETURN.",
        "      ENDIF.",
        "      lv_d7_adobe_lang = iv_text_language.",
        "      IF lv_d7_adobe_lang IS INITIAL.",
        "        lv_d7_adobe_lang = sy-langu.",
        "      ENDIF.",
        "      TRANSLATE lv_d7_adobe_lang TO UPPER CASE.",
        "      TRY.",
        "          CALL METHOD cl_fp_db_wrapper=>sel_lt_by_name_lang",
        "            EXPORTING",
        "              iv_name = lv_d7_adobe_name",
        "              iv_lang = lv_d7_adobe_lang",
        "            IMPORTING",
        "              es_layout = ls_d7_adobe_layout",
        "              ev_subrc = lv_d7_adobe_subrc.",
        "        CATCH cx_fp_api_internal INTO lx_d7_adobe_error.",
        "          lv_d7_adobe_error_text =",
        "            lx_d7_adobe_error->get_text( ).",
        "        CATCH cx_fp_api_repository INTO lx_d7_adobe_error.",
        "          lv_d7_adobe_error_text =",
        "            lx_d7_adobe_error->get_text( ).",
        "      ENDTRY.",
        "      IF lv_d7_adobe_error_text IS NOT INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'ADOBE_FORM_READ_FAILED'.",
        "        ev_message = lv_d7_adobe_error_text.",
        "        ev_version = '2.8'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF lv_d7_adobe_subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'ADOBE_FORM_NOT_FOUND'.",
        "        ev_message = 'Adobe form not found'.",
        "        ev_version = '2.8'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR lv_d7_adobe_error_text.",
        "      TRY.",
        "          CALL METHOD cl_fp_db_wrapper=>sel_xdp_by_name_lang",
        "            EXPORTING",
        "              iv_name = lv_d7_adobe_name",
        "              iv_lang = lv_d7_adobe_lang",
        "            IMPORTING",
        "              ev_layout = lv_d7_adobe_xdp",
        "              ev_subrc = lv_d7_adobe_subrc.",
        "        CATCH cx_fp_api_internal INTO lx_d7_adobe_error.",
        "          lv_d7_adobe_error_text =",
        "            lx_d7_adobe_error->get_text( ).",
        "        CATCH cx_fp_api_repository INTO lx_d7_adobe_error.",
        "          lv_d7_adobe_error_text =",
        "            lx_d7_adobe_error->get_text( ).",
        "      ENDTRY.",
        "      IF lv_d7_adobe_error_text IS NOT INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'ADOBE_FORM_READ_FAILED'.",
        "        ev_message = lv_d7_adobe_error_text.",
        "        ev_version = '2.8'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF lv_d7_adobe_xdp IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'ADOBE_FORM_NOT_FOUND'.",
        "        ev_message = 'Adobe form layout is empty'.",
        "        ev_version = '2.8'.",
        "        RETURN.",
        "      ENDIF.",
        "* The master language comes from TADIR (object type SFPF) through",
        "* a read-only lookup, so this path never needs a language check.",
        "      CALL METHOD cl_fp_wb_helper=>form_get_master_language",
        "        EXPORTING",
        "          iv_name = lv_d7_adobe_name",
        "        RECEIVING",
        "          ev_lang = lv_d7_adobe_master.",
        "      lv_d7_adobe_xdp_len = xstrlen( lv_d7_adobe_xdp ).",
        "* A very large layout must not turn the SOAP response into a",
        "* multi-megabyte payload; the cap is reported, never silent.",
        "      lv_d7_adobe_max = 1048576.",
        "      IF lv_d7_adobe_xdp_len > lv_d7_adobe_max.",
        "        lv_d7_adobe_trunc = 'X'.",
        "        lv_d7_adobe_xdp =",
        "          lv_d7_adobe_xdp(lv_d7_adobe_max).",
        "      ENDIF.",
        "      lv_d7_adobe_ret_len = xstrlen( lv_d7_adobe_xdp ).",
        "      CALL FUNCTION 'SCMS_BASE64_ENCODE_STR'",
        "        EXPORTING",
        "          input = lv_d7_adobe_xdp",
        "        IMPORTING",
        "          output = lv_d7_adobe_b64.",
        "      lv_d7_adobe_b64_len = strlen( lv_d7_adobe_b64 ).",
        "      REFRESH it_source.",
        "* Base64 goes through the payload channel, so it is split into",
        "* chunks that still fit one ABAPTXT255 payload line.",
        "      lv_d7_adobe_chunk_size = 200.",
        "      CLEAR lv_d7_adobe_index.",
        "      lv_d7_adobe_offset = 0.",
        "      lv_d7_adobe_rest = lv_d7_adobe_b64_len.",
        "      WHILE lv_d7_adobe_rest > 0.",
        "        IF lv_d7_adobe_rest > lv_d7_adobe_chunk_size.",
        "          lv_d7_adobe_take = lv_d7_adobe_chunk_size.",
        "        ELSE.",
        "          lv_d7_adobe_take = lv_d7_adobe_rest.",
        "        ENDIF.",
        "        lv_d7_adobe_chunk =",
        "          lv_d7_adobe_b64+lv_d7_adobe_offset(lv_d7_adobe_take).",
        "        ADD 1 TO lv_d7_adobe_index.",
        "        add_repo_payload 'Y' lv_d7_adobe_index 'LINE'",
        "          lv_d7_adobe_chunk.",
        "        ADD lv_d7_adobe_take TO lv_d7_adobe_offset.",
        "        SUBTRACT lv_d7_adobe_take FROM lv_d7_adobe_rest.",
        "      ENDWHILE.",
        "      add_repo_payload 'M' '1' 'ADOBE_NAME'",
        "        lv_d7_adobe_name.",
        "      add_repo_payload 'M' '1' 'LANGUAGE'",
        "        lv_d7_adobe_lang.",
        "      add_repo_payload 'M' '1' 'MASTER_LANGUAGE'",
        "        lv_d7_adobe_master.",
        "      add_repo_payload 'M' '1' 'STATE'",
        "        ls_d7_adobe_layout-state.",
        "      add_repo_payload 'M' '1' 'DIRTY'",
        "        ls_d7_adobe_layout-dirty.",
        "      add_repo_payload 'M' '1' 'ID'",
        "        ls_d7_adobe_layout-id.",
        "      lv_d7_adobe_number_text = lv_d7_adobe_xdp_len.",
        "      CONDENSE lv_d7_adobe_number_text.",
        "      add_repo_payload 'M' '1' 'XDP_LENGTH'",
        "        lv_d7_adobe_number_text.",
        "      lv_d7_adobe_number_text = lv_d7_adobe_ret_len.",
        "      CONDENSE lv_d7_adobe_number_text.",
        "      add_repo_payload 'M' '1' 'XDP_RETURNED_LENGTH'",
        "        lv_d7_adobe_number_text.",
        "      add_repo_payload 'M' '1' 'XDP_TRUNCATED'",
        "        lv_d7_adobe_trunc.",
        "      ev_status = 'S'.",
        "      ev_code = 'ADOBE_FORM_READ'.",
        "      ev_message = 'Adobe form read successfully'.",
        "      ev_version = '2.8'.",
        "      RETURN.",
        "    WHEN 'CREATE_TRANSPORT_REQUEST'.",
        # create_transport_request: TR_INSERT_REQUEST_WITH_TASKS is the only entry point
        # (remoteEnabled=false) and it is dialog-free - 0 CALL SCREEN, 0 POPUP_TO,
        # 0 COMMIT WORK, 2 ROLLBACK WORK, and it dequeues on every path. It never
        # commits, so the LUW belongs to this branch, at the top level, and only after
        # the new request has been read back from the database.
        "      CLEAR: lv_d9_request_trkorr, lv_d9_request_existing,",
        "             lv_d9_request_task.",
        "      lv_d9_request_type = iv_request_type.",
        "      TRANSLATE lv_d9_request_type TO UPPER CASE.",
        "      lv_d9_request_text = iv_request_text.",
        "      lv_d9_request_owner = iv_request_owner.",
        "      IF lv_d9_request_owner IS INITIAL.",
        "        lv_d9_request_owner = sy-uname.",
        "      ENDIF.",
        "      TRANSLATE lv_d9_request_owner TO UPPER CASE.",
        "      lv_d9_request_target = iv_request_target.",
        "      TRANSLATE lv_d9_request_target TO UPPER CASE.",
        "      lv_d9_request_allow_dup = iv_request_allow_duplicate.",
        "      IF lv_d9_request_type IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_REQUEST_TYPE_REQUIRED'.",
        "        ev_message = 'Request type is required'.",
        "        ev_version = '2.8'. RETURN.",
        "      ENDIF.",
        # Only K (workbench) and W (customizing) create a request. S, R, X and Q are
        # task types from the same TRFUNCTION domain: passing them here would create an
        # object of the wrong kind, so they are refused before SAP is touched.
        "      IF lv_d9_request_type <> 'K'",
        "         AND lv_d9_request_type <> 'W'.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_REQUEST_TYPE_INVALID'.",
        "        ev_message = 'Only types K and W create a request'.",
        "        ev_version = '2.8'. RETURN.",
        "      ENDIF.",
        "      IF lv_d9_request_text IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_REQUEST_TEXT_REQUIRED'.",
        "        ev_message = 'Request description is required'.",
        "        ev_version = '2.8'. RETURN.",
        "      ENDIF.",
        # Retry safety: TR_INSERT_REQUEST_WITH_TASKS has no external unique key, so a
        # repeated call is matched on owner + type + status + description. E070 holds no
        # description, so E07T is read per candidate. Without this guard a retried call
        # would silently create a second request.
        "      IF lv_d9_request_allow_dup IS INITIAL.",
        "        REFRESH lt_d9_request_candidates.",
        "        SELECT trkorr FROM e070",
        "          INTO TABLE lt_d9_request_candidates",
        "          WHERE trfunction = lv_d9_request_type",
        "            AND as4user = lv_d9_request_owner",
        "            AND trstatus = 'D'.",
        "        LOOP AT lt_d9_request_candidates",
        "          INTO lv_d9_request_candidate.",
        "          CLEAR ls_d9_request_text_db.",
        "          SELECT SINGLE * FROM e07t",
        "            INTO ls_d9_request_text_db",
        "            WHERE trkorr = lv_d9_request_candidate",
        "              AND langu = sy-langu.",
        "          IF sy-subrc = 0.",
        "            IF ls_d9_request_text_db-as4text",
        "               = lv_d9_request_text.",
        "              lv_d9_request_existing =",
        "                lv_d9_request_candidate.",
        "              EXIT.",
        "            ENDIF.",
        "          ENDIF.",
        "        ENDLOOP.",
        "      ENDIF.",
        "      IF lv_d9_request_existing IS NOT INITIAL.",
        "        ev_status = 'S'.",
        "        ev_code = 'TRANSPORT_REQUEST_EXISTS'.",
        "        ev_message =",
        "          'A modifiable request with the same owner and text exists'.",
        "        ev_version = '2.8'.",
        "        REFRESH it_source.",
        "        add_repo_payload 'M' '1' 'TRKORR'",
        "          lv_d9_request_existing.",
        "        add_repo_payload 'M' '1' 'CREATED' ' '.",
        "        add_repo_payload 'M' '1' 'MATCHED_BY'",
        "          'OWNER_TYPE_TEXT'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_d9_request_user, lt_d9_request_users.",
        "      ls_d9_request_user-user = lv_d9_request_owner.",
        "      APPEND ls_d9_request_user TO lt_d9_request_users.",
        "      CLEAR: ls_d9_request_header,",
        "             lt_d9_request_tasks.",
        "      CALL FUNCTION 'TR_INSERT_REQUEST_WITH_TASKS'",
        "        EXPORTING",
        "          iv_type = lv_d9_request_type",
        "          iv_text = lv_d9_request_text",
        "          iv_owner = lv_d9_request_owner",
        "          iv_target = lv_d9_request_target",
        "          it_users = lt_d9_request_users",
        "        IMPORTING",
        "          es_request_header = ls_d9_request_header",
        "          et_task_headers = lt_d9_request_tasks",
        "        EXCEPTIONS",
        "          insert_failed = 1",
        "          enqueue_failed = 2",
        "          OTHERS = 3.",
        # sy-subrc is saved before anything else runs: the FM itself issues ROLLBACK WORK
        # on its failure paths, and a rollback clears sy-subrc.
        "      lv_d9_request_subrc = sy-subrc.",
        "      IF lv_d9_request_subrc <> 0.",
        "        CLEAR lv_d9_request_error_text.",
        "        IF sy-msgid IS NOT INITIAL.",
        "          MESSAGE ID sy-msgid TYPE sy-msgty",
        "            NUMBER sy-msgno",
        "            WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "            INTO lv_d9_request_error_text.",
        "        ENDIF.",
        "        IF lv_d9_request_error_text IS INITIAL.",
        "          lv_d9_request_error_text =",
        "            'Request was not created'.",
        "        ENDIF.",
        "        ev_status = 'E'.",
        "        IF lv_d9_request_subrc = 1.",
        "          ev_code = 'TRANSPORT_REQUEST_INSERT_FAILED'.",
        "        ELSEIF lv_d9_request_subrc = 2.",
        "          ev_code = 'TRANSPORT_REQUEST_ENQUEUE_FAILED'.",
        "        ELSE.",
        "          ev_code = 'TRANSPORT_REQUEST_CREATE_FAILED'.",
        "        ENDIF.",
        "        ev_message = lv_d9_request_error_text.",
        "        ev_version = '2.8'. RETURN.",
        "      ENDIF.",
        # TRKORR is the one TRWBO_REQUEST_HEADER field read here: the FM fills the
        # header with MOVE-CORRESPONDING from E070, so the component is proven present.
        "      lv_d9_request_trkorr = ls_d9_request_header-trkorr.",
        "      IF lv_d9_request_trkorr IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_REQUEST_NUMBER_MISSING'.",
        "        ev_message = 'Request was created without a number'.",
        "        ev_version = '2.8'. RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      CLEAR ls_d9_request_db.",
        "      SELECT SINGLE * FROM e070 INTO ls_d9_request_db",
        "        WHERE trkorr = lv_d9_request_trkorr.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_REQUEST_NOT_PERSISTED'.",
        "        ev_message = 'Request was not found after commit'.",
        "        ev_version = '2.8'. RETURN.",
        "      ENDIF.",
        "      DESCRIBE TABLE lt_d9_request_tasks",
        "        LINES lv_d9_request_tasks.",
        "      lv_d9_request_count_text = lv_d9_request_tasks.",
        "      CONDENSE lv_d9_request_count_text.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'TRKORR'",
        "        lv_d9_request_trkorr.",
        "      add_repo_payload 'M' '1' 'TRFUNCTION'",
        "        ls_d9_request_db-trfunction.",
        "      add_repo_payload 'M' '1' 'TRSTATUS'",
        "        ls_d9_request_db-trstatus.",
        "      add_repo_payload 'M' '1' 'AS4USER'",
        "        ls_d9_request_db-as4user.",
        "      add_repo_payload 'M' '1' 'TARSYSTEM'",
        "        ls_d9_request_db-tarsystem.",
        "      add_repo_payload 'M' '1' 'AS4TEXT'",
        "        lv_d9_request_text.",
        "      add_repo_payload 'M' '1' 'CREATED' 'X'.",
        "      add_repo_payload 'M' '1' 'TASK_COUNT'",
        "        lv_d9_request_count_text.",
        "      CLEAR lv_d9_request_index.",
        "      LOOP AT lt_d9_request_tasks INTO ls_d9_request_task.",
        "        ADD 1 TO lv_d9_request_index.",
        "        add_repo_payload 'T' lv_d9_request_index 'TRKORR'",
        "          ls_d9_request_task-trkorr.",
        "      ENDLOOP.",
        "      ev_status = 'S'.",
        "      ev_code = 'TRANSPORT_REQUEST_CREATED'.",
        "      ev_message = 'Transport request created and persisted'.",
        "      ev_version = '2.8'.",
        "      RETURN.",
        # add_objects_to_transport. The callee owns the enqueue and rolls back on its own failure
        # paths, but it never commits, so this branch commits at the top level and only then proves
        # the result by reading E071 back. Dialog safety comes from iv_with_dialog = 'D': the callee
        # turns that into ls_g-suppress_dialog = 'X', and its only POPUP_TO_CONFIRM_STEP call sits in
        # the iv_with_dialog = 'X' branch. The callee has no CALL SCREEN at all.
        "    WHEN 'ADD_OBJECTS_TO_TRANSPORT'.",
        "      IF iv_add_request IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_REQUEST_REQUIRED'.",
        "        ev_message = 'An existing transport is required'.",
        "        ev_version = '2.8'. RETURN.",
        "      ENDIF.",
        "      lv_d9_add_order_in = iv_add_request.",
        "      REFRESH lt_d9_add_objects.",
        "      LOOP AT it_source INTO ls_source.",
        "        CLEAR: lv_payload_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|' INTO lv_payload_kind",
        "          lv_payload_index_text lv_payload_property",
        "          lv_payload_value.",
        "        IF lv_payload_kind <> 'O'.",
        "          ev_status = 'E'.",
        "          ev_code = 'TRANSPORT_OBJECT_PAYLOAD_INVALID'.",
        "          ev_message = 'Object payload kind is invalid'.",
        "          ev_version = '2.8'. RETURN.",
        "        ENDIF.",
        "        IF lv_payload_index_text IS INITIAL",
        "           OR lv_payload_index_text CN '0123456789'.",
        "          ev_status = 'E'.",
        "          ev_code = 'TRANSPORT_OBJECT_PAYLOAD_INVALID'.",
        "          ev_message = 'Object payload index is invalid'.",
        "          ev_version = '2.8'. RETURN.",
        "        ENDIF.",
        "        lv_payload_index = lv_payload_index_text.",
        "        IF lv_payload_index <= 0",
        "           OR lv_payload_property IS INITIAL.",
        "          ev_status = 'E'.",
        "          ev_code = 'TRANSPORT_OBJECT_PAYLOAD_INVALID'.",
        "          ev_message = 'Serialized object payload is invalid'.",
        "          ev_version = '2.8'. RETURN.",
        "        ENDIF.",
        "        REPLACE ALL OCCURRENCES OF '%7C'",
        "          IN lv_payload_value WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25'",
        "          IN lv_payload_value WITH '%'.",
        "        WHILE lines( lt_d9_add_objects ) < lv_payload_index.",
        "          CLEAR ls_d9_add_object.",
        "          APPEND ls_d9_add_object TO lt_d9_add_objects.",
        "        ENDWHILE.",
        "        READ TABLE lt_d9_add_objects",
        "          ASSIGNING <ls_d9_add_object>",
        "          INDEX lv_payload_index.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'TRANSPORT_OBJECT_PAYLOAD_INVALID'.",
        "          ev_message = 'Object payload row is missing'.",
        "          ev_version = '2.8'. RETURN.",
        "        ENDIF.",
        "        IF lv_payload_property = 'OBJECT_TABLES'.",
        "          ev_status = 'E'.",
        "          ev_code = 'TRANSPORT_OBJECT_KEYS_UNSUPPORTED'.",
        "          ev_message = 'Table keys are not accepted here'.",
        "          ev_version = '2.8'. RETURN.",
        "        ENDIF.",
        "        IF lv_payload_property <> 'PGMID'",
        "           AND lv_payload_property <> 'OBJECT'",
        "           AND lv_payload_property <> 'OBJ_NAME'",
        "           AND lv_payload_property <> 'LANG'.",
        "          ev_status = 'E'.",
        "          ev_code = 'TRANSPORT_OBJECT_PROPERTY_UNKNOWN'.",
        "          ev_message = 'Object property is not accepted'.",
        "          ev_version = '2.8'. RETURN.",
        "        ENDIF.",
        "        ASSIGN COMPONENT lv_payload_property",
        "          OF STRUCTURE <ls_d9_add_object>",
        "          TO <lv_payload_component>.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'TRANSPORT_OBJECT_PROPERTY_UNKNOWN'.",
        "          ev_message = 'Object property does not exist'.",
        "          ev_version = '2.8'. RETURN.",
        "        ENDIF.",
        "        <lv_payload_component> = lv_payload_value.",
        "      ENDLOOP.",
        "      IF lt_d9_add_objects IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_OBJECTS_REQUIRED'.",
        "        ev_message = 'At least one object is required'.",
        "        ev_version = '2.8'. RETURN.",
        "      ENDIF.",
        "      LOOP AT lt_d9_add_objects INTO ls_d9_add_object.",
        "        IF ls_d9_add_object-pgmid IS INITIAL",
        "           OR ls_d9_add_object-object IS INITIAL",
        "           OR ls_d9_add_object-obj_name IS INITIAL.",
        "          ev_status = 'E'.",
        "          ev_code = 'TRANSPORT_OBJECT_INCOMPLETE'.",
        "          ev_message = 'Every object needs PGMID, OBJECT, name'.",
        "          ev_version = '2.8'. RETURN.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      CLEAR: lv_d9_add_order, lv_d9_add_task,",
        "        lv_d9_add_subrc.",
        "      CALL FUNCTION 'TRINT_OBJECTS_CHECK_AND_INSERT'",
        "        EXPORTING",
        "          iv_order = lv_d9_add_order_in",
        "          iv_with_dialog = 'D'",
        "          iv_send_message = 'X'",
        "          it_obj_entries = lt_d9_add_objects",
        "        IMPORTING",
        "          ev_order = lv_d9_add_order",
        "          ev_task = lv_d9_add_task",
        "        EXCEPTIONS",
        "          OTHERS = 1.",
        # sy-subrc is saved before anything else runs: the callee issues ROLLBACK WORK on nine of
        # its failure paths, and a rollback clears sy-subrc.
        "      lv_d9_add_subrc = sy-subrc.",
        "      IF lv_d9_add_subrc <> 0.",
        "        CLEAR lv_d9_add_error_text.",
        "        IF sy-msgid IS NOT INITIAL.",
        "          MESSAGE ID sy-msgid TYPE sy-msgty",
        "            NUMBER sy-msgno",
        "            WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "            INTO lv_d9_add_error_text.",
        "        ENDIF.",
        "        IF lv_d9_add_error_text IS INITIAL.",
        "          lv_d9_add_error_text =",
        "            'Objects were not added'.",
        "        ENDIF.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_OBJECT_INSERT_FAILED'.",
        "        ev_message = lv_d9_add_error_text.",
        "        ev_version = '2.8'. RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      REFRESH lt_d9_add_e071.",
        "      IF lv_d9_add_task IS NOT INITIAL.",
        "        SELECT trkorr pgmid object obj_name FROM e071",
        "          INTO TABLE lt_d9_add_e071",
        "          WHERE trkorr = lv_d9_add_task.",
        "      ENDIF.",
        "      IF lv_d9_add_order IS NOT INITIAL.",
        "        SELECT trkorr pgmid object obj_name FROM e071",
        "          APPENDING TABLE lt_d9_add_e071",
        "          WHERE trkorr = lv_d9_add_order.",
        "      ENDIF.",
        "      lv_d9_add_expected = lines( lt_d9_add_objects ).",
        "      CLEAR lv_d9_add_inserted.",
        "      LOOP AT lt_d9_add_objects INTO ls_d9_add_object.",
        "        CLEAR ls_d9_add_e071.",
        "        READ TABLE lt_d9_add_e071 INTO ls_d9_add_e071",
        "          WITH KEY pgmid = ls_d9_add_object-pgmid",
        "                   object = ls_d9_add_object-object",
        "            obj_name = ls_d9_add_object-obj_name.",
        "        IF sy-subrc = 0.",
        "          ADD 1 TO lv_d9_add_inserted.",
        "        ENDIF.",
        "      ENDLOOP.",
        "      IF lv_d9_add_inserted < lv_d9_add_expected.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_OBJECT_NOT_PERSISTED'.",
        "        ev_message = 'Not every object reached E071'.",
        "        ev_version = '2.8'. RETURN.",
        "      ENDIF.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'REQUEST' lv_d9_add_order.",
        "      add_repo_payload 'M' '1' 'TASK' lv_d9_add_task.",
        "      lv_d9_add_count_text = lv_d9_add_expected.",
        "      CONDENSE lv_d9_add_count_text NO-GAPS.",
        "      add_repo_payload 'M' '1' 'OBJECT_COUNT'",
        "        lv_d9_add_count_text.",
        "      lv_d9_add_count_text = lv_d9_add_inserted.",
        "      CONDENSE lv_d9_add_count_text NO-GAPS.",
        "      add_repo_payload 'M' '1' 'INSERTED_COUNT'",
        "        lv_d9_add_count_text.",
        "      CLEAR lv_d9_add_index.",
        "      LOOP AT lt_d9_add_objects INTO ls_d9_add_object.",
        "        ADD 1 TO lv_d9_add_index.",
        "        add_repo_payload 'T' lv_d9_add_index 'PGMID'",
        "          ls_d9_add_object-pgmid.",
        "        add_repo_payload 'T' lv_d9_add_index 'OBJECT'",
        "          ls_d9_add_object-object.",
        "        add_repo_payload 'T' lv_d9_add_index 'OBJ_NAME'",
        "          ls_d9_add_object-obj_name.",
        "      ENDLOOP.",
        "      ev_status = 'S'.",
        "      ev_code = 'TRANSPORT_OBJECTS_ADDED'.",
        "      ev_message = 'Objects added to the transport'.",
        "      ev_version = '2.8'.",
        "      RETURN.",
        "    WHEN 'READ_TEXT_ELEMENTS' OR 'MERGE_TEXT_ELEMENTS'.",
        "      lv_textpool_program = iv_program.",
        "      lv_tadir_name = iv_program.",
        "      CASE iv_object_type.",
        "        WHEN 'PROG' OR space.",
        "          lv_tadir_type = 'PROG'.",
        "        WHEN 'CLAS'.",
        "          lv_tadir_type = 'CLAS'.",
        "          WHILE strlen( lv_textpool_program ) < 30.",
        "            CONCATENATE lv_textpool_program '='",
        "              INTO lv_textpool_program.",
        "          ENDWHILE.",
        "          CONCATENATE lv_textpool_program 'CP'",
        "            INTO lv_textpool_program.",
        "        WHEN 'FUGR'.",
        "          lv_tadir_type = 'FUGR'.",
        "          CONCATENATE 'SAPL' iv_program",
        "            INTO lv_textpool_program.",
        "        WHEN OTHERS.",
        "          ev_status = 'E'.",
        "          ev_code = 'TEXT_OBJECT_TYPE_INVALID'.",
        "          ev_message = 'Unsupported text element object type'.",
        "          ev_version = '1.7'.",
        "          RETURN.",
        "      ENDCASE.",
        "      SELECT SINGLE * FROM trdir INTO ls_trdir",
        "        WHERE name = lv_textpool_program.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'PROGRAM_NOT_FOUND'.",
        "        ev_message = 'Target program does not exist'.",
        "        ev_version = '1.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      REFRESH lt_textpool.",
        "      READ TEXTPOOL lv_textpool_program INTO lt_textpool",
        "        LANGUAGE sy-langu STATE 'A'.",
        "      IF iv_operation = 'MERGE_TEXT_ELEMENTS'.",
        "        REFRESH lt_text_changes.",
        "        LOOP AT it_source INTO ls_source.",
        "          CLEAR: lv_payload_kind, lv_payload_index_text,",
        "            lv_payload_property, lv_payload_value.",
        "          SPLIT ls_source-line AT '|'",
        "            INTO lv_payload_kind lv_payload_index_text",
        "              lv_payload_property lv_payload_value.",
        "          IF lv_payload_kind <> 'T'",
        "             OR lv_payload_index_text IS INITIAL",
        "             OR lv_payload_index_text CN '0123456789'.",
        "            ev_status = 'E'.",
        "            ev_code = 'TEXT_PAYLOAD_INVALID'.",
        "            ev_message = 'Text payload row is invalid'.",
        "            ev_version = '1.2'.",
        "            RETURN.",
        "          ENDIF.",
        "          lv_payload_index = lv_payload_index_text.",
        "          REPLACE ALL OCCURRENCES OF '%7C'",
        "            IN lv_payload_value WITH '|'.",
        "          REPLACE ALL OCCURRENCES OF '%25'",
        "            IN lv_payload_value WITH '%'.",
        "          WHILE lines( lt_text_changes )",
        "            < lv_payload_index.",
        "            CLEAR ls_text_change.",
        "            APPEND ls_text_change TO lt_text_changes.",
        "          ENDWHILE.",
        "          READ TABLE lt_text_changes",
        "            ASSIGNING <ls_text_change>",
        "            INDEX lv_payload_index.",
        "          CASE lv_payload_property.",
        "            WHEN 'ID'.",
        "              <ls_text_change>-id = lv_payload_value.",
        "            WHEN 'TEXT'.",
        "              <ls_text_change>-entry = lv_payload_value.",
        "            WHEN 'MAXLENGTH'.",
        "              <ls_text_change>-length = lv_payload_value.",
        "            WHEN 'ACTION'.",
        "              <ls_text_change>-action = lv_payload_value.",
        "            WHEN OTHERS.",
        "              ev_status = 'E'.",
        "              ev_code = 'TEXT_PROPERTY_INVALID'.",
        "              ev_message = 'Unknown text payload property'.",
        "              ev_version = '1.2'.",
        "              RETURN.",
        "          ENDCASE.",
        "        ENDLOOP.",
        "        IF lt_text_changes[] IS INITIAL.",
        "          ev_status = 'E'.",
        "          ev_code = 'TEXT_PAYLOAD_REQUIRED'.",
        "          ev_message = 'Text element rows are required'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        LOOP AT lt_text_changes ASSIGNING <ls_text_change>.",
        "          IF <ls_text_change>-id(3) CN",
        "               'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'",
        "             OR <ls_text_change>-id+3 IS NOT INITIAL.",
        "            ev_status = 'E'.",
        "            ev_code = 'TEXT_ID_INVALID'.",
        "            ev_message = 'Text symbol ID must be 3 characters'.",
        "            ev_version = '1.2'.",
        "            RETURN.",
        "          ENDIF.",
        "          IF <ls_text_change>-entry IS INITIAL",
        "             OR <ls_text_change>-length",
        "               < strlen( <ls_text_change>-entry ).",
        "            ev_status = 'E'.",
        "            ev_code = 'TEXT_VALUE_INVALID'.",
        "            ev_message = 'Text value or length is invalid'.",
        "            ev_version = '1.2'.",
        "            RETURN.",
        "          ENDIF.",
        "          READ TABLE lt_textpool INTO ls_textpool",
        "            WITH KEY id = 'I' key = <ls_text_change>-id.",
        "          IF <ls_text_change>-action = 'CREATE'",
        "             AND sy-subrc = 0.",
        "            ev_status = 'E'.",
        "            ev_code = 'TEXT_ELEMENT_EXISTS'.",
        "            ev_message = 'Text element already exists'.",
        "            ev_version = '1.2'.",
        "            RETURN.",
        "          ENDIF.",
        "          IF <ls_text_change>-action = 'UPDATE'",
        "             AND sy-subrc <> 0.",
        "            ev_status = 'E'.",
        "            ev_code = 'TEXT_ELEMENT_NOT_FOUND'.",
        "            ev_message = 'Text element does not exist'.",
        "            ev_version = '1.2'.",
        "            RETURN.",
        "          ENDIF.",
        "          IF <ls_text_change>-action <> 'CREATE'",
        "             AND <ls_text_change>-action <> 'UPDATE'.",
        "            ev_status = 'E'.",
        "            ev_code = 'TEXT_ACTION_INVALID'.",
        "            ev_message = 'Text action is invalid'.",
        "            ev_version = '1.2'.",
        "            RETURN.",
        "          ENDIF.",
        "          CLEAR ls_textpool.",
        "          ls_textpool-id = 'I'.",
        "          ls_textpool-key = <ls_text_change>-id.",
        "          ls_textpool-entry = <ls_text_change>-entry.",
        "          ls_textpool-length = <ls_text_change>-length.",
        "          MODIFY lt_textpool FROM ls_textpool",
        "            TRANSPORTING entry length",
        "            WHERE id = 'I' AND key = <ls_text_change>-id.",
        "          IF sy-subrc <> 0.",
        "            APPEND ls_textpool TO lt_textpool.",
        "          ENDIF.",
        "        ENDLOOP.",
        "        SELECT SINGLE * FROM tadir INTO ls_tadir",
        "          WHERE pgmid = 'R3TR' AND object = lv_tadir_type",
        "            AND obj_name = lv_tadir_name.",
        "        IF sy-subrc <> 0 OR ls_tadir-devclass = '`$TMP'.",
        "          ev_status = 'E'.",
        "          ev_code = 'TRANSPORTABLE_TEXT_OBJECT_REQUIRED'.",
        "          ev_message = 'A transportable text object is required'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        CLEAR lv_recorded_request.",
        "        SELECT e071~trkorr FROM e071 INNER JOIN e070",
        "          ON e070~trkorr = e071~trkorr",
        "          INTO lv_recorded_request",
        "          WHERE ( e071~obj_name = lv_tadir_name",
        "              OR e071~obj_name = lv_textpool_program )",
        "            AND e070~trstatus <> 'R'.",
        "          EXIT.",
        "        ENDSELECT.",
        "        IF lv_recorded_request IS INITIAL.",
        "          ev_status = 'E'.",
        "          ev_code = 'TRANSPORT_ASSIGNMENT_NOT_FOUND'.",
        "          ev_message = 'No open text transport assignment found'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        INSERT TEXTPOOL lv_textpool_program FROM lt_textpool",
        "          LANGUAGE sy-langu STATE 'A'.",
        "        IF sy-subrc <> 0.",
        "          ROLLBACK WORK.",
        "          ev_status = 'E'.",
        "          ev_code = 'TEXT_SAVE_FAILED'.",
        "          ev_message = 'Text pool save failed'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        COMMIT WORK AND WAIT.",
        "        REFRESH lt_textpool.",
        "        READ TEXTPOOL lv_textpool_program INTO lt_textpool",
        "          LANGUAGE sy-langu STATE 'A'.",
        "      ENDIF.",
        "      REFRESH it_source.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = lv_tadir_type",
        "          AND obj_name = lv_tadir_name.",
        "      SELECT SINGLE * FROM trdir INTO ls_trdir",
        "        WHERE name = lv_textpool_program.",
        "      CONCATENATE ls_trdir-udat '000000'",
        "        INTO lv_version.",
        "      add_repo_payload 'M' '1' 'PACKAGE' ls_tadir-devclass.",
        "      add_repo_payload 'M' '1' 'VERSION' lv_version.",
        "      add_repo_payload 'M' '1' 'REQUEST'",
        "        lv_recorded_request.",
        "      CLEAR lv_payload_index.",
        "      LOOP AT lt_textpool INTO ls_textpool WHERE id = 'I'.",
        "        ADD 1 TO lv_payload_index.",
        "        add_repo_payload 'T' lv_payload_index 'ID'",
        "          ls_textpool-key.",
        "        add_repo_payload 'T' lv_payload_index 'TEXT'",
        "          ls_textpool-entry.",
        "        add_repo_payload 'T' lv_payload_index 'MAXLENGTH'",
        "          ls_textpool-length.",
        "      ENDLOOP.",
        "      ev_status = 'S'.",
        "      IF iv_operation = 'MERGE_TEXT_ELEMENTS'.",
        "        ev_code = 'TEXT_ELEMENTS_SAVED'.",
        "        ev_message = 'Text elements saved and verified'.",
        "      ELSE.",
        "        ev_code = 'TEXT_ELEMENTS_READ'.",
        "        ev_message = 'Text elements read successfully'.",
        "      ENDIF.",
        "      ev_version = '1.2'.",
        "      RETURN.",
        "    WHEN 'DELETE_MESSAGE_CLASS'.",
        "      IF iv_object_name IS INITIAL OR iv_package IS INITIAL",
        "         OR iv_package = '`$TMP' OR iv_request IS INITIAL",
        "         OR iv_expected_version IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'DELETE_INPUT_REQUIRED'.",
        "        ev_message = 'Version package and request are required'.",
        "        ev_version = '1.9'. RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_message_info, ls_message_tadir.",
        "      SELECT SINGLE * FROM t100a INTO ls_message_info",
        "        WHERE arbgb = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'MESSAGE_CLASS_NOT_FOUND'.",
        "        ev_message = 'Message class does not exist'.",
        "        ev_version = '1.9'. RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tadir INTO ls_message_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'MSAG'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc <> 0 OR ls_message_tadir-devclass <> iv_package.",
        "        ev_status = 'E'. ev_code = 'PACKAGE_CONFLICT'.",
        "        ev_message = 'Message class package does not match'.",
        "        ev_version = '1.9'. RETURN.",
        "      ENDIF.",
        "      CONCATENATE ls_message_info-ldate ls_message_info-ltime",
        "        INTO lv_version.",
        "      IF lv_version <> iv_expected_version.",
        "        ev_status = 'E'. ev_code = 'VERSION_CONFLICT'.",
        "        ev_message = 'Message class changed since it was read'.",
        "        ev_version = '1.9'. RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_request, ls_task.",
        "      SELECT SINGLE * FROM e070 INTO ls_request",
        "        WHERE trkorr = iv_request.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'TRANSPORT_NOT_FOUND'.",
        "        ev_message = 'Transport request or task does not exist'.",
        "        ev_version = '1.9'. RETURN.",
        "      ENDIF.",
        "      IF ls_request-strkorr IS NOT INITIAL.",
        "        ls_task = ls_request.",
        "        SELECT SINGLE * FROM e070 INTO ls_request",
        "          WHERE trkorr = ls_task-strkorr.",
        "      ELSE.",
        "        SELECT SINGLE * FROM e070 INTO ls_task",
        "          WHERE strkorr = ls_request-trkorr",
        "            AND as4user = sy-uname AND trstatus = 'D'.",
        "      ENDIF.",
        "      IF ls_request-trfunction <> 'K'",
        "         OR ls_request-trstatus <> 'D'",
        "         OR ls_task-trstatus <> 'D'",
        "         OR ls_task-as4user <> sy-uname.",
        "        ev_status = 'E'. ev_code = 'TRANSPORT_NOT_MODIFIABLE'.",
        "        ev_message = 'Open workbench task for user is required'.",
        "        ev_version = '1.9'. RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_message_objects, lt_message_recorded_tadir.",
        "      CLEAR ls_message_object.",
        "      MOVE-CORRESPONDING ls_message_tadir TO ls_message_object.",
        "      ASSIGN COMPONENT 'OBJFUNC' OF STRUCTURE ls_message_object",
        "        TO <lv_payload_component>.",
        "      IF sy-subrc = 0. <lv_payload_component> = 'D'. ENDIF.",
        "      APPEND ls_message_object TO lt_message_objects.",
        "      CALL FUNCTION 'TR_RECORD_OBJ_CHANGE_TO_REQ'",
        "        EXPORTING iv_request = ls_request-trkorr",
        "          it_objects = lt_message_objects",
        "        IMPORTING et_tadir = lt_message_recorded_tadir",
        "        EXCEPTIONS cancel = 1.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'MESSAGE_TRANSPORT_RECORD_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.9'. RETURN.",
        "      ENDIF.",
        "      DELETE FROM t100 WHERE arbgb = iv_object_name.",
        "      DELETE t100a FROM ls_message_info.",
        "      IF sy-subrc = 0.",
        "        DELETE tadir FROM ls_message_tadir.",
        "      ENDIF.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'MESSAGE_CLASS_DELETE_FAILED'.",
        "        ev_message = 'Message repository rows could not be deleted'.",
        "        ev_version = '1.9'. RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      SELECT SINGLE * FROM t100a INTO ls_message_info",
        "        WHERE arbgb = iv_object_name.",
        "      IF sy-subrc = 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'MESSAGE_CLASS_DELETE_VERIFY_FAILED'.",
        "        ev_message = 'Message class still exists after delete'.",
        "        ev_version = '1.9'. RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tadir INTO ls_message_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'MSAG'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc = 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'MESSAGE_CLASS_TADIR_DELETE_FAILED'.",
        "        ev_message = 'Message class directory entry still exists'.",
        "        ev_version = '1.9'. RETURN.",
        "      ENDIF.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'REQUEST' ls_task-trkorr.",
        "      ev_status = 'S'. ev_code = 'MESSAGE_CLASS_DELETED'.",
        "      ev_message = 'Message class deleted and absence verified'.",
        "      ev_version = '1.9'. RETURN.",
        "    WHEN 'UPDATE_MESSAGE_CLASS'.",
        "      IF iv_object_name IS INITIAL OR iv_package IS INITIAL",
        "         OR iv_package = '`$TMP' OR iv_request IS INITIAL",
        "         OR iv_expected_version IS INITIAL",
        "         OR it_source[] IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'UPDATE_INPUT_REQUIRED'.",
        "        ev_message = 'Version package request and messages required'.",
        "        ev_version = '1.8'. RETURN.",
        "      ENDIF.",
        "      REFRESH lt_messages.",
        "      LOOP AT it_source INTO ls_source.",
        "        CLEAR: lv_payload_kind, lv_payload_index_text,",
        "          lv_payload_property, lv_payload_value.",
        "        SPLIT ls_source-line AT '|'",
        "          INTO lv_payload_kind lv_payload_index_text",
        "            lv_payload_property lv_payload_value.",
        "        IF lv_payload_kind <> 'F'",
        "           OR lv_payload_index_text IS INITIAL",
        "           OR lv_payload_index_text CN '0123456789'.",
        "          ev_status = 'E'. ev_code = 'MESSAGE_PAYLOAD_INVALID'.",
        "          ev_message = 'Message payload row is invalid'.",
        "          ev_version = '1.8'. RETURN.",
        "        ENDIF.",
        "        lv_payload_index = lv_payload_index_text.",
        "        REPLACE ALL OCCURRENCES OF '%7C'",
        "          IN lv_payload_value WITH '|'.",
        "        REPLACE ALL OCCURRENCES OF '%25'",
        "          IN lv_payload_value WITH '%'.",
        "        WHILE lines( lt_messages ) < lv_payload_index.",
        "          CLEAR ls_message_row.",
        "          APPEND ls_message_row TO lt_messages.",
        "        ENDWHILE.",
        "        READ TABLE lt_messages ASSIGNING <ls_message_row>",
        "          INDEX lv_payload_index.",
        "        CASE lv_payload_property.",
        "          WHEN 'MSGNR'.",
        "            <ls_message_row>-msgnr = lv_payload_value.",
        "          WHEN 'TEXT'.",
        "            <ls_message_row>-text = lv_payload_value.",
        "          WHEN OTHERS.",
        "            ev_status = 'E'.",
        "            ev_code = 'MESSAGE_PROPERTY_INVALID'.",
        "            ev_message = 'Unknown message payload property'.",
        "            ev_version = '1.8'. RETURN.",
        "        ENDCASE.",
        "      ENDLOOP.",
        "      LOOP AT lt_messages ASSIGNING <ls_message_row>.",
        "        IF <ls_message_row>-msgnr CN '0123456789'",
        "           OR strlen( <ls_message_row>-msgnr ) <> 3",
        "           OR <ls_message_row>-text IS INITIAL.",
        "          ev_status = 'E'. ev_code = 'MESSAGE_VALUE_INVALID'.",
        "          ev_message = 'Message number or text is invalid'.",
        "          ev_version = '1.8'. RETURN.",
        "        ENDIF.",
        "        <ls_message_row>-sprsl = sy-langu.",
        "        <ls_message_row>-arbgb = iv_object_name.",
        "      ENDLOOP.",
        "      CLEAR: ls_message_info, ls_message_tadir.",
        "      SELECT SINGLE * FROM t100a INTO ls_message_info",
        "        WHERE arbgb = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'MESSAGE_CLASS_NOT_FOUND'.",
        "        ev_message = 'Message class does not exist'.",
        "        ev_version = '1.8'. RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tadir INTO ls_message_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'MSAG'",
        "          AND obj_name = iv_object_name.",
        "      IF sy-subrc <> 0 OR ls_message_tadir-devclass <> iv_package.",
        "        ev_status = 'E'. ev_code = 'PACKAGE_CONFLICT'.",
        "        ev_message = 'Message class package does not match'.",
        "        ev_version = '1.8'. RETURN.",
        "      ENDIF.",
        "      CONCATENATE ls_message_info-ldate ls_message_info-ltime",
        "        INTO lv_version.",
        "      IF lv_version <> iv_expected_version.",
        "        ev_status = 'E'. ev_code = 'VERSION_CONFLICT'.",
        "        ev_message = 'Message class changed since it was read'.",
        "        ev_version = '1.8'. RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_request, ls_task.",
        "      SELECT SINGLE * FROM e070 INTO ls_request",
        "        WHERE trkorr = iv_request.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'TRANSPORT_NOT_FOUND'.",
        "        ev_message = 'Transport request or task does not exist'.",
        "        ev_version = '1.8'. RETURN.",
        "      ENDIF.",
        "      IF ls_request-strkorr IS NOT INITIAL.",
        "        ls_task = ls_request.",
        "        SELECT SINGLE * FROM e070 INTO ls_request",
        "          WHERE trkorr = ls_task-strkorr.",
        "      ELSE.",
        "        SELECT SINGLE * FROM e070 INTO ls_task",
        "          WHERE strkorr = ls_request-trkorr",
        "            AND as4user = sy-uname AND trstatus = 'D'.",
        "      ENDIF.",
        "      IF ls_request-trfunction <> 'K'",
        "         OR ls_request-trstatus <> 'D'",
        "         OR ls_task-trstatus <> 'D'",
        "         OR ls_task-as4user <> sy-uname.",
        "        ev_status = 'E'. ev_code = 'TRANSPORT_NOT_MODIFIABLE'.",
        "        ev_message = 'Open workbench task for user is required'.",
        "        ev_version = '1.8'. RETURN.",
        "      ENDIF.",
        "      REFRESH: lt_message_objects, lt_message_recorded_tadir.",
        "      CLEAR ls_message_object.",
        "      MOVE-CORRESPONDING ls_message_tadir TO ls_message_object.",
        "      APPEND ls_message_object TO lt_message_objects.",
        "      CALL FUNCTION 'TR_RECORD_OBJ_CHANGE_TO_REQ'",
        "        EXPORTING iv_request = ls_request-trkorr",
        "          it_objects = lt_message_objects",
        "        IMPORTING et_tadir = lt_message_recorded_tadir",
        "        EXCEPTIONS cancel = 1.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'MESSAGE_TRANSPORT_RECORD_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.8'. RETURN.",
        "      ENDIF.",
        "      ls_message_info-lastuser = sy-uname.",
        "      ls_message_info-ldate = sy-datum.",
        "      ls_message_info-ltime = sy-uzeit.",
        "      UPDATE t100a FROM ls_message_info.",
        "      IF sy-subrc = 0.",
        "        DELETE FROM t100 WHERE sprsl = sy-langu",
        "          AND arbgb = iv_object_name.",
        "        INSERT t100 FROM TABLE lt_messages.",
        "      ENDIF.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'MESSAGE_CLASS_UPDATE_FAILED'.",
        "        ev_message = 'Message repository rows could not be saved'.",
        "        ev_version = '1.8'. RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      lv_recorded_request = ls_task-trkorr.",
        "      REFRESH lt_messages.",
        "      CLEAR ls_message_info.",
        "      SELECT SINGLE * FROM t100a INTO ls_message_info",
        "        WHERE arbgb = iv_object_name.",
        "      SELECT * FROM t100 INTO TABLE lt_messages",
        "        WHERE sprsl = sy-langu AND arbgb = iv_object_name.",
        "      SORT lt_messages BY msgnr.",
        "      CONCATENATE ls_message_info-ldate",
        "        ls_message_info-ltime INTO lv_version.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'PACKAGE' iv_package.",
        "      add_repo_payload 'M' '1' 'VERSION' lv_version.",
        "      add_repo_payload 'M' '1' 'DESCRIPTION'",
        "        ls_message_info-stext.",
        "      add_repo_payload 'M' '1' 'MASTERLANG'",
        "        ls_message_info-masterlang.",
        "      add_repo_payload 'M' '1' 'REQUEST'",
        "        lv_recorded_request.",
        "      LOOP AT lt_messages INTO ls_message_row.",
        "        lv_payload_index = sy-tabix.",
        "        add_repo_payload 'F' lv_payload_index 'MSGNR'",
        "          ls_message_row-msgnr.",
        "        add_repo_payload 'F' lv_payload_index 'TEXT'",
        "          ls_message_row-text.",
        "      ENDLOOP.",
        "      ev_status = 'S'. ev_code = 'MESSAGE_CLASS_UPDATED'.",
        "      ev_message = 'Message class updated and verified'.",
        "      ev_version = '1.8'. RETURN.",
        "    WHEN 'READ_MESSAGE_CLASS' OR 'CREATE_MESSAGE_CLASS'.",
        "      IF iv_object_name IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'MESSAGE_CLASS_REQUIRED'.",
        "        ev_message = 'Message class is required'.",
        "        ev_version = '1.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      IF iv_operation = 'CREATE_MESSAGE_CLASS'.",
        "        IF iv_package IS INITIAL OR iv_package = '`$TMP'",
        "           OR iv_request IS INITIAL OR it_source[] IS INITIAL.",
        "          ev_status = 'E'.",
        "          ev_code = 'CREATE_INPUT_REQUIRED'.",
        "          ev_message = 'Package request and messages required'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        SELECT SINGLE * FROM tadir INTO ls_tadir",
        "          WHERE pgmid = 'R3TR' AND object = 'MSAG'",
        "            AND obj_name = iv_object_name.",
        "        IF sy-subrc = 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'MESSAGE_CLASS_EXISTS'.",
        "          ev_message = 'Message class already exists'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        REFRESH lt_messages.",
        "        LOOP AT it_source INTO ls_source.",
        "          CLEAR: lv_payload_kind, lv_payload_index_text,",
        "            lv_payload_property, lv_payload_value.",
        "          SPLIT ls_source-line AT '|'",
        "            INTO lv_payload_kind lv_payload_index_text",
        "              lv_payload_property lv_payload_value.",
        "          IF lv_payload_kind <> 'F'",
        "             OR lv_payload_index_text IS INITIAL",
        "             OR lv_payload_index_text CN '0123456789'.",
        "            ev_status = 'E'.",
        "            ev_code = 'MESSAGE_PAYLOAD_INVALID'.",
        "            ev_message = 'Message payload row is invalid'.",
        "            ev_version = '1.2'.",
        "            RETURN.",
        "          ENDIF.",
        "          lv_payload_index = lv_payload_index_text.",
        "          REPLACE ALL OCCURRENCES OF '%7C'",
        "            IN lv_payload_value WITH '|'.",
        "          REPLACE ALL OCCURRENCES OF '%25'",
        "            IN lv_payload_value WITH '%'.",
        "          WHILE lines( lt_messages ) < lv_payload_index.",
        "            CLEAR ls_message_row.",
        "            APPEND ls_message_row TO lt_messages.",
        "          ENDWHILE.",
        "          READ TABLE lt_messages ASSIGNING <ls_message_row>",
        "            INDEX lv_payload_index.",
        "          CASE lv_payload_property.",
        "            WHEN 'MSGNR'.",
        "              <ls_message_row>-msgnr = lv_payload_value.",
        "            WHEN 'TEXT'.",
        "              <ls_message_row>-text = lv_payload_value.",
        "            WHEN OTHERS.",
        "              ev_status = 'E'.",
        "              ev_code = 'MESSAGE_PROPERTY_INVALID'.",
        "              ev_message = 'Unknown message payload property'.",
        "              ev_version = '1.2'.",
        "              RETURN.",
        "          ENDCASE.",
        "        ENDLOOP.",
        "        LOOP AT lt_messages ASSIGNING <ls_message_row>.",
        "          IF <ls_message_row>-msgnr CN '0123456789'",
        "             OR strlen( <ls_message_row>-msgnr ) <> 3",
        "             OR <ls_message_row>-text IS INITIAL.",
        "            ev_status = 'E'.",
        "            ev_code = 'MESSAGE_VALUE_INVALID'.",
        "            ev_message = 'Message number or text is invalid'.",
        "            ev_version = '1.2'.",
        "            RETURN.",
        "          ENDIF.",
        "          <ls_message_row>-sprsl = sy-langu.",
        "          <ls_message_row>-arbgb = iv_object_name.",
        "        ENDLOOP.",
        "        SELECT SINGLE * FROM tdevc INTO ls_package",
        "          WHERE devclass = iv_package.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'PACKAGE_NOT_FOUND'.",
        "          ev_message = 'Transportable package does not exist'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        CLEAR: ls_request, ls_task.",
        "        SELECT SINGLE * FROM e070 INTO ls_request",
        "          WHERE trkorr = iv_request.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'TRANSPORT_NOT_FOUND'.",
        "          ev_message = 'Transport request or task does not exist'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        IF ls_request-strkorr IS NOT INITIAL.",
        "          ls_task = ls_request.",
        "          SELECT SINGLE * FROM e070 INTO ls_request",
        "            WHERE trkorr = ls_task-strkorr.",
        "        ELSE.",
        "          SELECT SINGLE * FROM e070 INTO ls_task",
        "            WHERE strkorr = ls_request-trkorr",
        "              AND as4user = sy-uname AND trstatus = 'D'.",
        "        ENDIF.",
        "        IF ls_request-trfunction <> 'K'",
        "           OR ls_request-trstatus <> 'D'",
        "           OR ls_task-trstatus <> 'D'",
        "           OR ls_task-as4user <> sy-uname.",
        "          ev_status = 'E'.",
        "          ev_code = 'TRANSPORT_NOT_MODIFIABLE'.",
        "          ev_message = 'Open workbench task for user is required'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        CLEAR: ls_message_tadir_input, ls_message_tadir.",
        "        ls_message_tadir_input-pgmid = 'R3TR'.",
        "        ls_message_tadir_input-object = 'MSAG'.",
        "        ls_message_tadir_input-obj_name = iv_object_name.",
        "        ls_message_tadir_input-srcsystem = sy-sysid.",
        "        ls_message_tadir_input-author = sy-uname.",
        "        ls_message_tadir_input-devclass = iv_package.",
        "        ls_message_tadir_input-masterlang = sy-langu.",
        "        CALL FUNCTION 'TR_TADIR_INTERFACE'",
        "          EXPORTING wi_test_modus = space",
        "            wi_tadir_pgmid = ls_message_tadir_input-pgmid",
        "            wi_tadir_object = ls_message_tadir_input-object",
        "            wi_tadir_obj_name = ls_message_tadir_input-obj_name",
        "            wi_tadir_srcsystem = ls_message_tadir_input-srcsystem",
        "            wi_tadir_author = ls_message_tadir_input-author",
        "            wi_tadir_devclass = ls_message_tadir_input-devclass",
        "            wi_tadir_masterlang = ls_message_tadir_input-masterlang",
        "          IMPORTING new_tadir_entry = ls_message_tadir",
        "          EXCEPTIONS OTHERS = 1.",
        "        IF sy-subrc <> 0",
        "           OR ls_message_tadir-devclass <> iv_package.",
        "          ROLLBACK WORK.",
        "          ev_status = 'E'.",
        "          ev_code = 'MESSAGE_TADIR_CREATE_FAILED'.",
        "          MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "            WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "            INTO ev_message.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        REFRESH: lt_message_objects, lt_message_recorded_tadir.",
        "        CLEAR ls_message_object.",
        "        MOVE-CORRESPONDING ls_message_tadir TO ls_message_object.",
        "        APPEND ls_message_object TO lt_message_objects.",
        "        CALL FUNCTION 'TR_RECORD_OBJ_CHANGE_TO_REQ'",
        "          EXPORTING iv_request = ls_request-trkorr",
        "            it_objects = lt_message_objects",
        "          IMPORTING et_tadir = lt_message_recorded_tadir",
        "          EXCEPTIONS cancel = 1.",
        "        IF sy-subrc <> 0.",
        "          ROLLBACK WORK.",
        "          ev_status = 'E'.",
        "          ev_code = 'MESSAGE_TRANSPORT_RECORD_FAILED'.",
        "          MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "            WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "            INTO ev_message.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        CLEAR ls_message_info.",
        "        ls_message_info-arbgb = iv_object_name.",
        "        ls_message_info-masterlang = sy-langu.",
        "        ls_message_info-respuser = sy-uname.",
        "        ls_message_info-lastuser = sy-uname.",
        "        ls_message_info-ldate = sy-datum.",
        "        ls_message_info-ltime = sy-uzeit.",
        "        ls_message_info-stext = iv_description.",
        "        INSERT t100a FROM ls_message_info.",
        "        IF sy-subrc = 0.",
        "          INSERT t100 FROM TABLE lt_messages.",
        "        ENDIF.",
        "        IF sy-subrc <> 0.",
        "          ROLLBACK WORK.",
        "          ev_status = 'E'.",
        "          ev_code = 'MESSAGE_CLASS_CREATE_FAILED'.",
        "          ev_message = 'Message repository rows could not be created'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        COMMIT WORK AND WAIT.",
        "        CLEAR ls_e071.",
        "        SELECT SINGLE * FROM e071 INTO ls_e071",
        "          WHERE trkorr = ls_task-trkorr",
        "            AND pgmid = 'R3TR' AND object = 'MSAG'",
        "            AND obj_name = iv_object_name.",
        "        IF sy-subrc <> 0.",
        "          SELECT SINGLE * FROM e071 INTO ls_e071",
        "            WHERE trkorr = ls_request-trkorr",
        "              AND pgmid = 'R3TR' AND object = 'MSAG'",
        "              AND obj_name = iv_object_name.",
        "        ENDIF.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'MESSAGE_TRANSPORT_VERIFY_FAILED'.",
        "          ev_message = 'Message created but transport entry is missing'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "        lv_recorded_request = ls_e071-trkorr.",
        "      ENDIF.",
        "      REFRESH lt_messages.",
        "      CLEAR ls_message_info.",
        "      SELECT SINGLE * FROM t100a INTO ls_message_info",
        "        WHERE arbgb = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'MESSAGE_CLASS_NOT_FOUND'.",
        "        ev_message = 'Message class does not exist'.",
        "        ev_version = '1.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT * FROM t100 INTO TABLE lt_messages",
        "        WHERE sprsl = sy-langu AND arbgb = iv_object_name.",
        "      SORT lt_messages BY msgnr.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'MSAG'",
        "          AND obj_name = iv_object_name.",
        "      CONCATENATE ls_message_info-ldate",
        "        ls_message_info-ltime INTO lv_version.",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'PACKAGE' ls_tadir-devclass.",
        "      add_repo_payload 'M' '1' 'VERSION' lv_version.",
        "      add_repo_payload 'M' '1' 'DESCRIPTION'",
        "        ls_message_info-stext.",
        "      add_repo_payload 'M' '1' 'MASTERLANG'",
        "        ls_message_info-masterlang.",
        "      add_repo_payload 'M' '1' 'REQUEST'",
        "        lv_recorded_request.",
        "      LOOP AT lt_messages INTO ls_message_row.",
        "        lv_payload_index = sy-tabix.",
        "        add_repo_payload 'F' lv_payload_index 'MSGNR'",
        "          ls_message_row-msgnr.",
        "        add_repo_payload 'F' lv_payload_index 'TEXT'",
        "          ls_message_row-text.",
        "      ENDLOOP.",
        "      ev_status = 'S'.",
        "      IF iv_operation = 'CREATE_MESSAGE_CLASS'.",
        "        ev_code = 'MESSAGE_CLASS_CREATED'.",
        "        ev_message = 'Message class created and verified'.",
        "      ELSE.",
        "        ev_code = 'MESSAGE_CLASS_READ'.",
        "        ev_message = 'Message class read successfully'.",
        "      ENDIF.",
        "      ev_version = '1.2'.",
        "      RETURN.",
        "    WHEN 'READ_TRANSACTION'.",
        "      REFRESH: et_tcodes, et_gui_attributes.",
        "      CALL FUNCTION 'RPY_TRANSACTION_READ'",
        "        EXPORTING transaction = iv_transaction",
        "        TABLES tcodes = et_tcodes",
        "          gui_attributes = et_gui_attributes",
        "        EXCEPTIONS permission_error = 1 cancelled = 2",
        "          not_found = 3 object_not_found = 4",
        "          OTHERS = 5.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        IF sy-subrc = 3 OR sy-subrc = 4.",
        "          ev_code = 'TRANSACTION_NOT_FOUND'.",
        "          ev_message = 'Transaction does not exist'.",
        "        ELSE.",
        "          ev_code = 'TRANSACTION_READ_FAILED'.",
        "          MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "            WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "            INTO ev_message.",
        "        ENDIF.",
        "      ELSE.",
        "        CLEAR ls_tadir.",
        "        SELECT SINGLE * FROM tadir INTO ls_tadir",
        "          WHERE pgmid = 'R3TR' AND object = 'TRAN'",
        "            AND obj_name = iv_transaction.",
        "        REFRESH it_source.",
        "        add_repo_payload 'M' '1' 'PACKAGE' ls_tadir-devclass.",
        "        ev_status = 'S'.",
        "        ev_code = 'TRANSACTION_READ'.",
        "        ev_message = 'Transaction read successfully'.",
        "      ENDIF.",
        "      ev_version = '1.2'.",
        "      RETURN.",
        "    WHEN 'CREATE_REPORT_TRANSACTION'.",
        "      IF iv_program IS INITIAL",
        "         OR ( iv_program(1) <> 'Z' AND iv_program(1) <> 'Y' )",
        "         OR iv_package IS INITIAL OR iv_package = '`$TMP'",
        "         OR iv_request IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'CREATE_INPUT_REQUIRED'.",
        "        ev_message = 'Report package and request are required'.",
        "        ev_version = '1.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM trdir INTO ls_trdir",
        "        WHERE name = iv_program AND subc = '1'.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'EXECUTABLE_REPORT_NOT_FOUND'.",
        "        ev_message = 'Executable report does not exist'.",
        "        ev_version = '1.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'PROG'",
        "          AND obj_name = iv_program",
        "          AND devclass = iv_package.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'REPORT_PACKAGE_MISMATCH'.",
        "        ev_message = 'Report package does not match'.",
        "        ev_version = '1.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      CLEAR lv_existing_tcode.",
        "      SELECT SINGLE tcode FROM tstc INTO lv_existing_tcode",
        "        WHERE tcode = iv_transaction.",
        "      IF sy-subrc = 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSACTION_EXISTS'.",
        "        ev_message = 'Transaction already exists'.",
        "        ev_version = '1.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      lv_report_variant = iv_object_name.",
        "      IF lv_report_variant IS NOT INITIAL.",
        "        SELECT SINGLE variant FROM varid",
        "          INTO lv_report_variant",
        "          WHERE report = iv_program",
        "            AND variant = lv_report_variant.",
        "        IF sy-subrc <> 0.",
        "          ev_status = 'E'.",
        "          ev_code = 'REPORT_VARIANT_NOT_FOUND'.",
        "          ev_message = 'Report variant does not exist'.",
        "          ev_version = '1.2'.",
        "          RETURN.",
        "        ENDIF.",
        "      ENDIF.",
        "      CALL FUNCTION 'RPY_TRANSACTION_INSERT'",
        "        EXPORTING transaction = iv_transaction",
        "          program = iv_program language = sy-langu",
        "          development_class = iv_package",
        "          transport_number = iv_request",
        "          transaction_type = 'R' shorttext = iv_description",
        "          variant = lv_report_variant",
        "          html_enabled = 'X' wingui_enabled = 'X'",
        "        EXCEPTIONS OTHERS = 1.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'REPORT_TRANSACTION_CREATE_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.2'.",
        "        RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      REFRESH: et_tcodes, et_gui_attributes.",
        "      CALL FUNCTION 'RPY_TRANSACTION_READ'",
        "        EXPORTING transaction = iv_transaction",
        "        TABLES tcodes = et_tcodes",
        "          gui_attributes = et_gui_attributes",
        "        EXCEPTIONS OTHERS = 5.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSACTION_VERIFY_FAILED'.",
        "        ev_message = 'Transaction created but re-read failed'.",
        "      ELSE.",
        "        ev_status = 'S'.",
        "        ev_code = 'REPORT_TRANSACTION_CREATED'.",
        "        ev_message = 'Report transaction created and re-read'.",
        "      ENDIF.",
        "      ev_version = '1.2'.",
        "      RETURN.",
        "    WHEN 'CREATE_TRANSACTION'.",
        "      IF iv_program IS INITIAL",
        "         OR ( iv_program(1) <> 'Z' AND iv_program(1) <> 'Y' )",
        "         OR iv_package IS INITIAL OR iv_package = '`$TMP'",
        "         OR iv_request IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'CREATE_INPUT_REQUIRED'.",
        "        ev_message = 'Program package and request are required'.",
        "        ev_version = '1.1'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM d020s INTO es_header",
        "        WHERE prog = iv_program AND dnum = iv_screen.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'SCREEN_NOT_FOUND'.",
        "        ev_message = 'Target screen does not exist'.",
        "        ev_version = '1.1'.",
        "        RETURN.",
        "      ENDIF.",
        "      CALL FUNCTION 'RPY_TRANSACTION_INSERT'",
        "        EXPORTING transaction = iv_transaction",
        "          program = iv_program dynpro = iv_screen",
        "          development_class = iv_package",
        "          transport_number = iv_request",
        "          transaction_type = 'D' shorttext = iv_description",
        "          html_enabled = 'X' wingui_enabled = 'X'",
        "        EXCEPTIONS cancelled = 1 already_exist = 2",
        "          permission_error = 3 name_not_allowed = 4",
        "          name_conflict = 5 illegal_type = 6",
        "          object_inconsistent = 7 db_access_error = 8",
        "          OTHERS = 9.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSACTION_CREATE_FAILED'.",
        "        MESSAGE ID sy-msgid TYPE 'S' NUMBER sy-msgno",
        "          WITH sy-msgv1 sy-msgv2 sy-msgv3 sy-msgv4",
        "          INTO ev_message.",
        "        ev_version = '1.1'.",
        "        RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      REFRESH: et_tcodes, et_gui_attributes.",
        "      CALL FUNCTION 'RPY_TRANSACTION_READ'",
        "        EXPORTING transaction = iv_transaction",
        "        TABLES tcodes = et_tcodes",
        "          gui_attributes = et_gui_attributes",
        "        EXCEPTIONS OTHERS = 5.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSACTION_VERIFY_FAILED'.",
        "        ev_message = 'Transaction created but re-read failed'.",
        "      ELSE.",
        "        ev_status = 'S'.",
        "        ev_code = 'TRANSACTION_CREATED'.",
        "        ev_message = 'Transaction created and re-read'.",
        "      ENDIF.",
        "      ev_version = '1.1'.",
        "      RETURN.",
        "    WHEN 'WRITE_FUNCTION_SOURCE'.",
        "      lv_function_name = iv_object_name.",
        "      IF iv_object_name IS INITIAL",
        "         OR ( iv_object_name(1) <> 'Z'",
        "         AND iv_object_name(1) <> 'Y' )",
        "         OR iv_package IS INITIAL OR iv_package = '`$TMP'",
        "         OR iv_request IS INITIAL OR it_source[] IS INITIAL.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_SOURCE_INPUT_REQUIRED'.",
        "        ev_message = 'Function package request and body required'.",
        "        ev_version = '2.9'.",
        "        RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tdevc INTO ls_package",
        "        WHERE devclass = iv_package.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'PACKAGE_NOT_FOUND'.",
        "        ev_message = 'Transportable package does not exist'.",
        "        ev_version = '2.9'. RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tfdir INTO ls_tfdir",
        "        WHERE funcname = iv_object_name.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'FUNCTION_NOT_FOUND'.",
        "        ev_message = 'Function module does not exist'.",
        "        ev_version = '2.9'. RETURN.",
        "      ENDIF.",
        "      lv_function_pool = ls_tfdir-pname+4.",
        '      " TFDIR-INCLUDE is the include suffix, not the include program.',
        '      " The physical include is resolved with the standard API; the',
        '      " READ REPORT below rejects any name that cannot be read.',
        "      CLEAR: lv_fm_include, lv_fm_include_group.",
        "      lv_fm_include_name = iv_object_name.",
        "      SELECT SINGLE funcname FROM tfdir INTO lv_fm_include_probe",
        "        WHERE funcname = 'FUNCTION_INCLUDE_INFO'.",
        "      IF sy-subrc = 0.",
        "        CALL FUNCTION 'FUNCTION_INCLUDE_INFO'",
        "          CHANGING funcname = lv_fm_include_name",
        "            group = lv_fm_include_group",
        "            include = lv_fm_include",
        "          EXCEPTIONS function_not_exists = 1",
        "            include_not_exists = 2 group_not_exists = 3",
        "            no_selections = 4 no_function_include = 5",
        "            OTHERS = 6.",
        "      ENDIF.",
        "      IF lv_fm_include IS INITIAL.",
        "        CONCATENATE 'L' lv_function_pool 'U' ls_tfdir-include",
        "          INTO lv_fm_include.",
        "      ENDIF.",
        "      IF iv_program IS NOT INITIAL",
        "         AND iv_program <> lv_function_pool.",
        "        ev_status = 'E'. ev_code = 'FUNCTION_GROUP_MISMATCH'.",
        "        ev_message = 'Function group does not own the module'.",
        "        ev_version = '2.9'. RETURN.",
        "      ENDIF.",
        "      IF lv_function_pool IS INITIAL",
        "         OR ( lv_function_pool(1) <> 'Z'",
        "         AND lv_function_pool(1) <> 'Y' ).",
        "        ev_status = 'E'.",
        "        ev_code = 'CUSTOMER_FUNCTION_REQUIRED'.",
        "        ev_message = 'Only customer function groups are valid'.",
        "        ev_version = '2.9'. RETURN.",
        "      ENDIF.",
        "      IF lv_function_pool = 'ZORVANTA_MCP_CORE'.",
        "        ev_status = 'E'.",
        "        ev_code = 'SELF_FUNCTION_GROUP_FORBIDDEN'.",
        "        ev_message = 'Helper function group cannot rewrite itself'.",
        "        ev_version = '2.9'. RETURN.",
        "      ENDIF.",
        "      SELECT SINGLE * FROM tadir INTO ls_tadir",
        "        WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "          AND obj_name = lv_function_pool",
        "          AND devclass = iv_package.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_GROUP_PACKAGE_MISMATCH'.",
        "        ev_message = 'Function group package does not match'.",
        "        ev_version = '2.9'. RETURN.",
        "      ENDIF.",
        "      CLEAR: ls_request, ls_task.",
        "      SELECT SINGLE * FROM e070 INTO ls_request",
        "        WHERE trkorr = iv_request.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'TRANSPORT_NOT_FOUND'.",
        "        ev_message = 'Transport request or task was not found'.",
        "        ev_version = '2.9'. RETURN.",
        "      ENDIF.",
        "      IF ls_request-strkorr IS NOT INITIAL.",
        "        ls_task = ls_request.",
        "        SELECT SINGLE * FROM e070 INTO ls_request",
        "          WHERE trkorr = ls_task-strkorr.",
        "      ELSE.",
        "        SELECT SINGLE * FROM e070 INTO ls_task",
        "          WHERE strkorr = ls_request-trkorr",
        "            AND as4user = sy-uname AND trstatus = 'D'.",
        "      ENDIF.",
        "      IF ls_request-trfunction <> 'K'",
        "         OR ls_request-trstatus <> 'D'",
        "         OR ls_task-trstatus <> 'D'",
        "         OR ls_task-as4user <> sy-uname.",
        "        ev_status = 'E'.",
        "        ev_code = 'TRANSPORT_NOT_MODIFIABLE'.",
        "        ev_message = 'Open user workbench task is required'.",
        "        ev_version = '2.9'. RETURN.",
        "      ENDIF.",
        "      CLEAR ls_e071.",
        "      SELECT SINGLE * FROM e071 INTO ls_e071",
        "        WHERE ( trkorr = ls_task-trkorr",
        "           OR trkorr = ls_request-trkorr )",
        "          AND ( obj_name = lv_function_pool",
        "             OR obj_name = lv_function_name",
        "             OR obj_name = lv_fm_include ).",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_TRANSPORT_MISMATCH'.",
        "        ev_message = 'Function module is not recorded in the request'.",
        "        ev_version = '2.9'. RETURN.",
        "      ENDIF.",
        "      REFRESH lt_fm_body.",
        "      LOOP AT it_source INTO ls_source.",
        "        lv_fm_body_text = ls_source-line.",
        "        lv_fm_body_length = strlen( lv_fm_body_text ).",
        "        WHILE lv_fm_body_length > 0.",
        "          lv_fm_body_length = lv_fm_body_length - 1.",
        "          IF lv_fm_body_text+lv_fm_body_length(1) <> ' '.",
        "            lv_fm_body_length = lv_fm_body_length + 1.",
        "            EXIT.",
        "          ENDIF.",
        "        ENDWHILE.",
        "        CLEAR lv_fm_body_line.",
        "        IF lv_fm_body_length > 0.",
        "          lv_fm_body_line = lv_fm_body_text(lv_fm_body_length).",
        "        ENDIF.",
        "        APPEND lv_fm_body_line TO lt_fm_body.",
        "      ENDLOOP.",
        "      WHILE lines( lt_fm_body ) > 0.",
        "        READ TABLE lt_fm_body INTO lv_fm_body_line INDEX 1.",
        "        IF lv_fm_body_line IS INITIAL.",
        "          DELETE lt_fm_body INDEX 1.",
        "        ELSE.",
        "          EXIT.",
        "        ENDIF.",
        "      ENDWHILE.",
        "      lv_fm_body_lines = lines( lt_fm_body ).",
        "      WHILE lv_fm_body_lines > 0.",
        "        READ TABLE lt_fm_body INTO lv_fm_body_line",
        "          INDEX lv_fm_body_lines.",
        "        IF lv_fm_body_line IS INITIAL.",
        "          DELETE lt_fm_body INDEX lv_fm_body_lines.",
        "          lv_fm_body_lines = lv_fm_body_lines - 1.",
        "        ELSE.",
        "          EXIT.",
        "        ENDIF.",
        "      ENDWHILE.",
        "      lv_fm_body_lines = lines( lt_fm_body ).",
        "      IF lv_fm_body_lines = 0.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_SOURCE_BODY_EMPTY'.",
        "        ev_message = 'Replacement function body is empty'.",
        "        ev_version = '2.9'. RETURN.",
        "      ENDIF.",
        "      CLEAR lv_fm_hash_input.",
        '      " Join the body lines with one LF byte, as the service does.',
        '      " x-to-c expands hex digits, so MOVE x(0A) TO c gave "0" instead;',
        '      " assign the LF character, not the hex byte.',
        "      CLEAR lv_fm_lf.",
        "      lv_fm_lf = cl_abap_char_utilities=>newline.",
        "      CONCATENATE LINES OF lt_fm_body INTO lv_fm_hash_input",
        "        SEPARATED BY lv_fm_lf.",
        "      CLEAR lv_fm_body_hash.",
        "      TRY.",
        "          CALL METHOD cl_abap_message_digest=>calculate_hash_for_char",
        "            EXPORTING if_algorithm = 'SHA256'",
        "              if_data = lv_fm_hash_input",
        "            IMPORTING ef_hashstring = lv_fm_body_hash.",
        "        CATCH cx_root.",
        "          CLEAR lv_fm_body_hash.",
        "      ENDTRY.",
        "      IF strlen( lv_fm_body_hash ) <> 64.",
        "        CLEAR lv_fm_body_hash.",
        "      ELSE.",
        "        TRANSLATE lv_fm_body_hash TO LOWER CASE.",
        "      ENDIF.",
        "      CALL FUNCTION 'ENQUEUE_ESFUNCTION'",
        "        EXPORTING funcname = lv_function_name",
        "          mode_tfdir = lv_fm_lock_mode",
        "        EXCEPTIONS foreign_lock = 1 OTHERS = 2.",
        "      IF sy-subrc <> 0.",
        "        ev_status = 'E'. ev_code = 'FUNCTION_LOCKED'.",
        "        ev_message = 'Function module is locked'.",
        "        ev_version = '2.9'. RETURN.",
        "      ENDIF.",
        "      REFRESH lt_fm_include.",
        "      READ REPORT lv_fm_include INTO lt_fm_include.",
        "      IF sy-subrc <> 0.",
        "        CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "          EXPORTING funcname = lv_function_name.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_INCLUDE_READ_FAILED'.",
        "        ev_message = 'Function include could not be read'.",
        "        ev_version = '2.9'. RETURN.",
        "      ENDIF.",
        "      CLEAR: lv_fm_body_start, lv_fm_marker_count.",
        "      LOOP AT lt_fm_include INTO lv_fm_include_line.",
        "        lv_fm_body_text = lv_fm_include_line.",
        "        lv_fm_body_length = strlen( lv_fm_body_text ).",
        "        WHILE lv_fm_body_length > 0.",
        "          lv_fm_body_length = lv_fm_body_length - 1.",
        "          IF lv_fm_body_text+lv_fm_body_length(1) <> ' '.",
        "            lv_fm_body_length = lv_fm_body_length + 1.",
        "            EXIT.",
        "          ENDIF.",
        "        ENDWHILE.",
        "        CLEAR lv_fm_body_line.",
        "        IF lv_fm_body_length > 0.",
        "          lv_fm_body_line = lv_fm_body_text(lv_fm_body_length).",
        "        ENDIF.",
        "        IF lv_fm_body_length > 1.",
        '          IF lv_fm_body_line(2) = ''*"''.',
        "            lv_fm_body_line = lv_fm_body_line+2.",
        "            IF lv_fm_body_line CA '-'",
        "               AND lv_fm_body_line CO '-'.",
        "              lv_fm_marker_count = lv_fm_marker_count + 1.",
        "              IF lv_fm_marker_count = 2.",
        "                lv_fm_body_start = sy-tabix + 1.",
        "              ENDIF.",
        "            ENDIF.",
        "          ENDIF.",
        "        ENDIF.",
        "      ENDLOOP.",
        '      " Layout without the interface skeleton: the interface lives',
        '      " in the FM parameter tables, so the include is FUNCTION ... .',
        '      " followed by the body. The body starts after the statement',
        '      " that ends the FUNCTION statement, as on the service side.',
        "      IF lv_fm_body_start IS INITIAL.",
        "        LOOP AT lt_fm_include INTO lv_fm_include_line.",
        "          lv_fm_body_text = lv_fm_include_line.",
        "          lv_fm_body_length = strlen( lv_fm_body_text ).",
        "          WHILE lv_fm_body_length > 0.",
        "            lv_fm_body_length = lv_fm_body_length - 1.",
        "            IF lv_fm_body_text+lv_fm_body_length(1) <> ' '.",
        "              lv_fm_body_length = lv_fm_body_length + 1.",
        "              EXIT.",
        "            ENDIF.",
        "          ENDWHILE.",
        "          IF sy-tabix = 1.",
        "            IF lv_fm_body_length < 8.",
        "              EXIT.",
        "            ENDIF.",
        "            lv_fm_body_line = lv_fm_body_text(lv_fm_body_length).",
        "            TRANSLATE lv_fm_body_line TO UPPER CASE.",
        "            IF lv_fm_body_line(8) <> 'FUNCTION'.",
        "              EXIT.",
        "            ENDIF.",
        "          ELSE.",
        "            IF lv_fm_body_length > 0.",
        "              lv_fm_body_length = lv_fm_body_length - 1.",
        "              IF lv_fm_body_text+lv_fm_body_length(1) = '.'.",
        "                lv_fm_body_start = sy-tabix + 1.",
        "                EXIT.",
        "              ENDIF.",
        "            ENDIF.",
        "          ENDIF.",
        "        ENDLOOP.",
        "      ENDIF.",
        "      IF lv_fm_body_start IS INITIAL.",
        "        CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "          EXPORTING funcname = lv_function_name.",
        "        ev_status = 'E'. ev_code = 'SOURCE_MARKER_ERROR'.",
        "        ev_message = 'Function interface skeleton marker is missing'.",
        "        ev_version = '2.9'. RETURN.",
        "      ENDIF.",
        "      lv_fm_end_index = lines( lt_fm_include ).",
        "      CLEAR lv_fm_end_found.",
        "      WHILE lv_fm_end_index > lv_fm_body_start.",
        "        READ TABLE lt_fm_include INTO lv_fm_include_line",
        "          INDEX lv_fm_end_index.",
        "        IF sy-subrc <> 0.",
        "          EXIT.",
        "        ENDIF.",
        "        IF lv_fm_include_line IS INITIAL.",
        "          lv_fm_end_index = lv_fm_end_index - 1.",
        "        ELSE.",
        "          IF lv_fm_include_line CS 'ENDFUNCTION'.",
        "            lv_fm_end_found = 'X'.",
        "          ENDIF.",
        "          EXIT.",
        "        ENDIF.",
        "      ENDWHILE.",
        "      IF lv_fm_end_found IS INITIAL.",
        "        CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "          EXPORTING funcname = lv_function_name.",
        "        ev_status = 'E'. ev_code = 'SOURCE_END_MARKER_ERROR'.",
        "        ev_message = 'Function end statement is missing'.",
        "        ev_version = '2.9'. RETURN.",
        "      ENDIF.",
        "      REFRESH lt_fm_current_body.",
        "      lv_fm_body_index = lv_fm_body_start.",
        "      WHILE lv_fm_body_index < lv_fm_end_index.",
        "        READ TABLE lt_fm_include INTO lv_fm_include_line",
        "          INDEX lv_fm_body_index.",
        "        IF sy-subrc = 0.",
        "          lv_fm_body_text = lv_fm_include_line.",
        "          lv_fm_body_length = strlen( lv_fm_body_text ).",
        "          WHILE lv_fm_body_length > 0.",
        "            lv_fm_body_length = lv_fm_body_length - 1.",
        "            IF lv_fm_body_text+lv_fm_body_length(1) <> ' '.",
        "              lv_fm_body_length = lv_fm_body_length + 1.",
        "              EXIT.",
        "            ENDIF.",
        "          ENDWHILE.",
        "          CLEAR lv_fm_body_line.",
        "          IF lv_fm_body_length > 0.",
        "            lv_fm_body_line = lv_fm_body_text(lv_fm_body_length).",
        "          ENDIF.",
        "          APPEND lv_fm_body_line TO lt_fm_current_body.",
        "        ENDIF.",
        "        lv_fm_body_index = lv_fm_body_index + 1.",
        "      ENDWHILE.",
        "      WHILE lines( lt_fm_current_body ) > 0.",
        "        READ TABLE lt_fm_current_body INTO lv_fm_body_line INDEX 1.",
        "        IF lv_fm_body_line IS INITIAL.",
        "          DELETE lt_fm_current_body INDEX 1.",
        "        ELSE.",
        "          EXIT.",
        "        ENDIF.",
        "      ENDWHILE.",
        "      lv_fm_body_lines = lines( lt_fm_current_body ).",
        "      WHILE lv_fm_body_lines > 0.",
        "        READ TABLE lt_fm_current_body INTO lv_fm_body_line",
        "          INDEX lv_fm_body_lines.",
        "        IF lv_fm_body_line IS INITIAL.",
        "          DELETE lt_fm_current_body INDEX lv_fm_body_lines.",
        "          lv_fm_body_lines = lv_fm_body_lines - 1.",
        "        ELSE.",
        "          EXIT.",
        "        ENDIF.",
        "      ENDWHILE.",
        "      CLEAR lv_fm_hash_input.",
        "      CONCATENATE LINES OF lt_fm_current_body INTO lv_fm_hash_input",
        "        SEPARATED BY lv_fm_lf.",
        "      CLEAR lv_fm_prior_body_hash.",
        "      TRY.",
        "          CALL METHOD cl_abap_message_digest=>calculate_hash_for_char",
        "            EXPORTING if_algorithm = 'SHA256'",
        "              if_data = lv_fm_hash_input",
        "            IMPORTING ef_hashstring = lv_fm_prior_body_hash.",
        "        CATCH cx_root.",
        "          CLEAR lv_fm_prior_body_hash.",
        "      ENDTRY.",
        "      IF strlen( lv_fm_prior_body_hash ) <> 64.",
        "        CLEAR lv_fm_prior_body_hash.",
        "      ELSE.",
        "        TRANSLATE lv_fm_prior_body_hash TO LOWER CASE.",
        "      ENDIF.",
        "      IF iv_expected_version IS NOT INITIAL.",
        "        IF lv_fm_prior_body_hash IS INITIAL.",
        "          CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "            EXPORTING funcname = lv_function_name.",
        "          ev_status = 'E'. ev_code = 'SOURCE_HASH_UNAVAILABLE'.",
        "          ev_message = 'Current body hash cannot be calculated'.",
        "          ev_version = '2.9'. RETURN.",
        "        ENDIF.",
        "        IF lv_fm_prior_body_hash <> iv_expected_version.",
        "          CALL FUNCTION 'DEQUEUE_ESFUNCTION'",
        "            EXPORTING funcname = lv_function_name.",
        "          ev_status = 'E'. ev_code = 'SOURCE_FINGERPRINT_CONFLICT'.",
        "          ev_message = 'Function body changed since the reviewed read'.",
        "          CONCATENATE ev_message lv_fm_prior_body_hash",
        "            INTO ev_message SEPARATED BY ' '.",
        "          ev_version = '2.9'. RETURN.",
        "        ENDIF.",
        "      ENDIF.",
        "      REFRESH lt_fm_trailer.",
        "      lv_fm_body_index = lv_fm_end_index.",
        "      WHILE lv_fm_body_index <= lines( lt_fm_include ).",
        "        READ TABLE lt_fm_include INTO lv_fm_include_line",
        "          INDEX lv_fm_body_index.",
        "        IF sy-subrc = 0.",
        "          APPEND lv_fm_include_line TO lt_fm_trailer.",
        "        ENDIF.",
        "        lv_fm_body_index = lv_fm_body_index + 1.",
        "      ENDWHILE.",
        "      DELETE lt_fm_include FROM lv_fm_body_start.",
        "      lv_fm_insert_index = lv_fm_body_start.",
        "      LOOP AT lt_fm_body INTO lv_fm_body_line.",
        "        INSERT lv_fm_body_line INTO lt_fm_include",
        "          INDEX lv_fm_insert_index.",
        "        lv_fm_insert_index = lv_fm_insert_index + 1.",
        "      ENDLOOP.",
        "      LOOP AT lt_fm_trailer INTO lv_fm_include_line.",
        "        INSERT lv_fm_include_line INTO lt_fm_include",
        "          INDEX lv_fm_insert_index.",
        "        lv_fm_insert_index = lv_fm_insert_index + 1.",
        "      ENDLOOP.",
        "      UPDATE enlfdir SET generated = space",
        "        WHERE funcname = lv_function_name.",
        "      INSERT REPORT lv_fm_include FROM lt_fm_include.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_SOURCE_INSERT_FAILED'.",
        "        ev_message = 'Function include could not be saved'.",
        "        ev_version = '2.9'. RETURN.",
        "      ENDIF.",
        "      CONCATENATE 'SAPL' lv_function_pool INTO lv_fm_pool_program.",
        "      CLEAR: lv_fm_generate_message, lv_fm_generate_line,",
        "        lv_fm_generate_word.",
        "      GENERATE REPORT lv_fm_pool_program",
        "        MESSAGE lv_fm_generate_message LINE lv_fm_generate_line",
        "        WORD lv_fm_generate_word.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'FUNCTION_SOURCE_ACTIVATION_FAILED'.",
        "        CONCATENATE 'Generation failed:'",
        "          lv_fm_generate_message INTO ev_message",
        "          RESPECTING BLANKS.",
        "        ev_version = '2.9'. RETURN.",
        "      ENDIF.",
        "      REFRESH lt_fm_verify_source.",
        "      READ REPORT lv_fm_include INTO lt_fm_verify_source.",
        "      IF sy-subrc <> 0.",
        "        lv_fm_verify_result = 'READ_FAILED'.",
        "      ELSE.",
        "        CLEAR: lv_fm_verify_mismatch, lv_fm_verify_index.",
        "        CLEAR lv_fm_verify_position.",
        "        LOOP AT lt_fm_body INTO lv_fm_body_line.",
        "          lv_fm_verify_position = lv_fm_verify_position + 1.",
        "          lv_fm_verify_index = lv_fm_body_start",
        "            + lv_fm_verify_position - 1.",
        "          READ TABLE lt_fm_verify_source INTO lv_fm_read_line",
        "            INDEX lv_fm_verify_index.",
        "          IF sy-subrc <> 0.",
        "            IF lv_fm_verify_mismatch IS INITIAL.",
        "              lv_fm_verify_mismatch = lv_fm_verify_position.",
        "            ENDIF.",
        "          ELSEIF lv_fm_read_line <> lv_fm_body_line.",
        "            IF lv_fm_verify_mismatch IS INITIAL.",
        "              lv_fm_verify_mismatch = lv_fm_verify_position.",
        "            ENDIF.",
        "          ENDIF.",
        "        ENDLOOP.",
        "        IF lv_fm_verify_mismatch IS INITIAL.",
        "          lv_fm_verify_result = 'OK'.",
        "        ELSE.",
        "          lv_fm_verify_result = 'MISMATCH'.",
        "        ENDIF.",
        "      ENDIF.",
        "      UPDATE enlfdir SET generated = 'X'",
        "        WHERE funcname = lv_function_name.",
        "      IF sy-subrc <> 0.",
        "        ROLLBACK WORK.",
        "        ev_status = 'E'. ev_code = 'FUNCTION_ACTIVATION_FLAG_ERROR'.",
        "        ev_message = 'Function active flag could not be set'.",
        "        ev_version = '2.9'. RETURN.",
        "      ENDIF.",
        "      COMMIT WORK AND WAIT.",
        "      lv_fm_include_lines = lines( lt_fm_verify_source ).",
        "      REFRESH it_source.",
        "      add_repo_payload 'M' '1' 'FUNCTION_NAME' lv_function_name.",
        "      add_repo_payload 'M' '1' 'FUNCTION_GROUP' lv_function_pool.",
        "      add_repo_payload 'M' '1' 'FUNCTION_INCLUDE' lv_fm_include.",
        "      add_repo_payload 'M' '1' 'PACKAGE' iv_package.",
        "      add_repo_payload 'M' '1' 'REQUEST' ls_task-trkorr.",
        "      add_repo_payload 'M' '1' 'SOURCE_LINES' lv_fm_include_lines.",
        "      add_repo_payload 'M' '1' 'BODY_LINES' lv_fm_body_lines.",
        "      add_repo_payload 'M' '1' 'BODY_HASH' lv_fm_body_hash.",
        "      add_repo_payload 'M' '1' 'PRIOR_BODY_HASH'",
        "        lv_fm_prior_body_hash.",
        "      add_repo_payload 'M' '1' 'VERIFY' lv_fm_verify_result.",
        "      add_repo_payload 'M' '1' 'VERIFY_MISMATCH_LINE'",
        "        lv_fm_verify_mismatch.",
        "      add_repo_payload 'M' '1' 'TRANSPORT_RELEASE' 'NONE'.",
        "      IF lv_fm_verify_result = 'OK'.",
        "        ev_status = 'S'.",
        "        ev_code = 'FUNCTION_SOURCE_WRITTEN'.",
        "        ev_message = 'Function body replaced generated and verified'.",
        "      ELSE.",
        "        ev_status = 'E'.",
        "        ev_code = 'FUNCTION_SOURCE_VERIFY_FAILED'.",
        "        ev_message = 'Function body written but verify failed'.",
        "      ENDIF.",
        "      ev_version = '2.9'.",
        "      RETURN.",
        "  ENDCASE.",
        "  zcl_orvanta_mcp_core=>execute(",
        "    EXPORTING",
        "      iv_operation = iv_operation",
        "      iv_object_type = iv_object_type",
        "      iv_object_name = iv_object_name",
        "    IMPORTING",
        "      ev_status = ev_status",
        "      ev_code = ev_code",
        "      ev_message = ev_message",
        "      ev_version = ev_version )."
    )
    # One predicate decides BOTH which body is installed and which D7 interface parameters are
    # declared, so a function module can never be installed with a body that references a field its
    # interface omits. The repository body is shared by Z_ORVANTA_MCP_EXECUTE and
    # Z_ORVANTA_MCP_DYNPRO_API, so gating the D7 parameters on one specific function module name
    # would break exactly that invariant (precedent: GENERATE_ERROR 4902 on IV_EXPECTED_VERSION).
    $usesRepositoryBody = $FunctionName -ne "Z_ORVANTA_MCP_DDIC_API"
    $functionSource = if ($usesRepositoryBody) {
        $repositoryFunctionSource
    }
    else {
        New-DdicFunctionSource
    }
    # SOURCE|HASH is the SHA-256 (lowercase hex) of the exact ABAP text about to be
    # uploaded -- ($functionSource -join "`n") -- while its own four 16-character
    # placeholders are still in place. The hash is then written into those slots in
    # order (no length change), so re-running the generator on the same source
    # reproduces the same hash. Recompute it the same way to verify a deployment.
    if (($functionSource -join "`n").Contains($capabilityHashSlots[0])) {
        $capabilityHashInput = $functionSource -join "`n"
        $capabilitySha256 = [Security.Cryptography.SHA256]::Create()
        try {
            $capabilityHashBytes = $capabilitySha256.ComputeHash(
                [Text.Encoding]::UTF8.GetBytes($capabilityHashInput)
            )
        }
        finally {
            $capabilitySha256.Dispose()
        }
        $capabilitySourceHash = (
            $capabilityHashBytes | ForEach-Object { $_.ToString("x2") }
        ) -join ""
        $functionSource = @(
            foreach ($capabilitySourceLine in $functionSource) {
                $capabilityHashedLine = $capabilitySourceLine
                for ($capabilityHashIndex = 0; $capabilityHashIndex -lt 4; $capabilityHashIndex++) {
                    $capabilityHashedLine = $capabilityHashedLine.Replace(
                        $capabilityHashSlots[$capabilityHashIndex],
                        $capabilitySourceHash.Substring($capabilityHashIndex * 16, 16)
                    )
                }
                $capabilityHashedLine
            }
        )
    }
    $operationDbField = if ($FunctionName -eq "Z_ORVANTA_MCP_DDIC_API") {
        "BAPIRET2-PARAMETER"
    }
    else {
        "RS38L-NAME"
    }
    # Every generated body references iv_expected_version: the shared repository body (used by
    # Z_ORVANTA_MCP_EXECUTE and Z_ORVANTA_MCP_DYNPRO_API) uses it for optimistic concurrency and
    # the DDIC body uses it for DDIC object patching. Excluding it for Z_ORVANTA_MCP_EXECUTE
    # failed the install with GENERATE_ERROR 4902 ("The field IV_EXPECTED_VERSION is unknown")
    # because the parameter list and the body disagreed. It is optional, so declaring it for all
    # helpers keeps existing callers compatible.
    $ddicImportLines = @(
        "CLEAR ls_import.",
        "ls_import-parameter = 'IV_EXPECTED_VERSION'.",
        # A reviewed implementation-source fingerprint is 64 hexadecimal characters, so the
        # parameter must not be shorter than the value the service already sends.
        "ls_import-dbfield = 'BAPIRET2-MESSAGE'.",
        "ls_import-optional = 'X'.",
        "APPEND ls_import TO lt_import."
    )

    $sourceProgramLines = foreach ($line in $functionSource) {
        if ($line.Length -gt 72) {
            throw "Generated function source exceeds 72 characters: $line"
        }
        $chunks = @()
        $offset = 0
        while ($offset -lt $line.Length) {
            $length = [Math]::Min(20, $line.Length - $offset)
            while (
                $length -gt 1 -and
                [char]::IsWhiteSpace($line[$offset + $length - 1])
            ) {
                $length--
            }
            $chunks += $line.Substring($offset, $length)
            $offset += $length
        }
        if (
            ($chunks[0] -match '^\s+$') -or
            $chunks.Where({ $_ -match '\s$' }).Count -gt 0 -or
            ($chunks -join '') -ne $line
        ) {
            throw "Generated source chunks cannot preserve whitespace: $line"
        }
        $chunks = @($chunks | ForEach-Object { $_.Replace("'", "''") })
        "lv_source_line = '$($chunks[0])'."
        foreach ($chunk in $chunks | Select-Object -Skip 1) {
            "CONCATENATE lv_source_line '$chunk'"
            "  INTO lv_source_line RESPECTING BLANKS."
        }
        "ls_source-line = lv_source_line."
        "APPEND ls_source TO lt_source."
    }

    # D7 interface extension (SAPscript form + SmartStyle), declared only for the function modules
    # that receive the repository body. Every reference below was verified against w200 BEFORE this
    # generator was changed; the plan's own §2.5 list was not taken on trust:
    #   * each carrier object exists and is flat -- DD03L shows no STRING/XSTRING/INT8/DECFLOAT
    #     field in any of the 15 row types exported to the service;
    #   * no parameter is declared with a bare data element name: a bare name such as TDSPRAS is
    #     resolved as a NON-FLAT type and stops the whole function group from loading, so every
    #     DBFIELD is a table-field reference (ITCTA-TDSTATUS, THEAD-TDSPRAS, TSTC-TCODE, ...);
    #   * SAP's own SSF_READ_STYLE types its parameters exactly this way (I_STYLE_ACTIVE_FLAG ::
    #     TDACTIVATE, I_STYLE_VARIANT :: TDVARIANT, I_STYLE_LANGUAGE :: TDSPRAS) and uses
    #     SSFCATS/SSFPARAS/SSFSTRINGS/STXSTAB as its EXPORTING/TABLES types, so this interface shape
    #     has a release-verified precedent rather than being an untried construct.
    # The spec wrote SY-LANGU for IV_TEXT_LANGUAGE; the carrier declares it as a flat table-field
    # reference (THEAD-TDSPRAS), so the verified carrier wins over the illustrative name.
    # All new IMPORTING parameters are OPTIONAL, so the 37 existing operations are unaffected.
    $repositoryInterfaceImportLines = if ($usesRepositoryBody) {
        @(
            "CLEAR ls_import.",
            "ls_import-parameter = 'IV_TEXT_STATUS'.",
            "ls_import-dbfield = 'ITCTA-TDSTATUS'.",
            "ls_import-optional = 'X'.",
            "APPEND ls_import TO lt_import.",
            "CLEAR ls_import.",
            "ls_import-parameter = 'IV_TEXT_LANGUAGE'.",
            "ls_import-dbfield = 'THEAD-TDSPRAS'.",
            "ls_import-optional = 'X'.",
            "APPEND ls_import TO lt_import.",
            "CLEAR ls_import.",
            "ls_import-parameter = 'IV_TEXT_VERSION'.",
            "ls_import-dbfield = 'THEAD-TDVERSION'.",
            "ls_import-optional = 'X'.",
            "APPEND ls_import TO lt_import.",
            "CLEAR ls_import.",
            "ls_import-parameter = 'IV_STYLE_VARIANT'.",
            "ls_import-dbfield = 'TADIR-OBJ_NAME'.",
            "ls_import-optional = 'X'.",
            "APPEND ls_import TO lt_import.",
            "CLEAR ls_import.",
            "ls_import-parameter = 'IV_STYLE_ACTIVE'.",
            "ls_import-dbfield = 'TSTC-TCODE'.",
            "ls_import-optional = 'X'.",
            "APPEND ls_import TO lt_import.",
            "CLEAR ls_import.",
            "ls_import-parameter = 'IV_STYLE_MODE'.",
            "ls_import-dbfield = 'THEAD-TDSPRAS'.",
            "ls_import-optional = 'X'.",
            "APPEND ls_import TO lt_import.",
            "CLEAR ls_import.",
            # read_sapscript_form needs its own switch: includeSource asks for the raw ID_DEF source in
            # addition to the parsed layout. No existing parameter means that, and reusing IV_STYLE_MODE
            # (a SmartStyle storage-family selector) would overload one flag with two unrelated meanings.
            "ls_import-parameter = 'IV_INCLUDE_SOURCE'.",
            "ls_import-dbfield = 'THEAD-TDSPRAS'.",
            "ls_import-optional = 'X'.",
            "APPEND ls_import TO lt_import.",
            # read_smartstyle needs its own switch for the same reason: includeCss triggers
            # SSF_CONVERT_STYLE_TO_CSS, which has nothing to do with the ID_DEF source of a form.
            "CLEAR ls_import.",
            "ls_import-parameter = 'IV_INCLUDE_CSS'.",
            "ls_import-dbfield = 'THEAD-TDSPRAS'.",
            "ls_import-optional = 'X'.",
            "APPEND ls_import TO lt_import.",
            # create_transport_request inputs. They are separate parameters rather than payload
            # rows because the request type and text are validated by SAP's own types: TRFUNCTION
            # carries the domain fixed values and AS4TEXT is the description column of E07T, so a
            # mistyped or overlong value is rejected at the RFC boundary instead of inside the body.
            "CLEAR ls_import.",
            "ls_import-parameter = 'IV_REQUEST_TYPE'.",
            "ls_import-dbfield = 'THEAD-TDSPRAS'.",
            "ls_import-optional = 'X'.",
            "APPEND ls_import TO lt_import.",
            "CLEAR ls_import.",
            "ls_import-parameter = 'IV_REQUEST_TEXT'.",
            "ls_import-dbfield = 'TSTCT-TTEXT'.",
            "ls_import-optional = 'X'.",
            "APPEND ls_import TO lt_import.",
            "CLEAR ls_import.",
            "ls_import-parameter = 'IV_REQUEST_OWNER'.",
            "ls_import-dbfield = 'E070-AS4USER'.",
            "ls_import-optional = 'X'.",
            "APPEND ls_import TO lt_import.",
            "CLEAR ls_import.",
            "ls_import-parameter = 'IV_REQUEST_TARGET'.",
            "ls_import-dbfield = 'TSTC-TCODE'.",
            "ls_import-optional = 'X'.",
            "APPEND ls_import TO lt_import.",
            "CLEAR ls_import.",
            "ls_import-parameter = 'IV_REQUEST_ALLOW_DUPLICATE'.",
            "ls_import-dbfield = 'THEAD-TDSPRAS'.",
            "ls_import-optional = 'X'.",
            "APPEND ls_import TO lt_import.",
            "CLEAR ls_import.",
            "ls_import-parameter = 'IV_ADD_REQUEST'.",
            "ls_import-dbfield = 'E070-TRKORR'.",
            "ls_import-optional = 'X'.",
            "APPEND ls_import TO lt_import."
        )
    }
    else {
        @()
    }
    $repositoryInterfaceExportLines = if ($usesRepositoryBody) {
        @(
            "CLEAR ls_export.",
            "ls_export-parameter = 'ES_FORM_HEADER'.",
            "ls_export-dbfield = 'ITCTA'.",
            "APPEND ls_export TO lt_export.",
            "CLEAR ls_export.",
            "ls_export-parameter = 'ES_TEXT_HEADER'.",
            "ls_export-dbfield = 'THEAD'.",
            "APPEND ls_export TO lt_export.",
            "CLEAR ls_export.",
            "ls_export-parameter = 'ES_STYLE_HEADER'.",
            "ls_export-dbfield = 'SSFCATS'.",
            "APPEND ls_export TO lt_export.",
            "CLEAR ls_export.",
            "ls_export-parameter = 'ES_SAPSCRIPT_STYLE_HEADER'.",
            "ls_export-dbfield = 'ITCDA'.",
            "APPEND ls_export TO lt_export."
        )
    }
    else {
        @()
    }
    # Row types are the real types of the called function modules' table parameters, all flat and
    # RFC-serializable. `STXSTAB` is a transparent table, not a structure, and is used as such.
    $repositoryInterfaceTableLines = if ($usesRepositoryBody) {
        @(
            "CLEAR ls_tables.",
            "ls_tables-parameter = 'ET_FORM_LINES'.",
            "ls_tables-dbstruct = 'TLINE'.",
            "APPEND ls_tables TO lt_tables.",
            "CLEAR ls_tables.",
            "ls_tables-parameter = 'ET_FORM_PAGES'.",
            "ls_tables-dbstruct = 'ITCTG'.",
            "APPEND ls_tables TO lt_tables.",
            "CLEAR ls_tables.",
            "ls_tables-parameter = 'ET_FORM_PAGE_WINDOWS'.",
            "ls_tables-dbstruct = 'ITCTH'.",
            "APPEND ls_tables TO lt_tables.",
            "CLEAR ls_tables.",
            "ls_tables-parameter = 'ET_FORM_PARAGRAPHS'.",
            "ls_tables-dbstruct = 'ITCDP'.",
            "APPEND ls_tables TO lt_tables.",
            "CLEAR ls_tables.",
            "ls_tables-parameter = 'ET_FORM_STRINGS'.",
            "ls_tables-dbstruct = 'ITCDS'.",
            "APPEND ls_tables TO lt_tables.",
            "CLEAR ls_tables.",
            "ls_tables-parameter = 'ET_FORM_TABS'.",
            "ls_tables-dbstruct = 'ITCDQ'.",
            "APPEND ls_tables TO lt_tables.",
            "CLEAR ls_tables.",
            "ls_tables-parameter = 'ET_FORM_WINDOWS'.",
            "ls_tables-dbstruct = 'ITCTW'.",
            "APPEND ls_tables TO lt_tables.",
            "CLEAR ls_tables.",
            "ls_tables-parameter = 'ET_FORM_VERSIONS'.",
            "ls_tables-dbstruct = 'ITCFORMVER'.",
            "APPEND ls_tables TO lt_tables.",
            "CLEAR ls_tables.",
            "ls_tables-parameter = 'ET_TEXT_HEADERS'.",
            "ls_tables-dbstruct = 'THEAD'.",
            "APPEND ls_tables TO lt_tables.",
            "CLEAR ls_tables.",
            "ls_tables-parameter = 'ET_STYLE_HEADERS'.",
            "ls_tables-dbstruct = 'SSFCATS'.",
            "APPEND ls_tables TO lt_tables.",
            "CLEAR ls_tables.",
            "ls_tables-parameter = 'ET_STYLE_PARAGRAPHS'.",
            "ls_tables-dbstruct = 'SSFPARAS'.",
            "APPEND ls_tables TO lt_tables.",
            "CLEAR ls_tables.",
            "ls_tables-parameter = 'ET_STYLE_STRINGS'.",
            "ls_tables-dbstruct = 'SSFSTRINGS'.",
            "APPEND ls_tables TO lt_tables.",
            "CLEAR ls_tables.",
            "ls_tables-parameter = 'ET_STYLE_TABSTOPS'.",
            "ls_tables-dbstruct = 'STXSTAB'.",
            "APPEND ls_tables TO lt_tables.",
            "CLEAR ls_tables.",
            "ls_tables-parameter = 'ET_STYLE_ITEMS_PARA'.",
            "ls_tables-dbstruct = 'ITCDP'.",
            "APPEND ls_tables TO lt_tables.",
            "CLEAR ls_tables.",
            "ls_tables-parameter = 'ET_STYLE_ITEMS_STR'.",
            "ls_tables-dbstruct = 'ITCDS'.",
            "APPEND ls_tables TO lt_tables.",
            "CLEAR ls_tables.",
            "ls_tables-parameter = 'ET_STYLE_ITEMS_TAB'.",
            "ls_tables-dbstruct = 'ITCDQ'.",
            "APPEND ls_tables TO lt_tables.",
            "CLEAR ls_tables."
        )
    }
    else {
        @()
    }

    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "DATA lt_import TYPE TABLE OF rsimp.",
        "DATA lt_export TYPE TABLE OF rsexp.",
        "DATA lt_tables TYPE TABLE OF rstbl.",
        "DATA lt_exceptions TYPE TABLE OF rsexc.",
        "DATA lt_parameter_docu TYPE TABLE OF rsfdo.",
        "DATA lt_source TYPE TABLE OF rssource.",
        "DATA ls_import TYPE rsimp.",
        "DATA ls_export TYPE rsexp.",
        "DATA ls_tables TYPE rstbl.",
        "DATA ls_source TYPE rssource.",
        "DATA lv_source_line TYPE string.",
        "DATA lt_function_code TYPE rsfb_source.",
        "DATA lv_function_line TYPE string.",
        "DATA lv_function_include TYPE rs38l-include.",
        "DATA lv_insert_index TYPE i.",
        "DATA lv_generate_message TYPE string.",
        "DATA lv_generate_line TYPE i.",
        "DATA lv_generate_word TYPE string.",
        "CALL FUNCTION 'FUNCTION_EXISTS'",
        "  EXPORTING funcname = '$FunctionName'",
        "  EXCEPTIONS function_not_exist = 1 others = 2."
    ) + $existingObjectLines + @(
        "ls_import-parameter = 'IV_OPERATION'.",
        "ls_import-dbfield = '$operationDbField'.",
        "APPEND ls_import TO lt_import.",
        "CLEAR ls_import.",
        "ls_import-parameter = 'IV_OBJECT_TYPE'.",
        "ls_import-dbfield = 'TADIR-OBJECT'.",
        "ls_import-optional = 'X'.",
        "APPEND ls_import TO lt_import.",
        "CLEAR ls_import.",
        "ls_import-parameter = 'IV_PROGRAM'.",
        "ls_import-dbfield = 'TRDIR-NAME'.",
        "ls_import-optional = 'X'.",
        "APPEND ls_import TO lt_import.",
        "CLEAR ls_import.",
        "ls_import-parameter = 'IV_SCREEN'.",
        "ls_import-dbfield = 'D020S-DNUM'.",
        "ls_import-optional = 'X'.",
        "APPEND ls_import TO lt_import.",
        "CLEAR ls_import.",
        "ls_import-parameter = 'IV_TRANSACTION'.",
        "ls_import-dbfield = 'TSTC-TCODE'.",
        "ls_import-optional = 'X'.",
        "APPEND ls_import TO lt_import.",
        "CLEAR ls_import.",
        "ls_import-parameter = 'IV_DESCRIPTION'.",
        "ls_import-dbfield = 'TSTCT-TTEXT'.",
        "ls_import-optional = 'X'.",
        "APPEND ls_import TO lt_import.",
        "CLEAR ls_import.",
        "ls_import-parameter = 'IV_PACKAGE'.",
        "ls_import-dbfield = 'TADIR-DEVCLASS'.",
        "ls_import-optional = 'X'.",
        "APPEND ls_import TO lt_import.",
        "CLEAR ls_import.",
        "ls_import-parameter = 'IV_REQUEST'.",
        "ls_import-dbfield = 'E070-TRKORR'.",
        "ls_import-optional = 'X'.",
        "APPEND ls_import TO lt_import.",
        "CLEAR ls_import.",
        "ls_import-parameter = 'IS_HEADER'.",
        "ls_import-dbfield = 'D020S'.",
        "ls_import-optional = 'X'.",
        "APPEND ls_import TO lt_import.",
        "CLEAR ls_import.",
        "ls_import-parameter = 'IV_OBJECT_NAME'.",
        "ls_import-dbfield = 'TADIR-OBJ_NAME'.",
        "ls_import-optional = 'X'.",
        "APPEND ls_import TO lt_import."
    ) + $repositoryInterfaceImportLines + $ddicImportLines + $repositoryInterfaceExportLines + @(
        "ls_export-parameter = 'EV_STATUS'.",
        "ls_export-dbfield = 'SY-MSGTY'.",
        "APPEND ls_export TO lt_export.",
        "CLEAR ls_export.",
        "ls_export-parameter = 'EV_CODE'.",
        "ls_export-dbfield = 'SY-MSGV1'.",
        "APPEND ls_export TO lt_export.",
        "CLEAR ls_export.",
        "ls_export-parameter = 'EV_MESSAGE'.",
        "ls_export-dbfield = 'BAPIRET2-MESSAGE'.",
        "APPEND ls_export TO lt_export.",
        "CLEAR ls_export.",
        "ls_export-parameter = 'EV_VERSION'.",
        "ls_export-dbfield = 'SY-MSGV1'.",
        "APPEND ls_export TO lt_export.",
        "CLEAR ls_export.",
        "ls_export-parameter = 'ES_HEADER'.",
        "ls_export-dbfield = 'D020S'.",
        "APPEND ls_export TO lt_export.",
        "CLEAR ls_export.",
        "ls_export-parameter = 'EV_DYNPROTEXT'.",
        "ls_export-dbfield = 'D020T-DTXT'.",
        "APPEND ls_export TO lt_export.",
        "ls_tables-parameter = 'CT_FIELDS'.",
        "ls_tables-dbstruct = 'D021S'.",
        "APPEND ls_tables TO lt_tables.",
        "CLEAR ls_tables.",
        "ls_tables-parameter = 'CT_FLOWLOGIC'.",
        "ls_tables-dbstruct = 'D022S'.",
        "APPEND ls_tables TO lt_tables.",
        "CLEAR ls_tables.",
        "ls_tables-parameter = 'CT_PARAMS'.",
        "ls_tables-dbstruct = 'D023S'.",
        "APPEND ls_tables TO lt_tables.",
        "CLEAR ls_tables.",
        "ls_tables-parameter = 'ET_TCODES'.",
        "ls_tables-dbstruct = 'TSTC'.",
        "APPEND ls_tables TO lt_tables.",
        "CLEAR ls_tables.",
        "ls_tables-parameter = 'ET_GUI_ATTRIBUTES'.",
        "ls_tables-dbstruct = 'TSTCC'.",
        "APPEND ls_tables TO lt_tables.",
        "CLEAR ls_tables.",
        "ls_tables-parameter = 'IT_SOURCE'.",
        "ls_tables-dbstruct = 'ABAPTXT255'.",
        "APPEND ls_tables TO lt_tables.",
        "CLEAR ls_tables."
    ) + $repositoryInterfaceTableLines + $sourceProgramLines + @(
        "CALL FUNCTION 'FUNCTION_CREATE'",
        "  EXPORTING",
        "    funcname = '$FunctionName'",
        "    function_pool = 'ZORVANTA_MCP_CORE'",
        "    remote_call = 'R'",
        "    short_text = 'ORVANTA MCP controlled entry point'",
        "    suppress_corr_check = 'X'",
        "    save_active = 'X'",
        "  IMPORTING",
        "    function_include = lv_function_include",
        "  TABLES",
        "    import_parameter = lt_import",
        "    export_parameter = lt_export",
        "    tables_parameter = lt_tables",
        "    exception_list = lt_exceptions",
        "    parameter_docu = lt_parameter_docu",
        "  EXCEPTIONS",
        "    double_task = 1",
        "    error_message = 2",
        "    function_already_exists = 3",
        "    invalid_function_pool = 4",
        "    invalid_name = 5",
        "    too_many_functions = 6",
        "    no_modify_permission = 7",
        "    no_show_permission = 8",
        "    enqueue_system_failure = 9",
        "    canceled_in_corr = 10",
        "    others = 11.",
        "IF sy-subrc <> 0.",
        "  WRITE: / 'CREATE_ERROR', sy-subrc, sy-msgid, sy-msgno,",
        "    sy-msgv1, sy-msgv2, sy-msgv3, sy-msgv4.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "UPDATE enlfdir SET generated = space",
        "  WHERE funcname = '$FunctionName'.",
        "READ REPORT lv_function_include INTO lt_function_code.",
        "IF sy-subrc <> 0.",
        "  WRITE: / 'SOURCE_READ_ERROR', sy-subrc,",
        "    lv_function_include.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "CLEAR lv_insert_index.",
        "LOOP AT lt_function_code INTO lv_function_line.",
        "  IF lv_function_line CS '""-----------------------------------------'",
        "     AND sy-tabix <> 2.",
        "    lv_insert_index = sy-tabix + 1.",
        "    EXIT.",
        "  ENDIF.",
        "ENDLOOP.",
        "IF lv_insert_index IS INITIAL.",
        "  WRITE / 'SOURCE_MARKER_ERROR'.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "LOOP AT lt_source INTO ls_source.",
        "  INSERT ls_source-line INTO lt_function_code",
        "    INDEX lv_insert_index.",
        "  lv_insert_index = lv_insert_index + 1.",
        "ENDLOOP.",
        "INSERT REPORT lv_function_include FROM lt_function_code.",
        "IF sy-subrc <> 0.",
        "  WRITE: / 'SOURCE_INSERT_ERROR', sy-subrc,",
        "    lv_function_include.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "GENERATE REPORT 'SAPLZORVANTA_MCP_CORE'",
        "  MESSAGE lv_generate_message LINE lv_generate_line",
        "  WORD lv_generate_word.",
        "IF sy-subrc <> 0.",
        "  WRITE: / 'GENERATE_ERROR', sy-subrc, lv_generate_line,",
        "    lv_generate_word, / lv_generate_message.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "UPDATE enlfdir SET generated = 'X'",
        "  WHERE funcname = '$FunctionName'.",
        "IF sy-subrc <> 0.",
        "  WRITE: / 'FUNCTION_ACTIVATION_FLAG_ERROR', sy-subrc.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "COMMIT WORK AND WAIT.",
        "WRITE / 'CREATED $FunctionName'."
    )
}

# >>> ORVANTA-APPLICATION-LOG-SOURCE
# Byte-identical copy of scripts/application-log-source.mjs -> applicationLogSource.
# The CAPABILITIES branch and the SOURCE|HASH digest are rendered there; this block is never
# re-rendered, only transported. Regenerate it from that module, never by hand.
$applicationLogFunctionSource = @(
    'DATA: lt_head TYPE STANDARD TABLE OF balhdr,',
    '      ls_head TYPE balhdr,',
    '      lv_object TYPE balhdr-object,',
    '      lv_after TYPE balhdr-lognumber,',
    '      lv_from_d TYPE d, lv_to_d TYPE d,',
    '      lv_from_t TYPE t, lv_to_t TYPE t,',
    '      lv_days TYPE i, lv_span TYPE i,',
    '      lv_limit TYPE i, lv_fetch TYPE i, lv_rows TYPE i,',
    '      lv_idx TYPE i, lv_num TYPE c LENGTH 20,',
    '      lv_action TYPE string, lv_base TYPE string,',
    '      lv_json TYPE string, lv_value TYPE string,',
    '      lv_time TYPE string, lv_from TYPE string, lv_to TYPE string,',
    '      lv_more TYPE string,',
    '      lv_default TYPE badi_main-default_class,',
    '      lv_impl TYPE badi_impl-badi_name.',
    'RANGES: lr_sub FOR ls_head-subobject,',
    '        lr_ext FOR ls_head-extnumber,',
    '        lr_user FOR ls_head-aluser.',
    'DEFINE append_json_field.',
    '  lv_value = &2.',
    '  lv_value = escape( val = lv_value',
    '                    format = cl_abap_format=>e_json_string ).',
    '  CONCATENATE lv_json &1 lv_value ''"'' INTO lv_json.',
    'END-OF-DEFINITION.',
    '  IF iv_action = ''CAPABILITIES''.',
    '    CLEAR: ev_result, lv_json.',
    '    CONCATENATE ''{"version":"1","status":"S","code":"CAPABILITIES",''',
    '      ''"message":"ORVANTA helper capabilities","readOnly":true,''',
    '      ''"payload":['' INTO ev_result.',
    '    CONCATENATE ev_result ''"HELPER|Z_ORVANTA_LOG_READ",'' INTO ev_result.',
    '    CONCATENATE ev_result ''"PROTOCOL|MIN|1.0",'' INTO ev_result.',
    '    CONCATENATE ev_result ''"PROTOCOL|MAX|1.0",'' INTO ev_result.',
    '    CONCATENATE ev_result ''"OPERATION|SEARCH|1.0|R",'' INTO ev_result.',
    '    CONCATENATE ev_result ''"OPERATION|DISCOVER|1.0|R",'' INTO ev_result.',
    '    CONCATENATE ev_result ''"OPERATION|READ|1.0|R",'' INTO ev_result.',
    '    CONCATENATE ev_result ''"OPERATION|READ_DIAGNOSTIC|1.0|R",''',
    '      INTO ev_result.',
    '    CONCATENATE ev_result ''"OPERATION|READ_BODY_CHECK|1.0|R",''',
    '      INTO ev_result.',
    '    CONCATENATE ev_result ''"SOURCE|PACKAGE|ZABAP",'' INTO ev_result.',
    '    CONCATENATE ev_result ''"SOURCE|TRANSPORT|GR2K923472|GR2K923473",''',
    '      INTO ev_result.',
    '    CONCATENATE ev_result ''"RUNTIME|HOST|'' sy-sysid ''/'' sy-mandt ''",''',
    '      INTO ev_result.',
    '    CONCATENATE ev_result ''"SOURCE|HASH|'' ''07383ef8df984087''',
    '      INTO ev_result.',
    '    CONCATENATE ev_result ''52203244607bf2b3'' ''0b225b0f3b506e95''',
    '      ''8d93ae25cde573ab'' ''"'' INTO ev_result.',
    '    CONCATENATE ev_result '']}'' INTO ev_result.',
    '    RETURN.',
    '  ENDIF.',
    'CLEAR ev_result.',
    'lv_action = ''SEARCH''.',
    'IF iv_action = ''READ'' OR iv_action = ''DISCOVER''.',
    '  lv_action = iv_action.',
    'ENDIF.',
    'IF iv_action = ''READ_DIAGNOSTIC''. lv_action = ''READ''. ENDIF.',
    'lv_value = escape( val = sy-uname',
    '                  format = cl_abap_format=>e_json_string ).',
    'CONCATENATE ''{"version":"1","action":"'' lv_action',
    '  ''","client":"'' sy-mandt ''","authenticatedUser":"''',
    '  lv_value ''","readOnly":true,'' INTO lv_base.',
    'CONCATENATE lv_base',
    '  ''"status":"unsupported","code":"READ_ONLY_UNSUPPORTED",''',
    '  ''"headers":[],"messages":[],"hasMore":false}'' INTO ev_result.',
    'IF iv_action = ''DISCOVER''.',
    '* Independent bounded references; SEARCH scope is unchanged.',
    '  IF iv_object IS NOT INITIAL OR iv_subobject IS NOT INITIAL',
    '     OR iv_external IS NOT INITIAL OR iv_user IS NOT INITIAL',
    '     OR iv_from IS NOT INITIAL OR iv_to IS NOT INITIAL',
    '     OR iv_after_log IS NOT INITIAL OR iv_lognumber IS NOT INITIAL',
    '     OR iv_revision IS NOT INITIAL.',
    '    RETURN.',
    '  ENDIF.',
    '  IF iv_after_msg IS NOT INITIAL AND iv_after_msg <> ''0''.',
    '    RETURN.',
    '  ENDIF.',
    '  lv_limit = 20.',
    '  IF iv_limit IS NOT INITIAL.',
    '    IF strlen( iv_limit ) > 2 OR iv_limit CN ''0123456789''.',
    '      RETURN.',
    '    ENDIF.',
    '    lv_limit = iv_limit.',
    '  ENDIF.',
    '  IF lv_limit < 1 OR lv_limit > 20.',
    '    RETURN.',
    '  ENDIF.',
    '* Discovery requires display authority across objects/subobjects.',
    '  AUTHORITY-CHECK OBJECT ''S_APPL_LOG''',
    '    ID ''ALG_OBJECT'' FIELD ''*''',
    '    ID ''ALG_SUBOBJ'' FIELD ''*''',
    '    ID ''ACTVT'' FIELD ''03''.',
    '  IF sy-subrc <> 0.',
    '    CONCATENATE lv_base',
    '      ''"status":"forbidden","code":"NO_AUTHORITY",''',
    '      ''"headers":[],"messages":[],"hasMore":false}'' INTO ev_result.',
    '    RETURN.',
    '  ENDIF.',
    '  TRY.',
    '    SELECT SINGLE default_class FROM badi_main INTO lv_default',
    '      WHERE badi_name = ''SBAL_AUTHORITY_RESTRICTION''.',
    '    IF sy-subrc <> 0 OR lv_default IS NOT INITIAL.',
    '      RETURN.',
    '    ENDIF.',
    '    SELECT badi_name FROM badi_impl INTO lv_impl UP TO 1 ROWS',
    '      WHERE badi_name = ''SBAL_AUTHORITY_RESTRICTION''.',
    '    ENDSELECT.',
    '    IF sy-subrc <> 4.',
    '      RETURN.',
    '    ENDIF.',
    '* Only reference fields; implicit client handling, no message load.',
    '    SELECT lognumber object subobject aldate altime',
    '      FROM balhdr INTO CORRESPONDING FIELDS OF TABLE lt_head',
    '      UP TO lv_limit ROWS',
    '      ORDER BY lognumber DESCENDING.',
    '    LOOP AT lt_head INTO ls_head.',
    '      AUTHORITY-CHECK OBJECT ''S_APPL_LOG''',
    '        ID ''ALG_OBJECT'' FIELD ls_head-object',
    '        ID ''ALG_SUBOBJ'' FIELD ls_head-subobject',
    '        ID ''ACTVT'' FIELD ''03''.',
    '      IF sy-subrc <> 0.',
    '        CONCATENATE lv_base',
    '          ''"status":"forbidden","code":"NO_AUTHORITY",''',
    '          ''"headers":[],"messages":[],"hasMore":false}'' INTO ev_result.',
    '        RETURN.',
    '      ENDIF.',
    '    ENDLOOP.',
    '    CATCH cx_root.',
    '      RETURN.',
    '  ENDTRY.',
    '  lv_json = ''[''.',
    '  LOOP AT lt_head INTO ls_head.',
    '    IF sy-tabix > 1.',
    '      CONCATENATE lv_json '','' INTO lv_json.',
    '    ENDIF.',
    '    CONCATENATE ls_head-aldate(4) ''-'' ls_head-aldate+4(2) ''-''',
    '      ls_head-aldate+6(2) ''T'' ls_head-altime(2) '':''',
    '      ls_head-altime+2(2) '':'' ls_head-altime+4(2) INTO lv_time.',
    '    append_json_field ''{"logNumber":"'' ls_head-lognumber.',
    '    append_json_field '',"object":"'' ls_head-object.',
    '    append_json_field '',"subobject":"'' ls_head-subobject.',
    '    append_json_field '',"systemTime":"'' lv_time.',
    '    CONCATENATE lv_json ''}'' INTO lv_json.',
    '  ENDLOOP.',
    '  CONCATENATE lv_json '']'' INTO lv_json.',
    '  CONCATENATE lv_base ''"status":"ok","code":"OK","headers":''',
    '    lv_json '',"messages":[],"hasMore":false}'' INTO ev_result.',
    '  RETURN.',
    'ENDIF.',
    'IF iv_action = ''READ'' OR iv_action = ''READ_DIAGNOSTIC''',
    '   OR iv_action = ''READ_BODY_CHECK''.',
    '  INCLUDE sbaltype.',
    '  DATA: lt_read_data TYPE baldat_t,',
    '        ls_read_data TYPE baldat,',
    '        ls_read_check TYPE balhdr,',
    '        ls_read_ldat TYPE bal_s_ldat,',
    '        ls_read_block TYPE bal_s_msgs,',
    '        ls_read_mhdr TYPE bal_s_mhdr,',
    '        ls_read_msg TYPE bal_s_msg,',
    '        lv_read_block TYPE baldat-block,',
    '        lv_read_prev TYPE baldat-srtf2,',
    '        lv_read_name TYPE c LENGTH 6,',
    '        lv_read_count TYPE i,',
    '        lv_read_after TYPE i,',
    '        lv_read_total TYPE i,',
    '        lv_read_text TYPE c LENGTH 4096,',
    '        lv_read_missing TYPE string,',
    '        lv_read_all TYPE string,',
    '        lv_read_page TYPE string,',
    '        lv_read_header TYPE string,',
    '        lv_read_hash TYPE string,',
    '        lv_read_t100 TYPE t100-text,',
    '        lv_read_langu TYPE sy-langu.',
    '  FIELD-SYMBOLS: <read_table> TYPE ANY TABLE,',
    '                 <read_row> TYPE any.',
    '  DEFINE read_stage.',
    '    IF iv_action = ''READ_BODY_CHECK''. ev_result = &1. ENDIF.',
    '    IF iv_action = ''READ_DIAGNOSTIC''.',
    '      CONCATENATE lv_base',
    '        ''"status":"unsupported","code":"READ_ONLY_UNSUPPORTED",''',
    '        ''"reason":"'' &1 ''","headers":[],"messages":[],''',
    '        ''"hasMore":false}'' INTO ev_result.',
    '    ENDIF.',
    '  END-OF-DEFINITION.',
    '  read_stage ''INPUT_VALIDATION''.',
    '  IF strlen( iv_lognumber ) <> 20',
    '     OR iv_lognumber CN ''0123456789''',
    '     OR iv_object IS NOT INITIAL OR iv_subobject IS NOT INITIAL',
    '     OR iv_external IS NOT INITIAL OR iv_user IS NOT INITIAL',
    '     OR iv_from IS NOT INITIAL OR iv_to IS NOT INITIAL',
    '     OR iv_after_log IS NOT INITIAL.',
    '    RETURN.',
    '  ENDIF.',
    '  lv_limit = 100.',
    '  IF iv_limit IS NOT INITIAL.',
    '    IF strlen( iv_limit ) > 3 OR iv_limit CN ''0123456789''.',
    '      RETURN.',
    '    ENDIF.',
    '    lv_limit = iv_limit.',
    '  ENDIF.',
    '  IF lv_limit < 1 OR lv_limit > 200.',
    '    RETURN.',
    '  ENDIF.',
    '  IF iv_after_msg IS NOT INITIAL.',
    '    IF strlen( iv_after_msg ) > 6 OR iv_after_msg CN ''0123456789''.',
    '      RETURN.',
    '    ENDIF.',
    '    lv_read_after = iv_after_msg.',
    '  ENDIF.',
    '  IF lv_read_after > 0 AND iv_revision IS INITIAL.',
    '    RETURN.',
    '  ENDIF.',
    '  IF iv_revision IS NOT INITIAL.',
    '    IF strlen( iv_revision ) <> 64',
    '       OR iv_revision CN ''0123456789abcdef''.',
    '      RETURN.',
    '    ENDIF.',
    '  ENDIF.',
    '  TRY.',
    '    SELECT SINGLE * FROM balhdr INTO ls_head',
    '      WHERE lognumber = iv_lognumber.',
    '    IF sy-subrc <> 0.',
    '      CONCATENATE lv_base',
    '        ''"status":"not_found","code":"NOT_FOUND",''',
    '        ''"headers":[],"messages":[],"hasMore":false}'' INTO ev_result.',
    '      RETURN.',
    '    ENDIF.',
    '    AUTHORITY-CHECK OBJECT ''S_APPL_LOG''',
    '      ID ''ALG_OBJECT'' FIELD ls_head-object',
    '      ID ''ALG_SUBOBJ'' FIELD ls_head-subobject',
    '      ID ''ACTVT'' FIELD ''03''.',
    '    IF sy-subrc <> 0.',
    '      CONCATENATE lv_base',
    '        ''"status":"forbidden","code":"NO_AUTHORITY",''',
    '        ''"headers":[],"messages":[],"hasMore":false}'' INTO ev_result.',
    '      RETURN.',
    '    ENDIF.',
    '    read_stage ''AUTHORITY_EXTENSION''.',
    '    SELECT SINGLE default_class FROM badi_main INTO lv_default',
    '      WHERE badi_name = ''SBAL_AUTHORITY_RESTRICTION''.',
    '    IF sy-subrc <> 0 OR lv_default IS NOT INITIAL.',
    '      RETURN.',
    '    ENDIF.',
    '    SELECT badi_name FROM badi_impl INTO lv_impl UP TO 1 ROWS',
    '      WHERE badi_name = ''SBAL_AUTHORITY_RESTRICTION''.',
    '    ENDSELECT.',
    '    IF sy-subrc <> 4.',
    '      RETURN.',
    '    ENDIF.',
    '* Only the reviewed current, native-character-size format is decoded.',
    '    read_stage ''DATABASE_VERSION''.',
    '    IF ls_head-db_version <> ''0001''.',
    '      RETURN.',
    '    ENDIF.',
    '    read_stage ''CHARACTER_SIZE''.',
    '    IF ls_head-char_size <> cl_abap_char_utilities=>charsize.',
    '      RETURN.',
    '    ENDIF.',
    '    read_stage ''MESSAGE_BUDGET''.',
    '    IF ls_head-last_msgnr > 1000 OR ls_head-msg_cnt_al > 1000.',
    '      RETURN.',
    '    ENDIF.',
    '    read_stage ''BLOCK_BUDGET''.',
    '    SELECT * FROM baldat INTO TABLE lt_read_data UP TO 513 ROWS',
    '      WHERE relid = ''AL'' AND log_handle = ls_head-log_handle',
    '        AND block <> ''000000''',
    '      ORDER BY PRIMARY KEY.',
    '    DESCRIBE TABLE lt_read_data LINES lv_rows.',
    '    IF lv_rows > 512.',
    '      RETURN.',
    '    ENDIF.',
    '    SORT lt_read_data BY mandant relid log_handle block srtf2.',
    '    ls_read_ldat-log_handle = ls_head-log_handle.',
    '    ls_read_ldat-admin-client = sy-mandt.',
    '    ls_read_ldat-admin-char_size = ls_head-char_size.',
    '    lv_read_all = ''[''.',
    '    lv_read_page = ''[''.',
    '    lv_more = ''false''.',
    '    read_stage ''BLOCK_LAYOUT''.',
    '    LOOP AT lt_read_data INTO ls_read_data.',
    '      IF ls_read_data-clustr < 1 OR ls_read_data-clustr > 512.',
    '        RETURN.',
    '      ENDIF.',
    '      IF ls_read_data-block <> lv_read_block.',
    '        lv_read_block = ls_read_data-block.',
    '        lv_read_prev = ls_read_data-srtf2.',
    '        IF lv_read_prev <> 0.',
    '          RETURN.',
    '        ENDIF.',
    '      ELSE.',
    '        ADD 1 TO lv_read_prev.',
    '        IF ls_read_data-srtf2 <> lv_read_prev.',
    '          RETURN.',
    '        ENDIF.',
    '      ENDIF.',
    '    ENDLOOP.',
    '    CLEAR lv_read_block.',
    '    LOOP AT lt_read_data INTO ls_read_data.',
    '      IF ls_read_data-block = lv_read_block.',
    '        CONTINUE.',
    '      ENDIF.',
    '      lv_read_block = ls_read_data-block.',
    '      CLEAR ls_read_block.',
    '      read_stage ''BLOCK_DECOMPRESSION''.',
    '* This routine only imports the supplied memory table, never loads,',
    '* converts, saves or calls log callbacks. Do not use BAL_DB_LOAD here.',
    '      PERFORM log_block_decompress IN PROGRAM (''SAPLSBAL_DB'')',
    '        USING ls_read_ldat lv_read_block lt_read_data',
    '        CHANGING ls_read_block.',
    '      DESCRIBE TABLE ls_read_block-t_mhdr LINES lv_rows.',
    '      IF lv_rows > 150.',
    '        RETURN.',
    '      ENDIF.',
    '      LOOP AT ls_read_block-t_mhdr INTO ls_read_mhdr.',
    '        read_stage ''MESSAGE_LAYOUT''.',
    '        IF ls_read_mhdr-msgnumber <= lv_read_total',
    '           OR ls_read_mhdr-msgnumber > 1000.',
    '          RETURN.',
    '        ENDIF.',
    '        lv_read_total = ls_read_mhdr-msgnumber.',
    '        CONCATENATE ''T_'' ls_read_mhdr-category-var',
    '          ls_read_mhdr-category-con ls_read_mhdr-category-src',
    '          ls_read_mhdr-category-par INTO lv_read_name.',
    '        UNASSIGN: <read_table>, <read_row>.',
    '        ASSIGN COMPONENT lv_read_name OF STRUCTURE ls_read_block',
    '          TO <read_table>.',
    '        IF sy-subrc <> 0.',
    '          RETURN.',
    '        ENDIF.',
    '        READ TABLE <read_table> ASSIGNING <read_row>',
    '          WITH KEY (''MSGNUMBER'') = ls_read_mhdr-msgnumber.',
    '        IF sy-subrc <> 0.',
    '          RETURN.',
    '        ENDIF.',
    '        CLEAR ls_read_msg.',
    '        MOVE-CORRESPONDING <read_row> TO ls_read_msg.',
    '        IF ls_read_msg-msgty NA ''AEWISX''',
    '           OR ls_read_msg-msgty IS INITIAL.',
    '          RETURN.',
    '        ENDIF.',
    '        read_stage ''MESSAGE_RENDERING''.',
    '        CLEAR: lv_read_text, lv_read_t100.',
    '        lv_read_langu = sy-langu.',
    '        lv_read_missing = ''false''.',
    '        SELECT SINGLE text FROM t100 INTO lv_read_t100',
    '          WHERE sprsl = lv_read_langu AND arbgb = ls_read_msg-msgid',
    '            AND msgnr = ls_read_msg-msgno.',
    '        IF sy-subrc <> 0.',
    '          SELECT SINGLE masterlang FROM t100a INTO lv_read_langu',
    '            WHERE arbgb = ls_read_msg-msgid.',
    '          IF sy-subrc = 0.',
    '            SELECT SINGLE text FROM t100 INTO lv_read_t100',
    '              WHERE sprsl = lv_read_langu AND arbgb = ls_read_msg-msgid',
    '                AND msgnr = ls_read_msg-msgno.',
    '          ENDIF.',
    '        ENDIF.',
    '        IF sy-subrc = 0.',
    '          CALL FUNCTION ''BAL_DSP_TXT_MSG_READ''',
    '            EXPORTING',
    '              i_langu = lv_read_langu i_msgid = ls_read_msg-msgid',
    '              i_msgno = ls_read_msg-msgno',
    '              i_msgv1 = ls_read_msg-msgv1 i_msgv2 = ls_read_msg-msgv2',
    '              i_msgv3 = ls_read_msg-msgv3 i_msgv4 = ls_read_msg-msgv4',
    '            IMPORTING e_message_text = lv_read_text.',
    '        ELSE.',
    '          lv_read_missing = ''true''.',
    '        ENDIF.',
    '* Self-check distinguishes missing definitions from unsupported languages.',
    '        IF iv_action = ''READ_BODY_CHECK'' AND lv_read_missing = ''true''.',
    '          SELECT sprsl FROM t100 INTO lv_read_langu UP TO 1 ROWS',
    '            WHERE arbgb = ls_read_msg-msgid',
    '              AND msgnr = ls_read_msg-msgno.',
    '          ENDSELECT.',
    '          IF sy-subrc = 4.',
    '            ev_result = ''MESSAGE_DEFINITION_ABSENT''.',
    '          ELSEIF sy-subrc = 0.',
    '            ev_result = ''MESSAGE_LANGUAGE_UNAVAILABLE''.',
    '          ELSE.',
    '            ev_result = ''MESSAGE_DEFINITION_CHECK_FAILED''.',
    '          ENDIF.',
    '          RETURN.',
    '        ENDIF.',
    '* Convert NUMC through the validated integer before JSON serialization.',
    '        lv_num = lv_read_total.',
    '        CONDENSE lv_num NO-GAPS.',
    '        CONCATENATE ''{"number":'' lv_num INTO lv_json.',
    '        append_json_field '',"type":"'' ls_read_msg-msgty.',
    '        append_json_field '',"messageClass":"'' ls_read_msg-msgid.',
    '        append_json_field '',"messageNumber":"'' ls_read_msg-msgno.',
    '        append_json_field '',"text":"'' lv_read_text.',
    '        CONCATENATE lv_json '',"textTruncated":false,''',
    '          ''"textUnavailable":'' lv_read_missing',
    '          '',"systemTime":null}'' INTO lv_json.',
    '        IF lv_read_count > 0.',
    '          CONCATENATE lv_read_all '','' INTO lv_read_all.',
    '        ENDIF.',
    '        CONCATENATE lv_read_all lv_json INTO lv_read_all.',
    '        ADD 1 TO lv_read_count.',
    '        IF ls_read_mhdr-msgnumber > lv_read_after.',
    '          IF lv_idx < lv_limit.',
    '            IF lv_idx > 0.',
    '              CONCATENATE lv_read_page '','' INTO lv_read_page.',
    '            ENDIF.',
    '            CONCATENATE lv_read_page lv_json INTO lv_read_page.',
    '            ADD 1 TO lv_idx.',
    '          ELSE.',
    '            lv_more = ''true''.',
    '          ENDIF.',
    '        ENDIF.',
    '      ENDLOOP.',
    '    ENDLOOP.',
    '    read_stage ''MESSAGE_COUNT''.',
    '    IF lv_read_count <> ls_head-msg_cnt_al.',
    '      RETURN.',
    '    ENDIF.',
    '* Detect a concurrent log update before returning any messages.',
    '    SELECT SINGLE * FROM balhdr INTO ls_read_check',
    '      WHERE lognumber = iv_lognumber.',
    '    IF sy-subrc <> 0 OR ls_read_check <> ls_head.',
    '      CONCATENATE lv_base',
    '        ''"status":"unsupported","code":"LOG_CHANGED",''',
    '        ''"headers":[],"messages":[],"hasMore":false}'' INTO ev_result.',
    '      RETURN.',
    '    ENDIF.',
    '    IF iv_action = ''READ_BODY_CHECK''. ev_result = ''OK''. RETURN. ENDIF.',
    '    CONCATENATE ls_head-aldate(4) ''-'' ls_head-aldate+4(2) ''-''',
    '      ls_head-aldate+6(2) ''T'' ls_head-altime(2) '':''',
    '      ls_head-altime+2(2) '':'' ls_head-altime+4(2) INTO lv_time.',
    '    lv_json = ''[''.',
    '    append_json_field ''{"logNumber":"'' ls_head-lognumber.',
    '    append_json_field '',"object":"'' ls_head-object.',
    '    append_json_field '',"subobject":"'' ls_head-subobject.',
    '    append_json_field '',"externalNumber":"'' ls_head-extnumber.',
    '    append_json_field '',"username":"'' ls_head-aluser.',
    '    append_json_field '',"program":"'' ls_head-alprog.',
    '    append_json_field '',"transaction":"'' ls_head-altcode.',
    '    append_json_field '',"systemTime":"'' lv_time.',
    '    lv_num = lv_read_count.',
    '    CONDENSE lv_num NO-GAPS.',
    '    CONCATENATE lv_json '',"messageCount":'' lv_num ''}]''',
    '      INTO lv_read_header.',
    '    CONCATENATE lv_read_all '']'' lv_read_header sy-mandt sy-langu',
    '      INTO lv_read_all.',
    '    read_stage ''REVISION_HASH''.',
    '    CALL METHOD cl_abap_message_digest=>calculate_hash_for_char',
    '      EXPORTING if_algorithm = ''SHA256'' if_data = lv_read_all',
    '      IMPORTING ef_hashstring = lv_read_hash.',
    '    IF strlen( lv_read_hash ) <> 64.',
    '      RETURN.',
    '    ENDIF.',
    '    TRANSLATE lv_read_hash TO LOWER CASE.',
    '    IF iv_revision IS NOT INITIAL AND iv_revision <> lv_read_hash.',
    '      CONCATENATE lv_base',
    '        ''"status":"unsupported","code":"LOG_CHANGED",''',
    '        ''"headers":[],"messages":[],"hasMore":false}'' INTO ev_result.',
    '      RETURN.',
    '    ENDIF.',
    '    CONCATENATE lv_read_page '']'' INTO lv_read_page.',
    '    CONCATENATE lv_base ''"status":"ok","code":"OK","headers":''',
    '      lv_read_header '',"messages":'' lv_read_page '',"hasMore":''',
    '      lv_more '',"revision":"'' lv_read_hash ''"}'' INTO ev_result.',
    '    CATCH cx_root.',
    '      RETURN.',
    '  ENDTRY.',
    '  RETURN.',
    'ENDIF.',
    'IF iv_action <> ''SEARCH''.',
    '  RETURN.',
    'ENDIF.',
    'IF iv_object IS INITIAL OR strlen( iv_object ) > 20',
    '   OR iv_object CA ''*+%?''',
    '   OR strlen( iv_subobject ) > 20',
    '   OR strlen( iv_external ) > 100 OR strlen( iv_user ) > 12',
    '   OR iv_subobject CA ''*+%?'' OR iv_user CA ''*+%?''',
    '   OR iv_lognumber IS NOT INITIAL OR iv_revision IS NOT INITIAL.',
    '  RETURN.',
    'ENDIF.',
    'IF iv_after_msg IS NOT INITIAL AND iv_after_msg <> ''0''.',
    '  RETURN.',
    'ENDIF.',
    'lv_limit = 50.',
    'IF iv_limit IS NOT INITIAL.',
    '  IF strlen( iv_limit ) > 2 OR iv_limit CN ''0123456789''.',
    '    RETURN.',
    '  ENDIF.',
    '  lv_limit = iv_limit.',
    'ENDIF.',
    'IF lv_limit < 1 OR lv_limit > 50.',
    '  RETURN.',
    'ENDIF.',
    'IF iv_after_log IS NOT INITIAL.',
    '  IF strlen( iv_after_log ) <> 20',
    '     OR iv_after_log CN ''0123456789''.',
    '    RETURN.',
    '  ENDIF.',
    '  lv_after = iv_after_log.',
    'ENDIF.',
    'IF iv_from IS INITIAL AND iv_to IS INITIAL.',
    '  GET TIME.',
    '  lv_to_d = sy-datum.',
    '  lv_to_t = sy-uzeit.',
    '  lv_from_d = lv_to_d - 1.',
    '  lv_from_t = lv_to_t.',
    'ELSE.',
    '  FIND REGEX',
    '    ''^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}$''',
    '    IN iv_from.',
    '  IF sy-subrc <> 0.',
    '    RETURN.',
    '  ENDIF.',
    '  FIND REGEX',
    '    ''^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}$''',
    '    IN iv_to.',
    '  IF sy-subrc <> 0.',
    '    RETURN.',
    '  ENDIF.',
    '  CONCATENATE iv_from(4) iv_from+5(2) iv_from+8(2) INTO lv_from_d.',
    '  CONCATENATE iv_to(4) iv_to+5(2) iv_to+8(2) INTO lv_to_d.',
    '  CONCATENATE iv_from+11(2) iv_from+14(2) iv_from+17(2)',
    '    INTO lv_from_t.',
    '  CONCATENATE iv_to+11(2) iv_to+14(2) iv_to+17(2)',
    '    INTO lv_to_t.',
    'ENDIF.',
    'CALL FUNCTION ''DATE_CHECK_PLAUSIBILITY''',
    '  EXPORTING date = lv_from_d',
    '  EXCEPTIONS OTHERS = 1.',
    'IF sy-subrc <> 0 OR lv_from_d(4) = ''0000''.',
    '  RETURN.',
    'ENDIF.',
    'CALL FUNCTION ''DATE_CHECK_PLAUSIBILITY''',
    '  EXPORTING date = lv_to_d',
    '  EXCEPTIONS OTHERS = 1.',
    'IF sy-subrc <> 0 OR lv_to_d(4) = ''0000''.',
    '  RETURN.',
    'ENDIF.',
    'IF lv_from_t(2) > ''23'' OR lv_to_t(2) > ''23''',
    '   OR lv_from_t+2(2) > ''59'' OR lv_to_t+2(2) > ''59''',
    '   OR lv_from_t+4(2) > ''59'' OR lv_to_t+4(2) > ''59''.',
    '  RETURN.',
    'ENDIF.',
    'lv_days = lv_to_d - lv_from_d.',
    'IF lv_days < 0 OR lv_days > 1.',
    '  RETURN.',
    'ENDIF.',
    'lv_span = lv_days * 86400 + lv_to_t - lv_from_t.',
    'IF lv_span < 0 OR lv_span > 86400.',
    '  RETURN.',
    'ENDIF.',
    'lv_object = iv_object.',
    'IF iv_subobject IS NOT INITIAL.',
    '  lr_sub-sign = ''I''. lr_sub-option = ''EQ''.',
    '  lr_sub-low = iv_subobject. APPEND lr_sub.',
    'ENDIF.',
    'IF iv_external IS NOT INITIAL.',
    '  lr_ext-sign = ''I''. lr_ext-option = ''EQ''.',
    '  lr_ext-low = iv_external. APPEND lr_ext.',
    'ENDIF.',
    'IF iv_user IS NOT INITIAL.',
    '  lr_user-sign = ''I''. lr_user-option = ''EQ''.',
    '  lr_user-low = iv_user. APPEND lr_user.',
    'ENDIF.',
    'AUTHORITY-CHECK OBJECT ''S_APPL_LOG''',
    '  ID ''ALG_OBJECT'' FIELD lv_object',
    '  ID ''ALG_SUBOBJ'' FIELD lr_sub-low',
    '  ID ''ACTVT'' FIELD ''03''.',
    'IF sy-subrc <> 0.',
    '  CONCATENATE lv_base',
    '    ''"status":"forbidden","code":"NO_AUTHORITY",''',
    '    ''"headers":[],"messages":[],"hasMore":false}'' INTO ev_result.',
    '  RETURN.',
    'ENDIF.',
    'lv_fetch = lv_limit + 1.',
    'TRY.',
    '* Refuse restrictions without instantiating extension classes.',
    '  SELECT SINGLE default_class FROM badi_main INTO lv_default',
    '    WHERE badi_name = ''SBAL_AUTHORITY_RESTRICTION''.',
    '  IF sy-subrc <> 0 OR lv_default IS NOT INITIAL.',
    '    RETURN.',
    '  ENDIF.',
    '  SELECT badi_name FROM badi_impl INTO lv_impl UP TO 1 ROWS',
    '    WHERE badi_name = ''SBAL_AUTHORITY_RESTRICTION''.',
    '  ENDSELECT.',
    '  IF sy-subrc <> 4.',
    '    RETURN.',
    '  ENDIF.',
    '* Implicit Open SQL client handling binds reads to SY-MANDT.',
    '  SELECT lognumber object subobject extnumber aldate altime',
    '         aluser alprog altcode msg_cnt_al',
    '    FROM balhdr INTO CORRESPONDING FIELDS OF TABLE lt_head',
    '    UP TO lv_fetch ROWS',
    '    WHERE object = lv_object AND subobject IN lr_sub',
    '      AND extnumber IN lr_ext AND aluser IN lr_user',
    '      AND lognumber > lv_after',
    '      AND ( aldate > lv_from_d OR',
    '            ( aldate = lv_from_d AND altime >= lv_from_t ) )',
    '      AND ( aldate < lv_to_d OR',
    '            ( aldate = lv_to_d AND altime <= lv_to_t ) )',
    '    ORDER BY lognumber.',
    '* Check every candidate, including the extra pagination row.',
    '  LOOP AT lt_head INTO ls_head.',
    '    AUTHORITY-CHECK OBJECT ''S_APPL_LOG''',
    '      ID ''ALG_OBJECT'' FIELD ls_head-object',
    '      ID ''ALG_SUBOBJ'' FIELD ls_head-subobject',
    '      ID ''ACTVT'' FIELD ''03''.',
    '    IF sy-subrc <> 0.',
    '      CONCATENATE lv_base',
    '        ''"status":"forbidden","code":"NO_AUTHORITY",''',
    '        ''"headers":[],"messages":[],"hasMore":false}'' INTO ev_result.',
    '      RETURN.',
    '    ENDIF.',
    '  ENDLOOP.',
    '  CATCH cx_root.',
    '    RETURN.',
    'ENDTRY.',
    'DESCRIBE TABLE lt_head LINES lv_rows.',
    'lv_more = ''false''.',
    'IF lv_rows > lv_limit.',
    '  lv_more = ''true''.',
    '  DELETE lt_head INDEX lv_fetch.',
    'ENDIF.',
    'lv_json = ''[''.',
    'LOOP AT lt_head INTO ls_head.',
    '  IF sy-tabix > 1.',
    '    CONCATENATE lv_json '','' INTO lv_json.',
    '  ENDIF.',
    '  CONCATENATE ls_head-aldate(4) ''-'' ls_head-aldate+4(2) ''-''',
    '    ls_head-aldate+6(2) ''T'' ls_head-altime(2) '':''',
    '    ls_head-altime+2(2) '':'' ls_head-altime+4(2) INTO lv_time.',
    '  append_json_field ''{"logNumber":"'' ls_head-lognumber.',
    '  append_json_field '',"object":"'' ls_head-object.',
    '  append_json_field '',"subobject":"'' ls_head-subobject.',
    '  append_json_field '',"externalNumber":"'' ls_head-extnumber.',
    '  append_json_field '',"username":"'' ls_head-aluser.',
    '  append_json_field '',"program":"'' ls_head-alprog.',
    '  append_json_field '',"transaction":"'' ls_head-altcode.',
    '  append_json_field '',"systemTime":"'' lv_time.',
    '  lv_idx = ls_head-msg_cnt_al.',
    '  IF lv_idx < 0 OR lv_idx > 999999.',
    '    RETURN.',
    '  ENDIF.',
    '  lv_num = lv_idx.',
    '  CONDENSE lv_num NO-GAPS.',
    '  CONCATENATE lv_json '',"messageCount":'' lv_num ''}'' INTO lv_json.',
    'ENDLOOP.',
    'CONCATENATE lv_json '']'' INTO lv_json.',
    'CONCATENATE lv_from_d(4) ''-'' lv_from_d+4(2) ''-''',
    '  lv_from_d+6(2) ''T'' lv_from_t(2) '':'' lv_from_t+2(2) '':''',
    '  lv_from_t+4(2) INTO lv_from.',
    'CONCATENATE lv_to_d(4) ''-'' lv_to_d+4(2) ''-''',
    '  lv_to_d+6(2) ''T'' lv_to_t(2) '':'' lv_to_t+2(2) '':''',
    '  lv_to_t+4(2) INTO lv_to.',
    'CONCATENATE lv_base ''"status":"ok","code":"OK","headers":''',
    '  lv_json '',"messages":[],"hasMore":'' lv_more',
    '  '',"fromSystemTime":"'' lv_from ''","toSystemTime":"''',
    '  lv_to ''"}'' INTO ev_result.',
    '',
    '',
    '',
    '',
    '',
    'ENDFUNCTION.'
)
# <<< ORVANTA-APPLICATION-LOG-SOURCE


# Deploys the CAPABILITIES self-description of the application-log helper Z_ORVANTA_LOG_READ
# (function group ZORVANTA_LOG). New-InstallProgram cannot be reused for it: that generator
# hard-codes the repository function group ZORVANTA_MCP_CORE, the repository interface and a
# TABLE OF rssource body buffer, whose 72-character LINE field would truncate the one
# 74-character comment line of this body.
#
# The rendered body is transported verbatim (see $applicationLogFunctionSource). The object is
# recorded on the function group's existing request assignment; this action never records,
# re-assigns, releases, deletes or otherwise mutates a transport.
function New-ApplicationLogProgram {
    param(
        [switch]$ReplaceExisting,
        [string]$FunctionName = "Z_ORVANTA_LOG_READ",
        [string]$TransportNumber = "GR2K923472"
    )

    $functionPool = "ZORVANTA_LOG"
    $functionShortText = "ORVANTA bounded read-only SLG1 heade"
    $applicationLogRequest = "GR2K923472"
    $applicationLogParameters = @(
        "IV_ACTION",
        "IV_OBJECT",
        "IV_SUBOBJECT",
        "IV_EXTERNAL",
        "IV_USER",
        "IV_FROM",
        "IV_TO",
        "IV_AFTER_LOG",
        "IV_LOGNUMBER",
        "IV_AFTER_MSG",
        "IV_REVISION",
        "IV_LIMIT"
    )

    if (-not $TransportNumber) {
        $TransportNumber = $applicationLogRequest
    }
    # The rendered body pins its own provenance (SOURCE|TRANSPORT|GR2K923472|GR2K923473), so the
    # deployment must run under exactly that request. Fail closed instead of writing the group
    # into a different request.
    if ($TransportNumber -ne $applicationLogRequest) {
        throw "New-ApplicationLogProgram deploys only under $applicationLogRequest; requested $TransportNumber."
    }

    $existingObjectLines = if ($ReplaceExisting) {
        @(
            "IF sy-subrc = 0.",
            "  CALL FUNCTION 'FUNCTION_DELETE'",
            "    EXPORTING",
            "      funcname = '$FunctionName'",
            "      suppress_success_message = 'X'",
            "    EXCEPTIONS error_message = 1.",
            "  IF sy-subrc <> 0.",
            "    WRITE: / 'DELETE_ERROR', sy-subrc, sy-msgid, sy-msgno.",
            "    ROLLBACK WORK.",
            "    STOP.",
            "  ENDIF.",
            "  COMMIT WORK AND WAIT.",
            "  WRITE / 'DELETED $FunctionName'.",
            "ELSEIF sy-subrc <> 1.",
            "  WRITE: / 'EXISTENCE_CHECK_ERROR', sy-subrc.",
            "  STOP.",
            "ENDIF."
        )
    }
    else {
        @(
            "IF sy-subrc = 0.",
            "  WRITE / 'ALREADY_EXISTS'.",
            "  STOP.",
            "ELSEIF sy-subrc <> 1.",
            "  WRITE: / 'EXISTENCE_CHECK_ERROR', sy-subrc.",
            "  STOP.",
            "ENDIF."
        )
    }

    # Fail-closed provenance gate. It runs before FUNCTION_EXISTS and FUNCTION_DELETE, so a
    # request that is missing or already released aborts before anything is changed. The object
    # assignment is never touched: the function module belongs to function group ZORVANTA_LOG,
    # whose existing request entry carries it. The e071 lookup below only reports what it finds;
    # it does not record, move or release anything.
    $transportGuardLines = @(
        "SELECT SINGLE * FROM e070 INTO ls_request",
        "  WHERE trkorr = '$TransportNumber'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR REQUEST_NOT_FOUND $TransportNumber'.",
        "  STOP.",
        "ENDIF.",
        "IF ls_request-trstatus <> 'D'.",
        "  WRITE: / 'ERROR REQUEST_NOT_MODIFIABLE',",
        "    ls_request-trkorr, ls_request-trstatus.",
        "  STOP.",
        "ENDIF.",
        "SELECT SINGLE * FROM tadir INTO ls_tadir",
        "  WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "    AND obj_name = '$functionPool'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR FUGR_TADIR_NOT_FOUND $functionPool'.",
        "  STOP.",
        "ENDIF.",
        "WRITE: / 'FUGR_PACKAGE', ls_tadir-devclass.",
        "SELECT SINGLE * FROM e071 INTO ls_e071",
        "  WHERE trkorr = '$TransportNumber'",
        "    AND pgmid = 'R3TR' AND object = 'FUGR'",
        "    AND obj_name = '$functionPool'.",
        "IF sy-subrc <> 0.",
        "  SELECT SINGLE * FROM e071 INTO ls_e071",
        "    WHERE trkorr = '$TransportNumber'",
        "      AND obj_name = '$functionPool'.",
        "ENDIF.",
        "IF sy-subrc <> 0.",
        "  SELECT SINGLE * FROM e071 INTO ls_e071",
        "    WHERE trkorr = '$TransportNumber'",
        "      AND obj_name = '$FunctionName'.",
        "ENDIF.",
        "IF sy-subrc = 0.",
        "  WRITE: / 'TRANSPORT', ls_e071-pgmid,",
        "    ls_e071-object, ls_e071-obj_name.",
        "ELSE.",
        "  WRITE / 'TRANSPORT_ENTRY_NOT_OBSERVED $functionPool'.",
        "ENDIF."
    )

    # One literal per parameter, in the declared order. dbfield STRINGVAL reproduces the live
    # signature (VALUE(IV_*) TYPE STRINGVAL OPTIONAL) and the existing pass-by-value default
    # (RSIMP-REFERENCE stays initial).
    $parameterLines = @()
    foreach ($parameter in $applicationLogParameters) {
        $parameterLines += @(
            "CLEAR ls_import.",
            "ls_import-parameter = '$parameter'.",
            "ls_import-dbfield = 'STRINGVAL'.",
            "ls_import-optional = 'X'.",
            "APPEND ls_import TO lt_import."
        )
    }
    $parameterLines += @(
        "CLEAR ls_export.",
        "ls_export-parameter = 'EV_RESULT'.",
        "ls_export-dbfield = 'STRINGVAL'.",
        "APPEND ls_export TO lt_export."
    )

    # The body is split into literal chunks that never end on a blank (and are never entirely
    # blank unless the whole line is), so CONCATENATE ... RESPECTING BLANKS reproduces each line
    # exactly. 40 characters keep every generated statement inside the 72-column limit of the
    # temporary program; the body itself may be up to the 255-character ABAP source line limit.
    $applicationLogChunkLength = 40
    $sourceProgramLines = foreach ($line in $applicationLogFunctionSource) {
        if ($line.Length -gt 255) {
            throw "Generated application-log source exceeds 255 characters: $line"
        }
        $chunks = @()
        $offset = 0
        while ($offset -lt $line.Length) {
            $length = [Math]::Min($applicationLogChunkLength, $line.Length - $offset)
            $hasText = $false
            for ($index = 0; $index -lt $length; $index++) {
                if (-not [char]::IsWhiteSpace($line[$offset + $index])) {
                    $hasText = $true
                    break
                }
            }
            if ($hasText) {
                while (
                    $length -gt 1 -and
                    [char]::IsWhiteSpace($line[$offset + $length - 1])
                ) {
                    $length--
                }
            }
            else {
                while (
                    ($offset + $length) -lt $line.Length -and
                    [char]::IsWhiteSpace($line[$offset + $length - 1])
                ) {
                    $length++
                }
            }
            $chunks += $line.Substring($offset, $length)
            $offset += $length
        }
        if ($chunks.Count -gt 1 -and -not ($chunks[-1] -match '\S')) {
            throw "Generated application-log line ends on blanks: $line"
        }
        if (($chunks | Where-Object { $_.Length -gt $applicationLogChunkLength }).Count -gt 0) {
            throw "Generated application-log chunk is too long: $line"
        }
        $chunks = @($chunks | ForEach-Object { $_.Replace("'", "''") })
        "lv_source_line = '$($chunks[0])'."
        foreach ($chunk in $chunks | Select-Object -Skip 1) {
            "CONCATENATE lv_source_line '$chunk'"
            "  INTO lv_source_line RESPECTING BLANKS."
        }
        "APPEND lv_source_line TO lt_body."
    }

    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "DATA lt_import TYPE TABLE OF rsimp.",
        "DATA lt_export TYPE TABLE OF rsexp.",
        "DATA lt_tables TYPE TABLE OF rstbl.",
        "DATA lt_exceptions TYPE TABLE OF rsexc.",
        "DATA lt_parameter_docu TYPE TABLE OF rsfdo.",
        "DATA lt_body TYPE STANDARD TABLE OF string.",
        "DATA ls_import TYPE rsimp.",
        "DATA ls_export TYPE rsexp.",
        "DATA lv_body_line TYPE string.",
        "DATA lv_read_line TYPE string.",
        "DATA lv_source_line TYPE string.",
        "DATA lt_function_code TYPE rsfb_source.",
        "DATA lt_verify TYPE rsfb_source.",
        "DATA lv_function_line TYPE string.",
        "DATA lv_function_include TYPE rs38l-include.",
        "DATA lv_insert_index TYPE i.",
        "DATA lv_body_start TYPE i.",
        "DATA lv_verify_index TYPE i.",
        "DATA lv_verify_position TYPE i.",
        "DATA lv_verify_mismatch TYPE i.",
        "DATA lv_expected_count TYPE i.",
        "DATA lv_body_count TYPE i.",
        "DATA lv_read_count TYPE i.",
        "DATA lv_generate_message TYPE string.",
        "DATA lv_generate_line TYPE i.",
        "DATA lv_generate_word TYPE string.",
        "DATA ls_tadir TYPE tadir.",
        "DATA ls_e071 TYPE e071.",
        "DATA ls_request TYPE e070."
    ) + $transportGuardLines + @(
        "CALL FUNCTION 'FUNCTION_EXISTS'",
        "  EXPORTING funcname = '$FunctionName'",
        "  EXCEPTIONS function_not_exist = 1 others = 2."
    ) + $existingObjectLines + $parameterLines + $sourceProgramLines + @(
        "CALL FUNCTION 'FUNCTION_CREATE'",
        "  EXPORTING",
        "    funcname = '$FunctionName'",
        "    function_pool = '$functionPool'",
        "    remote_call = 'R'",
        "    short_text = '$functionShortText'",
        "    suppress_corr_check = 'X'",
        "    save_active = 'X'",
        "  IMPORTING",
        "    function_include = lv_function_include",
        "  TABLES",
        "    import_parameter = lt_import",
        "    export_parameter = lt_export",
        "    tables_parameter = lt_tables",
        "    exception_list = lt_exceptions",
        "    parameter_docu = lt_parameter_docu",
        "  EXCEPTIONS",
        "    double_task = 1",
        "    error_message = 2",
        "    function_already_exists = 3",
        "    invalid_function_pool = 4",
        "    invalid_name = 5",
        "    too_many_functions = 6",
        "    no_modify_permission = 7",
        "    no_show_permission = 8",
        "    enqueue_system_failure = 9",
        "    canceled_in_corr = 10",
        "    others = 11."
    ) + @(
        "IF sy-subrc <> 0.",
        "  WRITE: / 'CREATE_ERROR', sy-subrc, sy-msgid, sy-msgno,",
        "    sy-msgv1, sy-msgv2, sy-msgv3, sy-msgv4.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "UPDATE enlfdir SET generated = space",
        "  WHERE funcname = '$FunctionName'.",
        "READ REPORT lv_function_include INTO lt_function_code.",
        "IF sy-subrc <> 0.",
        "  WRITE: / 'SOURCE_READ_ERROR', sy-subrc,",
        "    lv_function_include.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "CLEAR lv_insert_index.",
        "LOOP AT lt_function_code INTO lv_function_line.",
        "  IF lv_function_line CS '""-----------------------------------------'",
        "     AND sy-tabix <> 2.",
        "    lv_insert_index = sy-tabix + 1.",
        "    EXIT.",
        "  ENDIF.",
        "ENDLOOP.",
        "IF lv_insert_index IS INITIAL.",
        "  WRITE / 'SOURCE_MARKER_ERROR'.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "DELETE lt_function_code FROM lv_insert_index.",
        "lv_body_start = lv_insert_index.",
        "LOOP AT lt_body INTO lv_body_line.",
        "  INSERT lv_body_line INTO lt_function_code",
        "    INDEX lv_insert_index.",
        "  lv_insert_index = lv_insert_index + 1.",
        "ENDLOOP.",
        "INSERT REPORT lv_function_include FROM lt_function_code.",
        "IF sy-subrc <> 0.",
        "  WRITE: / 'SOURCE_INSERT_ERROR', sy-subrc,",
        "    lv_function_include.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "GENERATE REPORT 'SAPL$functionPool'",
        "  MESSAGE lv_generate_message LINE lv_generate_line",
        "  WORD lv_generate_word.",
        "IF sy-subrc <> 0.",
        "  WRITE: / 'GENERATE_ERROR', sy-subrc, lv_generate_line,",
        "    lv_generate_word, / lv_generate_message.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "DESCRIBE TABLE lt_body LINES lv_body_count.",
        "DESCRIBE TABLE lt_function_code LINES lv_expected_count.",
        "CLEAR lt_verify.",
        "READ REPORT lv_function_include INTO lt_verify.",
        "IF sy-subrc <> 0.",
        "  WRITE: / 'ERROR BODY_VERIFY_READ', sy-subrc.",
        "ELSE.",
        "  DESCRIBE TABLE lt_verify LINES lv_read_count.",
        "  IF lv_read_count <> lv_expected_count.",
        "    WRITE: / 'ERROR BODY_LINE_COUNT', lv_expected_count,",
        "      lv_read_count.",
        "  ENDIF.",
        "  CLEAR lv_verify_mismatch.",
        "  CLEAR lv_verify_position.",
        "  LOOP AT lt_body INTO lv_body_line.",
        "    lv_verify_position = lv_verify_position + 1.",
        "    lv_verify_index = lv_body_start + lv_verify_position - 1.",
        "    CLEAR lv_read_line.",
        "    READ TABLE lt_verify INTO lv_read_line",
        "      INDEX lv_verify_index.",
        "    IF sy-subrc <> 0 OR lv_read_line <> lv_body_line.",
        "      IF lv_verify_mismatch IS INITIAL.",
        "        lv_verify_mismatch = lv_verify_position.",
        "      ENDIF.",
        "    ENDIF.",
        "  ENDLOOP.",
        "  IF lv_verify_mismatch IS INITIAL.",
        "    WRITE: / 'BODY_VERIFY_OK', lv_body_count.",
        "  ELSE.",
        "    WRITE: / 'ERROR BODY_VERIFY_FAILED', lv_verify_mismatch.",
        "  ENDIF.",
        "ENDIF.",
        "UPDATE enlfdir SET generated = 'X'",
        "  WHERE funcname = '$FunctionName'.",
        "IF sy-subrc <> 0.",
        "  WRITE: / 'FUNCTION_ACTIVATION_FLAG_ERROR', sy-subrc.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "COMMIT WORK AND WAIT.",
        "WRITE / 'CREATED $FunctionName'."
    )
}

function New-FunctionGroupDiagnosticProgram {
    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "DATA lv_message TYPE string.",
        "DATA lv_line TYPE i.",
        "DATA lv_word TYPE string.",
        "GENERATE REPORT 'SAPLZORVANTA_MCP_CORE'",
        "  MESSAGE lv_message LINE lv_line WORD lv_word.",
        "WRITE: / 'SUBRC', sy-subrc.",
        "WRITE: / 'LINE', lv_line.",
        "WRITE: / 'WORD', lv_word.",
        "WRITE: / 'MESSAGE', lv_message."
    )
}

function New-HelperApiDiagnosticProgram {
    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "DATA lt_names TYPE TABLE OF rs38l-name.",
        "DATA lv_name TYPE rs38l-name.",
        "DATA lv_subrc TYPE sy-subrc.",
        "DATA ls_enlfdir TYPE enlfdir.",
        "APPEND 'Z_ORVANTA_MCP_EXECUTE' TO lt_names.",
        "APPEND 'Z_ORVANTA_MCP_DYNPRO_API' TO lt_names.",
        "APPEND 'Z_ORVANTA_MCP_DDIC_API' TO lt_names.",
        "LOOP AT lt_names INTO lv_name.",
        "  CALL FUNCTION 'FUNCTION_EXISTS'",
        "    EXPORTING funcname = lv_name",
        "    EXCEPTIONS function_not_exist = 1 others = 2.",
        "  lv_subrc = sy-subrc.",
        "  WRITE: / 'HELPER', lv_name, 'EXISTS', lv_subrc.",
        "  IF lv_subrc = 0.",
        "    CLEAR ls_enlfdir.",
        "    SELECT SINGLE * FROM enlfdir INTO ls_enlfdir",
        "      WHERE funcname = lv_name.",
        "    WRITE: / 'STATE', lv_name, ls_enlfdir-generated,",
        "      ls_enlfdir-active.",
        "  ENDIF.",
        "ENDLOOP."
    )
}

function New-RepositoryFunctionDiagnosticProgram {
    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "DATA ls_tfdir TYPE tfdir.",
        "DATA ls_enlfdir TYPE enlfdir.",
        "DATA lt_code TYPE TABLE OF rssource.",
        "DATA ls_code TYPE rssource.",
        "DATA lv_include TYPE sy-repid.",
        "DATA lv_group TYPE sy-repid.",
        "DATA lv_lines TYPE i.",
        "FIELD-SYMBOLS <lv_any> TYPE any.",
        "DEFINE write_component.",
        "  ASSIGN COMPONENT &1 OF STRUCTURE &2 TO <lv_any>.",
        "  IF sy-subrc = 0.",
        "    WRITE: / &1, <lv_any>.",
        "  ENDIF.",
        "END-OF-DEFINITION.",
        "CALL FUNCTION 'FUNCTION_EXISTS'",
        "  EXPORTING funcname = 'Z_ORVANTA_MCP_DYNPRO_API'",
        "  EXCEPTIONS function_not_exist = 1 OTHERS = 2.",
        "WRITE: / 'FUNCTION_EXISTS', sy-subrc.",
        "SELECT SINGLE * FROM tfdir INTO ls_tfdir",
        "  WHERE funcname = 'Z_ORVANTA_MCP_DYNPRO_API'.",
        "WRITE: / 'TFDIR_SUBRC', sy-subrc.",
        "write_component 'FUNCNAME' ls_tfdir.",
        "write_component 'PNAME' ls_tfdir.",
        "write_component 'INCLUDE' ls_tfdir.",
        "write_component 'FMODE' ls_tfdir.",
        "lv_group = ls_tfdir-pname+4.",
        "CONCATENATE 'L' lv_group 'U' ls_tfdir-include",
        "  INTO lv_include.",
        "SELECT SINGLE * FROM enlfdir INTO ls_enlfdir",
        "  WHERE funcname = 'Z_ORVANTA_MCP_DYNPRO_API'.",
        "WRITE: / 'ENLFDIR_SUBRC', sy-subrc.",
        "write_component 'FUNCNAME' ls_enlfdir.",
        "write_component 'GENERATED' ls_enlfdir.",
        "write_component 'ACTIVE' ls_enlfdir.",
        "WRITE: / 'SOURCE_INCLUDE', lv_include.",
        "READ REPORT lv_include INTO lt_code.",
        "WRITE: / 'SOURCE_SUBRC', sy-subrc.",
        "DESCRIBE TABLE lt_code LINES lv_lines.",
        "WRITE: / 'SOURCE_LINES', lv_lines.",
        "LOOP AT lt_code INTO ls_code.",
        "  IF sy-tabix <= 12 OR sy-tabix > lv_lines - 5.",
        "    WRITE: / 'SOURCE', sy-tabix, ls_code-line.",
        "  ENDIF.",
        "ENDLOOP."
    )
}

function New-AssignmentInspectionProgram {
    param([string]$RequestNumber)

    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "DATA ls_package TYPE tdevc.",
        "DATA ls_request TYPE e070.",
        "DATA ls_task TYPE e070.",
        "DATA ls_tadir TYPE tadir.",
        "DATA ls_tfdir TYPE tfdir.",
        "DATA ls_t100 TYPE t100.",
        "DATA ls_e071 TYPE e071.",
        "DATA lv_task TYPE trkorr.",
        "DATA lv_prog_transport TYPE c LENGTH 1.",
        "SELECT SINGLE * FROM tdevc INTO ls_package",
        "  WHERE devclass = 'ZABAP'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR PACKAGE_NOT_FOUND ZABAP'.",
        "  STOP.",
        "ENDIF.",
        "SELECT SINGLE * FROM e070 INTO ls_request",
        "  WHERE trkorr = '$RequestNumber'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR REQUEST_NOT_FOUND $RequestNumber'.",
        "  STOP.",
        "ENDIF.",
        "IF ls_request-strkorr IS NOT INITIAL.",
        "  ls_task = ls_request.",
        "  SELECT SINGLE * FROM e070 INTO ls_request",
        "    WHERE trkorr = ls_task-strkorr.",
        "  IF sy-subrc <> 0.",
        "    WRITE / 'ERROR PARENT_REQUEST_NOT_FOUND'.",
        "    STOP.",
        "  ENDIF.",
        "ELSE.",
        "  SELECT SINGLE * FROM e070 INTO ls_task",
        "    WHERE strkorr = ls_request-trkorr",
        "      AND as4user = sy-uname",
        "      AND trstatus = 'D'.",
        "  IF sy-subrc <> 0.",
        "    WRITE / 'ERROR MODIFIABLE_USER_TASK_NOT_FOUND'.",
        "    STOP.",
        "  ENDIF.",
        "ENDIF.",
        "IF ls_request-trfunction <> 'K'",
        "   OR ls_request-trstatus <> 'D'.",
        "  WRITE: / 'ERROR REQUEST_NOT_MODIFIABLE_WORKBENCH',",
        "    ls_request-trfunction, ls_request-trstatus.",
        "  STOP.",
        "ENDIF.",
        "lv_task = ls_task-trkorr.",
        "WRITE: / 'PACKAGE', ls_package-devclass.",
        "WRITE: / 'REQUEST', ls_request-trkorr,",
        "  ls_request-as4user, ls_request-trstatus,",
        "  ls_request-trfunction.",
        "WRITE: / 'TASK', lv_task, ls_task-as4user,",
        "  ls_task-trstatus, ls_task-trfunction.",
        "SELECT SINGLE * FROM tadir INTO ls_tadir",
        "  WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "    AND obj_name = 'ZORVANTA_MCP_CORE'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR FUGR_TADIR_NOT_FOUND'.",
        "  STOP.",
        "ENDIF.",
        "WRITE: / 'BEFORE FUGR', ls_tadir-devclass.",
        "SELECT SINGLE * FROM tadir INTO ls_tadir",
        "  WHERE pgmid = 'R3TR' AND object = 'CLAS'",
        "    AND obj_name = 'ZCL_ORVANTA_MCP_CORE'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR CLAS_TADIR_NOT_FOUND'.",
        "  STOP.",
        "ENDIF.",
        "WRITE: / 'BEFORE CLAS', ls_tadir-devclass.",
        "SELECT SINGLE * FROM tadir INTO ls_tadir",
        "  WHERE pgmid = 'R3TR' AND object = 'PROG'",
        "    AND obj_name = 'ZCODEX_MCP_DYNPRO'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR PROG_TADIR_NOT_FOUND'.",
        "  STOP.",
        "ENDIF.",
        "WRITE: / 'DYNPRO PROG PACKAGE', ls_tadir-devclass.",
        "SELECT SINGLE * FROM tadir INTO ls_tadir",
        "  WHERE pgmid = 'R3TR' AND object = 'TRAN'",
        "    AND obj_name = 'ZCODEX_MCP_UI'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR TRAN_TADIR_NOT_FOUND'.",
        "  STOP.",
        "ENDIF.",
        "WRITE: / 'DYNPRO TRAN PACKAGE', ls_tadir-devclass.",
        "SELECT SINGLE * FROM tfdir INTO ls_tfdir",
        "  WHERE funcname = 'Z_ORVANTA_MCP_EXECUTE'",
        "    AND pname = 'SAPLZORVANTA_MCP_CORE'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR FUNCTION_OWNER_MISMATCH'.",
        "  STOP.",
        "ENDIF.",
        "WRITE / 'FUNCTION_OWNER ZORVANTA_MCP_CORE'.",
        "SELECT SINGLE * FROM t100 INTO ls_t100",
        "  WHERE sprsl = sy-langu AND arbgb = 'TK'",
        "    AND msgnr = '127'.",
        "IF sy-subrc = 0.",
        "  WRITE: / 'TK127', ls_t100-text.",
        "ENDIF.",
        "SELECT SINGLE * FROM e071 INTO ls_e071",
        "  WHERE trkorr = ls_request-trkorr",
        "    AND pgmid = 'R3TR' AND object = 'FUGR'",
        "    AND obj_name = 'ZORVANTA_MCP_CORE'.",
        "IF sy-subrc = 0.",
        "  WRITE / 'TRANSPORT R3TR FUGR ZORVANTA_MCP_CORE'.",
        "ENDIF.",
        "SELECT SINGLE * FROM e071 INTO ls_e071",
        "  WHERE trkorr = ls_request-trkorr",
        "    AND pgmid = 'R3TR' AND object = 'CLAS'",
        "    AND obj_name = 'ZCL_ORVANTA_MCP_CORE'.",
        "IF sy-subrc = 0.",
        "  WRITE / 'TRANSPORT R3TR CLAS ZCL_ORVANTA_MCP_CORE'.",
        "ENDIF.",
        "SELECT SINGLE * FROM e071 INTO ls_e071",
        "  WHERE trkorr = ls_request-trkorr",
        "    AND pgmid = 'R3TR' AND object = 'PROG'",
        "    AND obj_name = 'ZCODEX_MCP_DYNPRO'.",
        "IF sy-subrc <> 0.",
        "  SELECT SINGLE * FROM e071 INTO ls_e071",
        "    WHERE trkorr = lv_task",
        "      AND pgmid = 'R3TR' AND object = 'PROG'",
        "      AND obj_name = 'ZCODEX_MCP_DYNPRO'.",
        "ENDIF.",
        "IF sy-subrc = 0.",
        "  WRITE / 'TRANSPORT R3TR PROG ZCODEX_MCP_DYNPRO'.",
        "  lv_prog_transport = 'X'.",
        "ELSE.",
        "  WRITE / 'INFO DYNPRO_PROG_NOT_IN_REQUEST'.",
        "ENDIF.",
        "SELECT SINGLE * FROM e071 INTO ls_e071",
        "  WHERE trkorr = ls_request-trkorr",
        "    AND pgmid = 'LIMU' AND object = 'DYNP'",
        "    AND obj_name = 'ZCODEX_MCP_DYNPRO0100'.",
        "IF sy-subrc <> 0.",
        "  SELECT SINGLE * FROM e071 INTO ls_e071",
        "    WHERE trkorr = lv_task",
        "      AND pgmid = 'LIMU' AND object = 'DYNP'",
        "      AND obj_name = 'ZCODEX_MCP_DYNPRO0100'.",
        "ENDIF.",
        "IF sy-subrc = 0.",
        "  WRITE / 'TRANSPORT LIMU DYNP ZCODEX_MCP_DYNPRO0100'.",
        "ELSEIF lv_prog_transport = 'X'.",
        "  WRITE / 'TRANSPORT SCREEN VIA R3TR PROG'.",
        "ELSE.",
        "  WRITE / 'INFO DYNPRO_SCREEN_NOT_IN_REQUEST'.",
        "ENDIF.",
        "SELECT SINGLE * FROM e071 INTO ls_e071",
        "  WHERE trkorr = ls_request-trkorr",
        "    AND pgmid = 'R3TR' AND object = 'TRAN'",
        "    AND obj_name = 'ZCODEX_MCP_UI'.",
        "IF sy-subrc <> 0.",
        "  SELECT SINGLE * FROM e071 INTO ls_e071",
        "    WHERE trkorr = lv_task",
        "      AND pgmid = 'R3TR' AND object = 'TRAN'",
        "      AND obj_name = 'ZCODEX_MCP_UI'.",
        "ENDIF.",
        "IF sy-subrc = 0.",
        "  WRITE / 'TRANSPORT R3TR TRAN ZCODEX_MCP_UI'.",
        "ELSE.",
        "  WRITE / 'INFO DYNPRO_TRANSACTION_NOT_IN_REQUEST'.",
        "ENDIF.",
        "WRITE / 'READY'."
    )
}

function New-AssignmentProgram {
    param([string]$RequestNumber)

    return @(
        "REPORT zorvanta_mcp_bootstrap.",
        "DATA ls_package TYPE tdevc.",
        "DATA ls_request TYPE e070.",
        "DATA ls_task TYPE e070.",
        "DATA ls_tadir TYPE tadir.",
        "DATA ls_new_tadir TYPE tadir.",
        "DATA ls_e071 TYPE e071.",
        "DATA lt_objects TYPE tredt_objects.",
        "DATA ls_object TYPE ko200.",
        "DATA lt_record_tadir TYPE scts_tadir.",
        "DATA lv_task TYPE trkorr.",
        "SELECT SINGLE * FROM tdevc INTO ls_package",
        "  WHERE devclass = 'ZABAP'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR PACKAGE_NOT_FOUND ZABAP'.",
        "  STOP.",
        "ENDIF.",
        "SELECT SINGLE * FROM e070 INTO ls_request",
        "  WHERE trkorr = '$RequestNumber'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR REQUEST_NOT_FOUND $RequestNumber'.",
        "  STOP.",
        "ENDIF.",
        "IF ls_request-strkorr IS NOT INITIAL.",
        "  ls_task = ls_request.",
        "  SELECT SINGLE * FROM e070 INTO ls_request",
        "    WHERE trkorr = ls_task-strkorr.",
        "  IF sy-subrc <> 0.",
        "    WRITE / 'ERROR PARENT_REQUEST_NOT_FOUND'.",
        "    STOP.",
        "  ENDIF.",
        "ELSE.",
        "  SELECT SINGLE * FROM e070 INTO ls_task",
        "    WHERE strkorr = ls_request-trkorr",
        "      AND as4user = sy-uname",
        "      AND trstatus = 'D'.",
        "  IF sy-subrc <> 0.",
        "    WRITE / 'ERROR MODIFIABLE_USER_TASK_NOT_FOUND'.",
        "    STOP.",
        "  ENDIF.",
        "ENDIF.",
        "IF ls_request-trfunction <> 'K'",
        "   OR ls_request-trstatus <> 'D'.",
        "  WRITE / 'ERROR REQUEST_NOT_MODIFIABLE_WORKBENCH'.",
        "  STOP.",
        "ENDIF.",
        "IF ls_task-as4user <> sy-uname",
        "   OR ls_task-trstatus <> 'D'.",
        "  WRITE / 'ERROR TASK_NOT_MODIFIABLE_BY_USER'.",
        "  STOP.",
        "ENDIF.",
        "lv_task = ls_task-trkorr.",
        "SELECT SINGLE * FROM tadir INTO ls_tadir",
        "  WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "    AND obj_name = 'ZORVANTA_MCP_CORE'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR FUGR_TADIR_NOT_FOUND'.",
        "  STOP.",
        "ENDIF.",
        "CALL FUNCTION 'TR_TADIR_INTERFACE'",
        "  EXPORTING",
        "    wi_test_modus = space",
        "    wi_tadir_pgmid = ls_tadir-pgmid",
        "    wi_tadir_object = ls_tadir-object",
        "    wi_tadir_obj_name = ls_tadir-obj_name",
        "    wi_tadir_srcsystem = ls_tadir-srcsystem",
        "    wi_tadir_author = ls_tadir-author",
        "    wi_tadir_devclass = 'ZABAP'",
        "    wi_tadir_masterlang = ls_tadir-masterlang",
        "  IMPORTING new_tadir_entry = ls_new_tadir",
        "  EXCEPTIONS others = 1.",
        "IF sy-subrc <> 0 OR ls_new_tadir-devclass <> 'ZABAP'.",
        "  WRITE: / 'ERROR FUGR_PACKAGE_CHANGE', sy-subrc,",
        "    sy-msgid, sy-msgno.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "CLEAR ls_object.",
        "MOVE-CORRESPONDING ls_new_tadir TO ls_object.",
        "APPEND ls_object TO lt_objects.",
        "SELECT SINGLE * FROM tadir INTO ls_tadir",
        "  WHERE pgmid = 'R3TR' AND object = 'CLAS'",
        "    AND obj_name = 'ZCL_ORVANTA_MCP_CORE'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR CLAS_TADIR_NOT_FOUND'.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "CALL FUNCTION 'TR_TADIR_INTERFACE'",
        "  EXPORTING",
        "    wi_test_modus = space",
        "    wi_tadir_pgmid = ls_tadir-pgmid",
        "    wi_tadir_object = ls_tadir-object",
        "    wi_tadir_obj_name = ls_tadir-obj_name",
        "    wi_tadir_srcsystem = ls_tadir-srcsystem",
        "    wi_tadir_author = ls_tadir-author",
        "    wi_tadir_devclass = 'ZABAP'",
        "    wi_tadir_masterlang = ls_tadir-masterlang",
        "  IMPORTING new_tadir_entry = ls_new_tadir",
        "  EXCEPTIONS others = 1.",
        "IF sy-subrc <> 0 OR ls_new_tadir-devclass <> 'ZABAP'.",
        "  WRITE: / 'ERROR CLAS_PACKAGE_CHANGE', sy-subrc,",
        "    sy-msgid, sy-msgno.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "CLEAR ls_object.",
        "MOVE-CORRESPONDING ls_new_tadir TO ls_object.",
        "APPEND ls_object TO lt_objects.",
        "CALL FUNCTION 'TR_RECORD_OBJ_CHANGE_TO_REQ'",
        "  EXPORTING iv_request = ls_request-trkorr",
        "    it_objects = lt_objects",
        "  IMPORTING et_tadir = lt_record_tadir",
        "  EXCEPTIONS cancel = 1.",
        "IF sy-subrc <> 0.",
        "  WRITE: / 'ERROR TRANSPORT_RECORD', sy-subrc,",
        "    sy-msgid, sy-msgno.",
        "  ROLLBACK WORK.",
        "  STOP.",
        "ENDIF.",
        "COMMIT WORK AND WAIT.",
        "SELECT SINGLE * FROM tadir INTO ls_tadir",
        "  WHERE pgmid = 'R3TR' AND object = 'FUGR'",
        "    AND obj_name = 'ZORVANTA_MCP_CORE'",
        "    AND devclass = 'ZABAP'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR FUGR_PACKAGE_VERIFY'.",
        "  STOP.",
        "ENDIF.",
        "SELECT SINGLE * FROM tadir INTO ls_tadir",
        "  WHERE pgmid = 'R3TR' AND object = 'CLAS'",
        "    AND obj_name = 'ZCL_ORVANTA_MCP_CORE'",
        "    AND devclass = 'ZABAP'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR CLAS_PACKAGE_VERIFY'.",
        "  STOP.",
        "ENDIF.",
        "SELECT SINGLE * FROM e071 INTO ls_e071",
        "  WHERE trkorr = ls_request-trkorr",
        "    AND pgmid = 'R3TR'",
        "    AND object = 'FUGR'",
        "    AND obj_name = 'ZORVANTA_MCP_CORE'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR FUGR_TRANSPORT_VERIFY'.",
        "  STOP.",
        "ENDIF.",
        "SELECT SINGLE * FROM e071 INTO ls_e071",
        "  WHERE trkorr = ls_request-trkorr",
        "    AND pgmid = 'R3TR'",
        "    AND object = 'CLAS'",
        "    AND obj_name = 'ZCL_ORVANTA_MCP_CORE'.",
        "IF sy-subrc <> 0.",
        "  WRITE / 'ERROR CLAS_TRANSPORT_VERIFY'.",
        "  STOP.",
        "ENDIF.",
        "WRITE: / 'ASSIGNMENT_OK PACKAGE ZABAP'.",
        "WRITE: / 'REQUEST', ls_request-trkorr.",
        "WRITE: / 'TASK', lv_task.",
        "LOOP AT lt_objects INTO ls_object.",
        "  WRITE: / 'OBJECT', ls_object-pgmid,",
        "    ls_object-object, ls_object-obj_name.",
        "ENDLOOP."
    )
}

function New-SoapEnvelope {
    param([string[]]$ProgramLines)

    foreach ($line in $ProgramLines) {
        if ($line.Length -gt 72) {
            throw "Bootstrap ABAP line exceeds 72 characters: $line"
        }
    }

    $settings = [Xml.XmlWriterSettings]::new()
    $settings.OmitXmlDeclaration = $false
    $settings.Encoding = [Text.UTF8Encoding]::new($false)
    $builder = [Text.StringBuilder]::new()
    $writer = [Xml.XmlWriter]::Create($builder, $settings)
    try {
        $writer.WriteStartDocument()
        $writer.WriteStartElement(
            "soapenv",
            "Envelope",
            "http://schemas.xmlsoap.org/soap/envelope/"
        )
        $writer.WriteStartElement(
            "soapenv",
            "Body",
            "http://schemas.xmlsoap.org/soap/envelope/"
        )
        $writer.WriteStartElement(
            "n1",
            "Z_AW_RFC_ABAP_INSTALL_AND_RUN",
            "urn:sap-com:document:sap:rfc:functions"
        )
        $writer.WriteElementString("MODE", "F")
        $writer.WriteElementString("PROGRAMNAME", 'Z$$$XRFC')
        $writer.WriteStartElement("PROGRAM")
        foreach ($line in $ProgramLines) {
            $writer.WriteStartElement("item")
            $writer.WriteElementString("LINE", $line)
            $writer.WriteEndElement()
        }
        $writer.WriteEndElement()
        $writer.WriteStartElement("WRITES")
        $writer.WriteEndElement()
        $writer.WriteEndElement()
        $writer.WriteEndElement()
        $writer.WriteEndElement()
        $writer.WriteEndDocument()
    }
    finally {
        $writer.Dispose()
    }
    return $builder.ToString()
}

function Get-LocalNameText {
    param(
        [xml]$Document,
        [string]$LocalName
    )

    $node = $Document.SelectSingleNode("//*[local-name()='$LocalName']")
    if ($node) {
        return $node.InnerText
    }
    return ""
}

function ConvertFrom-SapSoapResponse {
    param(
        [string]$ResponseBody,
        [int]$StatusCode,
        [string]$ContentType
    )

    $responseBytes = [Text.Encoding]::UTF8.GetByteCount($ResponseBody)
    $trimmedBody = $ResponseBody.TrimStart()
    $isHtml = $ContentType -match "(?i)(?:text/html|application/xhtml)" -or
        $trimmedBody -match "(?is)(?:<!DOCTYPE\s+html\b|<html\b|<head\b.{0,4096}<meta\b)"
    if ($isHtml) {
        $summary = [regex]::Replace(
            $ResponseBody,
            "(?is)<(?:script|style)\b[^>]*>.*?</(?:script|style)>",
            " "
        )
        $summary = [regex]::Replace($summary, "(?s)<[^>]*>", " ")
        $summary = [Net.WebUtility]::HtmlDecode($summary)
        $summary = [regex]::Replace($summary, "\s+", " ").Trim()
        if (-not $summary) {
            $summary = "无可读正文"
        }
        elseif ($summary.Length -gt 600) {
            $summary = $summary.Substring(0, 600) + "..."
        }
        throw "SAP SOAP端点返回了HTML登录或错误页面（HTTP $StatusCode，Content-Type: $ContentType，响应字节: $responseBytes）。摘要: $summary。请检查用户名、密码、SAP客户端以及/sap/bc/soap/rfc服务状态。"
    }

    # The legacy bootstrap RFC injects bare HTML paragraph markers into
    # long WRITE output instead of XML-escaping them.
    $sanitizedResponseBody = $ResponseBody -replace "(?i)<P(?:\s[^>]*)?>", ""
    try {
        return [xml]$sanitizedResponseBody
    }
    catch {
        $message = $_.Exception.GetBaseException().Message
        throw "SAP SOAP端点返回了无法解析的XML（HTTP $StatusCode，Content-Type: $ContentType，响应字节: $responseBytes）：$message"
    }
}

if ($Action -in @("InspectAssignment", "AssignPackageTransport") -and -not $TransportNumber) {
    throw "TransportNumber is required for $Action."
}

$program = switch ($Action) {
    "DiagnoseHelperApis" { New-HelperApiDiagnosticProgram }
    "InspectStructures" { New-InspectionProgram }
    "InspectInterface" { New-InterfaceInspectionProgram }
    "InspectRepositoryApis" { New-RepositoryApiInspectionProgram }
    "InspectGuiApis" { New-GuiApiInspectionProgram }
    "InspectGuiObject" { New-GuiObjectInspectionProgram }
    "InspectDdicApis" { New-DdicApiInspectionProgram }
    "DiagnoseDdicObject" { New-DdicObjectDiagnosticProgram }
    "Install" { New-InstallProgram }
    "RepairInterface" { New-InstallProgram -ReplaceExisting }
    "InstallRepositoryApi" {
        New-InstallProgram -FunctionName "Z_ORVANTA_MCP_DYNPRO_API"
    }
    "RepairRepositoryApi" {
        New-InstallProgram -ReplaceExisting -FunctionName "Z_ORVANTA_MCP_DYNPRO_API"
    }
    "InstallDdicApi" {
        New-InstallProgram -FunctionName "Z_ORVANTA_MCP_DDIC_API"
    }
    "RepairDdicApi" {
        New-InstallProgram -ReplaceExisting -FunctionName "Z_ORVANTA_MCP_DDIC_API"
    }
    "InstallApplicationLogApi" {
        New-ApplicationLogProgram -TransportNumber $TransportNumber
    }
    "RepairApplicationLogApi" {
        New-ApplicationLogProgram -ReplaceExisting -TransportNumber $TransportNumber
    }
    "DiagnoseFunctionGroup" { New-FunctionGroupDiagnosticProgram }
    "DiagnoseRepositoryApi" { New-RepositoryFunctionDiagnosticProgram }
    "InspectAssignment" { New-AssignmentInspectionProgram -RequestNumber $TransportNumber }
    "AssignPackageTransport" { New-AssignmentProgram -RequestNumber $TransportNumber }
}

$effectiveSecurePassword = if ($SecurePassword) {
    $SecurePassword
} else {
    Read-Host "Password for $Username" -AsSecureString
}
if ($effectiveSecurePassword.Length -eq 0) {
    throw "Password cannot be empty."
}
$passwordPointer = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($effectiveSecurePassword)
$httpClient = $null
$plainPassword = $null
$result = $null
$exitCode = 0
$statusCode = $null
$contentType = $null
$responseBytes = $null
$rawPath = $null

try {
    $plainPassword = [Runtime.InteropServices.Marshal]::PtrToStringBSTR($passwordPointer)
    $credential = [Convert]::ToBase64String(
        [Text.Encoding]::UTF8.GetBytes("${Username}:$plainPassword")
    )
    if ($AllowUnauthorized) {
        $handler = [Net.Http.HttpClientHandler]::new()
        $handler.ServerCertificateCustomValidationCallback = { $true }
        $httpClient = [Net.Http.HttpClient]::new($handler)
    } else {
        $httpClient = [Net.Http.HttpClient]::new()
    }
    $httpClient.Timeout = [TimeSpan]::FromSeconds(180)
    $httpClient.DefaultRequestHeaders.Authorization =
        [Net.Http.Headers.AuthenticationHeaderValue]::new("Basic", $credential)

    $envelope = New-SoapEnvelope -ProgramLines $program
    $content = [Net.Http.StringContent]::new(
        $envelope,
        [Text.Encoding]::UTF8,
        "text/xml"
    )
    $content.Headers.Add(
        "SOAPAction",
        "http://www.sap.com/Z_AW_RFC_ABAP_INSTALL_AND_RUN"
    )
    $normalizedBaseUrl = $BaseUrl.TrimEnd("/")
    $uri = "$normalizedBaseUrl/sap/bc/soap/rfc?sap-client=$Client&sap-language=$Language"
    $response = $httpClient.PostAsync($uri, $content).GetAwaiter().GetResult()
    $responseBody = $response.Content.ReadAsStringAsync().GetAwaiter().GetResult()
    $statusCode = [int]$response.StatusCode
    $contentType = [string]$response.Content.Headers.ContentType
    $responseBytes = [Text.Encoding]::UTF8.GetByteCount($responseBody)
    if ($ResultPath) {
        $rawPath = "$([IO.Path]::GetFullPath($ResultPath)).raw.xml"
        [IO.File]::WriteAllText(
            $rawPath,
            $responseBody,
            [Text.UTF8Encoding]::new($false)
        )
    }
    $responseXml = ConvertFrom-SapSoapResponse `
        -ResponseBody $responseBody `
        -StatusCode $statusCode `
        -ContentType $contentType
    $fault = Get-LocalNameText -Document $responseXml -LocalName "faultstring"
    $errorMessage = Get-LocalNameText -Document $responseXml -LocalName "ERRORMESSAGE"
    $writeNodes = $responseXml.SelectNodes("//*[local-name()='WRITES']/*[local-name()='item']/*[local-name()='ZEILE']")
    $writes = @($writeNodes | ForEach-Object { $_.InnerText.TrimEnd() })
    $writeError = $writes |
        Where-Object {
            $_ -match "^(?:CREATE|DELETE|EXISTENCE_CHECK|SOURCE_(?:READ|MARKER|INSERT)|GENERATE)_ERROR\b"
        } |
        Select-Object -First 1
    if (-not $errorMessage -and $writeError) {
        $errorMessage = $writeError
    }

    $result = [pscustomobject]@{
        Action       = $Action
        Status       = $statusCode
        ContentType  = $contentType
        ResponseBytes = $responseBytes
        RawResponsePath = $rawPath
        SoapFault    = $fault
        ErrorMessage = $errorMessage
        Writes       = $writes
    }
    if (-not $response.IsSuccessStatusCode -or $fault -or $errorMessage) {
        $exitCode = 2
    }
}
catch {
    $result = [pscustomobject]@{
        Action          = $Action
        Status          = $statusCode
        ContentType     = $contentType
        ResponseBytes   = $responseBytes
        RawResponsePath = $rawPath
        Error           = $_.Exception.GetBaseException().Message
    }
    $exitCode = 1
}
finally {
    if ($httpClient) {
        $httpClient.Dispose()
    }
    $plainPassword = $null
    [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($passwordPointer)
    Remove-Variable effectiveSecurePassword -ErrorAction SilentlyContinue
}

$result | Add-Member -NotePropertyName BootstrapExitCode -NotePropertyValue $exitCode -Force
if ($PassThru) {
    Write-Output $result
    return
}

$json = $result | ConvertTo-Json -Depth 5
if ($ResultPath) {
    $resolvedResultPath = [IO.Path]::GetFullPath($ResultPath)
    [IO.File]::WriteAllText($resolvedResultPath, $json, [Text.UTF8Encoding]::new($false))
}
Write-Output $json
exit $exitCode
